#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (!manager) return NULL;

    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    if (!manager->flows) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    if (manager->flows) free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_traffic_flow(TrafficManager *manager, const TrafficFlow *flow) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        TrafficFlow *new_flows = (TrafficFlow*)realloc(manager->flows, new_capacity * sizeof(TrafficFlow));
        if (!new_flows) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->flows = new_flows;
        manager->capacity = new_capacity;
    }

    manager->flows[manager->size++] = *flow;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int get_traffic_flow(TrafficManager *manager, size_t index, TrafficFlow *flow) {
    if (index >= manager->size) return -1; // Index out of bounds

    pthread_mutex_lock(&manager->lock);

    *flow = manager->flows[index];

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_traffic_flow(TrafficManager *manager, size_t index) {
    if (index >= manager->size) return -1; // Index out of bounds

    pthread_mutex_lock(&manager->lock);

    for (size_t i = index; i < manager->size - 1; ++i) {
        manager->flows[i] = manager->flows[i + 1];
    }
    --manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}
