#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#define DEFAULT_CHUNK_SIZE 1024 * 1024 // 1MB

int main(int argc, char *argv[]) {
    int opt;
    FILE *input_file = NULL;
    char *output_file = NULL;
    char delimiter = '\n';
    size_t chunk_size = DEFAULT_CHUNK_SIZE;

    while ((opt = getopt(argc, argv, "hc:o:d:")) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [options] input_file\n", argv[0]);
                printf("Options:\n");
                printf("  --help\t\tShow this help message\n");
                printf("  -c chunk_size\tSet the chunk size for processing (default: 1MB)\n");
                printf("  -o output_file\tSpecify an output file for results\n");
                printf("  -d delimiter\tSet a custom delimiter for line splitting (default: newline)\n");
                return 0;
            case 'c':
                chunk_size = atoi(optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'd':
                delimiter = optarg[0];
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                return 1;
        }
    }

    if (argc - optind != 1) {
        fprintf(stderr, "Usage: %s [options] input_file\n", argv[0]);
        return 1;
    }

    const char *input_filename = argv[optind];
    input_file = fopen(input_filename, "r");
    if (!input_file) {
        perror("Failed to open input file");
        return 1;
    }

    // Process the file in chunks
    size_t total_lines = 0;
    char buffer[chunk_size];
    while (fgets(buffer, chunk_size, input_file)) {
        char *line = buffer;
        while ((line = strchr(line, delimiter)) != NULL) {
            line++;
            total_lines++;
        }
    }

    fclose(input_file);

    if (output_file) {
        FILE *output = fopen(output_file, "w");
        if (!output) {
            perror("Failed to open output file");
            return 1;
        }
        fprintf(output, "Total lines: %zu\n", total_lines);
        fclose(output);
    } else {
        printf("Total lines: %zu\n", total_lines);
    }

    return 0;
}
