                    if (/* External validation successful */) {
                        break;
                    } else {
                        handle_network_failure();
                    }
                }
                if (retries == MAX_RETRIES) {
                    printf("Validation failed after %d retries.\n", MAX_RETRIES);
                    continue;
                }

                valid_integers = realloc(valid_integers, (valid_count + 1) * sizeof(int));
                if (valid_integers == NULL) {
                    fprintf(stderr, "Memory allocation failed.\n");
                    exit(EXIT_FAILURE);
                }
                valid_integers[valid_count++] = num;
            } else {
                printf("Invalid integer: %s\n", token);
