#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1MB per log file
#define LOG_DIR "logs/"

typedef struct {
    char filename[256];
    FILE* file;
    size_t current_size;
} LogFile;

LogFile* create_log_file(const char* app_name) {
    LogFile* log = (LogFile*)malloc(sizeof(LogFile));
    snprintf(log->filename, sizeof(log->filename), "%s%s.log", LOG_DIR, app_name);
    log->file = fopen(log->filename, "a");
    if (!log->file) {
        perror("Failed to open log file");
        free(log);
        return NULL;
    }
    fseek(log->file, 0, SEEK_END);
    log->current_size = ftell(log->file);
    return log;
}

void append_to_log(LogFile* log, const char* format, ...) {
    va_list args;
    va_start(args, format);
    vfprintf(log->file, format, args);
    va_end(args);
    fflush(log->file);
    log->current_size += vsnprintf(NULL, 0, format, args);
}

void rotate_log_file(LogFile* log) {
    fclose(log->file);
    char new_filename[256];
    snprintf(new_filename, sizeof(new_filename), "%s%s.old", LOG_DIR, log->filename);
    rename(log->filename, new_filename);
    log->file = fopen(log->filename, "a");
    if (!log->file) {
        perror("Failed to open new log file after rotation");
        return;
    }
    fseek(log->file, 0, SEEK_END);
    log->current_size = ftell(log->file);
}

void check_and_rotate_log(LogFile* log) {
    if (log->current_size > MAX_LOG_SIZE) {
        rotate_log_file(log);
    }
}

int main() {
    LogFile* app1_log = create_log_file("app1");
    LogFile* app2_log = create_log_file("app2");

    append_to_log(app1_log, "Application 1 log entry at %s\n", time(NULL));
    check_and_rotate_log(app1_log);

    append_to_log(app2_log, "Application 2 log entry at %s\n", time(NULL));
    check_and_rotate_log(app2_log);

    fclose(app1_log->file);
    fclose(app2_log->file);
    free(app1_log);
    free(app2_log);

    return 0;
}
