import java.util.concurrent.*;
import java.util.function.Function;
import java.util.stream.Stream;

public class PokemonReportGenerator {

    private final ExecutorService executor = Executors.newCachedThreadPool();
    private final RateLimiter rateLimiter = RateLimiter.create(10000); // 10,000 requests per minute
    private final int maxRetries = 5;
    private final long initialBackoff = 100; // milliseconds

    public void generateReports(Stream<Pokemon> pokemonStream) {
        pokemonStream.forEach(pokemon -> executor.submit(() -> processPokemon(pokemon)));
    }

    private void processPokemon(Pokemon pokemon) {
        rateLimiter.acquire();
        for (int attempt = 0; attempt <= maxRetries; attempt++) {
            try {
                PokemonTypeData typeData = fetchTypeData(pokemon.getType());
                generateReport(pokemon, typeData);
                return;
            } catch (Exception e) {
                if (attempt == maxRetries) {
                    logError("Failed to process Pokemon: " + pokemon.getName(), e);
                } else {
                    long backoffTime = initialBackoff * (1 << attempt);
                    logRetry(pokemon, attempt, backoffTime);
                    try {
                        Thread.sleep(backoffTime);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        return;
                    }
                }
            }
        }
    }

    private PokemonTypeData fetchTypeData(String type) throws Exception {
        // Simulate API call with potential network delays
        TimeUnit.MILLISECONDS.sleep(ThreadLocalRandom.current().nextInt(10, 50));
        if (ThreadLocalRandom.current().nextBoolean()) {
            throw new IOException("Temporary service outage");
        }
        return new PokemonTypeData(type);
    }

    private void generateReport(Pokemon pokemon, PokemonTypeData typeData) {
        // Generate detailed report based on type data
        System.out.println("Report for " + pokemon.getName() + ": " + typeData.getWeaknesses() + ", " + typeData.getResistances() + ", " + typeData.getImmunities());
    }

    private void logError(String message, Exception e) {
        // Log error with stack trace
        System.err.println(message);
        e.printStackTrace();
    }

    private void logRetry(Pokemon pokemon, int attempt, long backoffTime) {
        // Log retry information
        System.out.println("Retrying Pokemon " + pokemon.getName() + " (attempt " + attempt + ") in " + backoffTime + "ms");
    }

    public static class Pokemon {
        private final String name;
        private final String type;

        public Pokemon(String name, String type) {
            this.name = name;
            this.type = type;
        }

        public String getName() {
            return name;
        }

        public String getType() {
            return type;
        }
    }

    public static class PokemonTypeData {
        private final String type;
        private final String weaknesses;
        private final String resistances;
        private final String immunities;

        public PokemonTypeData(String type) {
            this.type = type;
            // Simulate fetching data from API
            this.weaknesses = "Grass, Water";
            this.resistances = "Fire, Electric";
            this.immunities = "";
        }

        public String getWeaknesses() {
            return weaknesses;
        }

        public String getResistances() {
            return resistances;
        }

        public String getImmunities() {
            return immunities;
        }
    }
}
