typedef struct {
    char name[256];
    void (*operation)(void);
    int id;
} CryptoAlgorithm;

typedef struct Node {
    CryptoAlgorithm data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} AlgorithmList;

// Function to dynamically check for algorithm availability
int is_algorithm_available(const char* name) {
    // Placeholder implementation
    return 1; // Assume all algorithms are available
}

// Function to add an algorithm to the list
void add_algorithm(AlgorithmList* list, const char* name, void (*operation)(void), int id) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (new_node == NULL) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    strcpy(new_node->data.name, name);
    new_node->data.operation = operation;
    new_node->data.id = id;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

// Function to initialize the algorithm list
AlgorithmList* init_algorithm_list() {
    AlgorithmList* list = (AlgorithmList*)malloc(sizeof(AlgorithmList));
    if (list == NULL) {
        perror("Failed to allocate memory for algorithm list");
        return NULL;
