#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    sem_t *sem;
    int initial_value;
} Semaphore;

Semaphore* create_semaphore(int initial_value) {
    Semaphore *s = (Semaphore*)malloc(sizeof(Semaphore));
    if (!s) return NULL;

    s->initial_value = initial_value;
    s->sem = (sem_t*)malloc(sizeof(sem_t));
    if (!s->sem || sem_init(s->sem, 0, initial_value) != 0) {
        free(s);
        return NULL;
    }

    return s;
}

void destroy_semaphore(Semaphore *s) {
    if (s && s->sem) {
        sem_destroy(s->sem);
        free(s->sem);
        free(s);
    }
}

int semaphore_wait(Semaphore *s) {
    if (!s || !s->sem) return -1;
    return sem_wait(s->sem);
}

int semaphore_post(Semaphore *s) {
    if (!s || !s->sem) return -1;
    return sem_post(s->sem);
}

int semaphore_get_value(Semaphore *s, int *value) {
    if (!s || !s->sem || !value) return -1;
    return sem_getvalue(s->sem, value);
}
```

