class DataStore {
public:
    void updateOrIncrement(int key, const std::string& value) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = data_.find(key);
        if (it == data_.end()) {
            data_[key] = value;
        } else {
            ++it->second;
        }
    }

    void synchronizeWith(const DataStore& other) {
        std::lock_guard<std::mutex> lock1(mutex_);
        std::lock_guard<std::mutex> lock2(other.mutex_);
        for (const auto& pair : other.data_) {
            data_[pair.first] = pair.second;
        }
    }

    double getLoadFactor() const {
        return data_.load_factor();
    }

    bool isResizeNecessary(double threshold) const {
        return getLoadFactor() > threshold;
    }

private:
    std::unordered_map<int, std::string> data_;
    mutable std::mutex mutex_;
};
