namespace logging = boost::log;
namespace src = boost::log::sources;
namespace expr = boost::log::expressions;
namespace keywords = boost::log::keywords;

typedef src::severity_logger<boost::log::trivial::severity_level> logger_t;

BOOST_LOG_GLOBAL_LOGGER(my_logger, logger_t)

void init_logging() {
    logging::add_file_log(
        keywords::file_name = "sample_%N.log",
        keywords::rotation_size = 10 * 1024 * 1024,
        keywords::time_based_rotation = expr::on_weekday_at_time(boost::gregorian::Monday, boost::posix_time::hours(3)),
        keywords::format = "[%TimeStamp%]: %Message%"
    );

    logging::add_console_log(
        std::clog,
        keywords::format = "[%TimeStamp%]: %Message%"
    );

    logging::core::get()->set_filter(
        expr::attr<boost::log::trivial::severity_level>("Severity") >= boost::log::trivial::info
    );
}

int main() {
    init_logging();

    BOOST_LOG(my_logger) << "This is an informational message";
    BOOST_LOG_SEV(my_logger, boost::log::trivial::warning) << "This is a warning message";

    return 0;
}
