using System;
using System.IO;
using System.Xml.XPath;

public class ConfigParser
{
    public static void ParseConfig(string xmlFilePath, string elementName)
    {
        try
        {
            XPathDocument doc = new XPathDocument(xmlFilePath);
            XPathNavigator nav = doc.CreateNavigator();
            XPathNodeIterator nodes = nav.Select($"//{elementName}");

            if (nodes.MoveNext())
            {
                Console.WriteLine(nodes.Current.Value);
            }
            else
            {
                Console.WriteLine($"Element '{elementName}' not found.");
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML: {ex.Message}");
        }
    }

    public static void ManageProjectDirectory(string projectVersion, string envVarName)
    {
        string directoryPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), "Projects", projectVersion);

        if (!Directory.Exists(directoryPath))
        {
            Directory.CreateDirectory(directoryPath);
            Console.WriteLine($"Created directory: {directoryPath}");
        }
        else
        {
            Console.WriteLine($"Directory already exists: {directoryPath}");
        }

        string currentEnvVar = Environment.GetEnvironmentVariable(envVarName);
        if (currentEnvVar != null)
        {
            Console.WriteLine($"Warning: Environment variable '{envVarName}' is already set to '{currentEnvVar}'.");
        }
        else
        {
            Environment.SetEnvironmentVariable(envVarName, directoryPath);
            Console.WriteLine($"Set environment variable '{envVarName}' to '{directoryPath}'.");
        }
    }

    public static void LogOperation(string operation)
    {
        string timestamp = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");
        Console.WriteLine($"{timestamp} - {operation}");
    }
}

public class Program
{
    public static void Main()
    {
        ConfigParser.ParseConfig("config.xml", "Setting");
        ConfigParser.ManageProjectDirectory("v1.0", "PROJECT_DIR");
        ConfigParser.LogOperation("Main method executed.");
    }
}
