import java.io.*;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileHashProcessor {

    private static final Map<String, String> md5Cache = new HashMap<>();
    private static final Map<String, String> sha256Cache = new HashMap<>();

    public static void main(String[] args) {
        try {
            processFiles("path/to/file1.txt", "path/to/file2.txt");
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    public static void processFiles(String... filePaths) throws IOException, NoSuchAlgorithmException {
        for (String path : filePaths) {
            if (!md5Cache.containsKey(path)) {
                String md5 = calculateMD5Hash(path);
                md5Cache.put(path, md5);
            }
            if (!sha256Cache.containsKey(path)) {
                String sha256 = calculateSHA256Hash(path);
                sha256Cache.put(path, sha256);
            }
        }
    }

    private static String calculateMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (InputStream is = new BufferedInputStream(new FileInputStream(filePath))) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private static String calculateSHA256Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new BufferedInputStream(new FileInputStream(filePath))) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
