<?php

function manageUserRequests($_POST) {
    $response = ['status' => 'success', 'data' => []];

    // Simulate database connection
    $db = new PDO('sqlite:memory:');
    $db->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // Create table for users if it doesn't exist
    $db->exec("CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, email TEXT UNIQUE, password TEXT)");

    foreach ($_POST['actions'] as $action) {
        try {
            switch ($action['sub_action']) {
                case 'create':
                    if (!isset($action['email'], $action['password'])) throw new Exception('Email and password are required for create action.');
                    $hashedPassword = password_hash($action['password'], PASSWORD_DEFAULT);
                    $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (:name, :email, :password)");
                    $stmt->execute(['name' => $action['name'], 'email' => $action['email'], 'password' => $hashedPassword]);
                    $response['data'][] = ['id' => $db->lastInsertId(), 'status' => 'created'];
                    break;
                case 'update':
                    if (!isset($action['id'], $action['email'])) throw new Exception('ID and email are required for update action.');
                    $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
                    $stmt->execute(['id' => $action['id']]);
                    $user = $stmt->fetch();
                    if (!$user) throw new Exception('User not found for update action.');

                    $hashedPassword = isset($action['password']) ? password_hash($action['password'], PASSWORD_DEFAULT) : $user['password'];
                    $stmt = $db->prepare("UPDATE users SET name = :name, email = :email, password = :password WHERE id = :id");
                    $stmt->execute(['name' => $action['name'], 'email' => $action['email'], 'password' => $hashedPassword, 'id' => $action['id']]);
                    $response['data'][] = ['id' => $action['id'], 'status' => 'updated'];
                    break;
                case 'delete':
                    if (!isset($action['id'])) throw new Exception('ID is required for delete action.');
                    $stmt = $db->prepare("SELECT * FROM users WHERE id = :id");
                    $stmt->execute(['id' => $action['id']]);
                    $user = $stmt->fetch();
                    if (!$user) throw new Exception('User not found for delete action.');

                    $stmt = $db->prepare("DELETE FROM users WHERE id = :id");
                    $stmt->execute(['id' => $action['id']]);
                    $response['data'][] = ['id' => $action['id'], 'status' => 'deleted'];
                    break;
                default:
                    throw new Exception('Invalid sub_action.');
            }
        } catch (Exception $e) {
            $response['status'] = 'error';
            $response['data'][] = ['error' => $e->getMessage()];
        }
    }

    return json_encode($response);
}

// Example usage
$_POST = [
    'actions' => [
        ['sub_action' => 'create', 'name' => 'John Doe', 'email' => 'john@example.com', 'password' => 'password123'],
        ['sub_action' => 'update', 'id' => 1, 'name' => 'Jane Doe', 'email' => 'jane@example.com'],
        ['sub_action' => 'delete', 'id' => 1]
    ]
];

echo manageUserRequests($_POST);
?>
