import java.io.*;
import java.util.Properties;

public class StateLoader {

    public static MoSTState loadState(String filePath) {
        MoSTState state = null;
        ObjectInputStream ois = null;
        try (FileInputStream fis = new FileInputStream(filePath)) {
            ois = new ObjectInputStream(fis);
            Object obj = ois.readObject();
            if (obj instanceof MoSTState) {
                state = (MoSTState) obj;
                // Handle theme bitmap recycling and default directory initialization
                handleThemeBitmap(state.getThemeBitmap());
                initializeDefaultThemeDirectory();
                parseAndCachePNGFile(state.getCacheRootDir());
            }
        } catch (IOException | ClassNotFoundException e) {
            e.printStackTrace();
        } finally {
            if (ois != null) {
                try {
                    ois.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
        return state;
    }

    private static void handleThemeBitmap(Bitmap bitmap) {
        if (!bitmap.isInUse()) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    private static void initializeDefaultThemeDirectory() {
        Properties properties = new Properties();
        try (FileInputStream fis = new FileInputStream("config.properties")) {
            properties.load(fis);
            String themeDir = properties.getProperty("theme.directory");
            if (themeDir == null || themeDir.isEmpty()) {
                properties.setProperty("theme.directory", "/default/theme/directory");
                try (FileOutputStream fos = new FileOutputStream("config.properties")) {
                    properties.store(fos, "Default theme directory configuration");
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

