["```javascript
const fs = require('fs').promises;
const path = require('path');
const axios = require('axios');

class FileProcessor {
  constructor(apiUrl) {
    this.apiUrl = apiUrl;
    this.cache = new Map();
    this.logger = console.log; // Default logger
  }

  async readFiles(directory, extension) {
    try {
      const files = await fs.readdir(directory);
      const filteredFiles = files.filter(file => path.extname(file).toLowerCase() === `.${extension}`);
      return Promise.all(filteredFiles.map(file => this.processFile(path.join(directory, file))));
    } catch (error) {
      this.logger(`Error reading directory: ${error.message}`);
      throw error;
    }
  }

  async processFile(filePath) {
    if (this.cache.has(filePath)) {
      return this.cache.get(filePath);
    }

    try {
      const content = await fs.readFile(filePath, 'utf8');
      const metadata = await this.fetchMetadata(content);
      this.cache.set(filePath, { content, metadata });
      return { filePath, content, metadata };
    } catch (error) {
      this.logger(`Error processing file ${filePath}: ${error.message}`);
      throw error;
    }
  }

  async fetchMetadata(content) {
    try {
      const response = await axios.post(this.apiUrl, { content });
      return response.data;
    } catch (error) {
      this.logger(`Error fetching metadata for file: ${error.message}`);
      throw error;
    }
  }

  setLogger(loggerFunction) {
    this.logger = loggerFunction;
  }

  clearCache() {
    this.cache.clear();
  }
}

// Usage example:
const processor = new FileProcessor('https://api.example.com/metadata');
processor.setLogger((message) => console.error(message));

(async () => {
  try {
    const files = await processor.readFiles('/path/to/directory', 'txt');
    console.log(files);
  } catch (error) {
    console.error('Failed to process files:', error);
  }
})();
```

This code defines a `FileProcessor` class that encapsulates the functionality for reading and processing files asynchronously. It uses Node.js's built-in `fs` module for file operations and `axios` for making HTTP requests to an external API. The class includes methods for reading files from a directory, filtering by extension, processing each file (including fetching metadata), and caching results for repeated access. It also provides mechanisms for logging errors and clearing the cache."]

