// Define the refreshDynamicFormFields function within an AngularJS service
angular.module('formService', []).service('FormService', ['$http', '$q', 'CacheFactory', function($http, $q, CacheFactory) {
    // Create a cache for storing form configurations and field values
    var formCache = CacheFactory.createCache('formCache', {
        maxAge: 60 * 1000, // Cache entries expire after 1 minute
        deleteOnExpire: 'aggressive'
    });

    // Function to refresh dynamic form fields
    this.refreshDynamicFormFields = function(resourceId, url, fieldIdentifiers) {
        var deferred = $q.defer();
        var cacheKey = resourceId + '-' + url;

        // Check if the data is already in the cache
        if (formCache.get(cacheKey)) {
            console.log('Using cached data for resource:', resourceId);
            this.updateFields(fieldIdentifiers, formCache.get(cacheKey));
            deferred.resolve();
        } else {
            // Make an API call to retrieve the latest form configuration and field values
            $http.get(url)
                .then(function(response) {
                    if (response.data && response.data.fields) {
                        console.log('Data retrieved from API for resource:', resourceId);
                        formCache.put(cacheKey, response.data);
                        this.updateFields(fieldIdentifiers, response.data);
                        deferred.resolve();
                    } else {
                        console.error('Invalid data received from API for resource:', resourceId);
                        deferred.reject(new Error('Invalid data received'));
                    }
                }.bind(this))
                .catch(function(error) {
                    console.error('Error fetching data from API for resource:', resourceId, error);
                    deferred.reject(error);
                });
        }

        return deferred.promise;
    };

    // Function to update form fields based on the retrieved data
    this.updateFields = function(fieldIdentifiers, formData) {
        fieldIdentifiers.forEach(function(fieldId) {
            if (formData.fields[fieldId]) {
                var fieldElement = document.getElementById(fieldId);
                if (fieldElement) {
                    fieldElement.value = formData.fields[fieldId];
                    // Add the field identifier to the forward list structure
                    this.addToList(fieldId);
                }
            }
        }.bind(this));
    };

    // Function to add a field identifier to the forward list structure
    this.addToList = function(fieldId) {
        var forwardList = document.getElementById('forwardList');
        if (!forwardList.contains(document.getElementById(fieldId))) {
            forwardList.appendChild(document.createElement('li')).id = fieldId;
        }
    };
}]);
