class DataPipeline {
  constructor() {
    this.sources = [];
    this.processors = [];
    this.isPaused = false;
    this.log = [];
  }

  addSource(source) {
    this.sources.push(source);
  }

  addProcessor(processor) {
    this.processors.push(processor);
  }

  startPipeline(interval) {
    setInterval(() => {
      if (!this.isPaused) {
        this.collectData();
      }
    }, interval);
  }

  pausePipeline() {
    this.isPaused = true;
  }

  resumePipeline() {
    this.isPaused = false;
  }

  collectData() {
    this.sources.forEach(source => {
      try {
        const data = source.fetchData();
        if (data) {
          this.processData(data);
        }
      } catch (error) {
        this.logError(error, 'Data fetching failed');
      }
    });
  }

  processData(data) {
    let transformedData = data;
    this.processors.forEach(processor => {
      try {
        transformedData = processor.transform(transformedData);
