// Define a JavaScript module for dynamic loading and execution of JavaScript files
const ScriptLoader = (function() {
    const loadedScripts = new Set();
    const scriptQueue = [];
    const dependencyMap = {};

    function loadScript(url, callback) {
        return new Promise((resolve, reject) => {
            const script = document.createElement('script');
            script.src = url;
            script.onload = () => {
                resolve(script);
                if (callback) callback();
            };
            script.onerror = () => {
                reject(new Error(`Failed to load script: ${url}`));
            };
            document.head.appendChild(script);
        });
    }

    function executeScript(script) {
        try {
            eval(script.text); // Evaluate the script in the current context
        } catch (error) {
            console.error('Error executing script:', error);
        }
    }

    function resolveDependencies(url) {
        const dependencies = dependencyMap[url] || [];
        return Promise.all(dependencies.map(dep => loadScript(dep)));
    }

    function processQueue() {
        if (scriptQueue.length === 0) return;

        const url = scriptQueue.shift();
        resolveDependencies(url)
            .then(() => loadScript(url))
            .then(script => {
                executeScript(script);
                loadedScripts.add(url);
                processQueue();
            })
            .catch(error => {
                console.error('Error loading or executing script:', error);
                processQueue();
            });
    }

    function addScript(url, dependencies = []) {
        if (loadedScripts.has(url)) return;
        dependencyMap[url] = dependencies;
        scriptQueue.push(url);
        processQueue();
    }

    function generateNewFilename(originalUrl) {
        const extensionIndex = originalUrl.lastIndexOf('.');
        const baseName = originalUrl.substring(0, extensionIndex);
        const newExtension = '.' + Math.random().toString(36).substr(2, 5); // Generate a random extension
        return baseName + newExtension;
    }

    return {
        addScript,
        generateNewFilename
    };
})();

// Example usage:
ScriptLoader.addScript('path/to/your/script.js', ['path/to/dependency1.js', 'path/to/dependency2.js']);
const newFilename = ScriptLoader.generateNewFilename('path/to/your/script.js');
console.log('New Filename:', newFilename);
