import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class LogProcessor {
    private final ConcurrentHashMap<String, AtomicInteger> eventCounters = new ConcurrentHashMap<>();
    private int bufferSize = 1024;
    private static final int MAX_BUFFER_SIZE = 8192;
    private static final int MIN_BUFFER_SIZE = 512;

    public void processLogEntries(LogEntry[] logEntries) {
        long startTime = System.currentTimeMillis();
        for (LogEntry entry : logEntries) {
            String eventType = entry.getEventType();
            eventCounters.putIfAbsent(eventType, new AtomicInteger(0));
            eventCounters.get(eventType).incrementAndGet();

            // Adjust buffer size dynamically
            if (logEntries.length > bufferSize && bufferSize < MAX_BUFFER_SIZE) {
                bufferSize *= 2;
                System.out.println("Buffer size increased to: " + bufferSize);
            } else if (logEntries.length <= bufferSize / 4 && bufferSize > MIN_BUFFER_SIZE) {
                bufferSize /= 2;
                System.out.println("Buffer size decreased to: " + bufferSize);
            }
        }
        long endTime = System.currentTimeMillis();
        System.out.println("Processing time: " + (endTime - startTime) + " ms");
    }

    public static class LogEntry {
        private final String timestamp;
        private final String eventType;

        public LogEntry(String timestamp, String eventType) {
            this.timestamp = timestamp;
            this.eventType = eventType;
        }

        public String getTimestamp() {
            return timestamp;
        }

        public String getEventType() {
            return eventType;
        }
    }
}
