import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.os.AsyncTask;
import android.util.Log;

import java.io.File;
import java.io.FileOutputStream;
import java.io.IOException;
import java.net.URL;
import java.util.concurrent.ConcurrentHashMap;

public class ThemeCacheManager {
    private static final String TAG = "ThemeCacheManager";
    private static final ConcurrentHashMap<String, Bitmap> cache = new ConcurrentHashMap<>();
    private static File themeDirectory;
    private static Object initLock = new Object();

    public static void initialize(Context context) {
        synchronized (initLock) {
            if (themeDirectory == null) {
                themeDirectory = new File(context.getCacheDir(), "themes");
                if (!themeDirectory.exists()) {
                    themeDirectory.mkdirs();
                }
            }
        }
    }

    public static Bitmap getThemeBitmap(String themeName) {
        Bitmap bitmap = cache.get(themeName);
        if (bitmap == null) {
            synchronized (cache) {
                bitmap = cache.get(themeName);
                if (bitmap == null) {
                    bitmap = loadThemeBitmap(themeName);
                    if (bitmap != null) {
                        cache.put(themeName, bitmap);
                    }
                }
            }
        }
        return bitmap;
    }

    private static Bitmap loadThemeBitmap(String themeName) {
        File file = new File(themeDirectory, themeName + ".png");
        try {
            return BitmapFactory.decodeStream(new URL(file.toURI().toString()).openStream());
        } catch (IOException e) {
            Log.e(TAG, "Failed to load theme bitmap: " + themeName, e);
            return null;
        }
    }

    public static void setThemeBitmap(String themeName, Bitmap bitmap) {
        cache.put(themeName, bitmap);
    }

    public static void removeThemeBitmap(String themeName) {
        Bitmap bitmap = cache.remove(themeName);
        if (bitmap != null) {
            bitmap.recycle();
            bitmap = null;
        }
    }

    public static void clearCache() {
        for (Bitmap bitmap : cache.values()) {
            bitmap.recycle();
        }
        cache.clear();
    }

    private static class ThemeLoader extends AsyncTask<String, Void, Bitmap> {
        @Override
        protected Bitmap doInBackground(String... params) {
            return loadThemeBitmap(params[0]);
        }

        @Override
        protected void onPostExecute(Bitmap result) {
            if (result != null) {
                setThemeBitmap(params[0], result);
            }
        }
    }

    public static void loadThemeAsync(String themeName) {
        new ThemeLoader().execute(themeName);
    }
}
