public class ServiceManager {
    private static final int HEALTH_CHECK_INTERVAL = 5; // seconds
    private static final int MAX_FAILURES = 3;
    private static final long INITIAL_BACKOFF = 1000; // milliseconds
    private static final double BACKOFF_MULTIPLIER = 2.0;

    private boolean isServiceActive = true;
    private int consecutiveFailures = 0;
    private ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);

    public void start() {
        scheduler.scheduleAtFixedRate(this::performHealthCheck, HEALTH_CHECK_INTERVAL, HEALTH_CHECK_INTERVAL, TimeUnit.SECONDS);
    }

    private void performHealthCheck() {
        if (!isServiceActive) return;

        long responseTime = checkServiceResponseTime();
        if (responseTime > getThreshold()) {
            consecutiveFailures++;
            if (consecutiveFailures >= MAX_FAILURES) {
                restartServiceWithExponentialBackoff(INITIAL_BACKOFF, BACKOFF_MULTIPLIER);
            }
        } else {
            consecutiveFailures = 0;
        }
    }

    private long checkServiceResponseTime() {
        // Simulate response time check
        return System.currentTimeMillis();
    }

    private void restartServiceWithExponentialBackoff(long initialDelay, double multiplier) {
        scheduler.schedule(() -> {
            try {
                // Restart logic here
                isServiceActive = true;
                consecutiveFailures = 0;
            } catch (Exception e) {
                long nextDelay = (long) (initialDelay * Math.pow(multiplier, consecutiveFailures));
                restartServiceWithExponentialBackoff(nextDelay, multiplier);
            }
        }, initialDelay, TimeUnit.MILLISECONDS);
    }

    private void sendNotification() {
        // Notification logic here
    }

    public void stop() {
        isServiceActive = false;
        scheduler.shutdown();
        sendNotification();
    }

    public void updateThreshold(long newThreshold) {
        // Update threshold logic here
    }

    public long getThreshold() {
