use reqwest::{Client, Error, Response};
use std::time::Duration;

#[derive(Debug)]
enum AuthMethod {
    BearerToken(String),
    OAuth2 { client_id: String, client_secret: String },
}

struct HttpClient {
    client: Client,
    auth_method: Option<AuthMethod>,
    api_gateway_url: String,
}

impl HttpClient {
    fn new(api_gateway_url: &str) -> Self {
        HttpClient {
            client: Client::new(),
            auth_method: None,
            api_gateway_url: api_gateway_url.to_string(),
        }
    }

    fn set_auth(&mut self, auth_method: AuthMethod) {
        self.auth_method = Some(auth_method);
    }

    async fn send_request(
        &self,
        method: reqwest::Method,
        url: &str,
        headers: Option<reqwest::header::HeaderMap>,
        body: Option<&[u8]>,
    ) -> Result<Response, Error> {
        let mut request = self.client.request(method, format!("{}{}", self.api_gateway_url, url));

        if let Some(headers) = headers {
            request = request.headers(headers);
        }

        if let Some(body) = body {
            request = request.body(body.to_vec());
        }

        if let Some(auth_method) = &self.auth_method {
            match auth_method {
                AuthMethod::BearerToken(token) => {
                    request = request.header("Authorization", format!("Bearer {}", token));
                }
                AuthMethod::OAuth2 { client_id, client_secret } => {
                    // Implement OAuth2 token management logic here
                }
            }
        }

        request.timeout(Duration::from_secs(10)).send().await
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[tokio::test]
    async fn test_send_request() {
        let mut client = HttpClient::new("https://api.example.com/");
        client.set_auth(AuthMethod::BearerToken("your_bearer_token".to_string()));

        let response = client
            .send_request(
                reqwest::Method::GET,
                "/endpoint",
                None,
                None,
            )
            .await;

        assert!(response.is_ok());
    }
}
```

