<?php

class UserProfileService {
    private $db;
    private $logger;
    private $notificationService;

    public function __construct($db, $logger, $notificationService) {
        $this->db = $db;
        $this->logger = $logger;
        $this->notificationService = $notificationService;
    }

    public function updateUserProfile($userId, $email = null, $lastLoginIp = null, $timestamp = null) {
        if (!is_numeric($userId)) {
            return ['error' => 'Invalid user ID'];
        }

        $updates = [];
        if ($email !== null) {
            $updates['email'] = $this->db->escapeString($email);
        }
        if ($lastLoginIp !== null) {
            $updates['last_login_ip'] = $this->db->escapeString($lastLoginIp);
        }
        if ($timestamp !== null) {
            $updates['updated_at'] = date('Y-m-d H:i:s', $timestamp);
        }

        if (empty($updates)) {
            return ['error' => 'No updates provided'];
        }

        $sql = "UPDATE users SET ";
        $values = [];
        foreach ($updates as $key => $value) {
            $sql .= "$key = ?, ";
            $values[] = $value;
        }
        $sql = rtrim($sql, ', ') . " WHERE id = ?";

        $stmt = $this->db->prepare($sql);
        if (!$stmt) {
            return ['error' => 'Database error: ' . $this->db->error];
        }

        array_push($values, $userId);

        if ($stmt->bind_param('sss', ...$values)) {
            if ($stmt->execute()) {
                $this->logger->log("User profile updated for user ID: $userId");
                $this->notificationService->notifyUser($userId, 'Profile updated successfully');
                return ['success' => true, 'metrics' => ['execution_time' => $stmt->get_execution_time(), 'affected_rows' => $stmt->affected_rows]];
            } else {
                return ['error' => 'Database error: ' . $stmt->error];
            }
        } else {
            return ['error' => 'Binding parameters failed'];
        }
    }
}
