  let config = await loadConfig(configPath);

  if (!config.randomString || isDuplicate(config.randomString)) {
    config.randomString = generateUniqueRandomString(16);
  }

  const encryptedConfig = await encryptConfig(config, secretKey);
  await saveConfig(encryptedConfig, configPath);
