const axios = require('axios');
const { PassThrough } = require('stream');

async function fetchCredentials(oauthToken) {
  const endpoint = `https://oauth-service.com/api/v1/credentials?token=${oauthToken}`;
  let retries = 0;
  const maxRetries = 5;
  const backoffFactor = 2;

  while (retries < maxRetries) {
    try {
      const response = await axios.get(endpoint, {
        responseType: 'stream',
        headers: {
          Authorization: `Bearer ${oauthToken}`
        }
      });

      const passThroughStream = new PassThrough();
      let dataBuffer = '';

      response.data.on('data', (chunk) => {
        dataBuffer += chunk.toString();
      });

      response.data.on('end', () => {
        console.log('Credentials fetched successfully');
        return dataBuffer;
      });

      response.data.on('error', (err) => {
        console.error('Error fetching credentials:', err);
        throw err;
      });

      return new Promise((resolve, reject) => {
        passThroughStream.on('data', (chunk) => {
          // Process chunk
        });

        passThroughStream.on('end', () => {
          resolve(dataBuffer);
        });

        passThroughStream.on('error', (err) => {
          reject(err);
        });
      });
    } catch (error) {
      retries++;
      const backoffTime = Math.pow(backoffFactor, retries) * 1000;
      console.log(`Retrying in ${backoffTime}ms...`);
      await new Promise(resolve => setTimeout(resolve, backoffTime));
    }
  }

  throw new Error('Failed to fetch credentials after multiple attempts');
}
