['```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_CONNECTIONS 1000

typedef struct {
    int id;
    time_t last_active;
    unsigned long total_bytes;
    double bandwidth_usage;
} Connection;

Connection connections[MAX_CONNECTIONS];
int connection_count = 0;

void add_connection(int id) {
    if (connection_count >= MAX_CONNECTIONS) return;
    connections[connection_count].id = id;
    connections[connection_count].last_active = time(NULL);
    connections[connection_count].total_bytes = 0;
    connections[connection_count].bandwidth_usage = 0.0;
    connection_count++;
}

void update_connection(int id, unsigned long bytes_transferred) {
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            connections[i].last_active = time(NULL);
            connections[i].total_bytes += bytes_transferred;
            // Simulate bandwidth usage calculation
            connections[i].bandwidth_usage = (double)bytes_transferred / difftime(time(NULL), connections[i].last_active);
            break;
        }
    }
}

void remove_connection(int id) {
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].id == id) {
            for (int j = i; j < connection_count - 1; j++) {
                connections[j] = connections[j + 1];
            }
            connection_count--;
            break;
        }
    }
}

void check_connection_timeout(int timeout_threshold) {
    time_t current_time = time(NULL);
    for (int i = 0; i < connection_count; i++) {
        if (difftime(current_time, connections[i].last_active) > timeout_threshold) {
            remove_connection(connections[i].id);
        }
    }
}

void print_connections() {
    printf("Current Connections:\n");
    for (int i = 0; i < connection_count; i++) {
        printf("ID: %d, Last Active: %ld, Total Bytes: %lu, Bandwidth Usage: %.2f\n",
               connections[i].id, connections[i].last_active, connections[i].total_bytes, connections[i].bandwidth_usage);
    }
}

int main() {
    add_connection(1);
    update_connection(1, 1024);
    print_connections();
    check_connection_timeout(60); // Remove connections inactive for more than 60 seconds
    return 0;
}
```

This code provides a basic structure for managing network connections with real-time monitoring and adaptive resource allocation. It includes functions to add, update, remove connections, check for timeouts, and print connection details. The `main` function demonstrates adding a connection, updating it, printing the current connections, and removing inactive connections based on a timeout threshold. This example can be expanded and optimized further based on specific requirements and system capabilities.']

