class AbilityManager {
public:
    enum class Ability { Ability1, Ability2, Ability3 };
    static constexpr int CooldownInterval = 9; // seconds

    AbilityManager() : lastUsed(Ability::Ability1), nextAvailable(std::chrono::system_clock::now()) {}

    bool useAbility(Ability ability) {
        std::unique_lock<std::mutex> lock(mutex);
        if (std::chrono::system_clock::now() < nextAvailable) {
            return false; // Cooldown not yet over
        }
        lastUsed = ability;
        nextAvailable = std::chrono::system_clock::now() + std::chrono::seconds(CooldownInterval);
        logAbility(ability);
        return true;
    }

private:
    Ability lastUsed;
    std::chrono::time_point<std::chrono::system_clock> nextAvailable;
    std::mutex mutex;

    void logAbility(Ability ability) {
        // Efficient logging system (e.g., using a circular buffer)
        static const int bufferSize = 1000;
        static Ability buffer[bufferSize];
        static int head = 0, tail = 0;
        buffer[tail] = ability;
        tail = (tail + 1) % bufferSize;
        if (head == tail) {
            // Handle buffer overflow (e.g., overwrite oldest entry)
            head = (head + 1) % bufferSize;
        }
    }
};

int main() {
    AbilityManager manager;
    manager.useAbility(AbilityManager::Ability::Ability1);
    manager.useAbility(AbilityManager::Ability::Ability2);
    manager.useAbility(AbilityManager::Ability::Ability3);
    return 0;
}
