using System;
using System.Collections.Generic;
using System.Drawing;
using Newtonsoft.Json;

public class DynamicValueGenerator
{
    private Dictionary<string, object> cachedValues = new Dictionary<string, object>();
    private Random random = new Random();

    public int GenerateRandomInt(int min, int max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max");
        return random.Next(min, max + 1);
    }

    public float GenerateRandomFloat(float min, float max)
    {
        if (min > max) throw new ArgumentException("Min cannot be greater than Max");
        return (float)(random.NextDouble() * (max - min)) + min;
    }

    public Color GenerateRandomColor(int minR, int maxR, int minG, int maxG, int minB, int maxB)
    {
        if (minR > maxR || minG > maxG || minB > maxB) throw new ArgumentException("Min values cannot be greater than Max values");
        return Color.FromArgb(GenerateRandomInt(minR, maxR), GenerateRandomInt(minG, maxG), GenerateRandomInt(minB, maxB));
    }

    public PointF GenerateRandomPoint(PointF topLeft, PointF bottomRight)
    {
        float x = (float)(random.NextDouble() * (bottomRight.X - topLeft.X)) + topLeft.X;
        float y = (float)(random.NextDouble() * (topLeft.Y - bottomRight.Y)) + bottomRight.Y;
        return new PointF(x, y);
    }

    public void UpdateCachedValues(Dictionary<string, object> newValues)
    {
        cachedValues.Clear();
        foreach (var item in newValues)
        {
            cachedValues[item.Key] = item.Value;
        }
    }

    public string SerializeToJson()
    {
        return JsonConvert.SerializeObject(cachedValues);
    }

    public void LogValue(string valueName, object value)
    {
        Console.WriteLine($"{valueName}: {value}");
    }

    public override string ToString()
    {
        return $"DynamicValueGenerator - Cached Values: {JsonConvert.SerializeObject(cachedValues)}";
    }
}
