/**
 * Generic reducer function that supports both synchronous and asynchronous operations.
 * @param {Array} array - The array to reduce.
 * @param {Function} reducer - The custom aggregation logic.
 * @param {*} initialValue - The initial value for the accumulator.
 * @param {boolean} isAsync - Flag to indicate if the operation is asynchronous.
 * @returns {*} The result of the reduction.
 */
async function genericReducer(array, reducer, initialValue, isAsync) {
  let accumulator = initialValue;

  for (const item of array) {
    try {
      if (isAsync) {
        accumulator = await reducer(accumulator, item);
      } else {
        accumulator = reducer(accumulator, item);
      }
    } catch (error) {
      console.error('Error during reduction:', error);
      return null; // Gracefully degrade in case of invalid inputs or unexpected errors
    }
  }

  return accumulator;
}

// Example usage:
const array = [1, 2, 3, 4, 5];
const reducer = (acc, curr) => acc + curr;

genericReducer(array, reducer, 0, false)
  .then(result => console.log('Synchronous result:', result))
  .catch(error => console.error('Error:', error));

// Asynchronous example with a delay
const asyncReducer = async (acc, curr) => {
  await new Promise(resolve => setTimeout(resolve, 100)); // Simulate network latency
  return acc + curr;
};

genericReducer(array, asyncReducer, 0, true)
  .then(result => console.log('Asynchronous result:', result))
  .catch(error => console.error('Error:', error));
```

This code snippet defines a generic reducer function that can handle both synchronous and asynchronous operations. It includes error handling strategies to gracefully degrade in case of invalid inputs or unexpected errors. The function is designed to be modular, allowing for easy integration with existing systems that may have varying data source latencies and throughput limitations."]

