typedef int (*CallbackFunction)(const char*);

char* processString(const char* input, int sizeLimit, CallbackFunction callback) {
    if (input == NULL || callback == NULL) {
        return NULL;
    }

    // Check if the string meets the criteria and does not exceed the size limit
    if (!callback(input) || strlen(input) >= sizeLimit) {
        return NULL;
    }

    // Allocate memory for the new string with space for the slash and null terminator
    char* result = (char*)malloc(strlen(input) + 2);
    if (result == NULL) {
        return NULL;
    }

    // Copy the original string to the new buffer
    strcpy(result, input);

    // Append a slash to the end of the string
    result[strlen(input)] = '/';
    result[strlen(input) + 1] = '\0';

    return result;
}
