function DOMTraversal(element, selectorFunction) {
    let matches = [];

    function traverse(node) {
        if (node.nodeType === Node.ELEMENT_NODE && selectorFunction(node)) {
            matches.push(node);
        }

        for (let child of node.childNodes) {
            traverse(child);
        }
    }

    traverse(document.body); // Start traversal from the root element
    return matches;
}
