#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 10
#define CACHE_SIZE 100

typedef struct {
    char **fields;
    int field_count;
} Record;

typedef struct {
    Record *records;
    int size;
    int capacity;
} Cache;

Cache cache = {NULL, 0, 0};

void init_cache(int size) {
    cache.capacity = size;
    cache.records = (Record *)malloc(size * sizeof(Record));
}

void free_record(Record *record) {
    for (int i = 0; i < record->field_count; i++) {
        free(record->fields[i]);
    }
    free(record->fields);
}

void free_cache() {
    for (int i = 0; i < cache.size; i++) {
        free_record(&cache.records[i]);
    }
    free(cache.records);
}

Record parse_line(const char *line) {
    Record record;
    record.fields = (char **)malloc(MAX_FIELDS * sizeof(char *));
    record.field_count = 0;

    const char *delim = " ";
    char *token = strtok((char *)line, delim);
    while (token != NULL && record.field_count < MAX_FIELDS) {
        record.fields[record.field_count++] = strdup(token);
        token = strtok(NULL, delim);
    }

    return record;
}

void update_record(Record *record) {
    if (record->field_count >= 2) {
        double sum = atof(record->fields[record.field_count - 1]) + atof(record->fields[record.field_count - 2]);
        free(record->fields[record.field_count - 1]);
        record->fields[record.field_count - 1] = (char *)malloc(50 * sizeof(char));
        sprintf(record->fields[record.field_count - 1], "%.2f", sum / 2);
    }
}

void add_to_cache(Record record) {
    if (cache.size >= cache.capacity) {
        // Implement LRU eviction policy
        free_record(&cache.records[0]);
        memmove(cache.records, cache.records + 1, (cache.size - 1) * sizeof(Record));
        cache.size--;
    }
    cache.records[cache.size++] = record;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        Record record = parse_line(line);
        update_record(&record);
        add_to_cache(record);
    }

    fclose(file);
}

int main() {
    init_cache(CACHE_SIZE);
    process_file("database_log.txt");
    free_cache();
    return 0;
}
