#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

#define MAX_FILENAME_LENGTH 256

void renameFile(const char* oldFilename) {
    if (oldFilename == NULL || strlen(oldFilename) >= MAX_FILENAME_LENGTH) {
        fprintf(stderr, "Invalid filename\n");
        return;
    }

    char newFilename[MAX_FILENAME_LENGTH];
    strcpy(newFilename, oldFilename);

    // Check if the file is a log file
    int isLog = (strstr(oldFilename, "log") != NULL);

    // Determine the number of digits to append as a suffix
    size_t len = strlen(oldFilename);
    int numDigits = isLog ? ((len / 2) + (len % 2)) : ((len / 3) + (len % 3));

    // Ensure the total filename length does not exceed 255 characters
    if (numDigits > MAX_FILENAME_LENGTH - len - 1) {
        numDigits = MAX_FILENAME_LENGTH - len - 1;
    }

    // Append digits to the filename
    char suffix[numDigits + 1];
    for (int i = 0; i < numDigits; ++i) {
        suffix[i] = '0' + (rand() % 10);
    }
    suffix[numDigits] = '\0';
    strcat(newFilename, suffix);

    // Set the new file type extension
    if (strrchr(oldFilename, '.') != NULL && strcmp(strrchr(oldFilename, '.'), ".bin") == 0) {
        strcpy(strrchr(newFilename, '.'), ".txt");
    } else {
        strcat(newFilename, ".dat");
    }

    // Rename the file
    if (rename(oldFilename, newFilename) != 0) {
        perror("Failed to rename file");
    }
}

int main() {
    srand(time(NULL));
    renameFile("example.log");
    renameFile("data.bin");
    renameFile("report.txt");
