#define KEY_LENGTH 32

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[IV_LENGTH];
} AESCipher;

AESCipher* init_aes_cipher(const char *password) {
    AESCipher *cipher = malloc(sizeof(AESCipher));
    if (!cipher) return NULL;

    // Derive key using Argon2
    uint8_t key[KEY_LENGTH];
    argon2id_ctx ctx;
    argon2id_init(&ctx, KEY_LENGTH, 16, 32, password, strlen(password), NULL, 0, NULL, 0, 1, ARGON2_DEFAULT_ITERATIONS, ARGON2_DEFAULT_MEMORY_COST, ARGON2_DEFAULT_LANES);
    argon2id_hash_raw(&ctx, key);

    // Initialize cipher context
    if (!(cipher->ctx = EVP_CIPHER_CTX_new())) {
        free(cipher);
        return NULL;
    }
    if (1 != EVP_EncryptInit_ex(cipher->ctx, EVP_aes_256_cbc(), NULL, key, cipher->iv)) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
        return NULL;
    }

    return cipher;
}

void cleanup_cipher(AESCipher *cipher) {
    if (cipher) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        free(cipher);
    }
}
