```java
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;

public class SerializationUtil {

    private static final ObjectCache cache = new ObjectCache();

    public static <T> T deserializeObject(byte[] bytes, Class<T> clazz) {
        try {
            // Check if the object is already in the cache
            T cachedObject = (T) cache.get(bytes);
            if (cachedObject != null) {
                return cachedObject;
            }

            ByteArrayInputStream bis = new ByteArrayInputStream(bytes);
            ObjectInputStream ois = new ObjectInputStream(bis);
            T obj = clazz.cast(ois.readObject());
            ois.close();
            bis.close();

            // Cache the object
            cache.put(bytes, obj);

            return obj;
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Error deserializing object", e);
        }
    }

    private static class ObjectCache {
        private final Map<byte[], Object> cache = new HashMap<>();

        public synchronized Object get(byte[] key) {
            return cache.get(key);
        }

        public synchronized void put(byte[] key, Object value) {
            cache.put(key, value);
        }
    }
}
```

