import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class CommandManager {
    private ExecutorService executorService;
    private Path targetDirectory;
    private long commandTimeout;

    public CommandManager(int threadPoolSize, Path targetDirectory, long commandTimeout) {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.targetDirectory = targetDirectory;
        this.commandTimeout = commandTimeout;
    }

    public void executeCommand(String... commands) {
        for (String command : commands) {
            executorService.submit(() -> {
                try {
                    clearDirectory();
                    ProcessBuilder processBuilder = new ProcessBuilder(command.split(" "));
                    Process process = processBuilder.start();
                    if (!process.waitFor(commandTimeout, TimeUnit.SECONDS)) {
                        process.destroyForcibly();
                        throw new IOException("Command execution timed out");
                    }
                    int exitCode = process.exitValue();
                    logExecutionStatus(exitCode);
                } catch (IOException | InterruptedException e) {
                    handleException(e);
                }
            });
        }
    }

    private void clearDirectory() throws IOException {
        Files.walk(targetDirectory)
             .sorted(java.util.Comparator.reverseOrder())
             .map(Path::toFile)
             .forEach(File::delete);
    }

    private void logExecutionStatus(int exitCode) {
        System.out.println("Command executed with exit code: " + exitCode);
    }

    private void handleException(Exception e) {
        System.err.println("Error executing command: " + e.getMessage());
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        Path targetDirectory = Paths.get("/path/to/target/directory");
        long commandTimeout = 30; // in seconds
        CommandManager manager = new CommandManager(10, targetDirectory, commandTimeout);
        manager.executeCommand("command1", "command2", "command3");
        manager.shutdown();
    }
}
