public class FileProcessor
{
    private readonly ConcurrentDictionary<string, string> _fileMetadataCache = new ConcurrentDictionary<string, string>();
    private readonly IDistributedDatabase _database;

    public FileProcessor(IDistributedDatabase database)
    {
        _database = database;
    }

    public async Task ProcessFilesAsync(IEnumerable<FileInfo> files)
    {
        var tasks = new List<Task>();

        foreach (var file in files)
        {
            tasks.Add(ProcessFileAsync(file));
        }

        await Task.WhenAll(tasks);
    }

    private async Task ProcessFileAsync(FileInfo file)
    {
        try
        {
            string newFilename = GenerateNewFilename(file.Name, file.Length);
            string newFilePath = Path.Combine(file.DirectoryName, newFilename);

            // Rename the file
            File.Move(file.FullName, newFilePath);

            // Store metadata in the database
            await _database.StoreMetadataAsync(newFilePath, GetFileMetadata(newFilePath));

            // Update cache
            _fileMetadataCache[newFilePath] = GetFileMetadata(newFilePath);
        }
        catch (Exception ex)
        {
            // Handle exceptions and log errors
            Console.WriteLine($"Error processing file {file.Name}: {ex.Message}");
        }
    }

    private string GenerateNewFilename(string originalFilename, long fileSize)
    {
        int maxFilenameLength = 255;
        string extension = Path.GetExtension(originalFilename);
        string baseName = Path.GetFileNameWithoutExtension(originalFilename);

        if (extension == ".bin")
        {
            int suffixLength = (int)Math.Ceiling(baseName.Length / 2.0);
            string newBaseName = baseName.Substring(0, maxFilenameLength - extension.Length - suffixLength);
            return $"{newBaseName}{suffixLength:D}{extension}";
        }
        else
        {
            int suffixLength = (int)Math.Ceiling(baseName.Length / 3.0);
            string newBaseName = baseName.Substring(0, maxFilenameLength - extension.Length - suffixLength);
            return $"{newBaseName}{suffixLength:D}{extension}";
        }
    }

    private string GetFileMetadata(string filePath)
    {
        // Implement logic to extract metadata from the file
        // For example, read a specific line or extract certain properties
        return $"Metadata for {filePath}";
    }
}

public interface IDistributedDatabase
{
    Task StoreMetadataAsync(string filePath, string metadata);
}
