using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class PayloadProcessor
{
    private readonly byte[] _key;
    private readonly int _bufferSize;

    public PayloadProcessor(byte[] key, int bufferSize = 4096)
    {
        _key = key;
        _bufferSize = bufferSize;
    }

    public string ProcessPayload(string payload, bool isEncryptMode)
    {
        try
        {
            byte[] decodedPayload = Convert.FromBase64String(payload);
            if (decodedPayload.Length < 32) // HMAC length
                throw new ArgumentException("Invalid payload format.");

            byte[] hmacBytes = new byte[32];
            Array.Copy(decodedPayload, hmacBytes, 32);

            byte[] messageBytes = new byte[decodedPayload.Length - 32];
            Array.Copy(decodedPayload, 32, messageBytes, 0, messageBytes.Length);

            if (isEncryptMode)
            {
                using (Aes aesAlg = Aes.Create())
                {
                    aesAlg.Key = _key;
                    aesAlg.Mode = CipherMode.CBC;
                    aesAlg.Padding = PaddingMode.PKCS7;

                    ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);
                    using (MemoryStream msEncrypt = new MemoryStream())
                    {
                        using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                        {
                            csEncrypt.Write(messageBytes, 0, messageBytes.Length);
                        }
                        byte[] encryptedMessage = msEncrypt.ToArray();
                        return Convert.ToBase64String(encryptedMessage);
                    }
                }
            }
            else
            {
                using (Aes aesAlg = Aes.Create())
                {
                    aesAlg.Key = _key;
                    aesAlg.Mode = CipherMode.CBC;
                    aesAlg.Padding = PaddingMode.PKCS7;

                    ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);
                    using (MemoryStream msDecrypt = new MemoryStream(messageBytes))
                    {
                        using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                        {
                            using (var buffer = new byte[_bufferSize])
                            {
                                int bytesRead;
                                while ((bytesRead = csDecrypt.Read(buffer, 0, buffer.Length)) > 0)
                                {
                                    // Process decrypted data
                                }
                            }
                        }
                    }

                    using (HMACSHA256 hmac = new HMACSHA256(_key))
                    {
                        byte[] computedHmac = hmac.ComputeHash(messageBytes);
                        if (!computedHmac.SequenceEqual(hmacBytes))
                            throw new InvalidOperationException("HMAC verification failed.");
                    }

                    return Encoding.UTF8.GetString(messageBytes);
                }
            }
        }
        catch (Exception ex)
        {
            // Log the exception and return an error message
            return $"Error processing payload: {ex.Message}";
        }
    }
}
