using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Threading.Tasks;

public class FileHasher
{
    private readonly ILogger _logger;
    private readonly bool _verboseLogging;

    public FileHasher(ILogger logger, bool verboseLogging)
    {
        _logger = logger;
        _verboseLogging = verboseLogging;
    }

    public async Task<Dictionary<string, string>> HashFilesAsync(string directoryPath)
    {
        var fileHashes = new Dictionary<string, string>();
        try
        {
            var files = Directory.GetFiles(directoryPath, "*", SearchOption.AllDirectories);
            await Parallel.ForEachAsync(files, async (file, ct) =>
            {
                try
                {
                    var hash = await ComputeFileHashAsync(file);
                    fileHashes[file] = hash;
                    LogVerbose($"Processed file: {file}");
                }
                catch (Exception ex)
                {
                    LogError($"Failed to process file: {file}", ex);
                }
            });
        }
        catch (Exception ex)
        {
            LogError($"Failed to access directory: {directoryPath}", ex);
        }

        return fileHashes;
    }

    private async Task<string> ComputeFileHashAsync(string filePath)
    {
        using var sha256 = SHA256.Create();
        using var stream = File.OpenRead(filePath);
        var hashBytes = await sha256.ComputeHashAsync(stream);
        return BitConverter.ToString(hashBytes).Replace("-", "").ToLowerInvariant();
    }

    private void LogVerbose(string message)
    {
        if (_verboseLogging)
        {
            _logger.Log(message, LogLevel.Verbose);
        }
    }

    private void LogError(string message, Exception ex)
    {
        _logger.Log($"{message} - Error: {ex.Message}", LogLevel.Error);
    }
}

public interface ILogger
{
    void Log(string message, LogLevel level);
}

public enum LogLevel
{
    Verbose,
    Error
}
