    public DecryptionService(byte[] encryptionKey, byte[] iv)
    {
        _encryptionKey = encryptionKey;
        _iv = iv;
        _hmac = new HMACSHA256(encryptionKey);
        _rateLimiter = new RateLimiter(100, TimeSpan.FromMinutes(1));
        _logger = new Logger();
    }

    public async Task<byte[]> DecryptAsync(byte[] ciphertext, byte[] signature)
    {
        var ip = GetClientIp(); // Implement this method to get the client's IP address
        if (!_rateLimiter.AllowRequest(ip))
        {
            _logger.Log("Rate limit exceeded", ip);
            return null;
        }

        try
        {
            var plaintext = await DecryptCiphertextAsync(ciphertext);
            if (!VerifySignature(plaintext, signature))
            {
                _logger.Log("Invalid signature", ip);
                return null;
            }

            _logger.Log("Decryption successful", ip);
            return plaintext;
        }
        catch (Exception ex)
        {
            _logger.Log($"Decryption failed: {ex.Message}", ip);
