    private readonly ConcurrentDictionary<string, DateTime> _requestTimes;

    public RateLimiter(int maxRequests, TimeSpan timeSpan)
    {
        _maxRequests = maxRequests;
        _timeSpan = timeSpan;
        _requestTimes = new ConcurrentDictionary<string, DateTime>();
    }

    public bool AllowRequest(string ip)
    {
        var now = DateTime.UtcNow;
        _requestTimes.TryRemove(ip, out _);

        if (_requestTimes.Count >= _maxRequests)
            return false;

        _requestTimes[ip] = now;
        return true;
    }
}

