    public T GetItem(string key)
    {
        if (!_cache.TryGetValue(key, out var item))
        {
            lock (_cache)
            {
                if (!_cache.TryGetValue(key, out item))
                {
                    item = LoadItemFromDisk(key);
                    _cache.TryAdd(key, item);
                }
            }
        }
        return item;
    }

    public void UpdateItem(string key, T item)
    {
        _cache[key] = item;
        SaveToDisk();
    }

    private void LoadFromDisk()
    {
        if (File.Exists(_filePath))
        {
            using (var stream = File.OpenRead(_filePath))
            {
                var data = (T)_formatter.Deserialize(stream);
                foreach (var kvp in (ConcurrentDictionary<string, T>)data)
                {
                    _cache.TryAdd(kvp.Key, kvp.Value);
                }
            }
        }
    }

