        try (JsonParser jsonParser = objectMapper.getFactory().createParser(jsonData)) {
            return objectMapper.readValue(jsonParser, configClass);
        } catch (Exception e) {
            throw new ConfigurationException("Failed to deserialize configuration data", e);
