#define MAX_LINE_LENGTH 1024

void resolve_dns(const char *hostname, char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address, INET_ADDRSTRLEN);
    freeaddrinfo(res);
}

double calculate_average(int a, int b) {
    return (a + b) / 2.0;
}

void process_file(const char *filename) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening file");
        return;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), file)) {
        // Process each line here
        // Example: Extract numbers and calculate average
        int num1 = 0, num2 = 0;
        sscanf(line, "%d %d", &num1, &num2);
        double avg = calculate_average(num1, num2);

        // Append average to the end of the line
        char new_line[MAX_LINE_LENGTH];
        snprintf(new_line, sizeof(new_line), "%s %.2f\n", line, avg);

        // Write the modified line back to a file or process it further
        printf("%s", new_line);
    }

    fclose(file);
}

int main() {
    const char *filename = "input.txt";
    process_file(filename);
