const { exec } = require('child_process');
const { promisify } = require('util');
const axios = require('axios');

const executeCommandWithTimeout = async (command, timeout) => {
  const execPromise = promisify(exec);
  try {
    const { stdout, stderr } = await Promise.race([
      execPromise(command),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error('Command execution timed out')), timeout)
      )
    ]);
    return sanitizeOutput(stdout);
  } catch (error) {
    return `Error: ${sanitizeOutput(error.message)}`;
  }
};

const fetchContextFromAPI = async () => {
  try {
    const response = await axios.get('https://api.example.com/context');
    return response.data;
  } catch (error) {
    return null;
  }
};

const sanitizeOutput = (output) => {
  // Implement sanitization logic here
  return output.replace(/[^a-zA-Z0-9\s]/g, '');
};

// Example usage in a web application route handler
app.get('/execute-command', async (req, res) => {
  const command = req.query.command || 'echo Hello World';
  const timeout = parseInt(req.query.timeout) || 5000; // Default timeout of 5 seconds

  try {
    const context = await fetchContextFromAPI();
    if (!context) {
      return res.status(400).send('Failed to fetch context from API');
    }

    const result = await executeCommandWithTimeout(command, timeout);
    res.send(result);
  } catch (error) {
    res.status(500).send(`Internal Server Error: ${error.message}`);
  }
});
```

