use tokio::task;
use log::{info, error};
use std::env;
use serde_json::from_str;

#[derive(Debug)]
enum Task {
    Task1,
    Task2,
}

impl Task {
    fn from_arg(arg: &str) -> Result<Self, String> {
        match arg {
            "task1" => Ok(Task::Task1),
            "task2" => Ok(Task::Task2),
            _ => Err(format!("Invalid task argument: {}", arg)),
        }
    }

    async fn execute(&self) {
        match self {
            Task::Task1 => info!("Executing Task 1"),
            Task::Task2 => info!("Executing Task 2"),
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    env_logger::init();

    let args: Vec<String> = env::args().collect();
    if args.len() < 2 {
        error!("Usage: {} <task>", args[0]);
        return Err("Missing task argument".into());
    }

    match Task::from_arg(&args[1]) {
        Ok(task) => {
            let handle = task.execute();
            tokio::join!(handle);
        }
        Err(e) => error!("{}", e),
    }

    Ok(())
}
