#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_CONCURRENT_QUERIES 10
#define WHITELIST_SIZE 5

const char* whitelist[WHITELIST_SIZE] = {
    "192.168.1.1",
    "10.0.0.1",
    "8.8.8.8",
    "8.8.4.4",
    "172.16.0.1"
};

typedef struct {
    int* array;
    size_t count;
} IntegerList;

typedef struct {
    char hostname[NI_MAXHOST];
    pthread_mutex_t lock;
} QueryTask;

void print_largest_integer(IntegerList list) {
    if (list.count == 0) {
        printf("No integers provided.\n");
        return;
    }
    int largest = list.array[0];
    for (size_t i = 1; i < list.count; ++i) {
        if (list.array[i] > largest) {
            largest = list.array[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

int validate_ip(const char* ip) {
    struct in_addr addr;
    return inet_pton(AF_INET, ip, &addr) == 1;
}

void* resolve_hostname(void* arg) {
    QueryTask* task = (QueryTask*)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(task->hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    pthread_mutex_lock(&task->lock);
    for (p = res; p != NULL; p = p->ai_next) {
        char ipstr[INET_ADDRSTRLEN];
        void* addr;
        if (p->ai_family == AF_INET) {
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
        } else {
            continue; // Unsupported address family
        }
        inet_ntop(p->ai_family, addr, ipstr, sizeof(ipstr));
        if (validate_ip(ipstr)) {
            printf("Resolved IP for %s: %s\n", task->hostname, ipstr);
        } else {
            printf("Invalid IP resolved for %s: %s\n", task->hostname, ipstr);
        }
    }
    freeaddrinfo(res);
    pthread_mutex_unlock(&task->lock);

    return NULL;
}

int process_hostnames(IntegerList list) {
    if (list.count == 0) {
        fprintf(stderr, "No hostnames provided.\n");
        return -1;
    }

    QueryTask tasks[list.count];
    pthread_t threads[list.count];
    int thread_count = 0;

    for (size_t i = 0; i < list.count; ++i) {
        if (thread_count >= MAX_CONCURRENT_QUERIES) {
            // Wait for some threads to finish
            for (int j = 0; j < MAX_CONCURRENT_QUERIES; ++j) {
                pthread_join(threads[j], NULL);
                thread_count--;
            }
        }

        tasks[i].lock = PTHREAD_MUTEX_INITIALIZER;
        snprintf(tasks[i].hostname, NI_MAXHOST, "%d", list.array[i]);
        if (pthread_create(&threads[thread_count++], NULL, resolve_hostname, &tasks[i]) != 0) {
            fprintf(stderr, "Failed to create thread for hostname %s\n", tasks[i].hostname);
            return -1;
        }
    }

    // Wait for all remaining threads
    while (thread_count > 0) {
        pthread_join(threads[--thread_count], NULL);
    }

    return 0;
}

int main() {
    IntegerList list = {NULL, 0};
    int num;

    printf("Enter a list of integers separated by spaces: ");
    while (scanf("%d", &num) == 1) {
        list.array = realloc(list.array, (list.count + 1) * sizeof(int));
        if (!list.array) {
            fprintf(stderr, "Memory allocation failed.\n");
            return -1;
        }
        list.array[list.count++] = num;
    }

    print_largest_integer(list);
    process_hostnames(list);

    free(list.array);
    return 0;
}
