import os
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed
import logging

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

def compute_md5(file_path):
    """Compute the MD5 hash of a file."""
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_files_in_directory(directory):
    """Process files in the specified directory concurrently."""
    file_hashes = {}
    with ThreadPoolExecutor(max_workers=10) as executor:
        futures = {executor.submit(compute_md5, os.path.join(directory, f)): f for f in os.listdir(directory)}
        for future in as_completed(futures):
            try:
                file_path = futures[future]
                md5_hash = future.result()
                file_hashes[file_path] = md5_hash
                logger.info(f"Processed {file_path} with MD5: {md5_hash}")
            except Exception as e:
                logger.error(f"Failed to process {futures[future]}: {e}")
    return file_hashes

def main():
    directory_path = input("Enter the directory path: ")
    try:
        hashes = process_files_in_directory(directory_path)
        print("File MD5 Hashes:", hashes)
    except Exception as e:
        logger.error(f"An error occurred: {e}")

if __name__ == "__main__":
    main()
