    EVP_CIPHER_CTX *cipher_ctx;
    EVP_MD_CTX *digest_ctx;
    RSA *rsa_key;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNFAPCRCIndication(config_t config) {
    NFAPI_CRC_INDICATION_PDU_T *indication_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(config.N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!indication_list) {
        // Handle memory allocation failure
        return;
    }

    for (int i = 0; i < config.N; i++) {
        // Initialize NFAPI structure and cryptographic operations
        indication_list[i].ue_info_tag = generateUEInfoTag();
        indication_list[i].rnti = generateRNTI();
        indication_list[i].crc_indication.CRCFLAG = generateRandomCRCFlag();

        indication_list[i].cipher_ctx = EVP_CIPHER_CTX_new();
        if (!indication_list[i].cipher_ctx) {
            // Handle cipher context creation failure
            continue;
        }

        indication_list[i].digest_ctx = EVP_MD_CTX_new();
        if (!indication_list[i].digest_ctx) {
            // Handle digest context creation failure
            EVP_CIPHER_CTX_free(indication_list[i].cipher_ctx);
            continue;
        }

        indication_list[i].rsa_key = RSA_generate_key(2048, 65537, NULL, NULL);
        if (!indication_list[i].rsa_key) {
            // Handle RSA key generation failure
            EVP_CIPHER_CTX_free(indication_list[i].cipher_ctx);
            EVP_MD_CTX_free(indication_list[i].digest_ctx);
            continue;
        }

        // Add cryptographic operations to library
        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_digest(EVP_sha256());
        EVP_add_digest_alias("sha256", "SHA-256");

        // Perform cryptographic operations
        performCryptoOperations(indication_list[i].cipher_ctx, indication_list[i].digest_ctx, indication_list[i].rsa_key);
    }

    // Free allocated resources
    for (int i = 0; i < config.N; i++) {
        EVP_CIPHER_CTX_free(indication_list[i].cipher_ctx);
        EVP_MD_CTX_free(indication_list[i].digest_ctx);
        RSA_free(indication_list[i].rsa_key);
    }
    free(indication_list);

    // Handle potential performance bottlenecks and resource limitations
