    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyTrafficManager(TrafficManager *manager) {
    free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addOrUpdateFlow(TrafficManager *manager, TrafficFlow flow) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->flows[i].SourceIP, flow.SourceIP) == 0 &&
            strcmp(manager->flows[i].DestinationIP, flow.DestinationIP) == 0) {
            manager->flows[i] = flow;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Updated
        }
    }
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        TrafficFlow *new_flows = realloc(manager->flows, new_capacity * sizeof(TrafficFlow));
        if (!new_flows) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->flows = new_flows;
        manager->capacity = new_capacity;
    }
    manager->flows[manager->count++] = flow;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Added
}

int getTotalPacketCount(TrafficManager *manager) {
    int total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        total += manager->flows[i].PacketCount;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}

TrafficFlow* getMaxFlow(TrafficManager *manager) {
    TrafficFlow *max_flow = NULL;
    int max_packets = -1;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->flows[i].PacketCount > max_packets) {
            max_packets = manager->flows[i].PacketCount;
            max_flow = &manager->flows[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return max_flow;
}

double getAveragePacketCount(TrafficManager *manager) {
    int total = getTotalPacketCount(manager);
    return (total > 0) ? ((double)total / manager->count) : 0.0;
}
