public class MD5Hasher {

    private static final Logger LOGGER = Logger.getLogger(MD5Hasher.class.getName());
    private static final int MAX_CONCURRENT_TASKS = 100;
    private static final double CPU_USAGE_LIMIT = 0.05;
    private static final long LATENCY_THRESHOLD = 60 * 1000; // 60 seconds
    private static final int RETRY_ATTEMPTS = 3;

    private final ExecutorService executorService;
    private final BlockingQueue<String> inputQueue;

    public MD5Hasher() {
        this.inputQueue = new LinkedBlockingQueue<>();
        this.executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_TASKS);
    }

    public void processInput(String input) {
        if (input == null) {
            LOGGER.warning("Skipping null input");
            return;
        }
        try {
            inputQueue.put(input);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            LOGGER.log(Level.SEVERE, "Interrupted while adding to queue", e);
        }
    }

    public void startProcessing() {
        for (int i = 0; i < MAX_CONCURRENT_TASKS; i++) {
            executorService.submit(this::processTask);
        }
    }

    private void processTask() {
        try {
            String input = inputQueue.take();
            long startTime = System.currentTimeMillis();
            String hash = computeMD5(input);
            long endTime = System.currentTimeMillis();

            double cpuUsage = calculateCPUUsage(startTime, endTime);
            if (cpuUsage > CPU_USAGE_LIMIT) {
                LOGGER.warning("High CPU usage detected: " + cpuUsage);
            }

            LOGGER.info("Input: " + input + ", Length: " + input.length() + ", Hash: " + hash +
                         ", Latency: " + (endTime - startTime) + "ms");
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            LOGGER.log(Level.SEVERE, "Interrupted while processing task", e);
        }
    }

    private String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] hashBytes = md.digest(input.getBytes());
        StringBuilder sb = new StringBuilder();
        for (byte b : hashBytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private double calculateCPUUsage(long startTime, long endTime) {
        // Placeholder for actual CPU usage calculation logic
        return 0.0;
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
            Thread.currentThread().interrupt();
        }
    }

    // Configuration option to adjust the maximum number of concurrent tasks
    public void setMaxConcurrentTasks(int maxConcurrentTasks) {
        MAX_CONCURRENT_TASKS = maxConcurrentTasks;
        executorService.shutdown();
        executorService = Executors.newFixedThreadPool(MAX_CONCURRENT_TASKS);
    }
}
