```csharp
using System;
using UnityEngine;

public class RangeConfig<T>
{
    public T? Min { get; set; }
    public T? Max { get; set; }

    public RangeConfig(T? min = null, T? max = null)
    {
        Min = min;
        Max = max;
    }
}

public static class ValueGenerator
{
    private static readonly Dictionary<string, RangeConfig<int>> intRanges = new();
    private static readonly Dictionary<string, RangeConfig<float>> floatRanges = new();

    public static void SetDefaultIntRange(string key, RangeConfig<int> config)
    {
        intRanges[key] = config;
    }

    public static void SetDefaultFloatRange(string key, RangeConfig<float> config)
    {
        floatRanges[key] = config;
    }

    public static int GetRandomInt(string key)
    {
        if (intRanges.TryGetValue(key, out var config))
        {
            return GenerateRandomInt(config);
        }
        throw new InvalidOperationException("No default range set for the specified key.");
    }

    public static float GetRandomFloat(string key)
    {
        if (floatRanges.TryGetValue(key, out var config))
        {
            return GenerateRandomFloat(config);
        }
        throw new InvalidOperationException("No default range set for the specified key.");
    }

    private static int GenerateRandomInt(RangeConfig<int> config)
    {
        int min = config.Min.HasValue ? config.Min.Value : int.MinValue;
        int max = config.Max.HasValue ? config.Max.Value : int.MaxValue;
        return UnityEngine.Random.Range(min, max + 1);
    }

    private static float GenerateRandomFloat(RangeConfig<float> config)
    {
        float min = config.Min.HasValue ? config.Min.Value : float.MinValue;
        float max = config.Max.HasValue ? config.Max.Value : float.MaxValue;
        return UnityEngine.Random.Range(min, max);
    }
}
