use reqwest::{Client, Error, RequestBuilder};
use std::time::Duration;

pub struct HttpClientFactory {
    client: Client,
}

impl HttpClientFactory {
    pub fn new() -> Self {
        HttpClientFactory {
            client: Client::new(),
        }
    }

    pub fn disable_certificate_validation(&mut self) -> &mut Self {
        let mut builder = reqwest::ClientBuilder::new();
        builder.dangerously_disable_hostname_verification();
        self.client = builder.build().unwrap();
        self
    }

    pub fn custom_header(&mut self, key: &str, value: &str) -> &mut Self {
        self.client = self.client.default_headers(reqwest::header::HeaderMap::from_iter(vec![(key.parse().unwrap(), value.parse().unwrap())]));
        self
    }

    pub async fn create_client(&self) -> Result<Client, Error> {
        Ok(self.client.clone())
    }
}

#[tokio::main]
async fn main() {
    let mut factory = HttpClientFactory::new();
    factory.disable_certificate_validation();
    factory.custom_header("User-Agent", "MyApp/1.0");

    match factory.create_client().await {
        Ok(client) => println!("Client created successfully."),
        Err(e) => eprintln!("Failed to create client: {}", e),
    }
}
```

