#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} TrafficFlow;

int compareTrafficFlows(const void *a, const void *b) {
    TrafficFlow *flowA = (TrafficFlow *)a;
    TrafficFlow *flowB = (TrafficFlow *)b;
    return strcmp(flowA->SourceIP, flowB->SourceIP);
}

void findDisjointPairs(TrafficFlow *flows, int count, int *pairCount, long long *timeTaken) {
    clock_t start = clock();

    qsort(flows, count, sizeof(TrafficFlow), compareTrafficFlows);

    *pairCount = 0;
    for (int i = 0; i < count - 1; i++) {
        if (strcmp(flows[i].SourceIP, flows[i + 1].SourceIP) != 0) {
            (*pairCount)++;
        }
    }

    clock_t end = clock();
    *timeTaken = (end - start) * 1000 / CLOCKS_PER_SEC;
}

int main() {
    TrafficFlow trafficData[] = {
        {"192.168.1.1", "10.0.0.1", 100},
        {"192.168.1.2", "10.0.0.2", 50},
        {"192.168.1.1", "10.0.0.3", 75},
        {"192.168.1.3", "10.0.0.4", 25}
    };
    int count = sizeof(trafficData) / sizeof(trafficData[0]);
    int pairCount;
    long long timeTaken;

    findDisjointPairs(trafficData, count, &pairCount, &timeTaken);

    printf("Number of disjoint pairs: %d\n", pairCount);
    printf("Time taken to check for pairs: %lld ms\n", timeTaken);

    return 0;
}
