// Function to execute a command in the background
int executeBackgroundCommand(const char *command[], int numArgs) {
    pid_t pid = fork();
    if (pid == -1) {
        perror("Error forking");
        return 0;
    } else if (pid == 0) {
        // Child process
        execvp(command[0], (char *const *)command);
        perror("Error executing command");
        exit(EXIT_FAILURE);
    } else {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        return WIFEXITED(status) && WEXITSTATUS(status) == 0 ? 1 : 0;
    }
}

int main() {
    const char *filename = "input.txt";
    processTextFile(filename);

    const char *command[] = {"ls", "-l", NULL};
    int result = executeBackgroundCommand(command, 2);
    printf("Command executed successfully: %d\n", result);

    return 0;
}
