void modifyFileName(const std::string& originalFilename) {
    try {
        // Extract file extension and name without extension
        size_t dotPos = originalFilename.find_last_of('.');
        std::string baseName = (dotPos != std::string::npos) ? originalFilename.substr(0, dotPos) : originalFilename;
        std::string extension = (dotPos != std::string::npos) ? originalFilename.substr(dotPos) : "";

        // Simulate metadata retrieval
        std::string metadata = MetadataRetriever::RetrieveMetadata(baseName);

        // Extract relevant information from metadata for filename modification
        size_t vmUuidStart = metadata.find("vm-uuid-");
        if (vmUuidStart != std::string::npos) {
            std::string vmUuid = metadata.substr(vmUuidStart + 8);
            size_t ipStart = vmUuid.find('-');
            if (ipStart != std::string::npos) {
                std::string ip = vmUuid.substr(0, ipStart);

                // Simulate network request using Sandesh client
                sandesh::SandeshClient client;
                std::string response = client.sendGetRequest("http://metadata-service/" + ip);
                if (!response.empty()) {
                    // Modify filename based on metadata and IP
                    std::string newFilename = baseName + "_" + vmUuid.substr(ipStart + 1) + "_meta" + extension;
                    std::cout << "Original: " << originalFilename << ", Modified: " << newFilename << std::endl;
                } else {
                    std::cerr << "Network error retrieving metadata for IP: " << ip << std::endl;
                }
            }
        }
    } catch (const std::exception& e) {
