#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define KEY_SIZE 32
#define SALT_SIZE 16
#define IV_SIZE 16

int initialize_aes_cbc(const char *passphrase, size_t passphrase_len, unsigned char **key, unsigned char **iv) {
    unsigned char salt[SALT_SIZE];
    if (!RAND_bytes(salt, sizeof(salt))) {
        return -1; // Failed to generate random salt
    }

    if (PKCS5_PBKDF2_HMAC(passphrase, passphrase_len, salt, SALT_SIZE, 100000, EVP_sha256(), KEY_SIZE, *key) != 1) {
        return -1; // PBKDF2 failed
    }

    if (!RAND_bytes(*iv, IV_SIZE)) {
        return -1; // Failed to generate random IV
    }

    return 0;
}

int encrypt_file(const char *input_file, const char *output_file, const unsigned char *key, const unsigned char *iv) {
    FILE *in = fopen(input_file, "rb");
    if (!in) {
        perror("Failed to open input file");
        return -1;
    }

    FILE *out = fopen(output_file, "wb");
    if (!out) {
        fclose(in);
        perror("Failed to open output file");
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        fclose(in);
        fclose(out);
        perror("Failed to create cipher context");
        return -1;
    }

    if (EVP_EncryptInit_ex(ctx, EVP_aes_256_cbc(), NULL, key, iv) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(in);
        fclose(out);
        perror("Encryption initialization failed");
        return -1;
    }

    unsigned char buffer[4096];
    int len, written;

    while ((len = fread(buffer, 1, sizeof(buffer), in)) > 0) {
        if (EVP_EncryptUpdate(ctx, buffer, &written, buffer, len) != 1) {
            EVP_CIPHER_CTX_free(ctx);
            fclose(in);
            fclose(out);
            perror("Encryption update failed");
            return -1;
        }
        fwrite(buffer, 1, written, out);
    }

    if (EVP_EncryptFinal_ex(ctx, buffer, &written) != 1) {
        EVP_CIPHER_CTX_free(ctx);
        fclose(in);
        fclose(out);
        perror("Encryption finalization failed");
        return -1;
    }
    fwrite(buffer, 1, written, out);

    EVP_CIPHER_CTX_free(ctx);
    fclose(in);
    fclose(out);

    return 0;
}

int main() {
    unsigned char *key = malloc(KEY_SIZE);
    unsigned char *iv = malloc(IV_SIZE);

    if (initialize_aes_cbc("user_passphrase", strlen("user_passphrase"), &key, &iv) != 0) {
        fprintf(stderr, "Failed to initialize AES-CBC\n");
        free(key);
        free(iv);
        return -1;
    }

    if (encrypt_file("input_data.bin", "encrypted_data.bin", key, iv) != 0) {
        fprintf(stderr, "Failed to encrypt file\n");
        free(key);
        free(iv);
        return -1;
    }

    free(key);
    free(iv);

    return 0;
}
