import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class DistributedGraphDatabase {
    private ConcurrentHashMap<String, Vertex> vertices;
    private ConcurrentHashMap<String, Edge> edges;
    private Lock lock;

    public DistributedGraphDatabase() {
        this.vertices = new ConcurrentHashMap<>();
        this.edges = new ConcurrentHashMap<>();
        this.lock = new ReentrantLock();
    }

    public void addVertex(String vertexId) {
        lock.lock();
        try {
            if (!vertices.containsKey(vertexId)) {
                vertices.put(vertexId, new Vertex(vertexId));
            }
        } finally {
            lock.unlock();
        }
    }

    public void addEdge(String edgeId, String fromVertexId, String toVertexId) {
        lock.lock();
        try {
            if (!edges.containsKey(edgeId)) {
                edges.put(edgeId, new Edge(edgeId, vertices.get(fromVertexId), vertices.get(toVertexId)));
                vertices.get(fromVertexId).addOutgoingEdge(edges.get(edgeId));
                vertices.get(toVertexId).addIncomingEdge(edges.get(edgeId));
            }
        } finally {
            lock.unlock();
        }
    }

    public void batchUpdate(Iterable<Vertex> newVertices, Iterable<Edge> newEdges) {
        lock.lock();
        try {
            for (Vertex vertex : newVertices) {
                vertices.put(vertex.getId(), vertex);
            }
            for (Edge edge : newEdges) {
                edges.put(edge.getId(), edge);
                edge.getFrom().addOutgoingEdge(edge);
                edge.getTo().addIncomingEdge(edge);
            }
        } finally {
            lock.unlock();
        }
    }

    public void handleFailedUpdate(Exception e) {
        // Log the error
        System.err.println("Failed to update graph: " + e.getMessage());
        // Optionally, retry the operation or notify an administrator
    }

    private static class Vertex {
        private String id;
        private ConcurrentHashMap<String, Edge> outgoingEdges;

        public Vertex(String id) {
            this.id = id;
            this.outgoingEdges = new ConcurrentHashMap<>();
        }

        public String getId() {
            return id;
        }

        public void addOutgoingEdge(Edge edge) {
            outgoingEdges.put(edge.getId(), edge);
        }
    }

    private static class Edge {
        private String id;
        private Vertex from;
        private Vertex to;

        public Edge(String id, Vertex from, Vertex to) {
            this.id = id;
            this.from = from;
            this.to = to;
        }

        public String getId() {
            return id;
        }

        public Vertex getFrom() {
            return from;
        }

        public Vertex getTo() {
            return to;
        }
    }
}
