        return;
    }
    newNode->data = pdu;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = newNode;
    } else {
        Node* current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
    pthread_mutex_unlock(&list->mutex);
}

