#define MAX_MEMORY_BUDGET 1024 * 1024 // 1 MB

typedef struct {
    int value;
} record;

unsigned long hash_function(unsigned long index) {
    return index * index + 3 * index + 7; // Example hash function
}

int calculate_key(int index, int constant) {
    return (index * constant) % 1000; // Example key calculation
}

record calculate_record_value(int index, int constant, int key) {
    record r;
    r.value = (index * constant + key) % 10000; // Example record value calculation
    return r;
}

void manage_memory(int num_elements, int constant) {
    if (num_elements * sizeof(long) > MAX_MEMORY_BUDGET ||
        num_elements * sizeof(int) > MAX_MEMORY_BUDGET ||
        num_elements * sizeof(record) > MAX_MEMORY_BUDGET) {
        fprintf(stderr, "Memory allocation exceeds budget\n");
        exit(EXIT_FAILURE);
    }

    long* offsets = (long*)malloc(num_elements * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_elements; i++) {
        offsets[i] = hash_function(i);
    }

    int* keys = (int*)malloc(num_elements * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_elements; i++) {
        keys[i] = calculate_key(i, constant);
    }

    record* records = (record*)malloc(num_elements * sizeof(record));
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < num_elements; i++) {
        records[i] = calculate_record_value(i, constant, keys[i]);
    }

    for (int i = 0; i < num_elements; i++) {
        printf("Index: %d, Key: %d, Value: %d\n", i, keys[i], records[i].value);
    }

    free(offsets);
    free(keys);
    free(records);
}

int main() {
    int num_elements = 1000;
    int constant = 5; // Example constant
    manage_memory(num_elements, constant);
    return 0;
}
