    if (semaphore == SEM_FAILED) {
        perror("Semaphore creation failed");
        exit(EXIT_FAILURE);
    }
    return semaphore;
}

void initialize_data_structures(int num_records) {
    long* offsets = allocate_memory(num_records * sizeof(long));
    int* keys = allocate_memory(num_records * sizeof(int));
    record* records = allocate_memory(num_records * sizeof(record));

    sem_t* semaphore = create_semaphore(num_records);

    srand(time(NULL));

    for (int i = 0; i < num_records; i++) {
        offsets[i] = (long)i * SYSTEM_CONSTANT + rand() % 100;
        keys[i] = (i * SYSTEM_CONSTANT + RANDOM_SEED) % 1000;

        records[i].value = (i * SYSTEM_CONSTANT + keys[i]) * 3 + 7;
    }

    for (int i = 0; i < num_records; i++) {
        printf("Record %d: Value=%d, Offset=%ld, Key=%d\n", i, records[i].value, offsets[i], keys[i]);
    }

    sem_close(semaphore);
    free(offsets);
    free(keys);
    free(records);
}

