#define MAX_IP_LENGTH 16
#define INITIAL_CAPACITY 1024
#define GROWTH_FACTOR 2

typedef struct {
    char SourceIP[MAX_IP_LENGTH];
    char DestinationIP[MAX_IP_LENGTH];
    int PacketCount;
} NetworkTraffic;

typedef struct {
    NetworkTraffic *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

void initTrafficManager(TrafficManager *manager) {
    manager->data = (NetworkTraffic *)malloc(INITIAL_CAPACITY * sizeof(NetworkTraffic));
    if (!manager->data) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->capacity = INITIAL_CAPACITY;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
}

void freeTrafficManager(TrafficManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->data);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

int addOrUpdateTraffic(TrafficManager *manager, const char *sourceIP, const char *destinationIP, int packetCount) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->data[i].SourceIP, sourceIP) == 0 && strcmp(manager->data[i].DestinationIP, destinationIP) == 0) {
            manager->data[i].PacketCount += packetCount;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Updated
        }
    }
    if (manager->size >= manager->capacity) {
        size_t newCapacity = manager->capacity * GROWTH_FACTOR;
        NetworkTraffic *newData = (NetworkTraffic *)realloc(manager->data, newCapacity * sizeof(NetworkTraffic));
        if (!newData) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory error
        }
        manager->data = newData;
        manager->capacity = newCapacity;
    }
    strcpy(manager->data[manager->size].SourceIP, sourceIP);
    strcpy(manager->data[manager->size].DestinationIP, destinationIP);
    manager->data[manager->size].PacketCount = packetCount;
    ++manager->size;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Added
}

// Additional functions for retrieving statistics, filtering, and identifying unusual traffic patterns would be implemented here.
