        return NULL;
    }

    for (int i = 0; i < N; i++) {
        // Initialize each structure with default values or user input
        channels[i].channel_type = LTE_PHYSICAL_CHANNEL_TYPE_FDD;
        channels[i].center_frequency = 0;
        channels[i].bw = 10;
        channels[i].rb_alloc = 25;
    }

    return channels;
}

void update_rb_alloc(LTE_PHY_CHANNEL_INFO_T* channels, int N, int center_frequency, int new_rb_alloc) {
    if (!channels || N <= 0) {
        fprintf(stderr, "Invalid input for updating RB_ALLOC\n");
        return;
    }

    for (int i = 0; i < N; i++) {
        if (channels[i].center_frequency == center_frequency) {
            channels[i].rb_alloc = new_rb_alloc;
            break;
        }
    }
