typedef struct {
    char* buffer;
    int index;
} Data;

void manage_memory(long offset_size, int key_size, int data_size, long max_string_length) {
    if (offset_size <= 0 || key_size <= 0 || data_size <= 0 || max_string_length <= 0) {
        fprintf(stderr, "Invalid size parameters\n");
        return;
    }

    long* offsets = malloc(offset_size * sizeof(long));
    int* keys = malloc(key_size * sizeof(int));
    Data* datas = malloc(data_size * sizeof(Data));

    if (!offsets || !keys || !datas) {
        fprintf(stderr, "Memory allocation failed\n");
        free(offsets);
        free(keys);
        free(datas);
        return;
    }

    srand(time(NULL));

    for (long i = 0; i < offset_size; ++i) {
        offsets[i] = rand() % max_string_length;
    }

    for (int i = 0; i < key_size; ++i) {
        keys[i] = rand();
    }

    for (int i = 0; i < data_size; ++i) {
        datas[i].buffer = malloc((max_string_length + 1) * sizeof(char));
        if (!datas[i].buffer) {
            fprintf(stderr, "Memory allocation failed for data buffer\n");
            for (int j = 0; j < i; ++j) {
                free(datas[j].buffer);
            }
            free(offsets);
            free(keys);
            free(datas);
            return;
        }

        int string_length = rand() % max_string_length + 1;
        datas[i].index = rand();
        for (int j = 0; j < string_length; ++j) {
            datas[i].buffer[j] = 'a' + rand() % 26;
        }
        datas[i].buffer[string_length] = '\0';
    }

    // Use the allocated memory here

    for (long i = 0; i < offset_size; ++i) {
        free(offsets[i]);
    }
    free(offsets);
    free(keys);

    for (int i = 0; i < data_size; ++i) {
        free(datas[i].buffer);
    }
    free(datas);
}
