#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>

#define MAX_LINE_LENGTH 1024
#define MAX_FIELDS 10

typedef struct {
    u_char ip[4];
} IPAddress;

int resolveDNS(const char *hostname, IPAddress *ip) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip->ip, &(ipv4->sin_addr), sizeof(ipv4->sin_addr));

    freeaddrinfo(res);
    return 0;
}

int processLogEntry(const char *line, char **output) {
    char *fields[MAX_FIELDS];
    int fieldCount = 0;
    char *token = strtok((char *)line, " ");
    while (token != NULL && fieldCount < MAX_FIELDS) {
        fields[fieldCount++] = token;
        token = strtok(NULL, " ");
    }

    if (fieldCount < 2) {
        return -1; // Not enough fields
    }

    int sum = 0;
    int count = 0;
    for (int i = fieldCount - 1; i >= 0 && count < 2; i--) {
        char *endptr;
        long num = strtol(fields[i], &endptr, 10);
        if (*endptr == '\0') {
            sum += num;
            count++;
        }
    }

    if (count != 2) {
        return -1; // Not enough valid numerical fields
    }

    double average = (double)sum / count;

    *output = malloc(strlen(line) + 32); // Enough space for original line and new field
    if (*output == NULL) {
        return -1; // Memory allocation failed
    }

    snprintf(*output, strlen(line) + 32, "%s,%.2f", line, average);

    return 0;
}

int main() {
    FILE *inputFile = fopen("input.log", "r");
    if (inputFile == NULL) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    FILE *outputFile = fopen("output.log", "w");
    if (outputFile == NULL) {
        perror("Failed to open output file");
        fclose(inputFile);
        return EXIT_FAILURE;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, sizeof(line), inputFile)) {
        char *outputLine;
        int result = processLogEntry(line, &outputLine);
        if (result == 0) {
            fputs(outputLine, outputFile);
            free(outputLine);
        } else {
            fprintf(stderr, "Error processing log entry: %s", line);
        }
    }

    fclose(inputFile);
    fclose(outputFile);

    return EXIT_SUCCESS;
}
