import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileHashProcessor {

    private static final Map<String, String> md5Cache = new HashMap<>();
    private static final Map<String, String> sha256Cache = new HashMap<>();

    public static void processFiles(String... filePaths) {
        for (String path : filePaths) {
            try {
                if (!new File(path).exists()) {
                    System.out.println("File does not exist: " + path);
                    continue;
                }

                String md5Hash = getMD5Hash(path);
                String sha256Hash = getSHA256Hash(path);

                // Process the hashes as needed (e.g., store in graph database)
                processGraph(md5Hash, sha256Hash);
            } catch (IOException | NoSuchAlgorithmException e) {
                System.err.println("Error processing file: " + path);
                e.printStackTrace();
            }
        }
    }

    private static String getMD5Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        if (md5Cache.containsKey(filePath)) {
            return md5Cache.get(filePath);
        }

        MessageDigest digest = MessageDigest.getInstance("MD5");
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }

        String hash = bytesToHex(digest.digest());
        md5Cache.put(filePath, hash);
        return hash;
    }

    private static String getSHA256Hash(String filePath) throws IOException, NoSuchAlgorithmException {
        if (sha256Cache.containsKey(filePath)) {
            return sha256Cache.get(filePath);
        }

        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        try (InputStream is = new FileInputStream(filePath)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = is.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        }

        String hash = bytesToHex(digest.digest());
        sha256Cache.put(filePath, hash);
        return hash;
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }

    private static void processGraph(String md5Hash, String sha256Hash) {
        // Implement logic to add vertices and edges to the graph database
