import java.util.concurrent.*;
import java.time.Instant;
import java.util.function.Function;

public class RecordProcessor {

    private final ExecutorService executorService;
    private final BlockingQueue<Record> inputQueue;
    private final ConcurrentMap<String, TransformationLog> logMap;
    private final RetryPolicy retryPolicy;

    public RecordProcessor(int concurrencyLimit, int queueCapacity) {
        this.executorService = Executors.newFixedThreadPool(concurrencyLimit);
        this.inputQueue = new LinkedBlockingQueue<>(queueCapacity);
        this.logMap = new ConcurrentHashMap<>();
        this.retryPolicy = new RetryPolicy(5, 100); // 5 retries with exponential backoff
    }

    public void processAndTransformRecords(Stream<Record> records) {
        records.forEach(record -> inputQueue.offer(record));
    }

    private void transformRecord(Record record) {
        try {
            int result = retryPolicy.execute(() -> performTransformation(record));
            logTransformation(record, result);
        } catch (Exception e) {
            handleFailure(record, e);
        }
    }

    private int performTransformation(Record record) throws Exception {
        // Perform transformation logic here
        return record.getValue() * 2; // Example transformation
    }

    private void logTransformation(Record record, int result) {
        TransformationLog log = new TransformationLog(
            Instant.now(),
            record.getLength(),
            System.currentTimeMillis() - record.getTimestamp(),
            result
        );
        logMap.put(record.getId(), log);
    }

    private void handleFailure(Record record, Exception e) {
        if (retryPolicy.canRetry()) {
            retryPolicy.retry(() -> transformRecord(record));
        } else {
            // Log failure and possibly fallback to a different service
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    private static class Record {
        private final int value;
        private final long timestamp;
        private final String id;
        private final int length;

        public Record(int value, long timestamp, String id, int length) {
            this.value = value;
            this.timestamp = timestamp;
            this.id = id;
            this.length = length;
        }

        public int getValue() {
            return value;
        }

        public long getTimestamp() {
            return timestamp;
        }

        public String getId() {
            return id;
        }

        public int getLength() {
            return length;
        }
    }

    private static class TransformationLog {
        private final Instant startTime;
        private final int inputLength;
        private final long duration;
        private final int result;

        public TransformationLog(Instant startTime, int inputLength, long duration, int result) {
            this.startTime = startTime;
            this.inputLength = inputLength;
            this.duration = duration;
            this.result = result;
        }

        // Getters and other methods
    }

