public class JavaExecutor
{
    public static void ExecuteCommand(string command, string[] envp = null, string workingDirectory = null)
    {
        using (var processInfo = new ProcessStartInfo
        {
            FileName = "cmd.exe",
            Arguments = $"/c {command}",
            RedirectStandardOutput = true,
            RedirectStandardError = true,
            UseShellExecute = false,
            CreateNoWindow = true,
            EnvironmentVariables = envp ?? new Dictionary<string, string>(),
            WorkingDirectory = workingDirectory
        })
        {
            using (var process = Process.Start(processInfo))
            {
                try
                {
                    process.WaitForExit();
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Error executing command: {ex.Message}");
                }
                finally
                {
                    DeleteTemporaryFile(workingDirectory);
                }
            }
        }
    }

    private static void DeleteTemporaryFile(string workingDirectory)
    {
        if (!string.IsNullOrEmpty(workingDirectory))
        {
            try
            {
                var tempFilePath = Path.Combine(workingDirectory, "tempfile.tmp");
                File.Delete(tempFilePath);
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error deleting temporary file: {ex.Message}");
            }
        }
    }
}
