#define CERT_DIR "/path/to/certs"
#define CONFIG_FILE "/path/to/config.json"

typedef struct {
    SSL_CTX *ctx;
    char *host;
    int port;
} TLSContext;

TLSContext* initialize_tls_context() {
    TLSContext *tls_ctx = (TLSContext*)malloc(sizeof(TLSContext));
    if (!tls_ctx) {
        perror("Failed to allocate memory for TLS context");
        return NULL;
    }

    // Initialize SSL library
    SSL_library_init();
    OpenSSL_add_all_algorithms();
    SSL_load_error_strings();

    // Create a new SSL context using TLS 1.3
    tls_ctx->ctx = SSL_CTX_new(TLS_client_method());
    if (!tls_ctx->ctx) {
        fprintf(stderr, "Failed to create SSL context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(tls_ctx);
        return NULL;
    }

    // Load client certificates and private keys
    if (SSL_CTX_use_certificate_file(tls_ctx->ctx, CERT_DIR "/client.crt", SSL_FILETYPE_PEM) <= 0 ||
        SSL_CTX_use_PrivateKey_file(tls_ctx->ctx, CERT_DIR "/client.key", SSL_FILETYPE_PEM) <= 0) {
        fprintf(stderr, "Failed to load client certificates and private keys\n");
        SSL_CTX_free(tls_ctx->ctx);
        free(tls_ctx);
        return NULL;
    }

    // Validate and configure session resumption
    if (!validate_session_resumption_config(CONFIG_FILE)) {
        recreate_session_resumption_config(CONFIG_FILE);
    }

    // Parse JSON configuration file
    if (!parse_json_config(CONFIG_FILE, &tls_ctx->host, &tls_ctx->port)) {
        fprintf(stderr, "Failed to parse JSON configuration file\n");
        SSL_CTX_free(tls_ctx->ctx);
        free(tls_ctx);
        return NULL;
    }

    // Enable TLS context
    tls_ctx->ctx = SSL_CTX_new(TLS_client_method());
    if (!tls_ctx->ctx) {
        fprintf(stderr, "Failed to create SSL context: %s\n", ERR_error_string(ERR_get_error(), NULL));
        free(tls_ctx);
        return NULL;
    }

    return tls_ctx;
}

void cleanup_tls_context(TLSContext *tls_ctx) {
    if (tls_ctx) {
        SSL_CTX_free(tls_ctx->ctx);
        free(tls_ctx);
    }
}
