        indication_list[i].rx_ue_information_tag = generateRandomRXUEInformationTag();
        indication_list[i].rnti = generateRandomRNTI();
        indication_list[i].crc_indication_rel8_tag.crcflag = generateRandomCRCFlag();

        // Initialize cryptographic operations
        EVP_CIPHER_CTX *aes_ctx = EVP_CIPHER_CTX_new();
        EVP_DigestInit_ex(EVP_sha256(), NULL, NULL);
        RSA *rsa_key = RSA_generate_key(2048, 3, NULL, NULL);

        // Perform cryptographic operations
        AES_cbc_encrypt(indication_list[i].data, indication_list[i].encrypted_data, sizeof(indication_list[i].data), aes_ctx->cipher, aes_ctx->iv, EVP_ENCRYPT);
        RSA_sign(NID_sha1, (unsigned char *)indication_list[i].data, strlen(indication_list[i].data), indication_list[i].signature, &sig_len, rsa_key);

        // Clean up
