#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int TransactionID;
    int UserID;
    double Amount;
    char Timestamp[20];
} Transaction;

typedef struct {
    Transaction* transactions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TransactionLog;

void initTransactionLog(TransactionLog* log, size_t initialCapacity) {
    log->transactions = (Transaction*)malloc(initialCapacity * sizeof(Transaction));
    if (!log->transactions) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    log->count = 0;
    log->capacity = initialCapacity;
    pthread_mutex_init(&log->lock, NULL);
}

void addTransaction(TransactionLog* log, Transaction transaction) {
    pthread_mutex_lock(&log->lock);
    if (log->count == log->capacity) {
        size_t newCapacity = log->capacity * 2;
        Transaction* newTransactions = (Transaction*)realloc(log->transactions, newCapacity * sizeof(Transaction));
        if (!newTransactions) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        log->transactions = newTransactions;
        log->capacity = newCapacity;
    }
    log->transactions[log->count++] = transaction;
    pthread_mutex_unlock(&log->lock);
}

void updateTransaction(TransactionLog* log, int userID, Transaction updatedTransaction) {
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count; ++i) {
        if (log->transactions[i].UserID == userID) {
            log->transactions[i] = updatedTransaction;
            break;
        }
    }
    pthread_mutex_unlock(&log->lock);
}

double getTotalTransactionAmount(TransactionLog* log, int userID) {
    double total = 0.0;
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count; ++i) {
        if (log->transactions[i].UserID == userID) {
            total += log->transactions[i].Amount;
        }
    }
    pthread_mutex_unlock(&log->lock);
    return total;
}

double getAverageTransactionAmount(TransactionLog* log, int userID) {
    double total = getTotalTransactionAmount(log, userID);
    pthread_mutex_lock(&log->lock);
    size_t count = 0;
    for (size_t i = 0; i < log->count; ++i) {
        if (log->transactions[i].UserID == userID) {
            ++count;
        }
    }
    pthread_mutex_unlock(&log->lock);
    return count > 0 ? total / count : 0.0;
}

double getMaxTransactionAmount(TransactionLog* log, int userID) {
    double max = 0.0;
    pthread_mutex_lock(&log->lock);
    for (size_t i = 0; i < log->count; ++i) {
        if (log->transactions[i].UserID == userID && log->transactions[i].Amount > max) {
            max = log->transactions[i].Amount;
        }
    }
    pthread_mutex_unlock(&log->lock);
    return max;
}

void freeTransactionLog(TransactionLog* log) {
    pthread_mutex_lock(&log->lock);
    free(log->transactions);
    pthread_mutex_destroy(&log->lock);
}
