#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY_BUDGET 1024 * 1024 // 1 MB

typedef struct {
    int value;
} Record;

long hash_function(long index, long seed) {
    return (index * seed + 17) % MAX_MEMORY_BUDGET;
}

int key_generator(int index, int constant, int secondary_index) {
    return (index * constant + secondary_index * 31) % MAX_MEMORY_BUDGET;
}

Record record_generator(int index, int constant, int key, int random_factor) {
    Record rec;
    rec.value = (index * constant + key * 7 + random_factor * 5) % MAX_MEMORY_BUDGET;
    return rec;
}

void manage_memory() {
    long seed_values[] = {13, 29, 41, 53};
    int constants[] = {7, 11, 13, 17};
    int secondary_indices[] = {0, 1, 2, 3};

    for (int i = 0; i < sizeof(seed_values) / sizeof(seed_values[0]); i++) {
        long *offsets = malloc(MAX_MEMORY_BUDGET * sizeof(long));
        if (!offsets) {
            printf("Failed to allocate memory for offsets\n");
            continue;
        }

        int *keys = malloc(MAX_MEMORY_BUDGET * sizeof(int));
        if (!keys) {
            printf("Failed to allocate memory for keys\n");
            free(offsets);
            continue;
        }

        Record *records = malloc(MAX_MEMORY_BUDGET * sizeof(Record));
        if (!records) {
            printf("Failed to allocate memory for records\n");
            free(offsets);
            free(keys);
            continue;
        }

        for (int j = 0; j < MAX_MEMORY_BUDGET; j++) {
            offsets[j] = hash_function(j, seed_values[i]);
            keys[j] = key_generator(j, constants[i], secondary_indices[j % sizeof(secondary_indices) / sizeof(secondary_indices[0])]);
            records[j] = record_generator(j, constants[i], keys[j], rand());
        }

        for (int j = 0; j < MAX_MEMORY_BUDGET; j++) {
            printf("Index: %d, Key: %d, Record Value: %d\n", j, keys[j], records[j].value);
        }

        free(offsets);
        free(keys);
        free(records);
    }
}

int main() {
    srand(time(NULL));
    manage_memory();
    return 0;
}
