#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char buffer[256];
    int index;
} Data;

typedef struct {
    int reference_count;
} Metadata;

void* allocate_memory(size_t offset_size, size_t key_size, size_t data_size, size_t metadata_size) {
    void* memory = malloc(offset_size + key_size + data_size * sizeof(Data) + metadata_size * sizeof(Metadata));
    if (memory == NULL) {
        return NULL;
    }

    long* offsets = (long*)memory;
    int* keys = (int*)(offsets + offset_size / sizeof(long));
    Data* datas = (Data*)(keys + key_size / sizeof(int));
    Metadata* metadatas = (Metadata*)((char*)datas + data_size * sizeof(Data));

    for (size_t i = 0; i < metadata_size; ++i) {
        metadatas[i].reference_count = 1;
    }

    return memory;
}

void free_memory(void* memory, size_t offset_size, size_t key_size, size_t data_size, size_t metadata_size) {
    free(memory);
}

void initialize_data(Data* datas, size_t data_size, int min_length, int max_length) {
    for (size_t i = 0; i < data_size; ++i) {
        int length = rand() % (max_length - min_length + 1) + min_length;
        datas[i].index = i;
        for (int j = 0; j < length; ++j) {
            datas[i].buffer[j] = 'a' + rand() % 26;
        }
        datas[i].buffer[length] = '\0';
    }
}

void merge_metadata(Metadata* metadatas, size_t metadata_size, int new_reference_count) {
    for (size_t i = 0; i < metadata_size; ++i) {
        pthread_mutex_lock(&metadatas[i].mutex);
        metadatas[i].reference_count += new_reference_count;
        pthread_mutex_unlock(&metadatas[i].mutex);
    }
}

void reclaim_memory(Metadata* metadatas, size_t metadata_size) {
    for (size_t i = 0; i < metadata_size; ++i) {
        if (metadatas[i].reference_count == 0) {
            pthread_mutex_lock(&metadatas[i].mutex);
            if (metadatas[i].reference_count == 0) {
                // Free the data structure
                free(datas + i);
                metadatas[i].reference_count = -1; // Mark as freed
            }
            pthread_mutex_unlock(&metadatas[i].mutex);
        }
    }
}
