#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

#define MAX_BUFFER_SIZE 1024
#define MAX_OPERATIONS_PER_MINUTE 1000

typedef enum {
    KEY_56_BIT,
    KEY_112_BIT,
    KEY_168_BIT
} KeyLength;

typedef enum {
    ECB_MODE,
    CBC_MODE,
    CFB_MODE,
    EDE_MODE,
    EDE3_MODE
} CipherMode;

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[24];
    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
    int key_length;
    int cipher_mode;
} EncryptionContext;

void generate_random_key(unsigned char *key, int length) {
    if (!RAND_bytes(key, length)) {
        fprintf(stderr, "Error generating random key\n");
        exit(EXIT_FAILURE);
    }
}

EncryptionContext* create_encryption_context(KeyLength key_length, CipherMode cipher_mode) {
    EncryptionContext *ctx = (EncryptionContext*)malloc(sizeof(EncryptionContext));
    ctx->key_length = key_length;
    ctx->cipher_mode = cipher_mode;

    switch (key_length) {
        case KEY_56_BIT:
            EVP_CIPHER_CTX_init(&ctx->ctx, EVP_des_cbc());
            break;
        case KEY_112_BIT:
            EVP_CIPHER_CTX_init(&ctx->ctx, EVP_desx_cbc());
            break;
        case KEY_168_BIT:
            EVP_CIPHER_CTX_init(&ctx->ctx, EVP_des_ede3_cbc());
            break;
    }

    generate_random_key(ctx->key, key_length / 8);
    generate_random_key(ctx->iv, EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ctx->ctx)));

    return ctx;
}

void encrypt_data(EncryptionContext *ctx, unsigned char *input, int input_len, unsigned char *output) {
    if (!EVP_EncryptInit_ex(ctx->ctx, NULL, NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Error initializing encryption\n");
        exit(EXIT_FAILURE);
    }

    int len;
    if (!EVP_EncryptUpdate(ctx->ctx, output, &len, input, input_len)) {
        fprintf(stderr, "Error encrypting data\n");
        exit(EXIT_FAILURE);
    }
    int final_len = 0;
    EVP_EncryptFinal_ex(ctx->ctx, output + len, &final_len);

    memcpy(output + len, ctx->iv, EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ctx->ctx)));
}

void decrypt_data(EncryptionContext *ctx, unsigned char *input, int input_len, unsigned char *output) {
    if (!EVP_DecryptInit_ex(ctx->ctx, NULL, NULL, ctx->key, ctx->iv)) {
        fprintf(stderr, "Error initializing decryption\n");
        exit(EXIT_FAILURE);
    }

    int len;
    if (!EVP_DecryptUpdate(ctx->ctx, output, &len, input, input_len)) {
        fprintf(stderr, "Error decrypting data\n");
        exit(EXIT_FAILURE);
    }
    int final_len = 0;
    EVP_DecryptFinal_ex(ctx->ctx, output + len, &final_len);

    memcpy(output + len, ctx->iv, EVP_CIPHER_block_size(EVP_CIPHER_CTX_cipher(ctx->ctx)));
}

void free_encryption_context(EncryptionContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}
