#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_LIST_T;

CRC_LIST_T* crc_list_create(size_t initial_capacity) {
    CRC_LIST_T *list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void crc_list_destroy(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    free(list->data);
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int crc_list_add(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failure
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *item = &list->data[list->size++];
    item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    item->RNTI = RNTI;
    item->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    item->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    time(&item->timestamp);

    pthread_mutex_unlock(&list->lock);
    return 0;
}

size_t crc_list_size(CRC_LIST_T *list) {
    size_t size;
    pthread_mutex_lock(&list->lock);
    size = list->size;
    pthread_mutex_unlock(&list->lock);
    return size;
}

size_t crc_list_capacity(CRC_LIST_T *list) {
    size_t capacity;
    pthread_mutex_lock(&list->lock);
    capacity = list->capacity;
    pthread_mutex_unlock(&list->lock);
    return capacity;
}
