#define MAX_IP_LENGTH 16

typedef struct {
    char SourceIP[MAX_IP_LENGTH];
    char DestinationIP[MAX_IP_LENGTH];
    int PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager() {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->flows);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_flow(TrafficManager *manager, const char *sourceIP, const char *destinationIP, int packetCount) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->flows[i].SourceIP, sourceIP) == 0 && strcmp(manager->flows[i].DestinationIP, destinationIP) == 0) {
            manager->flows[i].PacketCount += packetCount;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Updated
        }
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity > 0 ? manager->capacity * 2 : 16;
        TrafficFlow *new_flows = realloc(manager->flows, new_capacity * sizeof(TrafficFlow));
        if (!new_flows) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->flows = new_flows;
        manager->capacity = new_capacity;
    }

    strcpy(manager->flows[manager->count].SourceIP, sourceIP);
    strcpy(manager->flows[manager->count].DestinationIP, destinationIP);
    manager->flows[manager->count].PacketCount = packetCount;
    ++manager->count;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Added
}

int get_total_packet_count(TrafficManager *manager) {
    int total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        total += manager->flows[i].PacketCount;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}

int get_max_flow_packet_count(TrafficManager *manager) {
    int max = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->flows[i].PacketCount > max) {
            max = manager->flows[i].PacketCount;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return max;
}

double get_average_packet_count(TrafficManager *manager) {
    double total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        total += manager->flows[i].PacketCount;
    }
    pthread_mutex_unlock(&manager->lock);
    return manager->count > 0 ? total / manager->count : 0;
}
