    size_t count;
    size_t capacity;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->measurements = (PHY_MEASUREMENT_TAG *)malloc(NR_PHY_MEASUREMENT * sizeof(PHY_MEASUREMENT_TAG));
    if (array->measurements == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = NR_PHY_MEASUREMENT;
}

void freeDynamicArray(DynamicArray *array) {
    free(array->measurements);
    array->measurements = NULL;
    array->count = 0;
    array->capacity = 0;
}

void addMeasurement(DynamicArray *array, PHY_MEASUREMENT_TAG measurement) {
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        PHY_MEASUREMENT_TAG *new_measurements = (PHY_MEASUREMENT_TAG *)realloc(array->measurements, new_capacity * sizeof(PHY_MEASUREMENT_TAG));
        if (new_measurements == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->measurements = new_measurements;
        array->capacity = new_capacity;
    }
    array->measurements[array->count++] = measurement;
}

void readMeasurementsFromCSV(DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file: %s\n", filename);
        return;
    }

    PHY_MEASUREMENT_TAG measurement;
    while (fscanf(file, "%d,%d,%d", &measurement.tag, &measurement.tx_power_level, &measurement.rx_quality_factor) == 3) {
        addMeasurement(array, measurement);
    }

    fclose(file);
}

void printMeasurements(DynamicArray *array) {
    for (size_t i = 0; i < array->count; ++i) {
        printf("Tag: %d, TX Power Level: %d, RX Quality Factor: %d\n",
               array->measurements[i].tag,
               array->measurements[i].tx_power_level,
               array->measurements[i].rx_quality_factor);
    }
}

int main() {
    DynamicArray array;
    initDynamicArray(&array);

    readMeasurementsFromCSV(&array, "measurements.csv");

    printMeasurements(&array);

    freeDynamicArray(&array);

    return 0;
}
