#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef enum {
    CHANNEL_STATUS_ACTIVE,
    CHANNEL_STATUS_INACTIVE,
    CHANNEL_STATUS_ERROR
} CHANNEL_STATUS;

typedef struct LTE_MAC_TRANSPORT_CHANNEL_T {
    int TRANSPORT_CHANNEL_ID;
    int TENANT_ID;
    CHANNEL_STATUS CHANNEL_STATUS;
    // Other fields...
} LTE_MAC_TRANSPORT_CHANNEL_T;

typedef struct ListNode {
    LTE_MAC_TRANSPORT_CHANNEL_T *channel;
    struct ListNode *next;
} ListNode;

typedef struct {
    pthread_mutex_t lock;
    ListNode *head;
} ChannelList;

void initChannelList(ChannelList *list) {
    pthread_mutex_init(&list->lock, NULL);
    list->head = NULL;
}

void addChannel(ChannelList *list, LTE_MAC_TRANSPORT_CHANNEL_T *channel) {
    pthread_mutex_lock(&list->lock);
    ListNode *newNode = (ListNode *)malloc(sizeof(ListNode));
    newNode->channel = channel;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeChannel(ChannelList *list, int TRANSPORT_CHANNEL_ID) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;
    ListNode *prev = NULL;

    while (current != NULL) {
        if (current->channel->TRANSPORT_CHANNEL_ID == TRANSPORT_CHANNEL_ID) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

LTE_MAC_TRANSPORT_CHANNEL_T* getChannel(ChannelList *list, int TRANSPORT_CHANNEL_ID) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;

    while (current != NULL) {
        if (current->channel->TRANSPORT_CHANNEL_ID == TRANSPORT_CHANNEL_ID) {
            pthread_mutex_unlock(&list->lock);
            return current->channel;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void updateChannelStatus(ChannelList *list, int TRANSPORT_CHANNEL_ID, CHANNEL_STATUS newStatus) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;

    while (current != NULL) {
        if (current->channel->TRANSPORT_CHANNEL_ID == TRANSPORT_CHANNEL_ID) {
            current->channel->CHANNEL_STATUS = newStatus;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void freeChannelList(ChannelList *list) {
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->head;

    while (current != NULL) {
        ListNode *temp = current;
        current = current->next;
        free(temp->channel);
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
