#define MAX_RECORDS 1000
#define MAX_INPUT_SIZE 100

typedef struct {
    int value;
} Record;

void initializeArrays(long *offsets, int *keys, Record *records, int size) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % 1000000L;
        keys[i] = rand() % 1000;
        records[i].value = rand() % 1000;
    }
}

void readInput(int **inputArray, int *size) {
    printf("Enter the number of elements: ");
    scanf("%d", size);
    *inputArray = (int *)malloc(*size * sizeof(int));
    for (int i = 0; i < *size; i++) {
        scanf("%d", &(*inputArray)[i]);
    }
}

void findMax(int *max, int *array1, int size1, int *array2, int size2) {
    *max = array1[0];
    for (int i = 1; i < size1; i++) {
        if (array1[i] > *max) {
            *max = array1[i];
        }
    }
    for (int i = 0; i < size2; i++) {
        if (array2[i] > *max) {
            *max = array2[i];
        }
    }
}

void generateRandomString(char *buffer, int length) {
    const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (int i = 0; i < length; i++) {
        buffer[i] = charset[rand() % strlen(charset)];
    }
    buffer[length] = '\0';
}

void insertStringIntoRecords(Record *records, int position, char *buffer) {
    records[position].value = atoi(buffer);
}

int processPipeline(int inputSize, Record *records, int recordSize) {
    long offsets[MAX_RECORDS];
    int keys[MAX_RECORDS];
    int max;

    initializeArrays(offsets, keys, records, recordSize);

    int *inputArray;
    readInput(&inputArray, &inputSize);

    findMax(&max, inputArray, inputSize, (int *)records, recordSize);

    char buffer[MAX_INPUT_SIZE];
    generateRandomString(buffer, 10);
    insertStringIntoRecords(records, 5, buffer); // Insert at position 5 for example

    free(inputArray);

    return max;
}

int main() {
    Record records[MAX_RECORDS];
    int inputSize = 0;

    int result = processPipeline(inputSize, records, MAX_RECORDS);
    printf("Maximum value: %d\n", result);

    return 0;
}
