#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    long offset;
    int key;
} Record;

Record* create_record(long offset, int key) {
    Record* record = (Record*)malloc(sizeof(Record));
    if (!record) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    record->offset = offset;
    record->key = key;
    return record;
}

void free_record(Record* record) {
    free(record);
}

// Function to serialize records into a binary file
int serialize_records(const char* filename, Record** records, int count) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return -1;
    }

    size_t written = fwrite(records, sizeof(Record), count, file);
    if (written != count) {
        perror("Error writing records to file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

// Function to deserialize records from a binary file
int deserialize_records(const char* filename, Record** records, int* count) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *count = size / sizeof(Record);
    records = (Record*)malloc(*count * sizeof(Record));
    if (!records) {
        perror("Memory allocation failed");
        fclose(file);
        return -1;
    }

    size_t read = fread(records, sizeof(Record), *count, file);
    if (read != *count) {
        perror("Error reading records from file");
        free(records);
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}
