import hashlib
import os
from multiprocessing import Pool

def compute_hashes(file_path):
    try:
        with open(file_path, 'rb') as f:
            md5_hash = hashlib.md5()
            sha256_hash = hashlib.sha256()
            while chunk := f.read(4096):  # Read in chunks of 4KB
                md5_hash.update(chunk)
                sha256_hash.update(chunk)
        return file_path, md5_hash.hexdigest(), sha256_hash.hexdigest()
    except FileNotFoundError:
        print(f"File not found: {file_path}")
        return None
    except IOError as e:
        print(f"I/O error occurred while reading file: {e}")
        return None

def validate_hashes(file_paths, reference_hashes):
    for file_path in file_paths:
        if file_path in reference_hashes:
            md5_hash, sha256_hash = compute_hashes(file_path)
            if md5_hash and sha256_hash:
                if md5_hash != reference_hashes[file_path]['md5'] or sha256_hash != reference_hashes[file_path]['sha256']:
                    print(f"Hash mismatch for file: {file_path}")
        else:
            print(f"No reference hash found for file: {file_path}")

def compute_and_validate_hashes(file_paths, reference_hashes):
    with Pool(processes=os.cpu_count()) as pool:
        results = pool.map(compute_hashes, file_paths)

    valid_files = [result for result in results if result is not None]
    validate_hashes([result[0] for result in valid_files], reference_hashes)

# Example usage
file_paths = ['file1.txt', 'file2.txt']
reference_hashes = {
    'file1.txt': {'md5': 'expected_md5_hash', 'sha256': 'expected_sha256_hash'},
    'file2.txt': {'md5': 'expected_md5_hash', 'sha256': 'expected_sha256_hash'}
}
compute_and_validate_hashes(file_paths, reference_hashes)
```

