#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define DEFAULT_INTERVAL 60

typedef struct {
    int key;
    long timestamp;
} record;

typedef struct {
    record *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    int update_interval;
} metric_manager;

metric_manager* create_metric_manager(size_t initial_capacity, int interval) {
    metric_manager *mm = (metric_manager*)malloc(sizeof(metric_manager));
    if (!mm) return NULL;

    mm->records = (record*)calloc(initial_capacity, sizeof(record));
    if (!mm->records) {
        free(mm);
        return NULL;
    }

    mm->capacity = initial_capacity;
    mm->size = 0;
    pthread_mutex_init(&mm->mutex, NULL);
    mm->update_interval = interval > 0 ? interval : DEFAULT_INTERVAL;

    return mm;
}

void destroy_metric_manager(metric_manager *mm) {
    if (mm) {
        free(mm->records);
        pthread_mutex_destroy(&mm->mutex);
        free(mm);
    }
}

int add_record(metric_manager *mm, int key, long timestamp) {
    pthread_mutex_lock(&mm->mutex);
    if (mm->size >= mm->capacity) {
        size_t new_capacity = mm->capacity ? mm->capacity * 2 : 1;
        record *new_records = (record*)realloc(mm->records, new_capacity * sizeof(record));
        if (!new_records) {
            pthread_mutex_unlock(&mm->mutex);
            return -1; // Memory allocation failed
        }
        mm->records = new_records;
        mm->capacity = new_capacity;
    }
    mm->records[mm->size].key = key;
    mm->records[mm->size].timestamp = timestamp;
    mm->size++;
    pthread_mutex_unlock(&mm->mutex);
    return 0;
}

void* update_timestamps(void *arg) {
    metric_manager *mm = (metric_manager*)arg;
    while (1) {
        sleep(mm->update_interval);
        pthread_mutex_lock(&mm->mutex);
        for (size_t i = 0; i < mm->size; i++) {
            mm->records[i].timestamp = time(NULL);
        }
        pthread_mutex_unlock(&mm->mutex);
    }
    return NULL;
}

int main() {
    metric_manager *mm = create_metric_manager(10, 30); // Initial capacity of 10 records, update every 30 seconds
    if (!mm) {
        fprintf(stderr, "Failed to create metric manager\n");
        return 1;
    }

    pthread_t updater_thread;
    if (pthread_create(&updater_thread, NULL, update_timestamps, mm)) {
        fprintf(stderr, "Failed to create updater thread\n");
        destroy_metric_manager(mm);
        return 1;
    }

    // Example usage
    add_record(mm, 1, time(NULL));
    add_record(mm, 2, time(NULL));

    pthread_join(updater_thread, NULL);
    destroy_metric_manager(mm);

    return 0;
}
