typedef struct node {
    char* str;
    size_t length;
    struct node* next;
} Node;

Node* create_node(const char* str, size_t length) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->str = strdup(str);
    new_node->length = length;
    new_node->next = NULL;
    return new_node;
}

void insert_node(Node** head, const char* str, size_t length) {
    Node* new_node = create_node(str, length);
    if (!new_node) return;

    if (*head == NULL) {
        *head = new_node;
    } else {
        Node* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
}

void delete_node(Node** head, const char* str) {
    if (*head == NULL) return;

    if (strcmp((*head)->str, str) == 0) {
        Node* temp = *head;
        *head = (*head)->next;
        free(temp->str);
        free(temp);
        return;
    }

    Node* current = *head;
    while (current->next != NULL && strcmp(current->next->str, str) != 0) {
        current = current->next;
    }

    if (current->next != NULL) {
        Node* temp = current->next;
        current->next = current->next->next;
        free(temp->str);
        free(temp);
    }
}

Node* search_node(Node* head, const char* str) {
    while (head != NULL) {
        if (strcmp(head->str, str) == 0) {
            return head;
        }
        head = head->next;
    }
    return NULL;
}

void compress_nodes(Node** head) {
    Node* current = *head;
    while (current != NULL && current->next != NULL) {
        if (strcmp(current->str, current->next->str) == 0) {
            free(current->next->str);
            Node* temp = current->next;
            current->next = current->next->next;
            free(temp);
        } else {
            current = current->next;
        }
    }
}

void serialize_to_json(Node* head, FILE* file) {
    fprintf(file, "[");
    while (head != NULL) {
        fprintf(file, "{\"str\":\"%s\",\"length\":%zu}", head->str, head->length);
        if (head->next != NULL) fprintf(file, ",");
        head = head->next;
    }
    fprintf(file, "]");
}

Node* deserialize_from_json(const char* json_str) {
