typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_traffic_flow(TrafficManager *manager, TrafficFlow flow) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        // Resize the array
        manager->capacity *= 2;
        manager->flows = (TrafficFlow*)realloc(manager->flows, manager->capacity * sizeof(TrafficFlow));
    }
    memcpy(&manager->flows[manager->size], &flow, sizeof(TrafficFlow));
    manager->size++;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_traffic_flow(TrafficManager *manager, TrafficFlow flow) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; i++) {
        if (strcmp(manager->flows[i].SourceIP, flow.SourceIP) == 0 && strcmp(manager->flows[i].DestinationIP, flow.DestinationIP) == 0) {
            memcpy(&manager->flows[i], &flow, sizeof(TrafficFlow));
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Flow not found
}

void cleanup_old_flows(TrafficManager *manager) {
    time_t now = time(NULL);
    pthread_mutex_lock(&manager->lock);
    for (size_t i = manager->size - 1; i > 0; i--) {
        if (difftime(now, manager->flows[i].PacketCount) > 24 * 3600) {
            memmove(&manager->flows[i], &manager->flows[i + 1], (manager->size - i - 1) * sizeof(TrafficFlow));
            manager->size--;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

