// Define the record structure
typedef struct {
    int value;
} Record;

// Function to dynamically allocate memory for arrays and records
void* allocate_memory(size_t num_records, size_t batch_size) {
    // Allocate memory for long offset values
    long* offsets = (long*)malloc(num_records * sizeof(long));
    if (!offsets) return NULL;

    // Allocate memory for int keys
    int* keys = (int*)malloc(num_records * sizeof(int));
    if (!keys) {
        free(offsets);
        return NULL;
    }

    // Allocate memory for record structures
    Record* records = (Record*)malloc(num_records * sizeof(Record));
    if (!records) {
        free(keys);
        free(offsets);
        return NULL;
    }

    // Initialize the arrays and records
    for (size_t i = 0; i < num_records; ++i) {
        offsets[i] = i * batch_size;
        keys[i] = i;
        records[i].value = i * 10;
    }

    // Return a pointer to the allocated memory block
    return records;
}

// Function to serialize and deserialize records into binary format
void serialize_records(Record* records, size_t num_records, FILE* file) {
    if (!file) return;

    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i].value, sizeof(int), 1, file);
    }
}

int deserialize_records(Record** records, size_t* num_records, FILE* file) {
    if (!file) return -1;

    // Determine the number of records by reading from the file
    fseek(file, 0, SEEK_END);
    *num_records = ftell(file) / sizeof(int);
    fseek(file, 0, SEEK_SET);

    // Allocate memory for the records
    *records = (Record*)malloc(*num_records * sizeof(Record));
    if (!*records) return -1;

    // Read the records from the file
    size_t read_count = fread(*records, sizeof(int), *num_records, file);
    if (read_count != *num_records) {
        free(*records);
        return -1;
    }

    return 0;
}

// Function to compact records by removing unused entries
void compact_records(Record** records, size_t* num_records, size_t new_size) {
    // Allocate new memory for the records
    Record* new_records = (Record*)realloc(*records, new_size * sizeof(Record));
    if (!new_records) return;

    // Copy the valid records to the new array
    memcpy(new_records, *records, new_size * sizeof(Record));

    // Free the old memory and update the pointer
    free(*records);
    *records = new_records;
    *num_records = new_size;
}

// Function to dynamically allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_nfaapi_crc_pdu(size_t N) {
    if (N <= 0) return NULL;

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) return NULL;

    // Initialize the array of structures
    for (size_t i = 0; i < N; ++i) {
        pdus[i].RX_UE_INFORMATION_TAG = i;
        pdus[i].RNTI = rand() % 1024;
        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
    }

    return pdus;
}

// Function to update the CRCFLAG for a specific RNTI value
void update_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdus, size_t N, int rnti, int new_crcflag) {
    if (!pdus || N <= 0 || rnti < 0) return;

    for (size_t i = 0; i < N; ++i) {
        if (pdus[i].RNTI == rnti) {
            pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = new_crcflag;
            break;
        }
    }
}
