typedef struct {
    int value;
} record;

void custom_sort(int *array, size_t length) {
    // Implement a simple bubble sort for demonstration purposes
    for (size_t i = 0; i < length - 1; ++i) {
        for (size_t j = 0; j < length - i - 1; ++j) {
            if (array[j] < array[j + 1]) {
                int temp = array[j];
                array[j] = array[j + 1];
                array[j + 1] = temp;
            }
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <file_path>\n", argv[0]);
        return EXIT_FAILURE;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        perror("Failed to open file");
        return EXIT_FAILURE;
    }

    // Initialize variables
    size_t capacity = 1024; // Initial capacity for dynamic arrays
    long *offsets = malloc(capacity * sizeof(long));
    int *keys = malloc(capacity * sizeof(int));
    record *records = malloc(capacity * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed\n");
        fclose(file);
        return EXIT_FAILURE;
    }

    size_t count = 0;
    int value;

    // Read integers from file
    while (fscanf(file, "%d", &value) == 1) {
        if (count >= capacity) {
            capacity *= 2; // Double the capacity
            offsets = realloc(offsets, capacity * sizeof(long));
            keys = realloc(keys, capacity * sizeof(int));
            records = realloc(records, capacity * sizeof(record));

            if (!offsets || !keys || !records) {
                fprintf(stderr, "Memory reallocation failed\n");
                fclose(file);
                free(offsets);
                free(keys);
                free(records);
                return EXIT_FAILURE;
            }
        }

        offsets[count] = ftell(file); // Store offset
        keys[count] = value; // Store key
        records[count].value = rand() % 1000 + 1; // Initialize record with random value

        count++;
    }

    fclose(file);

    if (ferror(file)) {
        perror("Error reading file");
        free(offsets);
        free(keys);
        free(records);
        return EXIT_FAILURE;
    }

    // Sort keys in descending order
    custom_sort(keys, count);

    // Print the largest integer
    if (count > 0) {
        printf("Largest integer: %d\n", keys[0]);
    } else {
        printf("No integers found in file.\n");
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return EXIT_SUCCESS;
}
