    TrafficFlow** trafficFlows = NULL;
    int trafficCount = 0;

    // Example: Reading from file to initialize contexts and flows
    while (!feof(configFile)) {
        // Read configuration for each context and flow
        Layer2Context* newContext = createLayer2Context();
        TrafficFlow* newFlow = createTrafficFlow();

        addOrUpdateTrafficFlow(&trafficFlows, &trafficCount, newFlow);
        layer2Contexts = realloc(layer2Contexts, (layer2Count + 1) * sizeof(Layer2Context*));
        layer2Contexts[layer2Count++] = newContext;
    }

    fclose(configFile);

    // Example: Log initialization success
    logMessage(LOG_INFO, "Communication stack initialized successfully.");

    // Free allocated resources
    for (int i = 0; i < layer2Count; i++) {
        free(layer2Contexts[i]);
    }
    free(layer2Contexts);

    for (int i = 0; i < trafficCount; i++) {
        freeTrafficFlow(trafficFlows[i]);
    }
    free(trafficFlows);
}

void logMessage(LogLevel level, const char* message) {
    // Implement logging logic based on the log level and destination
    printf("[%s] %s\n", LogLevelToString(level), message);
}

Layer2Context* createLayer2Context() {
    // Allocate memory for a new Layer2Context
    return (Layer2Context*)malloc(sizeof(Layer2Context));
}

TrafficFlow* createTrafficFlow() {
    // Allocate memory for a new TrafficFlow
    return (TrafficFlow*)malloc(sizeof(TrafficFlow));
}

void addOrUpdateTrafficFlow(TrafficFlow** flows, int* count, TrafficFlow* flow) {
    // Add or update the traffic flow in the array
    for (int i = 0; i < *count; i++) {
        if (flows[i]->id == flow->id) {
            // Update existing flow
            memcpy(flows[i], flow, sizeof(TrafficFlow));
            return;
        }
    }

    // Add new flow
    flows = realloc(flows, (*count + 1) * sizeof(TrafficFlow*));
    flows[*count++] = flow;
}

TrafficFlow* getTrafficFlowById(TrafficFlow** flows, int count, int id) {
    // Retrieve traffic flow by ID
    for (int i = 0; i < count; i++) {
        if (flows[i]->id == id) {
            return flows[i];
        }
    }
    return NULL;
}

void freeTrafficFlow(TrafficFlow* flow) {
    // Free memory allocated for a TrafficFlow
    free(flow);
}
