int initialize_data_structures(int num_offsets, int num_keys) {
    if (num_offsets <= 0 || num_keys <= 0) {
        return -1; // Invalid dimensions
    }

    long_offset *offsets = malloc(num_offsets * sizeof(long_offset));
    key_record *keys = malloc(num_keys * sizeof(key_record));
    record *records = NULL;

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    int total_records = num_offsets * num_keys;
    if (total_records > MAX_SIZE) {
        free(offsets);
        free(keys);
        return -3; // Exceeds maximum allowed size
    }

    records = malloc(total_records * sizeof(record));
    if (!records) {
        free(offsets);
        free(keys);
        return -2; // Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    for (int i = 0; i < total_records; i++) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }

    // Initialize offsets and keys with dummy values
    for (int i = 0; i < num_offsets; i++) {
        offsets[i].offset = i * 10;
    }
    for (int i = 0; i < num_keys; i++) {
        keys[i].key = i + 1;
    }

    // Free allocated memory
    free(offsets);
    free(keys);
    free(records);

    return 0; // Success
}
