#include <fcntl.h>
#include <unistd.h>

#define SHM_NAME "/my_shm"
#define RECORD_COUNT 1000

typedef struct {
    int value;
} record;

void* allocate_and_initialize_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        perror("Failed to allocate memory");
        exit(EXIT_FAILURE);
    }
    memset(ptr, 0, size);
    return ptr;
}

int main() {
    long* offsets = allocate_and_initialize_memory(RECORD_COUNT * sizeof(long));
    int* keys = allocate_and_initialize_memory(RECORD_COUNT * sizeof(int));
    record* records = allocate_and_initialize_memory(RECORD_COUNT * sizeof(record));

    for (size_t i = 0; i < RECORD_COUNT; ++i) {
        offsets[i] = i * 10;
        keys[i] = rand() % 100;
        records[i].value = rand() % 1000;
    }

    int shm_fd = shm_open(SHM_NAME, O_CREAT | O_RDWR, 0666);
    if (shm_fd == -1) {
        perror("Failed to create shared memory object");
        exit(EXIT_FAILURE);
    }

    if (ftruncate(shm_fd, RECORD_COUNT * sizeof(record)) == -1) {
        perror("Failed to set size of shared memory object");
        exit(EXIT_FAILURE);
    }

    record* shm_records = mmap(NULL, RECORD_COUNT * sizeof(record), PROT_READ | PROT_WRITE, MAP_SHARED, shm_fd, 0);
    if (shm_records == MAP_FAILED) {
        perror("Failed to map shared memory object");
        exit(EXIT_FAILURE);
    }

    memcpy(shm_records, records, RECORD_COUNT * sizeof(record));

    munmap(shm_records, RECORD_COUNT * sizeof(record));
    close(shm_fd);

    return 0;
}
