#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define cryptographic operation structure
typedef struct CryptoOperation {
    char name[256];
    void (*function)(void*);
    int identifier;
    int version;
    // Add any necessary parameters for the function here
} CryptoOperation;

// Define a node in the binary search tree
typedef struct TreeNode {
    CryptoOperation data;
    struct TreeNode *left, *right;
} TreeNode;

// Define a lock for thread-safe operations
pthread_mutex_t bst_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to create a new tree node
TreeNode* createNode(CryptoOperation data) {
    TreeNode* newNode = (TreeNode*)malloc(sizeof(TreeNode));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new node");
        exit(EXIT_FAILURE);
    }
    newNode->data = data;
    newNode->left = newNode->right = NULL;
    return newNode;
}

// Function to insert a new node into the BST
TreeNode* insert(TreeNode* root, CryptoOperation data) {
    pthread_mutex_lock(&bst_lock);
    if (root == NULL) {
        root = createNode(data);
    } else if (strcmp(data.name, root->data.name) < 0) {
        root->left = insert(root->left, data);
    } else if (strcmp(data.name, root->data.name) > 0) {
        root->right = insert(root->right, data);
    }
    pthread_mutex_unlock(&bst_lock);
    return root;
}

// Function to search for a node in the BST
TreeNode* search(TreeNode* root, char* name) {
    if (root == NULL || strcmp(name, root->data.name) == 0) {
        return root;
    } else if (strcmp(name, root->data.name) < 0) {
        return search(root->left, name);
    } else {
        return search(root->right, name);
    }
}

// Function to delete a node from the BST
TreeNode* deleteNode(TreeNode* root, char* name) {
    pthread_mutex_lock(&bst_lock);
    if (root == NULL) {
        return root;
    } else if (strcmp(name, root->data.name) < 0) {
        root->left = deleteNode(root->left, name);
    } else if (strcmp(name, root->data.name) > 0) {
        root->right = deleteNode(root->right, name);
    } else {
        if (root->left == NULL) {
            TreeNode* temp = root->right;
            free(root);
            return temp;
        } else if (root->right == NULL) {
            TreeNode* temp = root->left;
            free(root);
            return temp;
        }
        TreeNode* temp = minValueNode(root->right);
        root->data = temp->data;
        root->right = deleteNode(root->right, temp->data.name);
    }
    pthread_mutex_unlock(&bst_lock);
    return root;
}

// Function to find the node with minimum value in a subtree
TreeNode* minValueNode(TreeNode* node) {
    TreeNode* current = node;
    while (current && current->left != NULL) {
        current = current->left;
    }
    return current;
}

// Function to free the memory allocated for the BST
void freeBST(TreeNode* root) {
    if (root != NULL) {
        freeBST(root->left);
        freeBST(root->right);
        free(root);
    }
}

// Main function to demonstrate usage of the cryptographic operation tree
int main() {
    TreeNode* root = NULL;
    CryptoOperation hashFunction1 = {"SHA256", sha256, 101, 1};
    CryptoOperation cipher1 = {"AES-256-CBC", aes256_cbc, 201, 1};

    root = insert(root, hashFunction1);
    root = insert(root, cipher1);

    TreeNode* searchResult = search(root, "SHA256");
    if (searchResult != NULL) {
        printf("Found SHA256: %s\n", searchResult->data.name);
    } else {
        printf("SHA256 not found\n");
    }

    root = deleteNode(root, "SHA256");

    freeBST(root);

    return 0;
}
```

