#define MAX_SESSIONS 1024
#define COMPRESSION_THRESHOLD 512

typedef struct {
    char UserID[64];
    char SessionID[64];
    time_t LastActivityTime;
    int ActivityDuration;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} SessionManager;

void init_session_manager(SessionManager *manager) {
    manager->sessions = (UserSession *)malloc(MAX_SESSIONS * sizeof(UserSession));
    if (!manager->sessions) {
        fprintf(stderr, "Failed to allocate memory for session manager\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = MAX_SESSIONS;
    pthread_mutex_init(&manager->lock, NULL);
}

void destroy_session_manager(SessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
}

int add_or_update_session(SessionManager *manager, const UserSession *session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->sessions[i].SessionID, session->SessionID) == 0) {
            memcpy(&manager->sessions[i], session, sizeof(UserSession));
            pthread_mutex_unlock(&manager->lock);
            return 1;
        }
    }
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UserSession *new_sessions = (UserSession *)realloc(manager->sessions, new_capacity * sizeof(UserSession));
        if (!new_sessions) {
            fprintf(stderr, "Failed to reallocate memory for session manager\n");
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->sessions = new_sessions;
        manager->capacity = new_capacity;
    }
    memcpy(&manager->sessions[manager->count], session, sizeof(UserSession));
    ++manager->count;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

// Additional functions for retrieving statistics, filtering sessions, and identifying unusual activity patterns would go here

int main() {
    SessionManager manager;
    init_session_manager(&manager);

    // Example usage
    UserSession session = {"user123", "session456", time(NULL), 3600};
    add_or_update_session(&manager, &session);

    destroy_session_manager(&manager);
    return 0;
}
```

