#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_SIZE 1000000

typedef struct {
    long offset;
} long_offset;

typedef struct {
    int key;
} key_record;

typedef struct {
    int value;
} record;

struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
};

void init_memory_pool(struct MemoryPool* pool, size_t block_size, size_t num_blocks) {
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;
    pool->pool = malloc(block_size * num_blocks);
}

void* allocate_from_pool(struct MemoryPool* pool) {
    if (pool->free_index >= pool->num_blocks) {
        return NULL; // Pool is full
    }
    void* block = (char*)pool->pool + pool->block_size * pool->free_index;
    pool->free_index++;
    return block;
}

void deallocate_to_pool(struct MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index < pool->num_blocks && index >= pool->free_index) {
        pool->free_index = index + 1;
    }
}

void manage_memory() {
    struct MemoryPool long_offset_pool, key_record_pool, record_pool;

    init_memory_pool(&long_offset_pool, sizeof(long_offset), MAX_SIZE);
    init_memory_pool(&key_record_pool, sizeof(key_record), MAX_SIZE);
    init_memory_pool(&record_pool, sizeof(record), MAX_SIZE * MAX_SIZE);

    // Allocate and initialize long_offset array
    long_offset* long_offsets = (long_offset*)allocate_from_pool(&long_offset_pool);
    if (!long_offsets) {
        fprintf(stderr, "Failed to allocate memory for long_offset array\n");
        return;
    }

    // Allocate and initialize key_record array
    key_record* key_records = (key_record*)allocate_from_pool(&key_record_pool);
    if (!key_records) {
        fprintf(stderr, "Failed to allocate memory for key_record array\n");
        deallocate_to_pool(&long_offset_pool, long_offsets);
        return;
    }

    // Allocate and initialize record array
    record* records = (record*)allocate_from_pool(&record_pool);
    if (!records) {
        fprintf(stderr, "Failed to allocate memory for record array\n");
        deallocate_to_pool(&key_record_pool, key_records);
        deallocate_to_pool(&long_offset_pool, long_offsets);
        return;
    }

    // Initialize records with random values
    srand(time(NULL));
    int num_long_offsets = 1000;
    int num_key_records = 500;
    for (int i = 0; i < num_long_offsets * num_key_records; i++) {
        records[i].value = rand() % 1000000;
    }

    // Deallocate memory
    deallocate_to_pool(&record_pool, records);
    deallocate_to_pool(&key_record_pool, key_records);
    deallocate_to_pool(&long_offset_pool, long_offsets);

    printf("Memory management completed successfully\n");
}

int main() {
    manage_memory();
    return 0;
}
```

