// Function to update or delete a resource based on user action
void* manageResource(void* arg) {
    Resource* resource = (Resource*)arg;
    char* action = strtok(NULL, " ");
    char* requestBody = strtok(NULL, "\n");

    if (strcmp(action, "UPDATE") == 0) {
        // Update the resource data
        free(resource->data);
        resource->data = strdup(requestBody);
        printf("Resource updated: %s\n", resource->id);
    } else if (strcmp(action, "DELETE") == 0) {
        // Delete the resource asynchronously
        pthread_t deleteThread;
        pthread_create(&deleteThread, NULL, deleteResource, resource);
        pthread_detach(deleteThread);
    }

    return NULL;
}

// Function to handle asynchronous deletion of a resource
void* deleteResource(void* arg) {
    Resource* resource = (Resource*)arg;

    // Simulate deletion process
    sleep(1); // Delay for demonstration purposes

    // Free the resource data and ID
    free(resource->data);
    free(resource->id);

    printf("Resource deleted: %s\n", resource->id);

    return NULL;
}

// Function to validate input strings
int validateInput(char* str, int maxLength) {
    if (str == NULL || strlen(str) > maxLength) {
        return 0; // Invalid input
    }
    return 1; // Valid input
}

