['```java
import java.io.FileInputStream;
import java.io.IOException;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HashMap;
import java.util.Map;

public class FileHasher {
    private static final Map<String, String> md5Cache = new HashMap<>();
    private static final Map<String, String> sha256Cache = new HashMap<>();

    public static void main(String[] args) {
        // Example usage
        try {
            computeFileHashes("path/to/file1.txt", "path/to/file2.txt");
        } catch (IOException | NoSuchAlgorithmException e) {
            e.printStackTrace();
        }
    }

    public static void computeFileHashes(String... filePaths) throws IOException, NoSuchAlgorithmException {
        for (String path : filePaths) {
            if (!md5Cache.containsKey(path)) {
                String md5 = computeMD5(path);
                md5Cache.put(path, md5);
            }
            if (!sha256Cache.containsKey(path)) {
                String sha256 = computeSHA256(path);
                sha256Cache.put(path, sha256);
            }
        }
    }

    private static String computeMD5(String path) throws IOException, NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (FileInputStream fis = new FileInputStream(path)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(md.digest());
    }

    private static String computeSHA256(String path) throws IOException, NoSuchAlgorithmException {
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
        try (FileInputStream fis = new FileInputStream(path)) {
            byte[] buffer = new byte[8192];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                sha256.update(buffer, 0, bytesRead);
            }
        }
        return bytesToHex(sha256.digest());
    }

    private static String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
