NFAPI_CRC_INDICATION_PDU_T *struct_list[MAX_STRUCTS];
int current_index = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_random_values(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    static int rnti_counter = 1;
    pdu->RX_UE_INFORMATION_TAG = rand() % MAX_RNTI + 1;
    pdu->RNTI = rnti_counter++;
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0);
}

int is_duplicate(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    for (int i = 0; i < current_index; i++) {
        if (struct_list[i]->RX_UE_INFORMATION_TAG == pdu->RX_UE_INFORMATION_TAG ||
            struct_list[i]->RNTI == pdu->RNTI) {
            return 1;
        }
    }
    return 0;
}

int add_to_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (current_index >= MAX_STRUCTS) {
        return -1; // List is full
    }
    if (is_duplicate(pdu)) {
        return -2; // Duplicate entry
    }
    struct_list[current_index++] = pdu;
    return 0;
}

void* generate_structs(void *arg) {
    int num_to_generate = *(int*)arg;
    for (int i = 0; i < num_to_generate; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            perror("Memory allocation failed");
            return NULL;
        }
        generate_random_values(pdu);
        pthread_mutex_lock(&mutex);
        int result = add_to_list(pdu);
        pthread_mutex_unlock(&mutex);
        if (result != 0) {
            free(pdu);
            printf("Failed to add struct: %d\n", result);
        }
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[10];
    int num_threads = 10;
    int structs_per_thread = MAX_STRUCTS / num_threads;

    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, generate_structs, &structs_per_thread) != 0) {
            perror("Thread creation failed");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    // Clean up and log results
    printf("Total structs generated: %d\n", current_index);

    for (int i = 0; i < current_index; i++) {
        free(struct_list[i]);
    }

    return 0;
}
