    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_USERS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: No space for new transaction
    }
    manager->transactions[manager->count++] = transaction;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int updateTransaction(TransactionManager *manager, int userID, Transaction updatedTransaction) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->transactions[i].UserID == userID) {
            manager->transactions[i] = updatedTransaction;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: Transaction not found
}

double getTotalTransactionAmount(TransactionManager *manager) {
    double total = 0.0;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        total += manager->transactions[i].Amount;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}

double getAverageTransactionAmountPerUser(TransactionManager *manager) {
    double total = getTotalTransactionAmount(manager);
    int userCount = 0;
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (i == 0 || manager->transactions[i].UserID != manager->transactions[i - 1].UserID) {
            userCount++;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return total / userCount;
}

int main() {
    TransactionManager manager;
    initTransactionManager(&manager);

    // Example usage
    Transaction transaction = {1, 101, 50.0, "2023-04-01"};
    addTransaction(&manager, transaction);
    updateTransaction(&manager, 101, (Transaction){2, 101, 60.0, "2023-04-02"});

    printf("Total Transaction Amount: %.2f\n", getTotalTransactionAmount(&manager));
    printf("Average Transaction Amount Per User: %.2f\n", getAverageTransactionAmountPerUser(&manager));

    return 0;
}
