import java.util.Random;
import java.util.concurrent.atomic.AtomicBoolean;

public class ServiceManager {
    private static final int MAX_DIMENSION = 1000;
    private static final int VALUE_RANGE = 10000;
    private static final String MESSAGE_TEMPLATE = "Service stopped at %s";

    private struct long_offset[] longOffsets;
    private struct key_record[] keyRecords;
    private struct record[] records;

    private AtomicBoolean isRunning = new AtomicBoolean(false);
    private Random random = new Random();

    public void start(int numLongOffsets, int numKeyRecords) {
        if (numLongOffsets <= 0 || numKeyRecords <= 0) {
            throw new IllegalArgumentException("Dimensions must be positive");
        }

        longOffsets = new struct long_offset[numLongOffsets];
        keyRecords = new struct key_record[numKeyRecords];

        int recordsSize = numLongOffsets * numKeyRecords;
        if (recordsSize > MAX_DIMENSION) {
            System.out.println("Warning: Dimension exceeds threshold. Degraded performance expected.");
            recordsSize = Math.min(recordsSize, MAX_DIMENSION);
        }

        records = new struct record[recordsSize];

        for (int i = 0; i < records.length; i++) {
            records[i] = new struct record(random.nextInt(VALUE_RANGE));
        }

        isRunning.set(true);
    }

    public void stop() {
        if (!isRunning.compareAndSet(true, false)) {
            return;
        }

        try {
            // Simulate sending a status message to an external messaging system
            String statusMessage = String.format(MESSAGE_TEMPLATE, System.currentTimeMillis());
            sendMessage(statusMessage);
        } catch (Exception e) {
            System.err.println("Failed to send status message: " + e.getMessage());
        }
    }

    private void sendMessage(String message) throws Exception {
        // Simulate sending a message with potential network latency
        Thread.sleep(100); // Simulating 100ms delay
        System.out.println("Message sent: " + message);
    }

    public static class struct long_offset {
        public long offset;
    }

    public static class struct key_record {
        public int key;
    }

    public static class struct record {
        public int value;

        public struct record(int value) {
            this.value = value;
        }
    }

    public static void main(String[] args) {
        ServiceManager manager = new ServiceManager();
        try {
            manager.start(10, 20);
            Thread.sleep(5000); // Simulate service running for 5 seconds
            manager.stop();
        } catch (InterruptedException e) {
            System.err.println("Service interrupted: " + e.getMessage());
        }
    }
}
