import os
import hashlib
import concurrent.futures
import logging
import re

# External dependencies
from tqdm import tqdm
from loguru import logger

def process_files(directory, extensions=None, algorithm='md5', max_workers=None):
    def read_in_chunks(file_path, chunk_size=8192):
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                yield data

    def calculate_checksum(file_path, algorithm='md5'):
        hasher = hashlib.new(algorithm)
        for chunk in read_in_chunks(file_path):
            hasher.update(chunk)
        return hasher.hexdigest()

    def filter_files(file_name):
        if extensions is None:
            return True
        if isinstance(extensions, str):
            return file_name.endswith(extensions)
        elif isinstance(extensions, re.Pattern):
            return extensions.match(file_name) is not None

    def log_file_processing(file_path):
        logger.info(f"Processing file: {file_path}")

    def log_completion():
        logger.info("File processing completed.")

    checksums = {}
    error_count = 0
    total_files = 0

    with concurrent.futures.ThreadPoolExecutor(max_workers=max_workers) as executor:
        futures = []
        for root, _, files in os.walk(directory):
            for file_name in files:
                if filter_files(file_name):
                    file_path = os.path.join(root, file_name)
                    futures.append(executor.submit(calculate_checksum, file_path))
                    total_files += 1

        for future in tqdm(concurrent.futures.as_completed(futures), total=len(futures)):
            try:
                checksums[file_path] = future.result()
                log_file_processing(file_path)
            except Exception as e:
                logger.error(f"Error processing file {file_path}: {e}")
                error_count += 1

    log_completion()

    summary_report = {
        'total_files': total_files,
        'successful_checksums': len(checksums),
        'errors': error_count
    }

    return checksums, summary_report
