#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_TRAFFIC 1000000
#define IP_RANGE_SIZE 256

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} NetworkTraffic;

typedef struct {
    NetworkTraffic *trafficArray;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} TrafficManager;

void initTrafficManager(TrafficManager *manager) {
    manager->trafficArray = (NetworkTraffic *)malloc(MAX_TRAFFIC * sizeof(NetworkTraffic));
    if (!manager->trafficArray) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    manager->count = 0;
    manager->capacity = MAX_TRAFFIC;
    pthread_mutex_init(&manager->lock, NULL);
}

void addOrUpdateTraffic(TrafficManager *manager, const char *sourceIP, const char *destinationIP, int packetCount) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (strcmp(manager->trafficArray[i].SourceIP, sourceIP) == 0 && strcmp(manager->trafficArray[i].DestinationIP, destinationIP) == 0) {
            manager->trafficArray[i].PacketCount += packetCount;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    if (manager->count >= manager->capacity) {
        // Resize array
        NetworkTraffic *newArray = (NetworkTraffic *)realloc(manager->trafficArray, manager->capacity * 2 * sizeof(NetworkTraffic));
        if (!newArray) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        manager->trafficArray = newArray;
        manager->capacity *= 2;
    }
    strcpy(manager->trafficArray[manager->count].SourceIP, sourceIP);
    strcpy(manager->trafficArray[manager->count].DestinationIP, destinationIP);
    manager->trafficArray[manager->count].PacketCount = packetCount;
    ++manager->count;
    pthread_mutex_unlock(&manager->lock);
}

// Additional functions for retrieving statistics, filtering, and identifying unusual traffic patterns would be implemented here

void freeTrafficManager(TrafficManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->trafficArray);
    manager->trafficArray = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}
