struct ArrayData {
    long* offsets;
    int* keys;
    record* records;
    size_t total_records;
};

struct ArrayData initializeArrays(size_t max_offset, int min_key, int max_key, int min_value, int max_value, size_t total_records) {
    struct ArrayData data = {NULL, NULL, NULL, 0};

    // Allocate memory for offsets
    data.offsets = (long*)malloc((max_offset + 1) * sizeof(long));
    if (!data.offsets) return data;

    // Initialize offsets
    for (size_t i = 0; i <= max_offset; ++i) {
        data.offsets[i] = i;
    }

    // Allocate memory for keys
    data.keys = (int*)malloc(total_records * sizeof(int));
    if (!data.keys) {
        free(data.offsets);
        return data;
    }

    // Initialize keys with unique values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < total_records; ++i) {
        int key;
        do {
            key = min_key + rand() % (max_key - min_key + 1);
        } while (isKeyDuplicate(data.keys, i, key));
        data.keys[i] = key;
    }

    // Allocate memory for records
    data.records = (record*)malloc(total_records * sizeof(record));
    if (!data.records) {
        free(data.offsets);
        free(data.keys);
        return data;
    }

    // Initialize records with random values and offsets
    for (size_t i = 0; i < total_records; ++i) {
        data.records[i].value = min_value + rand() % (max_value - min_value + 1);
        data.records[i].offset_ptr = &data.offsets[data.keys[i]];
    }

    data.total_records = total_records;
    return data;
}

int isKeyDuplicate(int* keys, size_t index, int key) {
    for (size_t i = 0; i < index; ++i) {
        if (keys[i] == key) return 1;
    }
    return 0;
}
