#include <iostream>
#include <string>
#include <vector>
#include <queue>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <unordered_map>

class StringStreamProcessor {
public:
    StringStreamProcessor(const std::string& delimiter, const std::function<std::string(std::string)>& transform)
        : delimiter(delimiter), transform(transform), stop(false) {}

    void start() {
        for (size_t i = 0; i < numThreads; ++i) {
            workers.emplace_back(&StringStreamProcessor::workerThread, this);
        }
    }

    void stopProcessing() {
        {
            std::unique_lock<std::mutex> lock(mutex);
            stop = true;
        }
        condition.notify_all();
        for (std::thread& worker : workers) {
            worker.join();
        }
    }

    void pushString(const std::string& str) {
        {
            std::lock_guard<std::mutex> lock(mutex);
            inputQueue.push(str);
        }
        condition.notify_one();
    }

private:
    void workerThread() {
        while (true) {
            std::string str;
            {
                std::unique_lock<std::mutex> lock(mutex);
                condition.wait(lock, [this] { return !inputQueue.empty() || stop; });
                if (stop && inputQueue.empty()) {
                    break;
                }
                str = inputQueue.front();
                inputQueue.pop();
            }

            // Parse and transform the string
            std::vector<std::string> segments = parseString(str);
            for (std::string& segment : segments) {
                segment = transform(segment);
            }

            // Append transformed segments back to the stream or handle them as needed
            for (const std::string& segment : segments) {
                outputQueue.push(segment);
            }
        }
    }

    std::vector<std::string> parseString(const std::string& str) {
        std::vector<std::string> segments;
        size_t pos = 0, nextPos;
        while ((nextPos = str.find(delimiter, pos)) != std::string::npos) {
            segments.push_back(str.substr(pos, nextPos - pos));
            pos = nextPos + delimiter.length();
        }
        if (pos < str.length()) {
            segments.push_back(str.substr(pos));
        } else {
            segments.push_back(defaultMarker);
        }
        return segments;
    }

    std::string defaultMarker = "END_OF_STREAM";
    size_t numThreads = std::thread::hardware_concurrency();
    std::queue<std::string> inputQueue;
    std::queue<std::string> outputQueue;
    std::vector<std::thread> workers;
    std::mutex mutex;
    std::condition_variable condition;
    bool stop;
    std::string delimiter;
    std::function<std::string(std::string)> transform;
};

int main() {
    StringStreamProcessor processor(";", [](const std::string& str) { return "TRANSFORMED: " + str; });
    processor.start();

    // Simulate pushing strings to the processor
    for (size_t i = 0; i < 1000; ++i) {
        processor.pushString("Segment" + std::to_string(i));
    }

    processor.stopProcessing();
    return 0;
}
