struct EventRecord {
    int timestamp;
    std::string eventType;
    int key;
};

class EncounterManager {
public:
    EncounterManager(const std::string& filePath) : filePath(filePath), lastEventTime(0) {
        loadEncounters();
        initializeOffsetsAndKeys();
    }

    void processCharacterEncounter() {
        if (events.empty()) return;

        std::lock_guard<std::mutex> lock(mutex);
        int currentTime = getCurrentTime();
        EventRecord& selectedEvent = events[selectRandomEvent(currentTime)];

        if (currentTime - lastEventTime[selectedEvent.eventType] >= 9) {
            executeEvent(selectedEvent);
            lastEventTime[selectedEvent.eventType] = currentTime;
        }
    }

private:
    std::string filePath;
    std::vector<EventRecord> events;
    std::vector<long> offsets;
    std::vector<int> keys;
    std::array<int, 3> lastEventTime; // Assuming event types are attack, heal, movement
    std::mutex mutex;

    void loadEncounters() {
