        if (!file) throw std::runtime_error("Failed to open file");

        int count;
        file.read(reinterpret_cast<char*>(&count), sizeof(count));
        events.resize(count);

        for (auto& event : events) {
            file.read(reinterpret_cast<char*>(&event.timestamp), sizeof(event.timestamp));
            int eventTypeLength;
            file.read(reinterpret_cast<char*>(&eventTypeLength), sizeof(eventTypeLength));
            event.eventType.resize(eventTypeLength);
            file.read(&event.eventType[0], eventTypeLength * sizeof(char));
            file.read(reinterpret_cast<char*>(&event.key), sizeof(event.key));
        }
    }

    void initializeOffsetsAndKeys() {
