    }

    int selectRandomEvent(int currentTime) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, events.size() - 1);
        return dis(gen);
    }

    void executeEvent(const EventRecord& event) {
        // Execute the selected event
        std::cout << "Executing event: " << event.eventType << " at time " << event.timestamp << std::endl;
    }

    int getCurrentTime() {
        // Get current time in seconds
        return static_cast<int>(std::time(nullptr));
    }
};

