#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int Timestamp;
    int SourcePort;
    int DestinationPort;
    int PacketSize;
} NetworkEvent;

typedef struct {
    NetworkEvent* events;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} EventManager;

EventManager* createEventManager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (!manager) return NULL;
    manager->events = NULL;
    manager->count = 0;
    manager->capacity = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroyEventManager(EventManager* manager) {
    if (manager->events) free(manager->events);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addEvent(EventManager* manager, NetworkEvent event) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NetworkEvent* new_events = realloc(manager->events, new_capacity * sizeof(NetworkEvent));
        if (!new_events) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->events = new_events;
        manager->capacity = new_capacity;
    }
    manager->events[manager->count++] = event;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int updateEvent(EventManager* manager, int sourcePort, int destinationPort, NetworkEvent updatedEvent) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i].SourcePort == sourcePort && manager->events[i].DestinationPort == destinationPort) {
            manager->events[i] = updatedEvent;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Event not found
}

// Additional functions for calculating statistics, handling concurrency, and integrating with asynchronous I/O would be implemented here.
```

