void* message_processor(void* arg) {
    MessageHandler* handler = (MessageHandler*)arg;
    while (1) {
        Message* message = dequeue_message(handler->queue);
        if (message == NULL) break; // Exit thread on NULL message
        // Process the message
        free(message); // Free the message after processing
    }
    return NULL;
}

MessageHandler* create_message_handler(size_t initial_capacity, const char* log_directory) {
    MessageHandler* handler = (MessageHandler*)malloc(sizeof(MessageHandler));
    if (!handler) return NULL;

    handler->queue = create_message_queue(initial_capacity);
    if (!handler->queue) {
        free(handler);
        return NULL;
    }

    pthread_create(&handler->thread_id, NULL, message_processor, handler);

    // Initialize logging
    FILE* log_file = fopen(log_directory, "w");
    if (log_file) fclose(log_file); // Truncate or create the log file

    return handler;
}

void destroy_message_handler(MessageHandler* handler) {
    pthread_join(handler->thread_id, NULL);
    destroy_message_queue(handler->queue);
