#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1MB
#define LOG_FILE_PATH "/var/log/error.log"

typedef struct {
    FILE *log_file;
    size_t current_size;
    pthread_mutex_t lock;
} LogContext;

void init_log_context(LogContext *ctx) {
    ctx->log_file = fopen(LOG_FILE_PATH, "a");
    if (!ctx->log_file) {
        perror("Failed to open log file");
        exit(EXIT_FAILURE);
    }
    ctx->current_size = 0;
    pthread_mutex_init(&ctx->lock, NULL);
}

void rotate_log_file(LogContext *ctx) {
    fclose(ctx->log_file);
    char new_path[256];
    time_t now = time(NULL);
    strftime(new_path, sizeof(new_path), "/var/log/error_%Y%m%d%H%M%S.log", localtime(&now));
    ctx->log_file = fopen(new_path, "a");
    if (!ctx->log_file) {
        perror("Failed to open new log file");
        exit(EXIT_FAILURE);
    }
    ctx->current_size = 0;
}

void safe_log_message(LogContext *ctx, int enabled, const char *format, ...) {
    if (!enabled) return;

    va_list args;
    va_start(args, format);

    pthread_mutex_lock(&ctx->lock);

    size_t buffer_size = vsnprintf(NULL, 0, format, args);
    if (buffer_size >= MAX_LOG_SIZE - ctx->current_size) {
        rotate_log_file(ctx);
        ctx->current_size = 0;
    }

    char *buffer = malloc(buffer_size + 1);
    if (!buffer) {
        perror("Failed to allocate memory for log buffer");
        pthread_mutex_unlock(&ctx->lock);
        return;
    }

    vsnprintf(buffer, buffer_size + 1, format, args);

    fprintf(ctx->log_file, "%s\n", buffer);
    fflush(ctx->log_file);
    ctx->current_size += buffer_size;

    free(buffer);
    va_end(args);
    pthread_mutex_unlock(&ctx->lock);
}

void cleanup_log_context(LogContext *ctx) {
    fclose(ctx->log_file);
    pthread_mutex_destroy(&ctx->lock);
}
