from unittest.mock import patch

def update_config(config_path, params_path):
    with open(params_path, 'r') as f:
        params = json.load(f)

    for key, value in params.items():
        command = f"sed -i 's/{key}/{value}/g' {config_path}"
        try:
            subprocess.run(command, shell=True, check=True)
        except subprocess.CalledProcessError as e:
            print(f"Failed to update config: {e}", file=sys.stderr)

def test_module(module_name):
    with patch('blueslip.reset'):
        try:
            result = subprocess.run(['pytest', module_name], capture_output=True, text=True)
            if result.returncode == 0:
                print(f"{module_name} tests passed")
            else:
                print(f"{module_name} tests failed", file=sys.stderr)
                print(result.stderr, file=sys.stderr)
        except Exception as e:
            print(f"Failed to run tests for {module_name}: {e}", file=sys.stderr)

if __name__ == "__main__":
    if len(sys.argv) != 4:
        print("Usage: python script.py <config_path> <params_path> <module_name>")
        sys.exit(1)

    config_path = sys.argv[1]
    params_path = sys.argv[2]
    module_name = sys.argv[3]

    update_config(config_path, params_path)
    test_module(module_name)
