@Service
public class ModuleService {

    @Autowired
    private RestTemplate restTemplate;

    @Cacheable(value = "moduleDetails", key = "#moduleName + '_' + #version + '_' + #buildNumber")
    public ModuleDetails getModuleDetails(String moduleName, String version, String buildNumber) {
        try {
            String url = "https://metadata-service.com/api/modules?name=" + moduleName + "&version=" + version;
            if (buildNumber != null && !buildNumber.isEmpty()) {
                url += "&build=" + buildNumber;
            }
            ResponseEntity<ModuleDetails> response = restTemplate.getForEntity(url, ModuleDetails.class);
            return response.getBody();
        } catch (Exception e) {
            // Log the error and handle it appropriately
            throw new RuntimeException("Failed to retrieve module details", e);
        }
    }
}

class ModuleDetails {
    private String name;
    private String version;
    private List<String> dependencies;
    private Map<String, String> configurationSettings;
    private List<String> knownIssues;

    // Getters and setters
}
