['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

typedef struct {
    void (*task_func)(void*);
    void* arg;
} Task;

typedef struct {
    Task** tasks;
    int front, rear, size;
    sem_t task_count;
    pthread_mutex_t lock;
} TaskQueue;

typedef struct {
    pthread_t* threads;
    TaskQueue* queue;
    int num_threads;
    int shutdown_flag;
} ThreadPool;

TaskQueue* create_task_queue(int initial_size) {
    TaskQueue* q = (TaskQueue*)malloc(sizeof(TaskQueue));
    q->tasks = (Task**)malloc(initial_size * sizeof(Task*));
    q->front = q->rear = -1;
    q->size = 0;
    sem_init(&q->task_count, 0, 0);
    pthread_mutex_init(&q->lock, NULL);
    return q;
}

void enqueue_task(TaskQueue* q, Task* task) {
    pthread_mutex_lock(&q->lock);
    if (q->rear == -1) {
        q->front = q->rear = 0;
    } else {
        q->rear = (q->rear + 1) % q->size;
    }
    q->tasks[q->rear] = task;
    sem_post(&q->task_count);
    pthread_mutex_unlock(&q->lock);
}

Task* dequeue_task(TaskQueue* q) {
    Task* task = NULL;
    sem_wait(&q->task_count);
    pthread_mutex_lock(&q->lock);
    if (q->front != -1) {
        task = q->tasks[q->front];
        if (q->front == q->rear) {
            q->front = q->rear = -1;
        } else {
            q->front = (q->front + 1) % q->size;
        }
    }
    pthread_mutex_unlock(&q->lock);
    return task;
}

void* worker_thread(void* arg) {
    ThreadPool* pool = (ThreadPool*)arg;
    while (!pool->shutdown_flag) {
        Task* task = dequeue_task(pool->queue);
        if (task != NULL) {
            task->task_func(task->arg);
            free(task);
        }
    }
    return NULL;
}

ThreadPool* create_thread_pool(int num_threads, int initial_queue_size) {
    ThreadPool* pool = (ThreadPool*)malloc(sizeof(ThreadPool));
    pool->threads = (pthread_t*)malloc(num_threads * sizeof(pthread_t));
    pool->queue = create_task_queue(initial_queue_size);
    pool->num_threads = num_threads;
    pool->shutdown_flag = 0;
    for (int i = 0; i < num_threads; i++) {
        pthread_create(&pool->threads[i], NULL, worker_thread, pool);
    }
    return pool;
}

void submit_task(ThreadPool* pool, void (*task_func)(void*), void* arg) {
    Task* task = (Task*)malloc(sizeof(Task));
    task->task_func = task_func;
    task->arg = arg;
    enqueue_task(pool->queue, task);
}

void shutdown_thread_pool(ThreadPool* pool) {
    pool->shutdown_flag = 1;
    for (int i = 0; i < pool->num_threads; i++) {
        pthread_join(pool->threads[i], NULL);
    }
    free(pool->threads);
    TaskQueue* q = pool->queue;
    while (!sem_getvalue(&q->task_count, &q->size) && q->front != -1) {
        Task* task = dequeue_task(q);
        if (task != NULL) {
            free(task);
        }
    }
    sem_destroy(&q->task_count);
    pthread_mutex_destroy(&q->lock);
    free(q->tasks);
    free(q);
    free(pool);
}

void example_task(void* arg) {
    int* data = (int*)arg;
    printf("Processing task with data: %d\n", *data);
    free(data);
}

int main() {
    ThreadPool* pool = create_thread_pool(4, 10);
    for (int i = 0; i < 20; i++) {
        int* data = (int*)malloc(sizeof(int));
        *data = i;
        submit_task(pool, example_task, data);
    }
    shutdown_thread_pool(pool);
    return 0;
}
```']

