#include <random>
#include <mutex>

class MTGenerator {
public:
    static std::mt19937 global_engine;
    static std::mutex mtx;

    explicit MTGenerator(unsigned long seed = std::random_device{}());

    template<typename T>
    T generate(T min, T max);

private:
    std::mt19937 engine;
};

template<>
int MTGenerator::generate<int>(int min, int max) {
    std::lock_guard<std::mutex> lock(mtx);
    return std::uniform_int_distribution<>(min, max)(engine);
}

template<>
double MTGenerator::generate<double>(double min, double max) {
    std::lock_guard<std::mutex> lock(mtx);
    return std::uniform_real_distribution<>(min, max)(engine);
}

#endif // RANDOM_ENGINE_H
```

