// main.cpp

#include "RandomEngine.h"
#include <iostream>
#include <thread>
#include <vector>

void thread_task(MTGenerator& generator) {
    for (int i = 0; i < 1000; ++i) {
        std::cout << generator.generate(1, 100) << " ";
    }
}

int main() {
    unsigned long seed = std::stoul(std::getenv("RANDOM_SEED") ?: "42");
    MTGenerator generator(seed);

    std::vector<std::thread> threads;
    for (int i = 0; i < 10; ++i) {
        threads.emplace_back(thread_task, std::ref(generator));
    }

    for (auto& thread : threads) {
        thread.join();
    }

    return 0;
}
