public class SqlQueryExecutor
{
    public void ExecuteDynamicSql(string connectionString, string sqlCommandTemplate, List<object> parameterValues, CipherMode cipherMode)
    {
        using (SqlConnection connection = new SqlConnection(connectionString))
        {
            try
            {
                connection.Open();
                SqlCommand command = new SqlCommand(sqlCommandTemplate, connection);

                for (int i = 0; i < parameterValues.Count; i++)
                {
                    string paramName = $"@Param{i}";
                    command.Parameters.AddWithValue(paramName, parameterValues[i]);
                }

                if (cipherMode != CipherMode.Null)
                {
                    byte[] encryptedParameters = EncryptParameters(parameterValues.ToArray(), cipherMode);
                    // Assuming a method to decrypt and use the parameters
                    DecryptAndUseParameters(encryptedParameters, command);
                }

                command.ExecuteNonQuery();
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred: {ex.Message}");
            }
        }
    }

    private byte[] EncryptParameters(object[] parameters, CipherMode cipherMode)
    {
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Mode = cipherMode;
            aesAlg.GenerateKey();
            aesAlg.GenerateIV();

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);

            using (MemoryStream msEncrypt = new MemoryStream())
            {
                using (CryptoStream csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    foreach (var param in parameters)
                    {
                        byte[] dataToEncrypt = System.Text.Encoding.UTF8.GetBytes(param.ToString());
                        csEncrypt.Write(dataToEncrypt, 0, dataToEncrypt.Length);
                    }
                }

                return msEncrypt.ToArray();
            }
        }
    }

    private void DecryptAndUseParameters(byte[] encryptedParameters, SqlCommand command)
    {
