    {
        var tiles = new Dictionary<int, Tile>();
        for (long y = 0; y < _worldHeight; y++)
        {
            for (long x = 0; x < _worldWidth; x++)
            {
                int tileValue = GenerateRandomTileValue();
                tiles[(int)(y * _worldWidth + x)] = new Tile((int)x, (int)y, tileValue);
            }
        }
        return tiles;
    }

    private int GenerateRandomTileValue()
    {
        // Implement random value generation logic here
        return new Random().Next(100);
    }

    public void UpdateTile(int key, int newValue)
    {
        lock (_tiles)
        {
            if (_tiles.ContainsKey(key))
            {
                _tiles[key] = new Tile(_tiles[key].X, _tiles[key].Y, newValue);
            }
        }
    }

    public Tile GetTile(int key)
    {
        lock (_tiles)
        {
            return _tiles.ContainsKey(key) ? _tiles[key] : null;
        }
    }
