from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

# In-memory cache to store resources
resource_cache = {}

# Mock database to store resource data
database = {}

# Log table to track deletions
log_table = []

@app.route('/update/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    updated_data = request.get_json()
    if resource_id in database:
        # Update the resource in the cache and database
        resource_cache[resource_id] = updated_data
        database[resource_id] = updated_data
        return jsonify(updated_data), 200
    else:
        return jsonify({"error": "Resource not found"}), 404

@app.route('/delete/<int:resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    if resource_id in database:
        # Remove the resource from the cache and database
        deleted_resource = resource_cache.pop(resource_id, None)
        database.pop(resource_id, None)

        # Log the deletion
        log_table.append({"resource_id": resource_id, "deleted_at": datetime.now()})

        # Notify external data processing service
        notify_external_service(resource_id)

        return jsonify({"message": "Resource deleted"}), 200
    else:
        return jsonify({"error": "Resource not found"}), 404

def notify_external_service(resource_id):
    try:
        response = requests.post('https://external-service.com/notify', json={"resource_id": resource_id})
        if response.status_code != 200:
            raise Exception("Failed to notify external service")
    except Exception as e:
        # Handle failure, retry or fallback
        print(f"Notification failed: {e}")

if __name__ == '__main__':
    app.run(debug=True)
```

