[ApiController]
[Route("api/[controller]")]
public class PageSectionController : ControllerBase
{
    private readonly IDistributedCache _cache;
    private readonly IVersionControlService _versionControlService;
    private readonly ISessionTokenValidator _sessionTokenValidator;

    public PageSectionController(IDistributedCache cache, IVersionControlService versionControlService, ISessionTokenValidator sessionTokenValidator)
    {
        _cache = cache;
        _versionControlService = versionControlService;
        _sessionTokenValidator = sessionTokenValidator;
    }

    [HttpPost("update")]
    public async Task<IActionResult> UpdatePageSection(string sessionToken, int pageSectionId, string elementId, string htmlContent)
    {
        if (!_sessionTokenValidator.Validate(sessionToken))
        {
            return Unauthorized();
        }

        var cacheKey = $"pageSection_{pageSectionId}";
        var cachedPageSection = await _cache.GetStringAsync(cacheKey);

        if (cachedPageSection == null)
        {
            // Fetch from database and cache
            var pageSectionFromDb = await FetchPageSectionFromDatabase(pageSectionId);
            if (pageSectionFromDb == null)
            {
                return NotFound();
            }
            cachedPageSection = JsonConvert.SerializeObject(pageSectionFromDb);
            await _cache.SetStringAsync(cacheKey, cachedPageSection, new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) });
        }

        var pageSection = JsonConvert.DeserializeObject<PageSection>(cachedPageSection);

        if (pageSection.ElementId != elementId)
        {
            return BadRequest("Element ID mismatch");
        }

        // Optimistic Locking
        if (pageSection.Version != 0 && pageSection.Version != htmlContent.GetHashCode())
        {
            return Conflict();
        }

        pageSection.HtmlContent = htmlContent;
        pageSection.Version++;

        await _cache.SetStringAsync(cacheKey, JsonConvert.SerializeObject(pageSection), new DistributedCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(10) });

        // Version Control
        await _versionControlService.SaveVersion(pageSectionId, elementId, htmlContent);

        return Ok();
    }

    private async Task<PageSection> FetchPageSectionFromDatabase(int pageSectionId)
    {
        // Implement database fetch logic here
        return new PageSection { Id = pageSectionId, ElementId = "exampleElement", HtmlContent = "<div>Initial Content</div>", Version = 0 };
