const fs = require('fs').promises;
const path = require('path');
const { promisify } = require('util');

const readFileAsync = promisify(fs.readFile);

async function readFilesInDirectory(directory, extension, maxConcurrentOperations = 5) {
    const fileContents = {};
    let currentOperations = 0;

    async function processFile(filePath) {
        try {
            const content = await readFileAsync(filePath);
            fileContents[path.basename(filePath)] = content.toString();
            console.log(`Read ${filePath} at ${new Date().toISOString()}`);
        } catch (error) {
            console.error(`Error reading ${filePath}:`, error);
        }
    }

    async function processDirectory(dirPath) {
        try {
            const entries = await fs.readdir(dirPath, { withFileTypes: true });
            for (const entry of entries) {
                if (entry.isDirectory()) {
                    await processDirectory(path.join(dirPath, entry.name));
                } else if (path.extname(entry.name).toLowerCase() === extension.toLowerCase()) {
                    if (currentOperations < maxConcurrentOperations) {
                        currentOperations++;
                        await processFile(path.join(dirPath, entry.name));
                        currentOperations--;
                    } else {
                        await new Promise(resolve => setTimeout(resolve, 100)); // Throttle
                        await processDirectory(dirPath);
                    }
                }
            }
        } catch (error) {
            console.error(`Error processing directory ${dirPath}:`, error);
        }
    }

    await processDirectory(directory);
    return fileContents;
}

// Example usage:
readFilesInDirectory('/path/to/directory', '.txt')
    .then(contents => console.log('File contents:', contents))
    .catch(error => console.error('Error reading files:', error));
```

