            }
        }

        blueslip.reset();

        return {
            passed: passedCount,
            failed: failedCount,
            failedTests: failedTests
        };
    }

    async function loadDependencies(testModule) {
        for (const dependency of testModule.dependencies) {
            await moduleCache.loadModule(dependency);
        }
    }

    async function runTestModules() {
        for (const testModule of testModules) {
            try {
                console.log(`Loading and running tests for module: ${testModule.name}`);
                await loadDependencies(testModule);
                const module = await moduleCache.loadModule(testModule.filePath);
                Object.assign(blueslip, module.blueslip); // Assuming the module exports a blueslip object
                await runTests();
            } catch (error) {
                console.error(`Failed to load or run tests for module: ${testModule.name}`, error.stack);
            }
        }
    }

    return runTestModules().then((result) => {
        console.log(`Test suite completed. Passed: ${result.passed}, Failed: ${result.failed}`);
        return result;
    }).catch((error) => {
        console.error('An unexpected error occurred during test execution:', error.stack);
        throw error;
    });
}
