const bookNames = [
  // List of Old Testament books
  "Genesis", "Exodus", "Leviticus", "Numbers", "Deuteronomy",
  "Joshua", "Judges", "Ruth", "1 Samuel", "2 Samuel",
  "1 Kings", "2 Kings", "1 Chronicles", "2 Chronicles", "Ezra",
  "Nehemiah", "Esther", "Job", "Psalms", "Proverbs",
  "Ecclesiastes", "Song of Solomon", "Isaiahu", "Jeremiah",
  "Lamentations", "Ezekiel", "Daniel", "Hosea", "Joel",
  "Amos", "Obadiah", "Jonah", "Micah", "Nahum",
  "Habakkuk", "Zephaniah", "Haggai", "Zechariah", "Malachi",

  // List of New Testament books
  "Matthew", "Mark", "Luke", "John", "Acts",
  "Romans", "1 Corinthians", "2 Corinthians", "Galatians", "Ephesians",
  "Philippians", "Colossians", "1 Thessalonians", "2 Thessalonians", "1 Timothy",
  "2 Timothy", "Titus", "Philemon", "Hebrews", "James",
  "1 Peter", "2 Peter", "1 John", "2 John", "3 John",
  "Jude", "Revelation"
];

const regexCache = new Map();

function createRegexPattern(bookNames) {
  const escapedBookNames = bookNames.map(name => name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'));
  return new RegExp(`\\b(${escapedBookNames.join('|')})\\b`, 'gi');
}

function processText(text) {
  if (!text.trim()) return {};

  let regex = regexCache.get(bookNames);
  if (!regex) {
    regex = createRegexPattern(bookNames);
    regexCache.set(bookNames, regex);
  }

  const matches = text.match(regex);
  const bookCounts = {};

  if (matches) {
    for (const match of matches) {
      const bookName = match.toLowerCase();
      bookCounts[bookName] = (bookCounts[bookName] || 0) + 1;
    }
  }

  return bookCounts;
}

// Example usage:
const text = "In the beginning, God created the heavens and the earth. Matthew 5:38";
console.log(processText(text));
```

