["```javascript
const scriptCache = new Map();
let apiFetchPromise;

function fetchScriptMetadata(scriptId) {
  if (!apiFetchPromise) {
    apiFetchPromise = fetch('https://api.example.com/scripts')
      .then(response => response.json())
      .catch(error => console.error('API fetch error:', error));
  }
  return apiFetchPromise.then(data => data[scriptId] || {});
}

function renderScripts(scripts, criticalIds) {
  const renderedScripts = [];
  for (const script of scripts) {
    if (!scriptCache.has(script.id)) {
      const metadata = await fetchScriptMetadata(script.id);
      scriptCache.set(script.id, { ...script, ...metadata });
    }
    const cachedScript = scriptCache.get(script.id);
    const tag = document.createElement('script');
    tag.key = cachedScript.id;
    tag.innerHTML = cachedScript.code;
    if (criticalIds.includes(cachedScript.id)) {
      tag.async = false;
      tag.defer = false;
    } else {
      tag.async = true;
      tag.defer = true;
    }
    renderedScripts.push(tag.outerHTML);
  }
  return renderedScripts.join('');
}

function renderFooter(scripts, criticalIds) {
  const htmlString = renderScripts(scripts, criticalIds);
  document.body.insertAdjacentHTML('beforeend', `<footer>${htmlString}</footer>`);
}
