function refreshDialogFields(resourceId, url, fieldNames) {
    const batchSize = 10;
    let requestQueue = [];
    let retryAttempts = 3;
    let timeout = 5000;

    function fetchFieldData(fieldName) {
        return $http.get(`${url}/${resourceId}/${fieldName}`, { timeout: timeout })
            .then(response => response.data)
            .catch(error => {
                console.error(`Failed to refresh ${fieldName}:`, error);
                if (retryAttempts > 0) {
                    retryAttempts--;
                    return fetchFieldData(fieldName); // Retry logic
                }
                throw error;
            });
    }

    function processBatch(batch) {
        batch.forEach(fieldName => {
            requestQueue.push(fetchFieldData(fieldName));
        });

        Promise.all(requestQueue)
            .then(data => {
                data.forEach((fieldData, index) => {
                    const fieldName = fieldNames[batch.indexOf(fieldData)];
                    updateDialogField(fieldName, fieldData);
                    console.log(`Refreshed ${fieldName}`);
                });
                requestQueue = [];
            })
            .catch(error => {
                console.error('Batch refresh failed:', error);
            });
    }

    function updateDialogField(fieldName, data) {
        // Logic to update the dialog field with new data
    }

    for (let i = 0; i < fieldNames.length; i += batchSize) {
        const batch = fieldNames.slice(i, i + batchSize);
        processBatch(batch);
    }
}
