class DataStreamManager {
  constructor() {
    this.cache = {};
    this.paused = false;
    this.apiEndpoints = [];
    this.errorCount = 0;
    this.maxErrorsBeforePause = 10;
  }

  addAPIEndpoint(endpoint) {
    this.apiEndpoints.push(endpoint);
  }

  async fetchDataFromAPIs() {
    if (this.paused) return;

    for (const endpoint of this.apiEndpoints) {
      try {
        const response = await fetch(endpoint.url, { method: 'GET' });
        if (!response.ok) throw new Error('Network response was not ok');

        const data = await response.json();
        this.updateCache(data);
      } catch (error) {
        console.error(`Error fetching data from ${endpoint.url}:`, error);
        this.errorCount++;
        if (this.errorCount >= this.maxErrorsBeforePause) {
          this.pause();
        }
      }
    }

    setTimeout(() => this.fetchDataFromAPIs(), endpoint.updateFrequency);
  }

  updateCache(data) {
    for (const [key, value] of Object.entries(data)) {
      if (!this.cache[key]) this.cache[key] = [];
      this.cache[key].push(value);
    }
  }

  pause() {
    this.paused = true;
    console.log('Data fetching paused due to errors.');
  }

  resume() {
    this.paused = false;
    console.log('Data fetching resumed.');
    this.fetchDataFromAPIs();
  }

  reset() {
    this.cache = {};
    this.errorCount = 0;
    this.paused = false;
    console.log('Cache and state reset.');
  }
}

// Example usage:
const manager = new DataStreamManager();
manager.addAPIEndpoint({ url: 'https://api.example.com/data1', updateFrequency: 5000 });
manager.addAPIEndpoint({ url: 'https://api.example.com/data2', updateFrequency: 3000 });

manager.fetchDataFromAPIs();

// To pause and resume fetching
manager.pause();
manager.resume();

// To reset the manager
manager.reset();
