['```java
import java.util.HashMap;
import java.util.Map;

public class DisjointPairProcessor {

    private Map<Integer, Integer> parentMap;
    private Map<Integer, Integer> sizeMap;

    public DisjointPairProcessor() {
        parentMap = new HashMap<>();
        sizeMap = new HashMap<>();
    }

    public void makeSet(int element) {
        parentMap.put(element, element);
        sizeMap.put(element, 1);
    }

    public int find(int element) {
        if (!parentMap.containsKey(element)) {
            makeSet(element);
            return element;
        }
        if (element != parentMap.get(element)) {
            parentMap.put(element, find(parentMap.get(element)));
        }
        return parentMap.get(element);
    }

    public void union(int element1, int element2) {
        int root1 = find(element1);
        int root2 = find(element2);

        if (root1 != root2) {
            if (sizeMap.get(root1) < sizeMap.get(root2)) {
                parentMap.put(root1, root2);
                sizeMap.put(root2, sizeMap.get(root1) + sizeMap.get(root2));
            } else {
                parentMap.put(root2, root1);
                sizeMap.put(root1, sizeMap.get(root1) + sizeMap.get(root2));
            }
        }
    }

    public boolean areDisjoint(int element1, int element2) {
        return find(element1) != find(element2);
    }

    public static void main(String[] args) {
        DisjointPairProcessor processor = new DisjointPairProcessor();
        long startTime = System.currentTimeMillis();

        // Simulate processing a large array of integers
        for (int i = 0; i < 1_000_000; i++) {
            processor.makeSet(i);
            if (i % 2 == 0) {
                processor.union(i, i + 1);
            }
        }

        long endTime = System.currentTimeMillis();
        System.out.println("Processing time: " + (endTime - startTime) + " ms");
    }
}
```

This code snippet provides a basic implementation of the Union-Find data structure in Java to identify and count disjoint pairs of elements. It includes methods for making sets, finding roots, union operations, and checking if two elements are disjoint. The `main` method demonstrates processing an array of 1 million integers, simulating batch processing and memory management techniques.']

['```java
import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.ByteBuffer;
import java.nio.channels.AsynchronousChannelGroup;
import java.nio.channels.AsynchronousServerSocketChannel;
import java.nio.channels.AsynchronousSocketChannel;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class AsyncNetworkService {

    private AsynchronousServerSocketChannel serverChannel;
    private ExecutorService executorService;

    public AsyncNetworkService(int port, int threadPoolSize) throws IOException {
        this.executorService = Executors.newFixedThreadPool(threadPoolSize);
        this.serverChannel = AsynchronousServerSocketChannel.open(AsynchronousChannelGroup.withFixedThreadPool(threadPoolSize));
        serverChannel.bind(new InetSocketAddress(port));
        startAcceptingConnections();
    }

    private void startAcceptingConnections() {
        serverChannel.accept(null, new CompletionHandler<AsynchronousSocketChannel, Void>() {
            @Override
            public void completed(AsynchronousSocketChannel result, Void attachment) {
                handleConnection(result);
                startAcceptingConnections(); // Continue accepting connections
            }

            @Override
            public void failed(Throwable exc, Void attachment) {
                System.err.println("Failed to accept connection: " + exc.getMessage());
                startAcceptingConnections(); // Retry accepting connections
            }
        });
    }

    private void handleConnection(AsynchronousSocketChannel clientChannel) {
        ByteBuffer buffer = ByteBuffer.allocate(1024);
        clientChannel.read(buffer, buffer, new CompletionHandler<Integer, ByteBuffer>() {
            @Override
            public void completed(Integer result, ByteBuffer attachment) {
                if (result == -1) {
                    try {
                        clientChannel.close();
                    } catch (IOException e) {
                        System.err.println("Failed to close connection: " + e.getMessage());
                    }
                } else {
                    buffer.flip();
                    byte[] data = new byte[buffer.remaining()];
                    buffer.get(data);
                    String message = new String(data);
                    System.out.println("Received message: " + message);

                    // Process the message asynchronously
                    executorService.submit(() -> processMessage(message, clientChannel));

                    buffer.clear();
                    clientChannel.read(buffer, buffer, this); // Continue reading from the same channel
                }
            }

            @Override
            public void failed(Throwable exc, ByteBuffer attachment) {
                System.err.println("Failed to read data: " + exc.getMessage());
                try {
                    clientChannel.close();
                } catch (IOException e) {
                    System.err.println("Failed to close connection: " + e.getMessage());
                }
            }
        });
    }

    private void processMessage(String message, AsynchronousSocketChannel clientChannel) {
        // Process the message here
        String response = "Processed: " + message;
        ByteBuffer buffer = ByteBuffer.wrap(response.getBytes());

        try {
            clientChannel.write(buffer).get(); // Synchronously write the response
        } catch (Exception e) {
            System.err.println("Failed to send response: " + e.getMessage());
        }
    }

    public void shutdown() throws IOException {
        serverChannel.close();
        executorService.shutdown();
    }

    public static void main(String[] args) {
        try {
            AsyncNetworkService service = new AsyncNetworkService(8080, 10);
            System.out.println("Server started on port 8080");
            // Keep the application running
            Thread.sleep(Long.MAX_VALUE);
        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```']

