```rust
use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

#[derive(Serialize, Deserialize)]
struct User {
    id: u32,
    name: String,
    email: String,
    password: String,
}

type Users = Arc<Mutex<HashMap<u32, User>>>;

async fn create_user(
    user: web::Json<User>,
    users: web::Data<Users>,
) -> impl Responder {
    let mut users = users.lock().unwrap();
    let id = users.len() as u32 + 1;
    users.insert(id, user.into_inner());
    HttpResponse::Created()
        .json(json!({"message": "success", "data": {"id": id}}))
}

async fn get_user(
    web::Path(user_id): web::Path<u32>,
    users: web::Data<Users>,
) -> impl Responder {
    let users = users.lock().unwrap();
    if let Some(user) = users.get(&user_id) {
        HttpResponse::Ok()
            .json(json!({"message": "success", "data": user}))
    } else {
        HttpResponse::NotFound()
            .json(json!({"message": "error", "data": {"id": user_id}}))
    }
}

async fn update_user(
    web::Path(user_id): web::Path<u32>,
    user: web::Json<User>,
    users: web::Data<Users>,
) -> impl Responder {
    let mut users = users.lock().unwrap();
    if let Some(u) = users.get_mut(&user_id) {
        *u = user.into_inner();
        HttpResponse::Ok()
            .json(json!({"message": "success", "data": u}))
    } else {
        HttpResponse::NotFound()
            .json(json!({"message": "error", "data": {"id": user_id}}))
    }
}

async fn delete_user(
    web::Path(user_id): web::Path<u32>,
    users: web::Data<Users>,
) -> impl Responder {
    let mut users = users.lock().unwrap();
    if users.remove(&user_id).is_some() {
        HttpResponse::Ok()
            .json(json!({"message": "success", "data": {"id": user_id}}))
    } else {
        HttpResponse::NotFound()
            .json(json!({"message": "error", "data": {"id": user_id}}))
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let users = web::Data::new(Arc::new(Mutex::new(HashMap::new())));
    HttpServer::new(move || {
        App::new()
            .app_data(users.clone())
            .route("/users", web::post().to(create_user))
            .route("/users/{id}", web::get().to(get_user))
            .route("/users/{id}", web::put().to(update_user))
            .route("/users/{id}", web::delete().to(delete_user))
    })
    .bind("127.0.0.1:8080")?
    .run()
    .await
}
