<?php

class SecurityLibrary {
    private static $defaultCharacterSet = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
    private static $defaultHashStrength = 10;

    public static function generateRandomString($length = 10, $characterSet = null) {
        if ($length <= 0 || empty($characterSet)) {
            return '';
        }

        $characters = $characterSet ?: self::$defaultCharacterSet;
        $string = '';

        for ($i = 0; $i < $length; $i++) {
            $string .= $characters[random_int(0, strlen($characters) - 1)];
        }

        return $string;
    }

    public static function hashPassword($password, $hashStrength = null) {
        if (empty($password)) {
            return '';
        }

        $hashStrength = $hashStrength ?: self::$defaultHashStrength;
        $salt = self::generateRandomString(16);

        return password_hash($password . $salt, PASSWORD_BCRYPT, ['cost' => $hashStrength]);
    }
}

// Example usage:
$randomString = SecurityLibrary::generateRandomString(20, 'abcdefghijklmnopqrstuvwxyz');
echo "Random String: " . $randomString . "\n";

$hashedPassword = SecurityLibrary::hashPassword('mySecretPassword', 12);
echo "Hashed Password: " . $hashedPassword . "\n";
?>
