    private $authService;
    private $directoryService;
    private $logger;
    private $cache;

    public function __construct(UserDAO $userDAO, ExternalAuthService $authService, DirectoryService $directoryService, Logger $logger, Cache $cache) {
        $this->userDAO = $userDAO;
        $this->authService = $authService;
        $this->directoryService = $directoryService;
        $this->logger = $logger;
        $this->cache = $cache;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            // Validate password strength
            if (!$this->authService->validatePassword($newPassword)) {
                throw new Exception("Invalid password");
            }

            // Retry logic with exponential backoff for external authentication service
            $retryCount = 0;
            while ($retryCount < 5) {
                try {
                    $this->authService->updatePassword($userId, $newPassword);
                    break;
                } catch (Exception $e) {
                    if ($retryCount == 4) {
                        throw $e;
                    }
                    sleep(pow(2, $retryCount));
                    $retryCount++;
                }
            }

            // Update user password in the database
            $this->userDAO->updatePassword($userId, $newPassword);

            // Cache the updated password
            $this->cache->set("user_password_{$userId}", $newPassword);

            // Create directory for password logs
            $directoryPath = "/home/{$userId}/password_logs";
            if (!file_exists($directoryPath)) {
                if (!$this->directoryService->createDirectory($directoryPath)) {
                    $this->logger->log("Failed to create directory", ['user_id' => $userId, 'path' => $directoryPath]);
                }
            }

            // Log successful password update
            $this->logger->log("Password updated successfully", ['user_id' => $userId]);

        } catch (Exception $e) {
            // Log error and provide meaningful feedback to the calling application
            $this->logger->log("Failed to update password", ['user_id' => $userId, 'error' => $e->getMessage()]);
            throw new Exception("Failed to update password");
        }
    }
}
