#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_TRANSACTIONS 10000
#define SLIDING_WINDOW_SIZE 5

typedef struct {
    int id;
    double weight;
    time_t timestamp;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int front, rear;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} TransactionQueue;

typedef struct {
    double max_weighted_sum;
    int max_transaction_id;
    double average_weight;
    double max_value;
    size_t total_transactions;
    size_t transactions_per_second;
} Metrics;

void init_queue(TransactionQueue *queue) {
    queue->front = 0;
    queue->rear = -1;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

int enqueue(TransactionQueue *queue, Transaction transaction) {
    pthread_mutex_lock(&queue->lock);
    if (queue->count == MAX_TRANSACTIONS) {
        pthread_mutex_unlock(&queue->lock);
        return -1;
    }
    queue->rear = (queue->rear + 1) % MAX_TRANSACTIONS;
    queue->transactions[queue->rear] = transaction;
    queue->count++;
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue(TransactionQueue *queue, Transaction *transaction) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->lock);
    }
    *transaction = queue->transactions[queue->front];
    queue->front = (queue->front + 1) % MAX_TRANSACTIONS;
    queue->count--;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void process_transactions(TransactionQueue *queue, Metrics *metrics) {
    Transaction transaction;
    double total_weight = 0.0;
    size_t transaction_count = 0;

    while (dequeue(queue, &transaction) == 0) {
        if ((time(NULL) - transaction.timestamp) > SLIDING_WINDOW_SIZE) {
            continue; // Ignore old transactions
        }
        total_weight += transaction.weight;
        transaction_count++;
        if (total_weight > metrics->max_weighted_sum) {
            metrics->max_weighted_sum = total_weight;
            metrics->max_transaction_id = transaction.id;
        }
        if (transaction.weight > metrics->max_value) {
            metrics->max_value = transaction.weight;
        }
    }

    metrics->average_weight = total_weight / transaction_count;
    metrics->total_transactions += transaction_count;
    metrics->transactions_per_second = transaction_count;

    // Log transactions exceeding threshold
    if (metrics->max_weighted_sum > 1000.0) {
        printf("Transaction ID: %d, Weighted Sum: %.2f\n", metrics->max_transaction_id, metrics->max_weighted_sum);
    }
}

int main() {
    TransactionQueue queue;
    Metrics metrics = {0};

    init_queue(&queue);

    // Simulate transaction processing
    for (int i = 1; i <= 10000; i++) {
        Transaction transaction = {i, rand() % 1000.0 / 100.0, time(NULL)};
        enqueue(&queue, transaction);
        process_transactions(&queue, &metrics);
    }

    printf("Max Weighted Sum: %.2f\n", metrics.max_weighted_sum);
    printf("Max Transaction ID: %d\n", metrics.max_transaction_id);
    printf("Average Weight: %.2f\n", metrics.average_weight);
    printf("Max Value: %.2f\n", metrics.max_value);
    printf("Total Transactions Processed: %zu\n", metrics.total_transactions);
    printf("Transactions Per Second: %zu\n", metrics.transactions_per_second);

    return 0;
}
