#include <iostream>
#include <thread>
#include <chrono>
#include <mutex>
#include <functional>

class AttackStrategy {
public:
    virtual void execute() = 0;
};

class FireballAttack : public AttackStrategy {
public:
    void execute() override {
        std::cout << "Fireball attack!" << std::endl;
    }
};

class IceSpearAttack : public AttackStrategy {
public:
    void execute() override {
        std::cout << "Ice spear attack!" << std::endl;
    }
};

class LightningBoltAttack : public AttackStrategy {
public:
    void execute() override {
        std::cout << "Lightning bolt attack!" << std::endl;
    }
};

class EarthquakeAttack : public AttackStrategy {
public:
    void execute() override {
        std::cout << "Earthquake attack!" << std::endl;
    }
};

class AttackSelector {
private:
    std::mutex mutex_;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime_[4];
    AttackStrategy* strategies_[4];

public:
    AttackSelector() {
        strategies_[0] = new FireballAttack();
        strategies_[1] = new IceSpearAttack();
        strategies_[2] = new LightningBoltAttack();
        strategies_[3] = new EarthquakeAttack();

        for (int i = 0; i < 4; ++i) {
            lastAttackTime_[i] = std::chrono::system_clock::now() - std::chrono::seconds(16);
        }
    }

    ~AttackSelector() {
        for (auto& strategy : strategies_) {
            delete strategy;
        }
    }

    void selectAttack(std::function<void()> logFunction) {
        std::lock_guard<std::mutex> lock(mutex_);

        auto now = std::chrono::system_clock::now();
        int selectedAttack = -1;

        for (int i = 0; i < 4; ++i) {
            if (now - lastAttackTime_[i] >= std::chrono::seconds(5 + rand() % 11)) {
                selectedAttack = i;
                break;
            }
        }

        if (selectedAttack != -1) {
            strategies_[selectedAttack]->execute();
            logFunction("Attack " << selectedAttack);
            lastAttackTime_[selectedAttack] = now;
        } else {
            std::cout << "All attacks are on cooldown." << std::endl;
        }
    }
};

void logAttack(const std::string& message) {
    std::cout << message << std::endl;
}

int main() {
    AttackSelector selector;

    for (int i = 0; i < 10; ++i) {
        selector.selectAttack(logAttack);
        std::this_thread::sleep_for(std::chrono::seconds(1));
    }

    return 0;
}
