// Import necessary libraries
const axios = require('axios');
const logger = require('./logger'); // Assuming a custom logging library

// Define the data processing pipeline
async function processTransactions() {
  try {
    // Fetch transactions from an external API
    const response = await axios.get('https://api.example.com/transactions');
    const transactions = response.data;

    // Transform each transaction into a summary object
    const transformedData = transactions.map(transaction => ({
      id: transaction.id,
      amount: transaction.amount
    }));

    // Reduce the transformed data to calculate the total amount for completed transactions
    const totalAmount = transformedData.reduce((acc, transaction) => {
      if (transaction.status === 'completed') {
        acc += transaction.amount;
      }
      return acc;
    }, 0);

    logger.info(`Total amount of completed transactions: ${totalAmount}`);
    return totalAmount;

  } catch (error) {
    logger.error('Failed to fetch or process transactions:', error);
    throw error;
  }
}

// Test the implementation with a sample dataset
async function testProcessTransactions() {
  try {
    const result = await processTransactions();
    console.log(`Test passed. Total amount of completed transactions: ${result}`);
  } catch (error) {
    console.error('Test failed:', error);
  }
}

testProcessTransactions();
