#include <stdio.h>
#include <stdlib.h>
#include <dirent.h>
#include <pthread.h>
#include <jpeglib.h>

typedef struct {
    char *image_path;
    int orientation;
    float x_resolution_dpi;
    float y_resolution_dpi;
} ImageMetadata;

void* process_image(void* arg) {
    ImageMetadata *metadata = (ImageMetadata*)arg;
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *infile;
    JSAMPARRAY buffer;
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    if ((infile = fopen(metadata->image_path, "rb")) == NULL) {
        fprintf(stderr, "Cannot open %s\n", metadata->image_path);
        return NULL;
    }

    jpeg_stdio_src(&cinfo, infile);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    row_stride = cinfo.output_width * cinfo.output_components;

    while (cinfo.output_scanline < cinfo.output_height) {
        buffer = (*cinfo.mem->alloc_sarray)((j_common_ptr)&cinfo, JPOOL_IMAGE, row_stride, 1);
        jpeg_read_scanlines(&cinfo, buffer, 1);
    }

    jpeg_finish_decompress(&cinfo);
    fclose(infile);

    metadata->orientation = cinfo.image_orientation;
    if (cinfo.density_unit == 1) {
        metadata->x_resolution_dpi = cinfo.X_density;
        metadata->y_resolution_dpi = cinfo.Y_density;
    } else if (cinfo.density_unit == 2) {
        metadata->x_resolution_dpi = cinfo.X_density * 2.54f;
        metadata->y_resolution_dpi = cinfo.Y_density * 2.54f;
    }

    jpeg_destroy_decompress(&cinfo);
    return NULL;
}

int process_images_in_directory(const char* directory_path) {
    DIR *dir;
    struct dirent *ent;
    pthread_t threads[10000];
    ImageMetadata metadata[10000];
    int thread_count = 0;

    if ((dir = opendir(directory_path)) != NULL) {
        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0)
                continue;
            snprintf(metadata[thread_count].image_path, sizeof(metadata[thread_count].image_path), "%s/%s", directory_path, ent->d_name);
            pthread_create(&threads[thread_count], NULL, process_image, &metadata[thread_count]);
            thread_count++;
        }
        closedir(dir);
    } else {
        perror("Could not open directory");
        return 1;
    }

    for (int i = 0; i < thread_count; i++) {
        pthread_join(threads[i], NULL);
    }

    // Process metadata here

    return 0;
}
