    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_error(const char *message) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_dynamic_array(int num_elements) {
    NFAPI_CRC_INDICATION_PDU_T *array = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }
    return array;
}

void populate_array(NFAPI_CRC_INDICATION_PDU_T *array, int num_elements) {
    srand(time(NULL));
    for (int i = 0; i < num_elements; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % (MAX_TAG - MIN_TAG + 1) + MIN_TAG;
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2 == 0 ? 1 : 0; // Randomly set CRCFLAG
    }
}

void validate_and_populate_array(NFAPI_CRC_INDICATION_PDU_T *array, int num_elements) {
    for (int i = 0; i < num_elements; i++) {
        if (array[i].RX_UE_INFORMATION_TAG < MIN_TAG || array[i].RX_UE_INFORMATION_TAG > MAX_TAG) {
            log_error("Invalid RX_UE_INFORMATION_TAG");
            return;
        }
    }
    populate_array(array, num_elements);
}

void *thread_function(void *arg) {
    int *num_elements = (int *)arg;
    NFAPI_CRC_INDICATION_PDU_T *array = create_dynamic_array(*num_elements);
    if (array != NULL) {
        validate_and_populate_array(array, *num_elements);
        free(array);
    }
    return NULL;
}

int main() {
    int num_threads = 5;
    pthread_t threads[num_threads];
    int elements_per_thread = MAX_ELEMENTS / num_threads;

    for (int i = 0; i < num_threads; i++) {
        if (pthread_create(&threads[i], NULL, thread_function, &elements_per_thread) != 0) {
            log_error("Thread creation failed");
            return 1;
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
