#include <pthread.h>

#define NR_PHY_MEASUREMENT 1024

typedef struct {
    int tag;
    int tx_power_level;
    int rx_quality_factor;
} PHY_MEASUREMENT_TAG;

typedef struct {
    PHY_MEASUREMENT_TAG *measurements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *array) {
    array->measurements = (PHY_MEASUREMENT_TAG *)malloc(NR_PHY_MEASUREMENT * sizeof(PHY_MEASUREMENT_TAG));
    if (!array->measurements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = NR_PHY_MEASUREMENT;
    pthread_mutex_init(&array->lock, NULL);
}

void add_measurement(DynamicArray *array, PHY_MEASUREMENT_TAG measurement) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        PHY_MEASUREMENT_TAG *new_measurements = (PHY_MEASUREMENT_TAG *)realloc(array->measurements, new_capacity * sizeof(PHY_MEASUREMENT_TAG));
        if (!new_measurements) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->measurements = new_measurements;
        array->capacity = new_capacity;
    }
    array->measurements[array->count++] = measurement;
    pthread_mutex_unlock(&array->lock);
}

void export_to_csv(DynamicArray *array, const char *filename) {
    FILE *file = fopen(filename, "w");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        fprintf(file, "%d,%d,%d\n", array->measurements[i].tag, array->measurements[i].tx_power_level, array->measurements[i].rx_quality_factor);
    }
    pthread_mutex_unlock(&array->lock);
    fclose(file);
}

void clear_measurements(DynamicArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->measurements);
    array->measurements = (PHY_MEASUREMENT_TAG *)malloc(NR_PHY_MEASUREMENT * sizeof(PHY_MEASUREMENT_TAG));
    if (!array->measurements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = NR_PHY_MEASUREMENT;
    pthread_mutex_unlock(&array->lock);
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->measurements);
    pthread_mutex_destroy(&array->lock);
}
