#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define NFAPI_CRC_INDICATION_REL8_TAG 0x1
#define NFAPI_CRC_INDICATION_REL15_TAG 0x2

typedef struct {
    int crc_flag;
    time_t last_modified;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} CRC_Indication_List;

CRC_Indication_List* create_crc_indication_list(size_t initial_capacity) {
    CRC_Indication_List *list = (CRC_Indication_List*)malloc(sizeof(CRC_Indication_List));
    if (!list) return NULL;

    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->data) {
        free(list);
        return NULL;
    }

    list->size = 0;
    list->capacity = initial_capacity;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_crc_indication_list(CRC_Indication_List *list) {
    if (list) {
        free(list->data);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_crc_indication(CRC_Indication_List *list, int crc_flag) {
    pthread_mutex_lock(&list->lock);

    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1;
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[list->size++];
    pdu->crc_flag = crc_flag;
    time_t current_time;
    time(&current_time);
    pdu->last_modified = current_time;

    pthread_mutex_unlock(&list->lock);

    return 0;
}

void print_crc_indication_list(CRC_Indication_List *list) {
    pthread_mutex_lock(&list->lock);

    for (size_t i = 0; i < list->size; ++i) {
        printf("CRC Flag: %d, Last Modified: %s", list->data[i].crc_flag, ctime(&list->data[i].last_modified));
    }

    pthread_mutex_unlock(&list->lock);
}

int main() {
    CRC_Indication_List *list = create_crc_indication_list(10);
    if (!list) {
        fprintf(stderr, "Failed to create CRC indication list\n");
        return 1;
    }

    add_crc_indication(list, NFAPI_CRC_INDICATION_REL8_TAG);
    add_crc_indication(list, NFAPI_CRC_INDICATION_REL15_TAG);

    print_crc_indication_list(list);

    destroy_crc_indication_list(list);

    return 0;
}
