#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_IP_RANGE 100

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    manager->capacity = initial_capacity;
    manager->size = 0;
    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    free(manager->flows);
    free(manager);
}

int add_or_update_flow(TrafficManager *manager, const char *source_ip, const char *destination_ip, int packet_count) {
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->flows[i].SourceIP, source_ip) == 0 && strcmp(manager->flows[i].DestinationIP, destination_ip) == 0) {
            manager->flows[i].PacketCount += packet_count;
            return 1;
        }
    }

    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->flows = (TrafficFlow*)realloc(manager->flows, manager->capacity * sizeof(TrafficFlow));
    }

    strcpy(manager->flows[manager->size].SourceIP, source_ip);
    strcpy(manager->flows[manager->size].DestinationIP, destination_ip);
    manager->flows[manager->size].PacketCount = packet_count;
    ++manager->size;

    return 0;
}

void print_statistics(TrafficManager *manager) {
    if (manager->size == 0) {
        printf("No traffic flows recorded.\n");
        return;
    }

    int total_packets = 0;
    int max_packets = manager->flows[0].PacketCount;

    for (size_t i = 1; i < manager->size; ++i) {
        if (manager->flows[i].PacketCount > max_packets) {
            max_packets = manager->flows[i].PacketCount;
        }
        total_packets += manager->flows[i].PacketCount;
    }

    double average_packets = (double)total_packets / manager->size;

    printf("Total Packet Count: %d\n", total_packets);
    printf("Maximum Flow Packet Count: %d\n", max_packets);
    printf("Average Packet Count per Flow: %.2f\n", average_packets);
}

int main() {
    TrafficManager *manager = create_traffic_manager(10);

    add_or_update_flow(manager, "192.168.1.1", "10.0.0.1", 50);
    add_or_update_flow(manager, "192.168.1.2", "10.0.0.2", 30);
    add_or_update_flow(manager, "192.168.1.1", "10.0.0.1", 20);

    print_statistics(manager);

    destroy_traffic_manager(manager);

    return 0;
}
