NFAPI_CRC_INDICATION_PDU_T* memory_pool[MEMORY_POOL_SIZE];
int pool_index = 0;

void initialize_memory_pool() {
    for (int i = 0; i < MEMORY_POOL_SIZE; i++) {
        memory_pool[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!memory_pool[i]) {
            fprintf(stderr, "Failed to allocate memory for memory pool\n");
            exit(EXIT_FAILURE);
        }
    }
}

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(int N) {
    if (N > MAX_ELEMENTS) {
        fprintf(stderr, "Requested number of elements exceeds maximum limit\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int retry_count = 0;

    while (!array && retry_count < 5) {
        array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array) {
            fprintf(stderr, "Out of memory. Retrying...\n");
            sleep(1);
            retry_count++;
        }
    }

    if (!array) {
        fprintf(stderr, "Failed to allocate memory after retries\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].CRCFLAG = rand() % 2;
    }

    return array;
}

void log_allocation(int call_count) {
    time_t now = time(NULL);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    FILE* log_file = fopen(LOG_DIR "/allocation_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file\n");
        return;
    }

    fprintf(log_file, "[%s] Allocation call count: %d\n", timestamp, call_count);
    fclose(log_file);
}

void* thread_safe_allocate_memory(int N) {
    static int call_count = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_memory(N);
    if (array) {
        log_allocation(++call_count);
    }

    pthread_mutex_unlock(&mutex);

    return array;
}

