typedef struct SubscriberIdentifier {
    char imsi[15];
    char meid[20];
    int signalStrength;
} SubscriberIdentifier;

typedef struct NetworkEvent {
    int EventTag;
    time_t Timestamp;
    SubscriberIdentifier *subscribers;
    int subscriberCount;
} NetworkEvent;

NetworkEvent* initializeNetworkEvents(int eventCount, int maxSubscribers) {
    NetworkEvent *events = (NetworkEvent*)malloc(eventCount * sizeof(NetworkEvent));
    if (!events) return NULL;

    for (int i = 0; i < eventCount; i++) {
        events[i].EventTag = i + 1;
        events[i].Timestamp = time(NULL);
        events[i].subscribers = (SubscriberIdentifier*)malloc(maxSubscribers * sizeof(SubscriberIdentifier));
        if (!events[i].subscribers) {
            // Handle memory allocation failure
            for (int j = 0; j < i; j++) free(events[j].subscribers);
            free(events);
            return NULL;
        }
        events[i].subscriberCount = 0;

        // Simulate fetching subscriber data from an external source
        for (int j = 0; j < maxSubscribers; j++) {
            snprintf(events[i].subscribers[j].imsi, sizeof(events[i].subscribers[j].imsi), "IMSI%012d", i * maxSubscribers + j);
            snprintf(events[i].subscribers[j].meid, sizeof(events[i].subscribers[j].meid), "MEID%019d", i * maxSubscribers + j);
            // Simulate dynamic signal strength calculation
            events[i].subscribers[j].signalStrength = rand() % 31; // Random value between 0 and 30
        }
    }

    return events;
}

void freeNetworkEvents(NetworkEvent *events, int eventCount) {
    for (int i = 0; i < eventCount; i++) {
        free(events[i].subscribers);
    }
    free(events);
}

int main() {
    srand(time(NULL));
    NetworkEvent *networkEvents = initializeNetworkEvents(5, 10);
    if (!networkEvents) {
        printf("Failed to initialize network events.\n");
        return 1;
    }

    // Simulate processing network events
    for (int i = 0; i < 5; i++) {
        printf("Event Tag: %d, Timestamp: %s", networkEvents[i].EventTag, ctime(&networkEvents[i].Timestamp));
        for (int j = 0; j < networkEvents[i].subscriberCount; j++) {
            printf("  Subscriber %d - IMSI: %s, MEID: %s, Signal Strength: %d\n",
                   j + 1, networkEvents[i].subscribers[j].imsi,
                   networkEvents[i].subscribers[j].meid,
                   networkEvents[i].subscribers[j].signalStrength);
        }
    }

    freeNetworkEvents(networkEvents, 5);
    return 0;
}
