void destroyLinkedList(LinkedList* list) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current->session.profile->activities);
        free(current->session.profile);
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

void addSession(LinkedList* list, UserSession session) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    newNode->session = session;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void removeSession(LinkedList* list, unsigned long sessionId) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current != NULL) {
        if (current->session.SessionId == sessionId) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->session.profile->activities);
            free(current->session.profile);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void logSessionChange(UserSession session, const char* action) {
    // Implement logging mechanism here
    printf("Action: %s, SessionId: %lu, Timestamp: %ld\n", action, session.SessionId, session.Timestamp);
}
