#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <netdb.h>

#define MAX_CONCURRENT_REQUESTS 10
#define BACKOFF_FACTOR 2
#define MAX_BACKOFF_RETRIES 5

typedef struct {
    u_char ip[4];
} IPAddress;

int dns_resolve(const char *hostname, IPAddress *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
        memcpy(ip_address->ip, &(ipv4->sin_addr), 4);
        freeaddrinfo(res); // Free the linked list
        return 0;
    }

    freeaddrinfo(res); // Free the linked list if no addresses were found
    return -1;
}

int main() {
    IPAddress ip;
    const char *hostname = "example.com";

    if (dns_resolve(hostname, &ip) == 0) {
        printf("IP Address: %d.%d.%d.%d\n", ip.ip[0], ip.ip[1], ip.ip[2], ip.ip[3]);
    } else {
        printf("Failed to resolve hostname.\n");
    }

    return 0;
}
```

This code snippet provides a basic implementation of the DNS resolution function in C. It uses the `getaddrinfo` function from the `<netdb.h>` library to perform the resolution and returns the IP address in a `u_char` array. Error handling is included, and the function attempts to resolve the hostname using IPv4 addresses only. The main function demonstrates how to call the `dns_resolve` function and print the resolved IP address.']

