    if (!event) return NULL;

    event->EventTag = event_tag;
    event->Timestamp = timestamp;
    event->subscribers = NULL;
    event->subscriber_count = 0;

    return event;
}

void add_subscriber_to_event(NetworkEvent *event, const char *imsi, const char *meid, int signal_strength) {
    SubscriberIdentifier *new_subscriber = (SubscriberIdentifier*)realloc(event->subscribers, (event->subscriber_count + 1) * sizeof(SubscriberIdentifier));
    if (!new_subscriber) return;

    event->subscribers = new_subscriber;
    SubscriberIdentifier *current_subscriber = &event->subscribers[event->subscriber_count];
    current_subscriber->signal_strength = signal_strength;
    strncpy(current_subscriber->imsi, imsi, sizeof(current_subscriber->imsi));
    strncpy(current_subscriber->meid, meid, sizeof(current_subscriber->meid));

    event->subscriber_count++;
}

void free_network_event(NetworkEvent *event) {
    if (event->subscribers) {
        free(event->subscribers);
    }
    free(event);
}
