#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1000
#define MAX_RNTI 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* dynamic_array[MAX_ELEMENTS];
int array_size = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
FILE* log_file = fopen("memory_allocation_errors.log", "w");

void log_error(const char* message) {
    fprintf(log_file, "%s\n", message);
}

bool is_valid_rnti(int rnti) {
    return rnti >= 0 && rnti < MAX_RNTI;
}

int find_available_rnti() {
    for (int i = 0; i < MAX_RNTI; i++) {
        bool available = true;
        pthread_mutex_lock(&mutex);
        for (int j = 0; j < array_size; j++) {
            if (dynamic_array[j]->RNTI == i) {
                available = false;
                break;
            }
        }
        pthread_mutex_unlock(&mutex);
        if (available) return i;
    }
    return -1;
}

NFAPI_CRC_INDICATION_PDU_T* create_new_element(int rx_tag, int rnti) {
    NFAPI_CRC_INDICATION_PDU_T* new_element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_element == NULL) {
        log_error("Memory allocation failed");
        return NULL;
    }
    new_element->RX_UE_INFORMATION_TAG = rx_tag;
    new_element->RNTI = rnti;
    new_element->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    return new_element;
}

void add_to_array(int rx_tag) {
    pthread_mutex_lock(&mutex);
    if (array_size >= MAX_ELEMENTS) {
        log_error("Array is full");
        pthread_mutex_unlock(&mutex);
        return;
    }
    int rnti = find_available_rnti();
    if (!is_valid_rnti(rnti)) {
        log_error("No available RNTI");
        pthread_mutex_unlock(&mutex);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T* new_element = create_new_element(rx_tag, rnti);
    if (new_element != NULL) {
        dynamic_array[array_size++] = new_element;
    }
    pthread_mutex_unlock(&mutex);
}

void monitor_health() {
    // Implement health monitoring logic here
}

void cache_rnti_values() {
    // Implement caching mechanism for RNTI values here
}

void handle_external_source_unavailability() {
    // Implement fallback strategy for RNTI allocation in case of external source unavailability here
}

void* manage_dynamic_array(void* arg) {
    int rx_tag = *(int*)arg;
    add_to_array(rx_tag);
    return NULL;
}

int main() {
    srand(time(NULL));
    pthread_t threads[MAX_ELEMENTS];
    int rx_tags[MAX_ELEMENTS];

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        rx_tags[i] = rand() % 1000;
        if (pthread_create(&threads[i], NULL, manage_dynamic_array, &rx_tags[i]) != 0) {
            log_error("Failed to create thread");
        }
    }

    for (int i = 0; i < MAX_ELEMENTS; i++) {
        pthread_join(threads[i], NULL);
    }

    monitor_health();
    cache_rnti_values();
    handle_external_source_unavailability();

    fclose(log_file);
    return 0;
}
