    pthread_mutex_lock(&mutex);

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        pduList[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pduList[i].RNTI = rand() % 256;
        pduList[i].CRC_INDICATION_REL8_TAG = rand() % 2;

