            fprintf(stderr, "Invalid CRC flag value: %d\n", pduList[i].CRC_INDICATION_REL8_TAG);
            free(pduList);
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
    }

    pthread_mutex_unlock(&mutex);

    // Simulate processing of PDUs
    for (int i = 0; i < N; i++) {
