               i, pduList[i].RX_UE_INFORMATION_TAG, pduList[i].RNTI, pduList[i].CRC_INDICATION_REL8_TAG);
    }

    free(pduList);
    return NULL;
}

// JavaScript function for DOM traversal
function DOMTraversal(element, selector) {
    let result = [];
    if (selector(element)) {
        result.push(element);
    }
    for (let i = 0; i < element.children.length; i++) {
        result = result.concat(DOMTraversal(element.children[i], selector));
    }
    return result;
}
