#include <string.h>
#include <pthread.h>

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    if (!manager) return NULL;

    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    if (!manager->flows) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->flows);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_flow(TrafficManager *manager, const char *source_ip, const char *destination_ip, int packet_count) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->flows[i].SourceIP, source_ip) == 0 && strcmp(manager->flows[i].DestinationIP, destination_ip) == 0) {
            manager->flows[i].PacketCount += packet_count;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Updated existing flow
        }
    }

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        TrafficFlow *new_flows = (TrafficFlow*)realloc(manager->flows, new_capacity * sizeof(TrafficFlow));
        if (!new_flows) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->flows = new_flows;
        manager->capacity = new_capacity;
    }

    strcpy(manager->flows[manager->size].SourceIP, source_ip);
    strcpy(manager->flows[manager->size].DestinationIP, destination_ip);
    manager->flows[manager->size].PacketCount = packet_count;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Added new flow
}

// Additional functions for retrieving statistics and pruning infrequent flows can be implemented here

int main() {
    TrafficManager *manager = create_traffic_manager(100);
    if (!manager) {
        fprintf(stderr, "Failed to create traffic manager\n");
        return 1;
    }

    // Example usage
    add_or_update_flow(manager, "192.168.1.1", "10.0.0.1", 50);
    add_or_update_flow(manager, "192.168.1.1", "10.0.0.1", 30);

    destroy_traffic_manager(manager);
    return 0;
}
