#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_STRUCTURES 1000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int count;
    pthread_mutex_t mutex;
} CircularDoublyLinkedList;

void initialize_list(CircularDoublyLinkedList *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_structure(int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_struct == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_struct->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_struct->RNTI = RNTI;
    new_struct->next = NULL;
    new_struct->prev = NULL;
    return new_struct;
}

void add_to_list(CircularDoublyLinkedList *list, NFAPI_CRC_INDICATION_PDU_T *new_struct) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_struct;
        list->tail = new_struct;
        new_struct->next = new_struct;
        new_struct->prev = new_struct;
    } else {
        list->tail->next = new_struct;
        new_struct->prev = list->tail;
        list->tail = new_struct;
        new_struct->next = list->head;
    }
    list->count++;
    pthread_mutex_unlock(&list->mutex);
}

void initialize_array(int N, CircularDoublyLinkedList *list) {
    if (N < 1 || N > MAX_STRUCTURES) {
        fprintf(stderr, "Invalid number of structures. Must be between 1 and %d\n", MAX_STRUCTURES);
        exit(1);
    }

    for (int i = 0; i < N; i++) {
        int RX_UE_INFORMATION_TAG = rand() % 1000;
        int RNTI = rand() % 1000;
        int CRCFLAG = rand() % 2;
        NFAPI_CRC_INDICATION_PDU_T *new_struct = create_structure(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG);
        add_to_list(list, new_struct);
    }
}

int main() {
    CircularDoublyLinkedList list;
    initialize_list(&list);

    int N = 500; // Example value
    initialize_array(N, &list);

    // Additional code to traverse and use the list

    return 0;
}
