void init_pdu_list(PDU_List *list, size_t initial_capacity) {
    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdu_list) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
