#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char session_id[100];
    time_t event_time;
    int network_status;
} NetworkEvent;

typedef struct {
    NetworkEvent *events;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} EventPool;

void initialize_event_pool(EventPool *pool, size_t initial_capacity) {
    pool->events = (NetworkEvent *)malloc(initial_capacity * sizeof(NetworkEvent));
    if (!pool->events) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->capacity = initial_capacity;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void expand_event_pool(EventPool *pool) {
    size_t new_capacity = pool->capacity * 2;
    NetworkEvent *new_events = (NetworkEvent *)realloc(pool->events, new_capacity * sizeof(NetworkEvent));
    if (!new_events) {
        fprintf(stderr, "Memory reallocation failed\n");
        exit(EXIT_FAILURE);
    }
    pool->events = new_events;
    pool->capacity = new_capacity;
}

void add_event_to_pool(EventPool *pool, NetworkEvent event) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count == pool->capacity) {
        expand_event_pool(pool);
    }
    pool->events[pool->count++] = event;
    pthread_mutex_unlock(&pool->lock);
}

void filter_events_by_time(EventPool *pool, time_t threshold) {
    pthread_mutex_lock(&pool->lock);
    size_t i = 0, j = 0;
    while (j < pool->count) {
        if (pool->events[j].event_time >= threshold) {
            pool->events[i++] = pool->events[j];
        }
        j++;
    }
    pool->count = i;
    pthread_mutex_unlock(&pool->lock);
}

void free_event_pool(EventPool *pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->events);
}
