typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_or_update_flow(TrafficManager *manager, const TrafficFlow *new_flow) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->flows[i].SourceIP, new_flow->SourceIP) == 0 &&
            strcmp(manager->flows[i].DestinationIP, new_flow->DestinationIP) == 0) {
            manager->flows[i] = *new_flow;
            pthread_mutex_unlock(&manager->lock);
            return 1; // Updated
        }
    }
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        TrafficFlow *new_flows = (TrafficFlow*)realloc(manager->flows, new_capacity * sizeof(TrafficFlow));
        if (!new_flows) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->flows = new_flows;
        manager->capacity = new_capacity;
    }
    manager->flows[manager->size++] = *new_flow;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Added
}

