int load_resource_bundle(const char *file_path, NFAPI_CRC_LIST_T *crc_list) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        return -1; // File not found or cannot be opened
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    crc_list->capacity = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    crc_list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(crc_list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_list->pdu_list) {
        fclose(file);
        return -2; // Memory allocation failed
    }

    size_t elements_read = fread(crc_list->pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), crc_list->capacity, file);
    crc_list->size = elements_read;

    fclose(file);

    if (elements_read != crc_list->capacity) {
        free(crc_list->pdu_list);
        return -3; // File corruption or incomplete read
    }

    return 0; // Success
}

void initialize_crc_list(NFAPI_CRC_LIST_T *crc_list) {
    pthread_mutex_init(&crc_list->mutex, NULL);
    crc_list->pdu_list = NULL;
    crc_list->capacity = 0;
    crc_list->size = 0;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *crc_list) {
    pthread_mutex_lock(&crc_list->mutex);
    free(crc_list->pdu_list);
    crc_list->pdu_list = NULL;
    crc_list->capacity = 0;
    crc_list->size = 0;
    pthread_mutex_unlock(&crc_list->mutex);
    pthread_mutex_destroy(&crc_list->mutex);
}

int add_crc_pdu(NFAPI_CRC_LIST_T *crc_list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&crc_list->mutex);

    if (crc_list->size >= crc_list->capacity) {
        size_t new_capacity = crc_list->capacity ? crc_list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_pdu_list = (NFAPI_CRC_INDICATION_PDU_T *)realloc(crc_list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdu_list) {
            pthread_mutex_unlock(&crc_list->mutex);
            return -1; // Memory reallocation failed
        }
        crc_list->pdu_list = new_pdu_list;
        crc_list->capacity = new_capacity;
    }

    crc_list->pdu_list[crc_list->size++] = pdu;

    pthread_mutex_unlock(&crc_list->mutex);
    return 0; // Success
}
