#define MAX_EVENTS 1000
#define MEMORY_POOL_SIZE 4096

typedef struct {
    int session_id;
    time_t event_time;
    char network_status[50];
} NetworkEvent;

typedef struct {
    NetworkEvent *events[MAX_EVENTS];
    int count;
    pthread_mutex_t lock;
} EventPool;

void* memory_pool = NULL;
int pool_index = 0;

NetworkEvent* allocate_event() {
    if (pool_index >= MEMORY_POOL_SIZE) {
        return malloc(sizeof(NetworkEvent));
    }
    return &((NetworkEvent*)memory_pool)[pool_index++];
}

void deallocate_event(NetworkEvent *event) {
    if ((char*)event < memory_pool || (char*)event >= memory_pool + MEMORY_POOL_SIZE) {
        free(event);
    } else {
        pool_index--;
    }
}

void initialize_event_pool() {
    memory_pool = malloc(MEMORY_POOL_SIZE * sizeof(NetworkEvent));
    pthread_mutex_init(&pool->lock, NULL);
}

void destroy_event_pool() {
    pthread_mutex_destroy(&pool->lock);
    free(memory_pool);
}

int fetch_and_process_events(EventPool *pool, time_t threshold) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->count; i++) {
        NetworkEvent *event = pool->events[i];
        if (event->event_time < threshold) {
            deallocate_event(event);
            pool->events[i] = NULL;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return pool->count;
}

void* fetch_data_thread(void *arg) {
    EventPool *pool = (EventPool*)arg;
    // Simulate fetching data from remote CSV feeds
    for (int i = 0; i < MAX_EVENTS; i++) {
        NetworkEvent *event = allocate_event();
        event->session_id = rand() % 1000;
        event->event_time = time(NULL) - rand() % 365 * 24 * 60 * 60;
        snprintf(event->network_status, sizeof(event->network_status), "Status%d", i);
        pthread_mutex_lock(&pool->lock);
        pool->events[pool->count++] = event;
        pthread_mutex_unlock(&pool->lock);
    }
    return NULL;
}

int main() {
    EventPool pool;
    initialize_event_pool();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, fetch_data_thread, &pool);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    time_t threshold = time(NULL) - 365 * 24 * 60 * 60;
    int remaining_events = fetch_and_process_events(&pool, threshold);

    destroy_event_pool();
    return 0;
}
