typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    int PacketCount;
    double TransactionValue;
    double TransactionWeight;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* create_traffic_manager(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_traffic_manager(TrafficManager *manager) {
    free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_flow(TrafficManager *manager, TrafficFlow flow) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->flows = (TrafficFlow*)realloc(manager->flows, manager->capacity * sizeof(TrafficFlow));
    }
    manager->flows[manager->size++] = flow;
    pthread_mutex_unlock(&manager->lock);
}

void update_flow(TrafficManager *manager, char *source_ip, TrafficFlow new_flow) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->flows[i].SourceIP, source_ip) == 0) {
            manager->flows[i] = new_flow;
            break;
        }
    }
    pthread_mutex_unlock(&manager->lock);
}

double get_total_packet_count(TrafficManager *manager) {
    double total = 0;
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        total += manager->flows[i].PacketCount;
    }
    pthread_mutex_unlock(&manager->lock);
    return total;
}

// Add other functions as needed to support the requirements

int main() {
    TrafficManager *manager = create_traffic_manager(1024);

    // Example usage
    TrafficFlow flow = {"192.168.1.1", "10.0.0.1", 100, 500.0, 1.5};
    add_flow(manager, flow);
    update_flow(manager, "192.168.1.1", (TrafficFlow){"192.168.1.1", "10.0.0.1", 200, 1000.0, 2.5});

    printf("Total Packet Count: %f\n", get_total_packet_count(manager));

    destroy_traffic_manager(manager);
    return 0;
}
