#define MAX_RNTI_VALUES 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_nfaapi_crc_list(size_t initial_capacity) {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    list->pdus = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_nfaapi_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_pdu_to_list(NFAPI_CRC_LIST_T *list, RX_UE_INFORMATION_TAG ue_info, uint16_t rnti, CRC_INDICATION_REL8_TAG crc_indication) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pdus = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pdus) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }

    if (list->count > 0 && list->pdus[list->count - 1].rnti == rnti) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Duplicate RNTI
    }

    list->pdus[list->count].ue_info = ue_info;
    list->pdus[list->count].rnti = rnti;
    list->pdus[list->count].crc_indication = crc_indication;
    list->count++;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

// Additional functions for managing the list, such as resizing, removing elements, and iterating over the list can be implemented here.
