    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    size_t num_entries_in_file = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (num_entries_in_file > MAX_ENTRIES) {
        fprintf(stderr, "Too many entries in the file\n");
        fclose(file);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* bundle = malloc(num_entries_in_file * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!bundle) {
        perror("Failed to allocate memory for resource bundle");
        fclose(file);
        return NULL;
    }

    size_t entries_read = fread(bundle, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_entries_in_file, file);
    if (entries_read != num_entries_in_file) {
        fprintf(stderr, "Failed to read all entries from the file\n");
        free(bundle);
        fclose(file);
        return NULL;
    }

    *num_entries = num_entries_in_file;
    fclose(file);
    return bundle;
}

void populate_nfaapi_list(NFAPI_CRC_INDICATION_PDU_T* list, size_t num_entries) {
    for (size_t i = 0; i < num_entries; ++i) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[i].RNTI = rand() % 256;
        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

int main() {
    size_t num_entries;
    NFAPI_CRC_INDICATION_PDU_T* resource_bundle = load_resource_bundle("resource_bundle.bin", &num_entries);
    if (!resource_bundle) {
        return EXIT_FAILURE;
    }

    NFAPI_CRC_INDICATION_PDU_T* nfaapi_list = malloc(num_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaapi_list) {
        perror("Failed to allocate memory for NFAPI list");
        free(resource_bundle);
        return EXIT_FAILURE;
    }

    populate_nfaapi_list(nfaapi_list, num_entries);

    // Use the nfaapi_list as needed

    free(nfaapi_list);
    free(resource_bundle);
    return EXIT_SUCCESS;
}
