    LTE_UE_Context *contexts[MAX_UE_CONTEXTS];
    int count;
    pthread_mutex_t mutex;
} UE_List;

void init_ue_list(UE_List *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_ue_context(UE_List *list, LTE_UE_Context *context) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_UE_CONTEXTS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    for (int i = 0; i < list->count; i++) {
        if (list->contexts[i]->ue_id == context->ue_id) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate UE-ID
        }
    }
    list->contexts[list->count++] = context;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

LTE_UE_Context* get_ue_context(UE_List *list, int ue_id) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            LTE_UE_Context *context = list->contexts[i];
            pthread_mutex_unlock(&list->mutex);
            return context;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void remove_ue_context(UE_List *list, int ue_id) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->contexts[i]->ue_id == ue_id) {
            free(list->contexts[i]);
            for (int j = i; j < list->count - 1; j++) {
                list->contexts[j] = list->contexts[j + 1];
            }
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

void destroy_ue_list(UE_List *list) {
    for (int i = 0; i < list->count; i++) {
        free(list->contexts[i]);
    }
    pthread_mutex_destroy(&list->mutex);
}
