    int key;
    char* data_buffer;
    int index;
} DATA_STRUCT;

typedef struct {
    int reference_count;
} METADATA_STRUCT;

typedef struct {
    pthread_mutex_t lock;
    DATA_STRUCT** data_pool;
    int pool_size;
    int pool_index;
} MEMORY_POOL;

NFAPI_SET1_DATA* create_nfaapi_set1_data(int rnti, char crcflag) {
    NFAPI_SET1_DATA* data = (NFAPI_SET1_DATA*)malloc(sizeof(NFAPI_SET1_DATA));
    data->rx_tag = RX_UE_INFORMATION_TAG;
    data->rnti = rnti;
    data->crc_tag.CRCFLAG = crcflag;
    return data;
}

DATA_STRUCT* create_data_struct(int size) {
    DATA_STRUCT* data = (DATA_STRUCT*)malloc(sizeof(DATA_STRUCT));
    data->offset = rand();
    data->key = rand() % 1000;
    data->data_buffer = (char*)malloc(size);
    for (int i = 0; i < size; i++) {
        data->data_buffer[i] = 'a' + rand() % 26;
    }
    data->index = rand() % 1000;
    return data;
}

METADATA_STRUCT* create_metadata_struct() {
    METADATA_STRUCT* metadata = (METADATA_STRUCT*)malloc(sizeof(METADATA_STRUCT));
    metadata->reference_count = 1;
    return metadata;
}

void initialize_memory_pool(MEMORY_POOL* pool, int size) {
    pthread_mutex_init(&pool->lock, NULL);
    pool->data_pool = (DATA_STRUCT**)malloc(size * sizeof(DATA_STRUCT*));
    pool->pool_size = size;
    pool->pool_index = 0;
}

DATA_STRUCT* allocate_from_memory_pool(MEMORY_POOL* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->pool_index < pool->pool_size) {
        DATA_STRUCT* data = create_data_struct(rand() % 100 + 1); // Random size between 1 and 100
        pool->data_pool[pool->pool_index++] = data;
        pthread_mutex_unlock(&pool->lock);
        return data;
    } else {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
}

void free_data_struct(DATA_STRUCT* data) {
    free(data->data_buffer);
    free(data);
}

void reclaim_memory(MEMORY_POOL* pool, DATA_STRUCT* data) {
    pthread_mutex_lock(&pool->lock);
    for (int i = 0; i < pool->pool_index; i++) {
        if (pool->data_pool[i] == data) {
            pool->data_pool[i] = NULL;
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}

void update_metadata(METADATA_STRUCT* metadata, int increment) {
    pthread_mutex_lock(&metadata->lock);
    metadata->reference_count += increment;
    pthread_mutex_unlock(&metadata->lock);
}
