DynamicList* dynamic_list_create(size_t initial_capacity) {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    free(list->pdu_list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int dynamic_list_add(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T pdu, uint16_t max_rnti) {
    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->pdu_list = new_list;
        list->capacity = new_capacity;
    }

    while (list->count > 0 && list->pdu_list[list->count - 1].rnti == pdu.rnti) {
        list->count--;
    }

    if (list->count >= max_rnti) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Maximum RNTI limit reached
    }

    list->pdu_list[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

