using System;
using System.Data;
using System.Data.SqlClient;

public static IDataReader CreateParameterizedCommand(string sqlQuery, List<object> values, SqlConnection connection)
{
    if (connection == null || !connection.State.Equals(ConnectionState.Open))
    {
        throw new ArgumentException("Connection must be open.");
    }

    using (SqlCommand command = new SqlCommand(sqlQuery, connection))
    {
        for (int i = 0; i < values.Count; i++)
        {
            command.Parameters.AddWithValue($"@Param{i}", values[i]);
        }
        return command.ExecuteReader(CommandBehavior.CloseConnection);
    }
