import os
from Crypto.Cipher import DES3, DES, CFBMode
from Crypto.Util.Padding import pad, unpad
from urllib.request import urlopen, Request
from urllib.error import URLError, HTTPError
import time

def encrypt_file(file_path, mode='ECB', key=None):
    if not key:
        raise ValueError("Key must be provided for encryption")

    cipher = None
    if mode == 'ECB':
        cipher = DES.new(key, DES.MODE_ECB)
    elif mode == 'EDE':
        cipher = DES3.new(key, DES3.MODE_EDE)
    elif mode == 'EDE3':
        cipher = DES3.new(key, DES3.MODE_EDE3)
    elif mode == 'CFB':
        cipher = CFBMode.new(key)
    else:
        raise ValueError("Unsupported encryption mode")

    with open(file_path, 'rb') as file:
        data = file.read()
        encrypted_data = cipher.encrypt(pad(data, cipher.block_size))

    return encrypted_data

def hash_file(file_path, algorithm='md5'):
    hasher = hashlib.new(algorithm)
    chunk_size = 1024 * 1024  # 1 MB
    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hasher.update(data)

    return hasher.hexdigest()

def download_file(url, timeout=30):
    request = Request(url)
    try:
        response = urlopen(request, timeout=timeout)
        with open('temp_file', 'wb') as file:
            while True:
                data = response.read(1024 * 1024)  # 1 MB
                if not data:
                    break
                file.write(data)
        return 'temp_file'
    except (URLError, HTTPError) as e:
        print(f"Failed to download file: {e}")
        return None

def process_file(file_source, mode='ECB', key=None, timeout=30):
    if file_source.startswith('http'):
        file_path = download_file(file_source, timeout)
        if not file_path:
            return None
    else:
        file_path = file_source

    encrypted_data = encrypt_file(file_path, mode, key)
    md5_hash = hash_file(file_path, 'md5')
    sha256_hash = hash_file(file_path, 'sha256')

    os.remove(file_path)  # Clean up temporary file if downloaded from remote source

    return {
        'encrypted_data': encrypted_data,
        'hashes': {
            'md5': md5_hash,
            'sha256': sha256_hash
        }
    }

# Example usage:
result = process_file('http://example.com/file.txt', mode='CFB', key=b'1234567890123456')
print(result)
```

This code snippet provides a modular function `process_file` that integrates cryptographic operations and file hashing functionalities. It supports DES-based ciphers (ECB, EDE, EDE3, and CFB modes) and computes MD5 and SHA-256 hashes for a file. The function is designed to handle files from various sources, including local storage and remote servers, with a focus on minimizing memory usage and optimizing performance. It includes error handling and graceful degradation strategies.']

