import os
import re
import subprocess
from concurrent.futures import ThreadPoolExecutor

def modify_kickstart_config(config_path, replacements):
    try:
        with open(config_path, 'r') as file:
            config_content = file.read()

        for placeholder, value in replacements.items():
            config_content = config_content.replace(placeholder, value)

        new_config_path = f"{config_path}.modified"
        with open(new_config_path, 'w') as file:
            file.write(config_content)

        return new_config_path
    except Exception as e:
        print(f"Error modifying Kickstart configuration: {e}")
        return None

def rename_files(file_paths):
    def rename_file(file_path):
        try:
            base_name, ext = os.path.splitext(os.path.basename(file_path))
            if 'log' in base_name.lower():
                digits_to_add = (len(base_name) + 1) // 2
            else:
                digits_to_add = len(base_name) // 3

            new_base_name = f"{base_name[:255 - digits_to_add - len(ext)]}{digits_to_add:0{digits_to_add}}{ext}"
            new_file_path = os.path.join(os.path.dirname(file_path), new_base_name)

            if not os.path.exists(new_file_path):
                os.rename(file_path, new_file_path)

        except Exception as e:
            print(f"Error renaming file {file_path}: {e}")

    with ThreadPoolExecutor() as executor:
        executor.map(rename_file, file_paths)

# Example usage
config_path = 'path/to/kickstart.ks'
replacements = {'%PLACEHOLDER%', 'actual_value'}
new_config_path = modify_kickstart_config(config_path, replacements)
if new_config_path:
    print(f"Modified configuration saved to {new_config_path}")

file_paths = ['path/to/logfile.log', 'path/to/datafile.bin']
rename_files(file_paths)
