#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

#define MAX_FILES 100
#define GC_FREQUENCY 5

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** file_list[MAX_FILES];
int file_count = 0;
int gc_counter = 0;

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T* pdu = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pdu->RX_UE_INFORMATION_TAG = rand();
    pdu->RNTI = rand();
    pdu->CRC_INDICATION_REL8_TAG = rand();
    pdu->CRCFLAG = rand() % 2;
    return pdu;
}

int load_file(const char* filename) {
    gzFile file = gzopen(filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T** new_list = safe_malloc((file_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    memcpy(new_list, file_list, file_count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu();
        if (gzread(file, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T)) != sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
            free(pdu);
            break;
        }
        new_list[file_count++] = pdu;
    }

    gzclose(file);
    file_list[gc_counter] = new_list;
    gc_counter = (gc_counter + 1) % MAX_FILES;

    if (file_count >= MAX_FILES) {
        fprintf(stderr, "Too many files loaded\n");
        return -1;
    }

    return 0;
}

void perform_gc() {
    for (int i = 0; i < file_count; i++) {
        free(file_list[i]);
    }
    file_count = 0;
}

void* thread_safe_access(int index) {
    if (index >= file_count || index < 0) {
        fprintf(stderr, "Invalid index\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T** list = file_list[index];
    void* data = safe_malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy(data, list[index], sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (++gc_counter >= GC_FREQUENCY) {
        perform_gc();
    }

    return data;
}

int main() {
    srand(time(NULL));
    load_file("example.gz");
    void* data = thread_safe_access(0);
    printf("CRCFLAG: %d\n", ((NFAPI_CRC_INDICATION_PDU_T*)data)->CRCFLAG);
    free(data);
    return 0;
}
