import json

class NetworkConfigManager:
    _factories = {}

    @staticmethod
    def register_factory(id, factory):
        NetworkConfigManager._factories[id] = factory

    @staticmethod
    def create_from_json(json_str):
        data = json.loads(json_str)
        config_type = data.get('type')
        if config_type in NetworkConfigManager._factories:
            return NetworkConfigManager._factories[config_type](data)
        else:
            raise ValueError(f"Unknown configuration type: {config_type}")

    def __init__(self, data):
        self.data = data

class SubNetworkConfig(NetworkConfigManager):
    @classmethod
    def from_json(cls, json_str):
        return cls(json.loads(json_str))

# Example usage
NetworkConfigManager.register_factory('sub', SubNetworkConfig.from_json)
config_json = '{"type": "sub", "data": {"key": "value"}}'
