        // Allocate memory for DL_FRAME_BUFFER based on max_frame_size
        frames[i].buffer = malloc(max_frame_size);
        if (!frames[i].buffer) {
            // Handle memory allocation failure for individual buffer
            // Free previously allocated buffers and return NULL
            for (int j = 0; j < i; j++) {
                free(frames[j].buffer);
            }
            free(frames);
            return NULL;
        }

        // Initialize DL_FRAME_BUFFER if necessary
        memset(frames[i].buffer, 0, max_frame_size);
    }

    return frames;
