#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

uint8_t* generateCRCIndicationsMD5(uint32_t numUEs) {
    if (numUEs <= 0) {
        return NULL; // Handle invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *crcArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray) {
        return NULL; // Handle memory allocation failure
    }

    uint8_t crcFlag = 0;
    for (uint32_t i = 0; i < numUEs; ++i) {
        crcArray[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag for each UE
        crcArray[i].RNTI = i * 256; // Example RNTI calculation
        crcArray[i].CRC_INDICATION_REL8_TAG = crcFlag;
        crcFlag = (crcFlag == 0) ? 1 : 0; // Toggle CRC flag to ensure no two adjacent structures have the same value
    }

    uint8_t *md5Hash = (uint8_t *)malloc(MD5_DIGEST_LENGTH);
    if (!md5Hash) {
        free(crcArray); // Free allocated memory before returning NULL
        return NULL; // Handle memory allocation failure
    }

    MD5_CTX md5Context;
    MD5_Init(&md5Context);

    for (uint32_t i = 0; i < numUEs; ++i) {
        MD5_Update(&md5Context, &crcArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    MD5_Final(md5Hash, &md5Context);

    free(crcArray); // Free allocated memory for CRC array

    return md5Hash;
}
