#include <arpa/inet.h>
#include <netdb.h>

#define N 100
#define M 50

typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

int create_and_populate_nfaapi_list(NFAPI_CRC_INDICATION_PDU_T *list, int N) {
    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = generate_rx_ue_info_tag(); // Assume this function exists
        list[i].RNTI = generate_rnti(); // Assume this function exists
        list[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
    return N;
}

int resolve_hostnames(char **hostnames, char *ip_addresses[], int M) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    for (int i = 0; i < M && hostnames[i] != NULL; i++) {
        if ((status = getaddrinfo(hostnames[i], NULL, &hints, &res)) != 0) {
            fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
            return -1;
        }

        for (p = res; p != NULL; p = p->ai_next) {
            void *addr;
            char ipstr[INET6_ADDRSTRLEN];

            // get the pointer to the address itself,
            // different fields in IPv4 and IPv6:
            if (p->ai_family == AF_INET) { // IPv4
                struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
                addr = &(ipv4->sin_addr);
            } else { // IPv6
                struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)p->ai_addr;
                addr = &(ipv6->sin6_addr);
            }

            // convert the IP to a string and print it:
            inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
            strcpy(ip_addresses[i], ipstr);
        }
        freeaddrinfo(res); // free the linked list
    }
    return M;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T *nfaapi_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfaapi_list == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    char **hostnames = (char **)malloc(M * sizeof(char *));
    for (int i = 0; i < M; i++) {
        hostnames[i] = (char *)malloc(256 * sizeof(char));
        if (hostnames[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
    }

    char **ip_addresses = (char **)malloc(M * sizeof(char *));
    for (int i = 0; i < M; i++) {
        ip_addresses[i] = (char *)malloc(INET6_ADDRSTRLEN * sizeof(char));
        if (ip_addresses[i] == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            return -1;
        }
    }

    int num_nfaapi_entries = create_and_populate_nfaapi_list(nfaapi_list, N);
    if (num_nfaapi_entries < 0) {
        free(nfaapi_list);
        for (int i = 0; i < M; i++) {
            free(hostnames[i]);
            free(ip_addresses[i]);
        }
        free(hostnames);
        free(ip_addresses);
        return -1;
    }

    int num_ip_addresses = resolve_hostnames(hostnames, ip_addresses, M);
    if (num_ip_addresses < 0) {
        free(nfaapi_list);
        for (int i = 0; i < M; i++) {
            free(hostnames[i]);
            free(ip_addresses[i]);
        }
        free(hostnames);
        free(ip_addresses);
        return -1;
    }

    // Free allocated memory
    free(nfaapi_list);
    for (int i = 0; i < M; i++) {
        free(hostnames[i]);
        free(ip_addresses[i]);
    }
    free(hostnames);
    free(ip_addresses);

    return 0;
}
