void log_creation(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Implement logging logic here
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_crc_indication_pdu_array(int N, int* error_code) {
    if (N <= 0) {
        *error_code = -1; // Invalid input
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        *error_code = -2; // Memory allocation failed
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    int* rnti_set = (int*)calloc(N, sizeof(int));
    if (!rnti_set) {
        free(array);
        *error_code = -3; // Memory allocation failed
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        int rnti;
        do {
            rnti = rand() % 10000; // Generate a random RNTI
        } while (rnti_set[rnti / 32] & (1 << (rnti % 32))); // Ensure uniqueness

        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].RNTI = rnti;
        array[i].CRC_INDICATION_REL8_TAG = i + 100;
        array[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        rnti_set[rnti / 32] |= (1 << (rnti % 32)); // Mark RNTI as used
        log_creation(&array[i]);
    }

    free(rnti_set);
    *error_code = 0; // Success
    return array;
}

void free_nfaapi_crc_indication_pdu_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        free(array);
    }
}
