void configureCommunicationStackWithPDUs(const char* configFilePath, int maxEntries) {
    FILE* configFile = fopen(configFilePath, "r");
    if (!configFile) {
        perror("Failed to open configuration file");
        return;
    }

    NFAPI_MCP_MESSAGE_PDU_T** pdus = (NFAPI_MCP_MESSAGE_PDU_T**)malloc(maxEntries * sizeof(NFAPI_MCP_MESSAGE_PDU_T*));
    if (!pdus) {
        perror("Memory allocation failed for PDUs");
        fclose(configFile);
        return;
    }

    PDU_T** pds = (PDU_T**)malloc(maxEntries * sizeof(PDU_T*));
    if (!pds) {
        perror("Memory allocation failed for PDs");
        free(pdus);
        fclose(configFile);
        return;
    }

    int entryCount = 0;

    while (entryCount < maxEntries && fscanf(configFile, "%d %d %d", &pdus[entryCount]->RX_UE_INFORMATION_TAG, &pdus[entryCount]->RNTI, &pdus[entryCount]->MCP_MESSAGE_TAG) == 3) {
        if (entryCount > 0 && pdus[entryCount]->RNTI == pdus[entryCount - 1]->RNTI) {
            fprintf(stderr, "Error: Duplicate RNTI detected\n");
            continue;
        }

        pds[entryCount] = (PDU_T*)malloc(sizeof(PDU_T));
        if (!pds[entryCount]) {
            perror("Memory allocation failed for PDU");
            free(pdus);
            free(pds);
            fclose(configFile);
            return;
        }

        // Initialize PDU fields
        pds[entryCount]->MCP_MESSAGE_TAG = pdus[entryCount]->MCP_MESSAGE_TAG;
