typedef struct {
    int MAC_INSTANCE_ID;
    int CELL_ID;
    time_t TIMESTAMP;
    int CHANNEL_STATE;
} MAC_CONTEXT_T;

MAC_CONTEXT_T* allocate_and_populate_mac_contexts(int num_elements) {
    if (num_elements <= 0) {
        return NULL;
    }

    MAC_CONTEXT_T* mac_contexts = (MAC_CONTEXT_T*)malloc(num_elements * sizeof(MAC_CONTEXT_T));
    if (mac_contexts == NULL) {
        // Handle memory allocation failure
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    int cell_ids[num_elements];
    for (int i = 0; i < num_elements; i++) {
        do {
            mac_contexts[i].CELL_ID = rand() % 10000; // Generate a random CELL_ID
        } while (i > 0 && mac_contexts[i].CELL_ID == cell_ids[i - 1]); // Ensure uniqueness

        cell_ids[i] = mac_contexts[i].CELL_ID;

