#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>
#include <arpa/inet.h>

#define MAX_NFAPIS 1000
#define DNS_CACHE_SIZE 100
#define RATE_LIMIT 10

typedef struct {
    int rx_ue_information_tag;
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char hostname[256];
    struct in_addr ip_address;
    time_t last_resolved;
} DNS_CACHE_ENTRY_T;

NFAPI_CRC_INDICATION_PDU_T nfapi_list[MAX_NFAPIS];
DNS_CACHE_ENTRY_T dns_cache[DNS_CACHE_SIZE];
int cache_index = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cache_cv = PTHREAD_COND_INITIALIZER;
int cache_count = 0;

void* resolve_dns(void* arg) {
    char* hostname = (char*)arg;
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        struct sockaddr_in* h = (struct sockaddr_in*)p->ai_addr;
        memcpy(&dns_cache[cache_index].ip_address, &h->sin_addr, sizeof(struct in_addr));
        dns_cache[cache_index].last_resolved = time(NULL);
        strcpy(dns_cache[cache_index].hostname, hostname);
        cache_index = (cache_index + 1) % DNS_CACHE_SIZE;
        cache_count++;
        break;
    }

    freeaddrinfo(res);
    return NULL;
}

void* populate_nfaapi_list(void* arg) {
    int n = *(int*)arg;
    pthread_t dns_thread;

    for (int i = 0; i < n; i++) {
        nfapi_list[i].rx_ue_information_tag = rand() % 1000;
        nfapi_list[i].rnti = rand() % 65536;
        nfapi_list[i].crc_indication_rel8_tag = rand() % 2;

        char hostname[256];
        snprintf(hostname, sizeof(hostname), "example%d.com", i);

        pthread_mutex_lock(&cache_lock);
        for (int j = 0; j < DNS_CACHE_SIZE; j++) {
            if (strcmp(dns_cache[j].hostname, hostname) == 0 && time(NULL) - dns_cache[j].last_resolved < 3600) {
                memcpy(&nfapi_list[i].ip_address, &dns_cache[j].ip_address, sizeof(struct in_addr));
                pthread_mutex_unlock(&cache_lock);
                continue;
            }
        }

        if (pthread_create(&dns_thread, NULL, resolve_dns, hostname) != 0) {
            fprintf(stderr, "Failed to create DNS thread\n");
            pthread_mutex_unlock(&cache_lock);
            continue;
        }

        pthread_join(dns_thread, NULL);
        pthread_mutex_unlock(&cache_lock);
    }

    return NULL;
}

int main() {
    int n = 100;

    if (pthread_create(NULL, NULL, populate_nfaapi_list, &n) != 0) {
        fprintf(stderr, "Failed to create thread\n");
        return 1;
    }

    pthread_join(NULL, NULL);

    for (int i = 0; i < n; i++) {
        printf("NFAPILIST[%d]: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d, IP_ADDRESS=%s\n",
               i, nfapi_list[i].rx_ue_information_tag, nfapi_list[i].rnti,
               nfapi_list[i].crc_indication_rel8_tag, inet_ntoa(nfapi_list[i].ip_address));
    }

    return 0;
}
