#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <openssl/md5.h>
#include <openssl/sha.h>

#define MAX_FILES 1000
#define MAX_PATH_LENGTH 256

typedef struct {
    char rx_ue_information_tag[MAX_PATH_LENGTH];
    int rnti;
    int crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char file_path[MAX_PATH_LENGTH];
    unsigned char md5_hash[MD5_DIGEST_LENGTH];
    unsigned char sha256_hash[SHA256_DIGEST_LENGTH];
} FileHashResult;

void* compute_hashes(void* arg) {
    FileHashResult* result = (FileHashResult*)arg;
    FILE* file = fopen(result->file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    unsigned char buffer[1024 * 1024]; // 1 MB chunk size
    size_t bytes_read;

    MD5_CTX md5_ctx;
    SHA256_CTX sha256_ctx;
    MD5_Init(&md5_ctx);
    SHA256_Init(&sha256_ctx);

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5_Update(&md5_ctx, buffer, bytes_read);
        SHA256_Update(&sha256_ctx, buffer, bytes_read);
    }

    fclose(file);

    MD5_Final(result->md5_hash, &md5_ctx);
    SHA256_Final(result->sha256_hash, &sha256_ctx);

    return NULL;
}

void generate_nfaapi_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T pdus[n];
    for (int i = 0; i < n; i++) {
        snprintf(pdus[i].rx_ue_information_tag, MAX_PATH_LENGTH, "RX_UE_%d", i);
        pdus[i].rnti = rand() % 1024;
        pdus[i].crc_indication_rel8_tag = rand() % 2;
    }
}

void process_files(char* file_paths[], int num_files) {
    pthread_t threads[MAX_FILES];
    FileHashResult results[MAX_FILES];

    for (int i = 0; i < num_files; i++) {
        results[i].file_path = file_paths[i];
        if (pthread_create(&threads[i], NULL, compute_hashes, &results[i]) != 0) {
            perror("Failed to create thread");
            return;
        }
    }

    for (int i = 0; i < num_files; i++) {
        pthread_join(threads[i], NULL);
    }

    // Process results and validate file integrity
}

int main() {
    char* file_paths[MAX_FILES] = {"file1.txt", "file2.txt", /* ... */};
    int num_files = sizeof(file_paths) / sizeof(file_paths[0]);

    generate_nfaapi_crc_indication_pdu(num_files);
    process_files(file_paths, num_files);

    return 0;
}
