typedef struct {
    NFAPI_LTE_PDU_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArrayT;

DynamicArrayT* dynamic_array_create(size_t initial_capacity) {
    DynamicArrayT *da = (DynamicArrayT*)malloc(sizeof(DynamicArrayT));
    da->array = (NFAPI_LTE_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_LTE_PDU_T));
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->mutex, NULL);
    return da;
}

void dynamic_array_destroy(DynamicArrayT *da) {
    free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int dynamic_array_add(DynamicArrayT *da, NFAPI_LTE_PDU_T item) {
    pthread_mutex_lock(&da->mutex);
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        NFAPI_LTE_PDU_T *new_array = (NFAPI_LTE_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_LTE_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = item;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int dynamic_array_update(DynamicArrayT *da, size_t index, NFAPI_LTE_PDU_T item) {
    if (index >= da->size) return -1; // Index out of bounds
    pthread_mutex_lock(&da->mutex);
    da->array[index] = item;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

int dynamic_array_remove(DynamicArrayT *da, size_t index) {
    if (index >= da->size) return -1; // Index out of bounds
    pthread_mutex_lock(&da->mutex);
    for (size_t i = index; i < da->size - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }
    --da->size;
    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void validate_thresholds(DynamicArrayT *da, void (*validate_func)(NFAPI_LTE_PDU_T)) {
    pthread_mutex_lock(&da->mutex);
    for (size_t i = 0; i < da->size; ++i) {
        validate_func(da->array[i]);
    }
    pthread_mutex_unlock(&da->mutex);
}

