#include <sys/statvfs.h>

#define MAX_FILES 100
#define BUFFER_SIZE 4096

typedef struct {
    int NFAPI_CRC_INDICATION_PDU_T;
    // Add other fields as needed
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_NFAPI_CRC_INDICATION_PDU(int N) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory for NFAPI CRC Indication PDU list");
        return NULL;
    }
    // Initialize each structure with valid values
    for (int i = 0; i < N; i++) {
        pdu_list[i].NFAPI_CRC_INDICATION_PDU_T = i; // Example initialization
        // Set other fields as needed
    }
    return pdu_list;
}

void* compute_hashes(void* arg) {
    char** file_paths = (char**)arg;
    int num_files = 0;
    while (file_paths[num_files] != NULL) {
        num_files++;
    }

    for (int i = 0; i < num_files; i++) {
        FILE* file = fopen(file_paths[i], "rb");
        if (!file) {
            perror("Failed to open file");
            continue;
        }

        struct statvfs buf;
        if (statvfs(file_paths[i], &buf) != 0) {
            perror("Failed to get file system statistics");
            fclose(file);
            continue;
        }

        unsigned long long total_size = buf.f_blocks * buf.f_frsize;
        unsigned long long bytes_read = 0;

        while (bytes_read < total_size) {
            char buffer[BUFFER_SIZE];
            size_t bytes_to_read = sizeof(buffer);
            if (total_size - bytes_read < bytes_to_read) {
                bytes_to_read = total_size - bytes_read;
            }

            size_t bytes_actually_read = fread(buffer, 1, bytes_to_read, file);
            if (bytes_actually_read == 0) {
                break;
            }

            // Update MD5 and SHA-256 hashes here
            // Example:
            // md5.update(buffer, bytes_actually_read);
            // sha256.update(buffer, bytes_actually_read);

            bytes_read += bytes_actually_read;
        }

        fclose(file);
    }

    return NULL;
}

int main() {
    char* file_paths[MAX_FILES + 1] = {"file1.txt", "file2.txt", NULL}; // Add more file paths as needed

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, compute_hashes, file_paths) != 0) {
        perror("Failed to create thread");
        return EXIT_FAILURE;
    }

    if (pthread_join(thread_id, NULL) != 0) {
        perror("Failed to join thread");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
