DynamicArray_T* dynamic_array_create(size_t initial_capacity) {
    DynamicArray_T *array = (DynamicArray_T*)malloc(sizeof(DynamicArray_T));
    array->array = (NFAPI_LTE_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_LTE_PDU_T));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void dynamic_array_destroy(DynamicArray_T *array) {
    free(array->array);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

void dynamic_array_add(DynamicArray_T *array, NFAPI_LTE_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->array = (NFAPI_LTE_PDU_T*)realloc(array->array, array->capacity * sizeof(NFAPI_LTE_PDU_T));
    }
    array->array[array->size++] = element;
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_update(DynamicArray_T *array, size_t index, NFAPI_LTE_PDU_T new_element) {
    pthread_mutex_lock(&array->mutex);
    if (index < array->size) {
        array->array[index] = new_element;
    }
    pthread_mutex_unlock(&array->mutex);
}

void dynamic_array_remove(DynamicArray_T *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index < array->size) {
        for (size_t i = index; i < array->size - 1; ++i) {
            array->array[i] = array->array[i + 1];
        }
        --array->size;
    }
    pthread_mutex_unlock(&array->mutex);
}

void* validate_tags(void *arg) {
