#define MAX_ELEMENTS 10000

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* prev;
    struct Node* next;
} Node;

typedef struct DoublyLinkedList {
    Node* head;
    Node* tail;
    pthread_mutex_t mutex;
} DoublyLinkedList;

void initList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

int addElement(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL || list->tail == NULL) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        newNode->data = data;
        newNode->prev = NULL;
        newNode->next = NULL;
        list->head = newNode;
        list->tail = newNode;
    } else if (list->tail->next == NULL) {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        newNode->data = data;
        newNode->prev = list->tail;
        newNode->next = NULL;
        list->tail->next = newNode;
        list->tail = newNode;
    } else {
        Node* newNode = (Node*)malloc(sizeof(Node));
        if (newNode == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        newNode->data = data;
        newNode->prev = list->tail;
        newNode->next = NULL;
        list->tail->next = newNode;
        list->tail = newNode;
    }
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void freeList(DoublyLinkedList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    DoublyLinkedList list;
    initList(&list);

    NFAPI_CRC_INDICATION_PDU_T data;
    // Populate data from external source
    for (int i = 0; i < MAX_ELEMENTS + 100; i++) {
        data.RX_UE_INFORMATION_TAG = i;
        data.RNTI = i * 2;
        data.CRCFLAG = (data.RNTI % 5 == 0) ? 1 : 0;
        if (addElement(&list, data) != 0) {
            printf("Failed to add element\n");
        }
    }

    freeList(&list);
    return 0;
}
