enum AttackType { ATTACK_ONE, ATTACK_TWO };

class GameCharacter {
private:
    std::atomic<AttackType> currentAttack;
    std::chrono::time_point<std::chrono::system_clock> lastAttackTime;
    std::mutex attackMutex;

public:
    GameCharacter() : currentAttack(ATTACK_ONE), lastAttackTime(std::chrono::system_clock::now()) {}

    AttackType selectAttack(const std::string& configFilePath) {
        std::lock_guard<std::mutex> lock(attackMutex);
        auto now = std::chrono::system_clock::now();
        if (now - lastAttackTime < std::chrono::seconds(9)) {
            return currentAttack;
        }
        currentAttack = (currentAttack == ATTACK_ONE) ? ATTACK_TWO : ATTACK_ONE;
        lastAttackTime = now;

        // Log the attack choice and timestamp
        std::ofstream auditLog("audit_log.txt", std::ios::app);
        if (auditLog.is_open()) {
            auditLog << "Attack: " << currentAttack << ", Timestamp: " << std::chrono::system_clock::to_time_t(now) << std::endl;
            auditLog.close();
        }

        return currentAttack;
    }
};

int main() {
    GameCharacter character;
    AttackType selectedAttack = character.selectAttack("config.txt");
    std::cout << "Selected Attack: " << selectedAttack << std::endl;

    return 0;
}
