typedef struct {
    char* buffer;
    int key;
    double value;
} Entry;

typedef struct {
    Entry** entries;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} EntryPool;

EntryPool* create_entry_pool(size_t initial_capacity, size_t max_entries) {
    EntryPool* pool = (EntryPool*)malloc(sizeof(EntryPool));
    pool->entries = (Entry**)calloc(initial_capacity, sizeof(Entry*));
    pool->capacity = initial_capacity;
    pool->size = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void destroy_entry_pool(EntryPool* pool) {
    for (size_t i = 0; i < pool->size; ++i) {
        free(pool->entries[i]->buffer);
        free(pool->entries[i]);
    }
    free(pool->entries);
    pthread_mutex_destroy(&pool->lock);
    free(pool);
}

Entry* allocate_entry(EntryPool* pool, size_t buffer_size) {
    Entry* entry = (Entry*)malloc(sizeof(Entry));
    entry->buffer = (char*)malloc(buffer_size);
    entry->key = 0;
    entry->value = 0.0;

    pthread_mutex_lock(&pool->lock);
    if (pool->size < pool->capacity) {
        pool->entries[pool->size++] = entry;
    } else {
        // Handle pool full scenario, e.g., expand the pool
        Entry** new_entries = (Entry**)realloc(pool->entries, pool->capacity * 2 * sizeof(Entry*));
        if (new_entries) {
            pool->entries = new_entries;
            pool->entries[pool->size++] = entry;
            pool->capacity *= 2;
        } else {
            free(entry->buffer);
            free(entry);
            pthread_mutex_unlock(&pool->lock);
            return NULL; // Handle memory allocation failure
        }
    }
    pthread_mutex_unlock(&pool->lock);

    return entry;
}

void deallocate_entry(EntryPool* pool, Entry* entry) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->size; ++i) {
        if (pool->entries[i] == entry) {
            free(entry->buffer);
            free(entry);
            pool->entries[i] = pool->entries[--pool->size];
            break;
        }
    }
    pthread_mutex_unlock(&pool->lock);
}
