#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    char SourceIP[16];
    char DestinationIP[16];
    unsigned long PacketCount;
} TrafficFlow;

typedef struct {
    TrafficFlow *flows;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TrafficManager;

TrafficManager* traffic_manager_init(size_t initial_capacity) {
    TrafficManager *manager = (TrafficManager*)malloc(sizeof(TrafficManager));
    manager->flows = (TrafficFlow*)calloc(initial_capacity, sizeof(TrafficFlow));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void traffic_manager_add(TrafficManager *manager, TrafficFlow flow) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        manager->capacity *= 2;
        manager->flows = realloc(manager->flows, manager->capacity * sizeof(TrafficFlow));
    }
    manager->flows[manager->size++] = flow;
    pthread_mutex_unlock(&manager->lock);
}

void traffic_manager_update(TrafficManager *manager, TrafficFlow new_flow) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (strcmp(manager->flows[i].SourceIP, new_flow.SourceIP) == 0 &&
            strcmp(manager->flows[i].DestinationIP, new_flow.DestinationIP) == 0) {
            manager->flows[i].PacketCount += new_flow.PacketCount;
            pthread_mutex_unlock(&manager->lock);
            return;
        }
    }
    traffic_manager_add(manager, new_flow);
    pthread_mutex_unlock(&manager->lock);
}

void traffic_manager_compress(TrafficManager *manager) {
    pthread_mutex_lock(&manager->lock);
    TrafficFlow *new_flows = (TrafficFlow*)calloc(manager->capacity, sizeof(TrafficFlow));
    size_t new_size = 0;
    for (size_t i = 0; i < manager->size; ++i) {
        int found = 0;
        for (size_t j = 0; j < new_size; ++j) {
            if (strcmp(new_flows[j].SourceIP, manager->flows[i].SourceIP) == 0 &&
                strcmp(new_flows[j].DestinationIP, manager->flows[i].DestinationIP) == 0) {
                new_flows[j].PacketCount += manager->flows[i].PacketCount;
                found = 1;
                break;
            }
        }
        if (!found) {
            new_flows[new_size++] = manager->flows[i];
        }
    }
    free(manager->flows);
    manager->flows = new_flows;
    manager->size = new_size;
    pthread_mutex_unlock(&manager->lock);
}

void traffic_manager_destroy(TrafficManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->flows);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
