    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            free(array->messages[i].extension);
            memmove(&array->messages[i], &array->messages[i + 1], (array->count - i - 1) * sizeof(NFAPI_MESSAGE_T));
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Message not found
}

NFAPI_MESSAGE_T* get_message(DynamicArray *array, int id) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            NFAPI_MESSAGE_T *message = malloc(sizeof(NFAPI_MESSAGE_T));
            memcpy(message, &array->messages[i], sizeof(NFAPI_MESSAGE_T));
            pthread_mutex_unlock(&array->lock);
            return message;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL; // Message not found
}

