#define MAX_PAYLOAD_SIZE 1024

typedef struct {
    int id;
    time_t timestamp;
    char payload[MAX_PAYLOAD_SIZE];
} Message;

typedef struct {
    Message* messages;
    size_t count;
    size_t capacity;
} MessageArray;

void initMessageArray(MessageArray* array) {
    array->messages = NULL;
    array->count = 0;
    array->capacity = 0;
}

void freeMessageArray(MessageArray* array) {
    for (size_t i = 0; i < array->count; ++i) {
        // Assuming payload is dynamically allocated, if needed
    }
    free(array->messages);
    array->messages = NULL;
    array->count = 0;
    array->capacity = 0;
}

void addMessage(MessageArray* array, Message message) {
    if (array->count >= array->capacity) {
        size_t new_capacity = (array->capacity == 0) ? 1 : array->capacity * 2;
        Message* new_messages = realloc(array->messages, new_capacity * sizeof(Message));
        if (!new_messages) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->count++] = message;
}

void removeMessageById(MessageArray* array, int id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            memmove(&array->messages[i], &array->messages[i + 1], (array->count - i - 1) * sizeof(Message));
            --array->count;
            break;
        }
    }
}

Message* getMessageById(const MessageArray* array, int id) {
    for (size_t i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            return &array->messages[i];
        }
    }
    return NULL;
}

void serializeMessageArray(const MessageArray* array, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }
    fwrite(&array->count, sizeof(size_t), 1, file);
    for (size_t i = 0; i < array->count; ++i) {
        fwrite(&array->messages[i], sizeof(Message), 1, file);
    }
    fclose(file);
}

void deserializeMessageArray(MessageArray* array, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        fprintf(stderr, "Failed to open file for reading\n");
        return;
    }
    size_t count;
    fread(&count, sizeof(size_t), 1, file);
    initMessageArray(array);
    array->messages = realloc(array->messages, count * sizeof(Message));
    array->capacity = count;
    array->count = count;
    for (size_t i = 0; i < count; ++i) {
        fread(&array->messages[i], sizeof(Message), 1, file);
    }
    fclose(file);
}

void logOperation(const char* operation, int id) {
    time_t now = time(NULL);
    printf("%s: %s at %ld\n", operation, id == -1 ? "General" : "Message ID", (long)now);
}
