#include <stdlib.h>
#include <pthread.h>

typedef int64_t offset_t;
typedef uint32_t key_t;

typedef struct {
    key_t key;
    offset_t offset;
} record_t;

int allocate_memory(offset_t **offsets, size_t *offset_count,
                    key_t **keys, size_t *key_count,
                    record_t **records, size_t *record_count) {
    // Initialize mutexes for thread-safe operations
    pthread_mutex_t offsets_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t keys_mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_t records_mutex = PTHREAD_MUTEX_INITIALIZER;

    // Allocate memory for offsets array
    *offsets = (offset_t *)malloc(*offset_count * sizeof(offset_t));
    if (*offsets == NULL) {
        return -1; // Memory allocation failed
    }

    // Initialize offsets array with values derived from index
    pthread_mutex_lock(&offsets_mutex);
    for (size_t i = 0; i < *offset_count; ++i) {
        (*offsets)[i] = (offset_t)i;
    }
    pthread_mutex_unlock(&offsets_mutex);

    // Allocate memory for keys array
    *keys = (key_t *)malloc(*key_count * sizeof(key_t));
    if (*keys == NULL) {
        free(*offsets);
        return -1; // Memory allocation failed
    }

    // Initialize keys array with unique identifiers
    pthread_mutex_lock(&keys_mutex);
    for (size_t i = 0; i < *key_count; ++i) {
        (*keys)[i] = (key_t)i;
    }
    pthread_mutex_unlock(&keys_mutex);

    // Allocate memory for records array
    *records = (record_t *)malloc(*record_count * sizeof(record_t));
    if (*records == NULL) {
        free(*offsets);
        free(*keys);
        return -1; // Memory allocation failed
    }

    // Populate records array with random offsets and unique keys
    pthread_mutex_lock(&records_mutex);
    for (size_t i = 0; i < *record_count; ++i) {
        (*records)[i].key = (*keys)[i % *key_count];
        (*records)[i].offset = (*offsets)[rand() % *offset_count];
    }
    pthread_mutex_unlock(&records_mutex);

    return 0; // Success
}

void free_memory(offset_t *offsets, key_t *keys, record_t *records) {
    if (offsets != NULL) {
        free(offsets);
    }
    if (keys != NULL) {
        free(keys);
    }
    if (records != NULL) {
        free(records);
    }
}
