    PDU_TYPE type;
    void* extension_data;
    size_t extension_size;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T messages[MAX_MESSAGES];
    int count;
    pthread_mutex_t lock;
} NFAPI_MESSAGE_ARRAY_T;

void init_nfaapi_message_array(NFAPI_MESSAGE_ARRAY_T* array) {
    memset(array, 0, sizeof(*array));
    pthread_mutex_init(&array->lock, NULL);
}

int add_nfaapi_message(NFAPI_MESSAGE_ARRAY_T* array, int id, PDU_TYPE type, void* extension_data, size_t extension_size) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= MAX_MESSAGES) {
        pthread_mutex_unlock(&array->lock);
        return -1; // Array is full
    }
    NFAPI_MESSAGE_T* msg = &array->messages[array->count++];
    msg->id = id;
    msg->type = type;
    msg->extension_data = malloc(extension_size);
    if (!msg->extension_data) {
        pthread_mutex_unlock(&array->lock);
        return -2; // Memory allocation failed
    }
    memcpy(msg->extension_data, extension_data, extension_size);
    msg->extension_size = extension_size;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int remove_nfaapi_message(NFAPI_MESSAGE_ARRAY_T* array, int id) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            free(array->messages[i].extension_data);
            memmove(&array->messages[i], &array->messages[i + 1], sizeof(NFAPI_MESSAGE_T) * (array->count - i - 1));
            array->count--;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Message not found
}

NFAPI_MESSAGE_T* get_nfaapi_message(NFAPI_MESSAGE_ARRAY_T* array, int id) {
    pthread_mutex_lock(&array->lock);
    for (int i = 0; i < array->count; ++i) {
        if (array->messages[i].id == id) {
            NFAPI_MESSAGE_T* msg = &array->messages[i];
            pthread_mutex_unlock(&array->lock);
            return msg;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL; // Message not found
}

void free_nfaapi_message_array(NFAPI_MESSAGE_ARRAY_T* array) {
    for (int i = 0; i < array->count; ++i) {
        free(array->messages[i].extension_data);
    }
    pthread_mutex_destroy(&array->lock);
}
