    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} NFAPI_LIST_T;

NFAPI_LIST_T* create_nfaapi_list() {
    NFAPI_LIST_T *list = (NFAPI_LIST_T*)malloc(sizeof(NFAPI_LIST_T));
    if (!list) return NULL;

    list->nfapi_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_NFAPIS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->nfapi_list) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = MAX_NFAPIS;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

void destroy_nfaapi_list(NFAPI_LIST_T *list) {
    if (list) {
        free(list->nfapi_list);
        pthread_mutex_destroy(&list->lock);
        free(list);
    }
}

int add_nfaapi_pdu(NFAPI_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->nfapi_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }

        list->nfapi_list = new_list;
        list->capacity = new_capacity;
    }

    list->nfapi_list[list->count++] = pdu;

    pthread_mutex_unlock(&list->lock);
    return 0;
}

