void print_usage() {
    printf("Usage: program_name [--help] -c count [-o output_file] [input_file]\n");
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        print_usage();
        return 1;
    }

    int count = 0;
    const char *output_file = NULL;
    const char *input_file = NULL;
    int opt;

    while ((opt = getopt(argc, argv, "c:o:")) != -1) {
        switch (opt) {
            case 'c':
                count = atoi(optarg);
                break;
            case 'o':
                output_file = optarg;
                break;
            case '?':
                print_usage();
                return 1;
            default:
                abort();
        }
    }

    if (argc > optind) {
        input_file = argv[optind];
    }

    if (count <= 0) {
        fprintf(stderr, "Error: Invalid count value.\n");
        return 1;
    }

    record *records = malloc(count * sizeof(record));
    if (!records) {
        perror("Failed to allocate memory for records");
        return 1;
    }

    srand(time(NULL));

    for (int i = 0; i < count; i++) {
        records[i].value = rand() % 1000; // Random value between 0 and 999
    }

    if (input_file) {
        FILE *file = fopen(input_file, "r");
        if (!file) {
            perror("Failed to open input file");
            free(records);
            return 1;
        }

        size_t offset_size = count * sizeof(long);
        long *offsets = malloc(offset_size);
        if (!offsets) {
            perror("Failed to allocate memory for offsets");
            fclose(file);
            free(records);
            return 1;
        }

        int key_size = count * sizeof(int);
        int *keys = malloc(key_size);
        if (!keys) {
            perror("Failed to allocate memory for keys");
            free(offsets);
            fclose(file);
            free(records);
            return 1;
        }

        // Read file in bulk and populate offsets and keys arrays
        // ...

        fclose(file);
        free(offsets);
        free(keys);
    } else {
        printf("No input file provided. Usage information:\n");
        print_usage();
    }

    if (output_file) {
        FILE *file = fopen(output_file, "w");
        if (!file) {
            perror("Failed to open output file");
            free(records);
            return 1;
        }

        for (int i = 0; i < count; i++) {
            fprintf(file, "%d\n", records[i].value);
        }

        fclose(file);
    } else {
        printf("No output file specified. Records will be printed to stdout.\n");
        for (int i = 0; i < count; i++) {
            printf("%d\n", records[i].value);
        }
    }

    free(records);
    return 0;
}
