#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_RNTI 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} List;

void initList(List* list) {
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
}

void freeList(List* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

int addToList(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    newNode->data = data;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int validateRNTI(int RNTI, int minRNTI, int maxRNTI) {
    if (RNTI < minRNTI || RNTI > maxRNTI) {
        fprintf(stderr, "Invalid RNTI: %d\n", RNTI);
        return 0;
    }
    return 1;
}

int validateList(List* list, int minRNTI, int maxRNTI) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        if (!validateRNTI(current->data.RNTI, minRNTI, maxRNTI)) {
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return 1;
}

int createStructures(int numStructs, int minRNTI, int maxRNTI, unsigned int seed) {
    if (seed == 0) {
        seed = time(NULL);
    }
    srand(seed);

    List list;
    initList(&list);

    for (int i = 0; i < numStructs; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        pdu.RNTI = minRNTI + rand() % (maxRNTI - minRNTI + 1);
        pdu.CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG

        if (!validateRNTI(pdu.RNTI, minRNTI, maxRNTI)) {
            fprintf(stderr, "Duplicate RNTI: %d\n", pdu.RNTI);
            continue;
        }

        if (addToList(&list, pdu) != 0) {
            freeList(&list);
            return -1;
        }
    }

    if (!validateList(&list, minRNTI, maxRNTI)) {
        freeList(&list);
        return -1;
    }

    freeList(&list);
    return 0;
}
