typedef struct {
    CellRadioInterface *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->data = (CellRadioInterface*)calloc(INITIAL_CAPACITY, sizeof(CellRadioInterface));
    list->size = 0;
    list->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void resize_dynamic_list(DynamicList *list) {
    size_t new_capacity = list->capacity * 2;
    CellRadioInterface *new_data = (CellRadioInterface*)realloc(list->data, new_capacity * sizeof(CellRadioInterface));
    if (new_data) {
        list->data = new_data;
        list->capacity = new_capacity;
    }
}

void add_to_dynamic_list(DynamicList *list, CellRadioInterface item) {
    pthread_mutex_lock(&list->lock);
    if (list->size == list->capacity) {
        resize_dynamic_list(list);
    }
    list->data[list->size++] = item;
    pthread_mutex_unlock(&list->lock);
}

void remove_from_dynamic_list(DynamicList *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index < list->size) {
        for (size_t i = index; i < list->size - 1; ++i) {
            list->data[i] = list->data[i + 1];
        }
        --list->size;
    }
    pthread_mutex_unlock(&list->lock);
}

void iterate_dynamic_list(DynamicList *list, void (*callback)(CellRadioInterface)) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->size; ++i) {
        callback(list->data[i]);
    }
    pthread_mutex_unlock(&list->lock);
}
