void initialize_entries(entry** entries, int count) {
    for (int i = 0; i < count; i++) {
        entries[i] = allocate_memory(sizeof(entry));
        entries[i]->value = rand() % 100; // Random value between 0 and 99
        entries[i]->key = NULL;
    }
}

void initialize_offsets(long** offsets, int count) {
    for (int i = 0; i < count; i++) {
        offsets[i] = allocate_memory(sizeof(long));
        *offsets[i] = rand() % MAX_ALLOCATION_SIZE; // Random offset within the allocation limit
    }
}

void validate_memory(void* ptr, size_t size) {
    if (ptr == NULL || size == 0) {
        fprintf(stderr, "Invalid memory allocation\n");
        exit(EXIT_FAILURE);
    }
}

void* fetch_data_from_source() {
    // Simulate fetching data from an external source
    return allocate_memory(MAX_ALLOCATION_SIZE);
}

void* manage_memory(int count, long** offsets, int** keys, entry*** entries) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    *offsets = allocate_memory(count * sizeof(long));
    *keys = allocate_memory(count * sizeof(char*));
    *entries = allocate_memory(count * sizeof(entry*));

    initialize_offsets(*offsets, count);
    initialize_keys(*keys, count);
    initialize_entries(*entries, count);

    validate_memory(*offsets, count * sizeof(long));
    validate_memory(*keys, count * sizeof(char*));
    validate_memory(*entries, count * sizeof(entry*));

    pthread_mutex_unlock(&mutex);

    return fetch_data_from_source();
}

int main() {
    srand(time(NULL)); // Seed the random number generator

    int count = 10;
    long* offsets;
    char** keys;
    entry** entries;

    void* data = manage_memory(count, &offsets, &keys, &entries);

    printf("Data fetched from source: %p\n", data);

    for (int i = 0; i < count; i++) {
        printf("Offset %d: %ld, Key %d: %s, Entry Value %d\n",
               i, offsets[i], i, keys[i], entries[i]->value);
    }

    // Free allocated memory
    free(offsets);
    for (int i = 0; i < count; i++) {
        free(keys[i]);
        free(entries[i]);
    }
    free(entries);

    return 0;
}
