NFAPI_CRC_INDICATION_PDU_T* generateNfaApiList(int numStreams, int seed) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStreams * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) return NULL;

    for (int i = 0; i < numStreams; i++) {
        // Populate each structure with valid data
        RX_UE_INFORMATION_TAG* ueInfo = &list[i].ueInfo;
        RNTI* rnti = &list[i].rnti;
        CRC_INDICATION_REL8_TAG* crcTag = &list[i].crcTag;

        // Generate unique CRCFLAG based on current time and seed
        unsigned long currentTime = time(NULL);
        crcTag->CRCFLAG = (currentTime * seed) % 0xFFFFFFFF;
    }

    return list;
}

int decryptCiphertext(unsigned char* ciphertext, int ciphertextLen, unsigned char* key, unsigned char* iv, unsigned char* plaintext) {
    AES_KEY aesKey;
    if (AES_set_decrypt_key(key, 128, &aesKey) < 0) return -1;

    int padding = 0;
    if (AES_cbc_encrypt(ciphertext, plaintext, ciphertextLen, &aesKey, iv, AES_DECRYPT) < 0) return -1;

    // Handle padding
    unsigned char* lastByte = plaintext + ciphertextLen - 1;
    padding = *lastByte;
    if (padding > 16 || padding == 0) return -1;

    for (int i = 0; i < padding; i++) {
        if (plaintext[ciphertextLen - 1 - i] != padding) return -1;
    }

    plaintext[ciphertextLen - padding] = '\0';
    return ciphertextLen - padding;
}
