#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_LIST_SIZE 1000

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
    int crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list[MAX_LIST_SIZE];
    size_t count;
    size_t max_size;
    pthread_mutex_t lock;
    FILE *flush_file;
    time_t last_flush_time;
    int flush_interval;
} PduManager;

void initialize_pdu_manager(PduManager *manager, size_t max_size, const char *flush_file_path, int flush_interval) {
    manager->count = 0;
    manager->max_size = max_size;
    pthread_mutex_init(&manager->lock, NULL);
    manager->flush_file = fopen(flush_file_path, "a");
    if (!manager->flush_file) {
        perror("Failed to open flush file");
        exit(EXIT_FAILURE);
    }
    manager->last_flush_time = time(NULL);
    manager->flush_interval = flush_interval;
}

void destroy_pdu_manager(PduManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->list[i]);
    }
    fclose(manager->flush_file);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) {
        perror("Failed to allocate memory for PDU");
        exit(EXIT_FAILURE);
    }
    // Initialize pdu fields with random values
    pdu->ue_info = generate_random_ue_info();
    pdu->rnti = generate_random_rnti();
    pdu->crc_indication = generate_random_crc_indication();
    pdu->crcflag = rand() % 2; // Randomly set CRCFLAG
    return pdu;
}

void add_pdu(PduManager *manager, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= manager->max_size) {
        fprintf(stderr, "PDU list is full. Consider increasing max_size.\n");
        pthread_mutex_unlock(&manager->lock);
        return;
    }
    manager->list[manager->count++] = pdu;
    pthread_mutex_unlock(&manager->lock);

    time_t current_time = time(NULL);
    if (current_time - manager->last_flush_time >= manager->flush_interval) {
        flush_pdu_list(manager);
    }
}

void flush_pdu_list(PduManager *manager) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->count; ++i) {
        fprintf(manager->flush_file, "UE Info: %d, RNTI: %d, CRC Indication: %d, CRC Flag: %d\n",
                manager->list[i]->ue_info, manager->list[i]->rnti,
                manager->list[i]->crc_indication, manager->list[i]->crcflag);
        free(manager->list[i]);
    }
    manager->count = 0;
    manager->last_flush_time = time(NULL);
    pthread_mutex_unlock(&manager->lock);
}

void* pdu_manager_thread(void *arg) {
    PduManager *manager = (PduManager*)arg;
    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu();
        add_pdu(manager, pdu);
        // Simulate some processing time
        sleep(1);
    }
    return NULL;
}

int main() {
    PduManager manager;
    initialize_pdu_manager(&manager, MAX_LIST_SIZE, "pdu_log.txt", 60);

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, pdu_manager_thread, &manager) != 0) {
        perror("Failed to create thread");
        exit(EXIT_FAILURE);
    }

    pthread_join(thread_id, NULL);

    destroy_pdu_manager(&manager);
    return 0;
}
