    pthread_cond_destroy(&buffer->log_cond);
    free(buffer);
}

void log_message(LogBuffer *buffer, const char *message) {
    pthread_mutex_lock(&buffer->log_mutex);
    while ((buffer->tail + 1) % LOG_BUFFER_SIZE == buffer->head) {
        pthread_cond_wait(&buffer->log_cond, &buffer->log_mutex);
    }
    size_t index = (buffer->tail++) % LOG_BUFFER_SIZE;
    snprintf(buffer->buffer + index * sizeof(char), sizeof(char), "%s", message);
    pthread_cond_signal(&buffer->log_cond);
    pthread_mutex_unlock(&buffer->log_mutex);
}

