    pthread_mutex_lock(&list->mutex);
    while (list->size == list->capacity) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    list->pdus[list->size++] = pdu;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

void resize_pdu_list(PduList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->size; ++i) {
        new_pdus[i] = list->pdus[(list->head + i) % list->capacity];
    }
    free(list->pdus);
    list->pdus = new_pdus;
    list->capacity = new_capacity;
    list->head = 0;
    pthread_mutex_unlock(&list->mutex);
}

void *pdu_creation_thread(void *arg) {
    PduList *list = (PduList *)arg;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Populate pdu with data
    add_pdu(list, pdu);
    return NULL;
}

