#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PAYLOAD_SIZE 1024

typedef struct Message {
    char sender_id[64];
    time_t timestamp;
    char payload[MAX_PAYLOAD_SIZE];
} Message;

typedef struct Node {
    Message msg;
    struct Node* next;
} Node;

typedef struct MessageQueue {
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
} MessageQueue;

MessageQueue* create_message_queue() {
    MessageQueue* queue = (MessageQueue*)malloc(sizeof(MessageQueue));
    if (!queue) return NULL;
    queue->head = queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    return queue;
}

void enqueue_message(MessageQueue* queue, Message msg) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return;
    new_node->msg = msg;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->lock);
    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
    pthread_mutex_unlock(&queue->lock);
}

Message dequeue_message(MessageQueue* queue) {
    Message msg = {0};
    pthread_mutex_lock(&queue->lock);
    if (queue->head) {
        Node* temp = queue->head;
        msg = temp->msg;
        queue->head = temp->next;
        if (!queue->head) {
            queue->tail = NULL;
        }
        free(temp);
    }
    pthread_mutex_unlock(&queue->lock);
    return msg;
}

void destroy_message_queue(MessageQueue* queue) {
    Node* current = queue->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    free(queue);
}
