NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, int min_RNTI, int max_RNTI) {
    if (N <= 0 || min_RNTI < 0 || max_RNTI < min_RNTI) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < N; ) {
        int RNTI = rand() % (max_RNTI - min_RNTI + 1) + min_RNTI;

        // Check for duplicate RNTI
        bool is_duplicate = false;
        for (int j = 0; j < i; j++) {
            if (list[j].RNTI == RNTI) {
                is_duplicate = true;
                break;
            }
        }

        if (!is_duplicate) {
            list[i].RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
            list[i].RNTI = RNTI;
            list[i].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG (0 or 1)
            i++;
        }
    }

    return list;
}

