#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int sender_id;
    time_t timestamp;
    size_t payload_size;
} Message;

typedef struct {
    Message* messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MessageArray;

void init_message_array(MessageArray* array, size_t initial_capacity) {
    array->messages = (Message*)malloc(initial_capacity * sizeof(Message));
    if (!array->messages) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->count = 0;
    pthread_mutex_init(&array->lock, NULL);
}

void add_message(MessageArray* array, Message message) {
    pthread_mutex_lock(&array->lock);
    if (array->count == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Message* new_messages = (Message*)realloc(array->messages, new_capacity * sizeof(Message));
        if (!new_messages) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }
    array->messages[array->count++] = message;
    pthread_mutex_unlock(&array->lock);
}

void remove_outdated_messages(MessageArray* array, time_t threshold) {
    pthread_mutex_lock(&array->lock);
    size_t i = 0, j = 0;
    while (j < array->count) {
        if (difftime(array->messages[j].timestamp, threshold) > 0) {
            array->messages[i++] = array->messages[j++];
        } else {
            j++;
        }
    }
    array->count = i;
    pthread_mutex_unlock(&array->lock);
}

size_t get_messages_in_range(MessageArray* array, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&array->lock);
    size_t count = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (array->messages[i].timestamp >= start_time && array->messages[i].timestamp <= end_time) {
            count++;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return count;
}

void free_message_array(MessageArray* array) {
    pthread_mutex_lock(&array->lock);
    free(array->messages);
    pthread_mutex_destroy(&array->lock);
}
