#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_CONTEXTS 10000
#define MAX_PDU_SESSIONS 5

typedef struct PduSession {
    char suci[20];
    char snssai[10];
    struct PduSession *next;
} PduSession;

typedef struct UeContext {
    int ueId;
    int rrcState;
    PduSession *pduSessions;
    pthread_mutex_t lock;
} UeContext;

UeContext *ueContextList[MAX_UE_CONTEXTS];

int initializeUeContext(int ueId, int rrcState) {
    if (ueId < 0 || ueId >= MAX_UE_CONTEXTS) return -1;

    UeContext *newUe = (UeContext *)malloc(sizeof(UeContext));
    if (!newUe) return -2;

    newUe->ueId = ueId;
    newUe->rrcState = rrcState;
    newUe->pduSessions = NULL;
    pthread_mutex_init(&newUe->lock, NULL);

    ueContextList[ueId] = newUe;
    return 0;
}

int addPduSession(int ueId, char *suci, char *snssai) {
    if (ueId < 0 || ueId >= MAX_UE_CONTEXTS) return -1;

    pthread_mutex_lock(&ueContextList[ueId]->lock);

    PduSession *newSession = (PduSession *)malloc(sizeof(PduSession));
    if (!newSession) {
        pthread_mutex_unlock(&ueContextList[ueId]->lock);
        return -2;
    }

    strncpy(newSession->suci, suci, sizeof(newSession->suci) - 1);
    strncpy(newSession->snssai, snssai, sizeof(newSession->snssai) - 1);
    newSession->next = ueContextList[ueId]->pduSessions;

    ueContextList[ueId]->pduSessions = newSession;

    pthread_mutex_unlock(&ueContextList[ueId]->lock);
    return 0;
}

PduSession *findPduSession(int ueId, char *snssai) {
    if (ueId < 0 || ueId >= MAX_UE_CONTEXTS) return NULL;

    pthread_mutex_lock(&ueContextList[ueId]->lock);

    PduSession *current = ueContextList[ueId]->pduSessions;
    while (current != NULL) {
        if (strcmp(current->snssai, snssai) == 0) {
            pthread_mutex_unlock(&ueContextList[ueId]->lock);
            return current;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&ueContextList[ueId]->lock);
    return NULL;
}

void freeUeContext(int ueId) {
    if (ueId < 0 || ueId >= MAX_UE_CONTEXTS) return;

    pthread_mutex_lock(&ueContextList[ueId]->lock);

    PduSession *current = ueContextList[ueId]->pduSessions;
    while (current != NULL) {
        PduSession *temp = current;
        current = current->next;
        free(temp);
    }

    pthread_mutex_unlock(&ueContextList[ueId]->lock);
    free(ueContextList[ueId]);
    ueContextList[ueId] = NULL;
}
