#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_CI_VALUES 1000
#define TIME_WINDOW_SECONDS 60

typedef struct LTE_EUTRAN_CellularMeasurementConfig {
    int cellIdentity;
    time_t lastMeasurementTime;
    float measurementAccuracy;
} LTE_EUTRAN_CellularMeasurementConfig;

typedef struct Node {
    LTE_EUTRAN_CellularMeasurementConfig data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* createLinkedList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (list == NULL) {
        perror("Failed to allocate memory for linked list");
        exit(EXIT_FAILURE);
    }
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insertMeasurement(LinkedList* list, LTE_EUTRAN_CellularMeasurementConfig config) {
    pthread_mutex_lock(&list->lock);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        perror("Failed to allocate memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->data = config;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void cleanupOldMeasurements(LinkedList* list, time_t currentTime) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;

    while (current != NULL) {
        if ((currentTime - current->data.lastMeasurementTime) > TIME_WINDOW_SECONDS) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void* measurementThread(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    LTE_EUTRAN_CellularMeasurementConfig config;
    time_t currentTime;

    while (1) {
        // Simulate fetching new measurements
        currentTime = time(NULL);
        config.cellIdentity = rand() % MAX_CI_VALUES;
        config.lastMeasurementTime = currentTime;
        config.measurementAccuracy = 0.5 + (rand() / (float)RAND_MAX);

        insertMeasurement(list, config);
        cleanupOldMeasurements(list, currentTime);

        // Simulate thread sleep
        sleep(1);
    }

    return NULL;
}

int main() {
    LinkedList* list = createLinkedList();

    pthread_t thread;
    if (pthread_create(&thread, NULL, measurementThread, list) != 0) {
        perror("Failed to create thread");
        free(list);
        exit(EXIT_FAILURE);
    }

    pthread_join(thread, NULL);

    free(list);
    return 0;
}
