typedef struct LTE_RRC_RECONFIGURATION_REQUEST {
    int cellID;
    int* frequencies;
    size_t numFrequencies;
    time_t configTimestamp;
} LTE_RRC_RECONFIGURATION_REQUEST;

typedef struct Node {
    LTE_RRC_RECONFIGURATION_REQUEST data;
    struct Node* next;
} Node;

typedef struct DynamicArray {
    Node* head;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (array == NULL) return NULL;
    array->head = NULL;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void insertDynamicArray(DynamicArray* array, LTE_RRC_RECONFIGURATION_REQUEST data) {
    pthread_mutex_lock(&array->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        pthread_mutex_unlock(&array->mutex);
        return;
    }
    newNode->data = data;
    newNode->next = array->head;
    array->head = newNode;
    pthread_mutex_unlock(&array->mutex);
}

void deleteDynamicArray(DynamicArray* array, int cellID) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    Node* previous = NULL;

    while (current != NULL) {
        if (current->data.cellID == cellID) {
            if (previous == NULL) {
                array->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&array->mutex);
}

LTE_RRC_RECONFIGURATION_REQUEST* getDynamicArray(DynamicArray* array, int cellID) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;

    while (current != NULL) {
        if (current->data.cellID == cellID) {
            LTE_RRC_RECONFIGURATION_REQUEST* result = &current->data;
            pthread_mutex_unlock(&array->mutex);
            return result;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&array->mutex);
    return NULL;
}

void destroyDynamicArray(DynamicArray* array) {
    pthread_mutex_lock(&array->mutex);
    Node* current = array->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}
