typedef struct {
    int RNTI;
    // Other fields for MCP structure
} MCP;

typedef struct {
    MCP mcp;
    // Communication protocol setup
} PDU;

typedef struct Node {
    PDU pdu;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
} Stack;

Stack* createAndPopulateNFABasebandStackWithPDUs(const char* configFilePath, int N) {
    Stack* stack = (Stack*)malloc(sizeof(Stack));
    if (!stack) {
        perror("Failed to allocate memory for stack");
        return NULL;
    }
    stack->head = stack->tail = NULL;
    stack->size = 0;

    FILE* file = fopen(configFilePath, "r");
    if (!file) {
        perror("Failed to open configuration file");
        free(stack);
        return NULL;
    }

    for (int i = 0; i < N; ++i) {
        PDU pdu;
        // Read and parse PDU data from file
        if (fscanf(file, "%d", &pdu.mcp.RNTI) != 1) {
            perror("Failed to read RNTI from configuration file");
            fclose(file);
            free(stack);
            return NULL;
        }

        Node* newNode = (Node*)malloc(sizeof(Node));
        if (!newNode) {
            perror("Failed to allocate memory for new node");
            fclose(file);
            free(stack);
            return NULL;
        }
        newNode->pdu = pdu;
        newNode->next = NULL;

        if (stack->size == 0) {
            stack->head = stack->tail = newNode;
        } else {
            stack->tail->next = newNode;
            stack->tail = newNode;
        }
        stack->size++;
    }

    fclose(file);
    return stack;
}
