        int RNTI;
        int CRCFLAG;
    };

    std::mutex mutex_;
    int minCRCFlag_;
    int maxCRCFlag_;

    int getRandomInt(int min, int max) {
        std::lock_guard<std::mutex> lock(mutex_);
        return min + rand() % (max - min + 1);
    }

    float getRandomFloat(float min, float max) {
        std::lock_guard<std::mutex> lock(mutex_);
        return min + static_cast<float>(rand()) / RAND_MAX * (max - min);
    }

public:
    Nfademo(int minCRCFlag, int maxCRCFlag) : minCRCFlag_(minCRCFlag), maxCRCFlag_(maxCRCFlag) {}

    void generatePDU() {
        std::lock_guard<std::mutex> lock(mutex_);
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = getRandomInt(1, 100);
        pdu.RNTI = getRandomInt(1000, 2000);
        pdu.CRCFLAG = getRandomInt(minCRCFlag_, maxCRCFlag_);
        std::cout << "Generated PDU: RX_UE_INFORMATION_TAG=" << pdu.RX_UE_INFORMATION_TAG
                  << ", RNTI=" << pdu.RNTI << ", CRCFLAG=" << pdu.CRCFLAG << std::endl;
    }

    void updateCRCFlagRange(int minCRCFlag, int maxCRCFlag) {
        std::lock_guard<std::mutex> lock(mutex_);
        minCRCFlag_ = minCRCFlag;
        maxCRCFlag_ = maxCRCFlag;
    }

    std::string ToString() const {
        return "Nfademo - CRCFLAG Range: [" + std::to_string(minCRCFlag_) + ", " + std::to_string(maxCRCFlag_) + "]";
    }
};

