#include <pthread.h>
#include "memory_pool.h"
#include "garbage_collector.h"
#include "logging_framework.h"

typedef struct {
    PHY_RX_CONTEXT phy_rx_context;
    RX_QCI rx_qci;
} MAC_RX_DATA_PDU_T;

typedef struct {
    MAC_RX_DATA_PDU_T *pdu_list;
    size_t list_size;
    size_t used_count;
    pthread_mutex_t lock;
} MAC_RX_LIST_T;

void mac_rx_list_init(MAC_RX_LIST_T *list, size_t initial_size) {
    list->pdu_list = memory_pool_alloc(initial_size * sizeof(MAC_RX_DATA_PDU_T));
    list->list_size = initial_size;
    list->used_count = 0;
    pthread_mutex_init(&list->lock, NULL);
}

void mac_rx_list_add(MAC_RX_LIST_T *list, MAC_RX_DATA_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->used_count >= list->list_size) {
        size_t new_size = list->list_size * 2;
        list->pdu_list = memory_pool_realloc(list->pdu_list, new_size * sizeof(MAC_RX_DATA_PDU_T));
        list->list_size = new_size;
    }
    list->pdu_list[list->used_count++] = *pdu;
    pthread_mutex_unlock(&list->lock);
}

void mac_rx_list_update(MAC_RX_LIST_T *list, size_t index, MAC_RX_DATA_PDU_T *new_pdu) {
    pthread_mutex_lock(&list->lock);
    if (index < list->used_count) {
        list->pdu_list[index] = *new_pdu;
    }
    pthread_mutex_unlock(&list->lock);
}

void mac_rx_list_remove(MAC_RX_LIST_T *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index < list->used_count) {
        for (size_t i = index; i < list->used_count - 1; ++i) {
            list->pdu_list[i] = list->pdu_list[i + 1];
        }
        --list->used_count;
    }
    pthread_mutex_unlock(&list->lock);
}

void mac_rx_list_cleanup(MAC_RX_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    memory_pool_free(list->pdu_list);
    list->pdu_list = NULL;
    list->list_size = 0;
    list->used_count = 0;
    pthread_mutex_unlock(&list->lock);
}

