struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
};

class AttackManager {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> attackCache;
    std::mutex cacheMutex;
    std::random_device rd;
    std::mt19937 gen;

public:
    AttackManager() : gen(rd()) {}

    NFAPI_CRC_INDICATION_PDU_T generateAttack(int tag, int rnti) {
        std::lock_guard<std::mutex> lock(cacheMutex);
        if (attackCache.size() > 0 && attackCache.back().RX_UE_INFORMATION_TAG == tag && attackCache.back().RNTI == rnti) {
            return attackCache.back();
        }
        NFAPI_CRC_INDICATION_PDU_T attack;
        attack.RX_UE_INFORMATION_TAG = tag;
        attack.RNTI = rnti;
        attack.CRC_INDICATION_REL8_TAG = gen() % 256; // Random CRCFLAG
        attackCache.push_back(attack);
        return attack;
    }
};

class HttpClient {
private:
    CURL* curl;

public:
    HttpClient() {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
    }

    ~HttpClient() {
        if (curl) {
            curl_easy_cleanup(curl);
        }
        curl_global_cleanup();
    }

    std::string makeGetRequest(const std::string& url, bool verifySSL = true) {
        CURLcode res;
        std::string readBuffer;

        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        if (!verifySSL) {
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYPEER, 0L);
            curl_easy_setopt(curl, CURLOPT_SSL_VERIFYHOST, 0L);
        }
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, [](void* contents, size_t size, size_t nmemb, void* userp) -> size_t {
            ((std::string*)userp)->append((char*)contents, size * nmemb);
            return size * nmemb;
        });
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &readBuffer);

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            std::cerr << "curl_easy_perform() failed: " << curl_easy_strerror(res) << std::endl;
        }

        return readBuffer;
    }
};

void executeDynamicAttacksAndFetchServerData(int N, const std::string& url, bool verifySSL = true) {
    AttackManager attackManager;
    HttpClient httpClient;

    for (int i = 0; i < N; ++i) {
        int tag = i % 100; // Example tag generation
        int rnti = i % 256; // Example RNTI generation

        NFAPI_CRC_INDICATION_PDU_T attack = attackManager.generateAttack(tag, rnti);
        std::cout << "Generated Attack: Tag=" << attack.RX_UE_INFORMATION_TAG << ", RNTI=" << attack.RNTI << ", CRCFLAG=" << attack.CRC_INDICATION_REL8_TAG << std::endl;

        std::string response = httpClient.makeGetRequest(url, verifySSL);
        std::cout << "Server Response: " << response << std::endl;
    }
}

int main() {
    executeDynamicAttacksAndFetchServerData(10000, "https://example.com/api/data", false);
    return 0;
}
