    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_T;

NFAPI_CRC_ARRAY_T* create_crc_array(size_t initial_capacity) {
    NFAPI_CRC_ARRAY_T *array = (NFAPI_CRC_ARRAY_T*)malloc(sizeof(NFAPI_CRC_ARRAY_T));
    if (!array) return NULL;

    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->array) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void destroy_crc_array(NFAPI_CRC_ARRAY_T *array) {
    if (array) {
        free(array->array);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int add_crc_indication(NFAPI_CRC_ARRAY_T *array, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_item = &array->array[array->size++];
    new_item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_item->RNTI = RNTI;
    new_item->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_item->CRCFLAG = CRCFLAG;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

