typedef struct {
    // Define the structure for RRC_MESSAGE_T
} RRC_MESSAGE_T;

typedef struct {
    // Define the structure for RX_UE_INFO_PDU
} RX_UE_INFO_PDU;

typedef struct NFAPI_MESSAGE_T {
    RX_UE_INFO_PDU rx_ue_info_pdu;
    int ue_id;
    pthread_mutex_t mutex; // Mutex for thread safety
    RRC_MESSAGE_T** rrc_messages; // Dynamically allocated list of RRC messages
    size_t num_rrc_messages; // Number of RRC messages in the list
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T* initialize_and_populate_nfaip_message(int n, int max_rrc_messages) {
    NFAPI_MESSAGE_T* messages = (NFAPI_MESSAGE_T*)malloc(n * sizeof(NFAPI_MESSAGE_T));
    if (!messages) return NULL;

    for (int i = 0; i < n; ++i) {
        pthread_mutex_init(&messages[i].mutex, NULL);
        messages[i].ue_id = i;
        messages[i].rrc_messages = (RRC_MESSAGE_T**)malloc(max_rrc_messages * sizeof(RRC_MESSAGE_T*));
        if (!messages[i].rrc_messages) {
            // Handle memory allocation failure
            for (int j = 0; j < i; ++j) {
                pthread_mutex_destroy(&messages[j].mutex);
                free(messages[j].rrc_messages);
            }
            free(messages);
            return NULL;
        }
        messages[i].num_rrc_messages = 0;

        // Populate RRC messages
        for (int j = 0; j < max_rrc_messages; ++j) {
            messages[i].rrc_messages[j] = (RRC_MESSAGE_T*)malloc(sizeof(RRC_MESSAGE_T));
            if (!messages[i].rrc_messages[j]) {
                // Handle memory allocation failure
                for (int k = 0; k <= j; ++k) {
                    free(messages[i].rrc_messages[k]);
                }
                free(messages[i].rrc_messages);
                pthread_mutex_destroy(&messages[i].mutex);
            } else {
                // Initialize RRC message fields
                messages[i].num_rrc_messages++;
            }
        }
    }

    return messages;
}

void destroy_nfaip_message(NFAPI_MESSAGE_T* messages, int n) {
    for (int i = 0; i < n; ++i) {
        pthread_mutex_lock(&messages[i].mutex);
        for (int j = 0; j < messages[i].num_rrc_messages; ++j) {
            free(messages[i].rrc_messages[j]);
        }
        free(messages[i].rrc_messages);
        pthread_mutex_unlock(&messages[i].mutex);
        pthread_mutex_destroy(&messages[i].mutex);
    }
    free(messages);
}
