#define MAX_RECORDS 1000

typedef struct {
    int value;
} record;

long* allocate_offset_array(int size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Memory allocation failed for offset array\n");
        exit(EXIT_FAILURE);
    }
    return offsets;
}

int* allocate_key_array(int size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Memory allocation failed for key array\n");
        exit(EXIT_FAILURE);
    }
    return keys;
}

record* allocate_record_array(int size) {
    record* records = (record*)malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed for record array\n");
        exit(EXIT_FAILURE);
    }
    return records;
}

void initialize_arrays(long* offsets, int* keys, record* records, int size, long offset_range, int key_range) {
    srand(time(NULL));
    for (int i = 0; i < size; i++) {
        offsets[i] = rand() % offset_range;
        keys[i] = rand() % key_range;
        records[i].value = rand();
    }
}

void update_record(record* records, int index, int new_value) {
    if (index >= 0 && index < MAX_RECORDS) {
        records[index].value = new_value;
    } else {
        fprintf(stderr, "Invalid record index\n");
    }
}

void prune_old_records(record* records, int* keys, long* offsets, int size, int max_age) {
    for (int i = 0; i < size; i++) {
        if (time(NULL) - offsets[i] > max_age) {
            records[i].value = 0;
            keys[i] = -1;
            offsets[i] = 0;
        }
    }
}

void log_memory_usage(long* offsets, int* keys, record* records, int size) {
    printf("Memory Usage: Offsets (%ld bytes), Keys (%ld bytes), Records (%ld bytes)\n",
           size * sizeof(long), size * sizeof(int), size * sizeof(record));
}

int main() {
    long* offsets = allocate_offset_array(MAX_RECORDS);
    int* keys = allocate_key_array(MAX_RECORDS);
    record* records = allocate_record_array(MAX_RECORDS);

    initialize_arrays(offsets, keys, records, MAX_RECORDS, 1000000L, 1000);

    // Simulate real-time updates
    for (int i = 0; i < MAX_RECORDS; i++) {
        update_record(records, i, rand());
    }

    // Prune old records periodically
    prune_old_records(records, keys, offsets, MAX_RECORDS, 3600);

    log_memory_usage(offsets, keys, records, MAX_RECORDS);

    free(offsets);
    free(keys);
    free(records);

    return 0;
}
