#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct NR_RRC_MESSAGE {
    // Define the fields of NR_RRC_MESSAGE here
} NR_RRC_MESSAGE;

typedef struct RRC_TRANSACTION标识 {
    // Define the fields of RRC_TRANSACTION标识 here
} RRC_TRANSACTION标识;

typedef struct NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER {
    NR_RRC_MESSAGE message;
    RRC_TRANSACTION标识 transaction_id;
    struct NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *next;
} NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER;

typedef struct {
    NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *head;
    NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *tail;
    pthread_mutex_t lock;
    int outstanding_transactions;
} MessageQueue;

void init_message_queue(MessageQueue *queue) {
    queue->head = NULL;
    queue->tail = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    queue->outstanding_transactions = 0;
}

int enqueue_message(MessageQueue *queue, NR_RRC_MESSAGE message, RRC_TRANSACTION标识 transaction_id) {
    pthread_mutex_lock(&queue->lock);
    NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *new_node = (NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *)malloc(sizeof(NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER));
    if (!new_node) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Memory allocation failed
    }
    new_node->message = message;
    new_node->transaction_id = transaction_id;
    new_node->next = NULL;

    if (queue->tail) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
    queue->outstanding_transactions++;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_message(MessageQueue *queue, NR_RRC_MESSAGE *message, RRC_TRANSACTION标识 *transaction_id) {
    pthread_mutex_lock(&queue->lock);
    if (!queue->head) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }
    NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *temp = queue->head;
    *message = temp->message;
    *transaction_id = temp->transaction_id;
    queue->head = temp->next;
    if (!queue->head) {
        queue->tail = NULL;
    }
    free(temp);
    queue->outstanding_transactions--;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int get_outstanding_transactions(MessageQueue *queue) {
    int count;
    pthread_mutex_lock(&queue->lock);
    count = queue->outstanding_transactions;
    pthread_mutex_unlock(&queue->lock);
    return count;
}

void destroy_message_queue(MessageQueue *queue) {
    NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *current = queue->head;
    while (current) {
        NR_RRC_CU_DOWNLINK_CCCH_MESSAGE_TRANSFER *temp = current;
        current = current->next;
        free(temp);
    }
    pthread_mutex_destroy(&queue->lock);
}
