void initialize_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int n) {
    srand(time(NULL));
    for (int i = 0; i < n; i++) {
        pdu[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        pdu[i].RNTI = rand() % 1000;
        pdu[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
}

void process_file(const char *file_path, int buffer_size) {
    FILE *file = fopen(file_path, "rb");
    if (!file) {
        perror("Failed to open file");
        return;
    }

    fseek(file, 0, SEEK_END);
    long file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    char *buffer = (char *)malloc(buffer_size);
    if (!buffer) {
        perror("Failed to allocate buffer");
        fclose(file);
        return;
    }

    double total_chunks = (double)file_size / buffer_size;
    for (long offset = 0; offset < file_size; offset += buffer_size) {
        size_t bytes_read = fread(buffer, 1, buffer_size, file);
        if (bytes_read == 0 && ferror(file)) {
            perror("Error reading file");
            break;
        }

        // Process the buffer here
        // For example, calculate hash or perform other operations

        double progress = ((double)(offset + bytes_read) / file_size) * 100.0;
        printf("%.2f%% processed\r", progress);
    }

    free(buffer);
    fclose(file);
}

int main() {
    int nfaapi_count = 100;
    NFAPI_CRC_INDICATION_PDU_T *nfaapi_pdu = (NFAPI_CRC_INDICATION_PDU_T *)malloc(nfaapi_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!nfaapi_pdu) {
        perror("Failed to allocate memory for NFAPI structures");
        return 1;
    }

    initialize_nfaapi_crc_indication_pdu(nfaapi_pdu, nfaapi_count);

    const char *file_path = "path_to_your_file";
    int buffer_size = MAX_BUFFER_SIZE;

    process_file(file_path, buffer_size);

    free(nfaapi_pdu);
    return 0;
}
