    void* data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t lock;
} List;

List* create_list() {
    List* list = (List*)malloc(sizeof(List));
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void insert(List* list, void* data) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    new_node->data = data;
    new_node->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete(List* list, void* data) {
    Node* current = list->head;
    Node* previous = NULL;
    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data == data) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void update(List* list, void* old_data, void* new_data) {
    Node* current = list->head;
    pthread_mutex_lock(&list->lock);
    while (current != NULL) {
        if (current->data == old_data) {
            current->data = new_data;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize(List* list, FILE* file) {
    Node* current = list->head;
    while (current != NULL) {
        fwrite(current->data, sizeof(void*), 1, file);
        current = current->next;
    }
}

List* deserialize(FILE* file) {
    List* list = create_list();
    void* data;
    while ((fread(&data, sizeof(void*), 1, file)) == 1) {
        insert(list, data);
    }
    return list;
}
