#include <string.h>

typedef struct NR_RRC_MESSAGE {
    // Define the structure for NR_RRC_MESSAGE
} NR_RRC_MESSAGE;

typedef struct RRC_TRANSACTION标识 {
    // Define the structure for RRC_TRANSACTION标识
} RRC_TRANSACTION标识;

typedef struct NR_RRC_CU_UPLINK_CCCH_MESSAGE_TRANSFER {
    NR_RRC_MESSAGE message;
    RRC_TRANSACTION标识 transaction_id;
} NR_RRC_CU_UPLINK_CCCH_MESSAGE_TRANSFER;

typedef struct MessageNode {
    NR_RRC_CU_UPLINK_CCCH_MESSAGE_TRANSFER data;
    struct MessageNode* next;
} MessageNode;

typedef struct MessageQueue {
    MessageNode* head;
    MessageNode* tail;
    size_t count;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
} MessageQueue;

void init_message_queue(MessageQueue* queue, size_t capacity) {
    queue->head = NULL;
    queue->tail = NULL;
    queue->count = 0;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
}

void destroy_message_queue(MessageQueue* queue) {
    MessageNode* current = queue->head;
    while (current != NULL) {
        MessageNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
}

void enqueue_message(MessageQueue* queue, NR_RRC_CU_UPLINK_CCCH_MESSAGE_TRANSFER message) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }
    MessageNode* new_node = (MessageNode*)malloc(sizeof(MessageNode));
    if (new_node == NULL) {
        // Handle memory allocation failure gracefully
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    new_node->data = message;
    new_node->next = NULL;
    if (queue->tail != NULL) {
        queue->tail->next = new_node;
    } else {
        queue->head = new_node;
    }
    queue->tail = new_node;
    queue->count++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

NR_RRC_CU_UPLINK_CCCH_MESSAGE_TRANSFER dequeue_message(MessageQueue* queue) {
    pthread_mutex_lock(&queue->lock);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }
    MessageNode* old_head = queue->head;
    NR_RRC_CU_UPLINK_CCCH_MESSAGE_TRANSFER message = old_head->data;
    if (old_head->next != NULL) {
        queue->head = old_head->next;
    } else {
        queue->head = NULL;
        queue->tail = NULL;
    }
    free(old_head);
    queue->count--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);
    return message;
}

size_t get_message_count(MessageQueue* queue) {
    size_t count;
    pthread_mutex_lock(&queue->lock);
    count = queue->count;
    pthread_mutex_unlock(&queue->lock);
    return count;
}
