    if (!da) return NULL;
    da->array = (LTE_RRC_UE_CONTEXT*)calloc(MAX_ENTRIES, sizeof(LTE_RRC_UE_CONTEXT));
    if (!da->array) {
        free(da);
        return NULL;
    }
    da->count = 0;
    da->capacity = MAX_ENTRIES;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->lock);
    free(da->array);
    pthread_mutex_unlock(&da->lock);
    free(da);
}

int add_entry(DynamicArray *da, LTE_RRC_UE_CONTEXT entry) {
    pthread_mutex_lock(&da->lock);
    if (da->count >= da->capacity) {
        pthread_mutex_unlock(&da->lock);
        return -1; // Array is full
    }
    da->array[da->count++] = entry;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

LTE_RRC_UE_CONTEXT* get_entry(DynamicArray *da, size_t index) {
    if (index >= da->count) return NULL; // Invalid index
    pthread_mutex_lock(&da->lock);
    LTE_RRC_UE_CONTEXT *entry = &da->array[index];
    pthread_mutex_unlock(&da->lock);
    return entry;
}

