        fprintf(stderr, "Failed to add entry to dynamic array\n");
        destroy_dynamic_array(da);
        return 1;
    }

    LTE_RRC_UE_CONTEXT *entry = get_entry(da, 0);
    if (!entry) {
        fprintf(stderr, "Failed to retrieve entry from dynamic array\n");
        destroy_dynamic_array(da);
        return 1;
    }
    // Use the retrieved entry

    destroy_dynamic_array(da);
    return 0;
}
