#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Record {
    int key;
    long offset;
} Record;

typedef struct RecordManager {
    Record* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RecordManager;

RecordManager* create_record_manager(size_t initial_capacity) {
    RecordManager* manager = (RecordManager*)malloc(sizeof(RecordManager));
    if (!manager) return NULL;

    manager->records = (Record*)calloc(initial_capacity, sizeof(Record));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_record_manager(RecordManager* manager) {
    if (manager) {
        pthread_mutex_destroy(&manager->lock);
        free(manager->records);
        free(manager);
    }
}

int add_record(RecordManager* manager, int key, long offset) {
    pthread_mutex_lock(&manager->lock);

    // Check for duplicate keys
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].key == key) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate key error
        }
    }

    // Resize if necessary
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        Record* new_records = (Record*)realloc(manager->records, new_capacity * sizeof(Record));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation error
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    // Insert in sorted order
    size_t insert_index = 0;
    while (insert_index < manager->size && manager->records[insert_index].key < key) {
        ++insert_index;
    }
    for (size_t i = manager->size; i > insert_index; --i) {
        manager->records[i] = manager->records[i - 1];
    }
    manager->records[insert_index].key = key;
    manager->records[insert_index].offset = offset;
    ++manager->size;

    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

Record* get_records(RecordManager* manager) {
    return manager->records;
}
