void init_crc_list(CRC_LIST_T *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

int insert_crc_indication(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_node) {
        perror("Memory allocation failed");
        pthread_mutex_unlock(&list->lock);
        return -1;
    }

    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = CRCFLAG;
    new_node->next = NULL;

    if (list->head == NULL || list->head->RNTI > RNTI) {
        new_node->next = list->head;
        list->head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *current = list->head;
        while (current->next != NULL && current->next->RNTI < RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }

    pthread_mutex_unlock(&list->lock);
    return 0;
}

void free_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }

    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
