            array[i].RNTI = rand() % 65536; // Valid RNTI range

            int duplicate = 0;
            for (int j = 0; j < i; j++) {
                if (array[j].RX_UE_INFORMATION_TAG == array[i].RX_UE_INFORMATION_TAG) {
                    duplicate = 1;
                    break;
