} DoublyLinkedList;

DoublyLinkedList* createList() {
    DoublyLinkedList* list = (DoublyLinkedList*)malloc(sizeof(DoublyLinkedList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroyList(DoublyLinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int insertNode(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= MAX_CAPACITY) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return -2; // Memory allocation failed
    }
    newNode->data = data;
    newNode->prev = NULL;
    newNode->next = list->head;

    if (list->head) {
        list->head->prev = newNode;
    } else {
        list->tail = newNode;
    }

    list->head = newNode;
    list->size++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

// Additional functions for deletion, search, and other operations can be implemented similarly

int main() {
    DoublyLinkedList* list = createList();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T data = {1, 2, 3, rand() % 2};
    if (insertNode(list, data) != 0) {
        fprintf(stderr, "Failed to insert node\n");
        destroyList(list);
        return 1;
    }

    // Additional operations can be performed here

    destroyList(list);
    return 0;
}
