import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class StringHashService {

    private static final int THREAD_POOL_SIZE = 10;
    private ExecutorService executorService;

    public StringHashService() {
        this.executorService = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
    }

    public void processStrings(String... inputStrings) {
        for (String input : inputStrings) {
            executorService.submit(() -> {
                try {
                    byte[] hash = computeSHA256(input);
                    logProcessedString(input, input.length(), hash.length);
                } catch (NoSuchAlgorithmException e) {
                    e.printStackTrace();
                }
            });
        }
    }

    private byte[] computeSHA256(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        return digest.digest(input.getBytes());
    }

    private void logProcessedString(String original, int originalLength, int hashLength) {
        System.out.println("Original Length: " + originalLength + ", Hash Length: " + hashLength);
    }

    public void shutdown() throws InterruptedException {
        executorService.shutdown();
        executorService.awaitTermination(1, TimeUnit.MINUTES);
    }

    public static void main(String[] args) {
        StringHashService service = new StringHashService();
        // Simulate processing multiple strings
        for (int i = 0; i < 1000; i++) {
            StringBuilder sb = new StringBuilder();
            for (int j = 0; j < 8192; j++) {
                sb.append('a');
            }
            service.processStrings(sb.toString());
        }
        try {
            service.shutdown();
        } catch (InterruptedException e) {
            e.printStackTrace();
        }
    }
}
