        pthread_mutex_lock(&data[i].mutex);
        if (!data[i].rrc_messages) {
            fprintf(stderr, "Invalid RRC_MESSAGE_T array pointer at index %zu\n", i);
            pthread_mutex_unlock(&data[i].mutex);
            continue;
        }

        for (size_t j = 0; j < data[i].num_rrc_messages; ++j) {
            if (!data[i].rrc_messages[j]) {
                fprintf(stderr, "Invalid RRC_MESSAGE_T pointer at index %zu, %zu\n", i, j);
            }
        }
        pthread_mutex_unlock(&data[i].mutex);
    }

    printf("NFAPI_MESSAGE_T array validated successfully\n");
}

void freeNfarxData(NFAPI_MESSAGE_T* data, size_t num_messages) {
    for (size_t i = 0; i < num_messages; ++i) {
        pthread_mutex_lock(&data[i].mutex);
        if (data[i].rrc_messages) {
            for (size_t j = 0; j < data[i].num_rrc_messages; ++j) {
                free(data[i].rrc_messages[j]);
            }
            free(data[i].rrc_messages);
        }
        pthread_mutex_unlock(&data[i].mutex);
        pthread_mutex_destroy(&data[i].mutex);
    }

    free(data);
    printf("NFAPI_MESSAGE_T array freed successfully\n");
