typedef struct {
    RX_UE_INFORMATION_TAG ue_tag;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t lock;
} DynamicList;

void initDynamicList(DynamicList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertNode(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (newNode == NULL) {
        // Handle memory allocation failure
        return;
    }
    newNode->data = data;
    newNode->next = list->head;
    pthread_mutex_lock(&list->lock);
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void updateCRCFlag(DynamicList* list, RX_UE_INFORMATION_TAG ue_tag, uint8_t newCRCFlag) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.ue_tag == ue_tag) {
            pthread_mutex_lock(&list->lock);
            current->data.CRCFLAG = newCRCFlag;
            pthread_mutex_unlock(&list->lock);
            return;
        }
        current = current->next;
    }
}

NFAPI_CRC_INDICATION_PDU_T* findNode(DynamicList* list, RX_UE_INFORMATION_TAG ue_tag) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.ue_tag == ue_tag) {
            pthread_mutex_lock(&list->lock);
            NFAPI_CRC_INDICATION_PDU_T* result = &current->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        current = current->next;
    }
    return NULL;
}

void freeDynamicList(DynamicList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
}
