#define MAX_LIST_SIZE 1000
#define MEMORY_THRESHOLD 500000 // 500 KB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int max_size, int *current_size, int *memory_usage) {
    if (max_size <= 0) {
        fprintf(stderr, "Error: Maximum size must be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (*current_size = 0; *current_size < max_size; (*current_size)++) {
        list[*current_size].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[*current_size].RNTI = rand() % 1000;
        list[*current_size].CRC_INDICATION_REL8_TAG = rand() % 2;

        *memory_usage += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        if (*memory_usage > MEMORY_THRESHOLD) {
            fprintf(stderr, "Warning: Memory usage exceeds threshold. Reducing list size.\n");
            break;
        }
    }

    return list;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T *list, int current_size) {
    if (list) {
        free(list);
    }
}

int main() {
    int max_size = 1500;
    int current_size = 0;
    int memory_usage = 0;

    NFAPI_CRC_INDICATION_PDU_T *list = create_and_populate_list(max_size, &current_size, &memory_usage);
    if (list) {
        printf("List created successfully with %d entries.\n", current_size);
        free_list(list, current_size);
    }

    return 0;
}
