#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct MeasurementReport {
    int signal_strength;
    time_t timestamp;
} MeasurementReport;

typedef struct UEContext {
    int ue_id;
    RadioResourceManager *rrm_config;
    MeasurementReport *reports;
    int report_count;
    pthread_mutex_t lock;
} UEContext;

typedef struct DynamicArray {
    UEContext **array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = (UEContext**)malloc(initial_capacity * sizeof(UEContext*));
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    for (size_t i = 0; i < da->size; ++i) {
        free(da->array[i]->reports);
        free(da->array[i]);
    }
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

UEContext* find_ue_context(DynamicArray *da, int ue_id) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&da->lock);
            return da->array[i];
        }
    }
    pthread_mutex_unlock(&da->lock);
    return NULL;
}

void add_or_update_ue_context(DynamicArray *da, int ue_id, RadioResourceManager *rrm_config) {
    UEContext *ue = find_ue_context(da, ue_id);
    if (ue == NULL) {
        pthread_mutex_lock(&da->lock);
        if (da->size >= da->capacity) {
            da->array = realloc(da->array, 2 * da->capacity * sizeof(UEContext*));
            da->capacity *= 2;
        }
        ue = (UEContext*)malloc(sizeof(UEContext));
        ue->ue_id = ue_id;
        ue->rrm_config = rrm_config;
        ue->reports = NULL;
        ue->report_count = 0;
        pthread_mutex_init(&ue->lock, NULL);
        da->array[da->size++] = ue;
        pthread_mutex_unlock(&da->lock);
    } else {
        pthread_mutex_lock(&ue->lock);
        // Update RRM configuration if needed
        pthread_mutex_unlock(&ue->lock);
    }
}

void add_measurement_report(DynamicArray *da, int ue_id, MeasurementReport report) {
    UEContext *ue = find_ue_context(da, ue_id);
    if (ue != NULL) {
        pthread_mutex_lock(&ue->lock);
        if (ue->report_count >= 10) { // Assuming a maximum of 10 reports
            free(ue->reports);
            ue->reports = NULL;
            ue->report_count = 0;
        }
        MeasurementReport *new_reports = realloc(ue->reports, (ue->report_count + 1) * sizeof(MeasurementReport));
        new_reports[ue->report_count++] = report;
        ue->reports = new_reports;
        pthread_mutex_unlock(&ue->lock);
    }
}

MeasurementReport* get_latest_measurement(DynamicArray *da, int ue_id) {
    UEContext *ue = find_ue_context(da, ue_id);
    if (ue != NULL) {
        pthread_mutex_lock(&ue->lock);
        if (ue->report_count > 0) {
            MeasurementReport *latest_report = &ue->reports[ue->report_count - 1];
            pthread_mutex_unlock(&ue->lock);
            return latest_report;
        }
        pthread_mutex_unlock(&ue->lock);
    }
    return NULL;
}
