#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_FRAMES 1024

typedef struct LTE_PHY_RX_FRAME_INFO {
    int PHY_RX_CHANNEL;
    int TX_POWER;
    int FRAME_SEQ_ID;
    int CRC_FLAG;
} LTE_PHY_RX_FRAME_INFO;

typedef struct HashNode {
    int key; // FRAME_SEQ_ID
    LTE_PHY_RX_FRAME_INFO value;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    HashNode** buckets;
    int size;
    pthread_mutex_t lock;
} HashTable;

HashTable* createHashTable(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->buckets = (HashNode**)calloc(size, sizeof(HashNode*));
    table->size = size;
    pthread_mutex_init(&table->lock, NULL);
    return table;
}

unsigned int hashFunction(int key, int size) {
    return abs(key % size);
}

void insertFrame(HashTable* table, LTE_PHY_RX_FRAME_INFO frame) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(frame.FRAME_SEQ_ID, table->size);
    HashNode* newNode = (HashNode*)malloc(sizeof(HashNode));
    newNode->key = frame.FRAME_SEQ_ID;
    newNode->value = frame;
    newNode->next = table->buckets[index];
    table->buckets[index] = newNode;
    pthread_mutex_unlock(&table->lock);
}

LTE_PHY_RX_FRAME_INFO* getFrame(HashTable* table, int key) {
    pthread_mutex_lock(&table->lock);
    unsigned int index = hashFunction(key, table->size);
    HashNode* current = table->buckets[index];
    while (current != NULL) {
        if (current->key == key) {
            pthread_mutex_unlock(&table->lock);
            return &current->value;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

void updateCRCFlag(HashTable* table, int key) {
    LTE_PHY_RX_FRAME_INFO* frame = getFrame(table, key);
    if (frame != NULL) {
        srand(time(NULL));
        frame->CRC_FLAG = rand() % 2; // Randomize CRC_FLAG
    }
}

void freeHashTable(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        HashNode* current = table->buckets[i];
        while (current != NULL) {
            HashNode* next = current->next;
            free(current);
            current = next;
        }
    }
    free(table->buckets);
    pthread_mutex_destroy(&table->lock);
    free(table);
}

int main() {
    HashTable* table = createHashTable(MAX_FRAMES);

    LTE_PHY_RX_FRAME_INFO frame1 = {1, 20, 1001};
    insertFrame(table, frame1);

    updateCRCFlag(table, 1001);

    LTE_PHY_RX_FRAME_INFO* retrievedFrame = getFrame(table, 1001);
    if (retrievedFrame != NULL) {
        printf("CRC_FLAG: %d\n", retrievedFrame->CRC_FLAG);
    }

    freeHashTable(table);

    return 0;
}
