    pthread_mutex_lock(&manager->mutex);
    if (manager->lte_rrc_size == 0 || manager->lte_rrc_requests[manager->lte_rrc_size - 1]->cell_id < request->cell_id) {
        manager->lte_rrc_requests = realloc(manager->lte_rrc_requests, (manager->lte_rrc_size + 1) * sizeof(LTE_RRC_RECONFIGURATION_REQUEST*));
        manager->lte_rrc_requests[manager->lte_rrc_size] = request;
        ++manager->lte_rrc_size;
    } else {
        size_t insert_index = 0;
        while (insert_index < manager->lte_rrc_size && manager->lte_rrc_requests[insert_index]->cell_id < request->cell_id) {
            ++insert_index;
        }
        memmove(&manager->lte_rrc_requests[insert_index + 1], &manager->lte_rrc_requests[insert_index], (manager->lte_rrc_size - insert_index) * sizeof(LTE_RRC_RECONFIGURATION_REQUEST*));
        manager->lte_rrc_requests[insert_index] = request;
        ++manager->lte_rrc_size;
    }
    pthread_mutex_unlock(&manager->mutex);
