    while (index < manager->lte_rrc_size && manager->lte_rrc_requests[index]->cell_id != cell_id) {
        ++index;
    }
    LTE_RRC_RECONFIGURATION_REQUEST* result = (index < manager->lte_rrc_size) ? manager->lte_rrc_requests[index] : NULL;
