#define MAX_ELEMENTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_memory(void* ptr) {
    free(ptr);
}

int serialize_array(NFAPI_CRC_INDICATION_PDU_T* array, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return -1;
    }

    size_t total_size = count * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > 1024) {
        fprintf(stderr, "Serialized data exceeds 1KB per element\n");
        fclose(file);
        return -1;
    }

    if (fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file) != count) {
        perror("Failed to write to file");
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int deserialize_array(NFAPI_CRC_INDICATION_PDU_T** array, int* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    size_t file_size = ftell(file);
    fseek(file, 0, SEEK_SET);

    *count = file_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (*count > MAX_ELEMENTS) {
        fprintf(stderr, "Number of elements exceeds maximum limit\n");
        fclose(file);
        return -1;
    }

    *array = allocate_memory(*count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (fread(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *count, file) != *count) {
        perror("Failed to read from file");
        free_memory(*array);
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int count = 0;

    // Example usage
    if (deserialize_array(&array, &count, "data.bin") == 0) {
        printf("Deserialized %d elements\n", count);
        free_memory(array);
    }

    return 0;
}
