typedef struct RxUeInformationTag {
    int Rnti;
    // Other fields as needed
} RxUeInformationTag;

typedef struct CrcIndicationRel8Tag {
    int CrcFlag;
    // Other fields as needed
} CrcIndicationRel8Tag;

typedef struct DOMElement {
    char* class;
    char* id;
    struct DOMElement** children;
    int childCount;
    // Other fields as needed
} DOMElement;

typedef struct RxUeInformationList {
    RxUeInformationTag** tags;
    int count;
} RxUeInformationList;

int processElement(DOMElement* element, void (*callback)(DOMElement*, void*), void* userData) {
    if (element == NULL || callback == NULL) {
        return -1; // Error handling for null pointers
    }

    if (!callback(element, userData)) {
        return 0; // Skip processing if callback returns false
    }

    RxUeInformationTag* tag = malloc(sizeof(RxUeInformationTag));
    if (tag == NULL) {
        return -2; // Memory allocation error
    }
    tag->Rnti = generateUniqueRnti(); // Function to generate a unique RNTI

    CrcIndicationRel8Tag* crcTag = malloc(sizeof(CrcIndicationRel8Tag));
    if (crcTag == NULL) {
        free(tag);
        return -2; // Memory allocation error
    }
    crcTag->CrcFlag = rand() % 2; // Randomly set CRC flag

    tag->crcIndicationRel8Tag = crcTag;

    // Add the tag to the list or process it further as needed

    return 1;
}

RxUeInformationList* traverseDOM(DOMElement* root, void (*callback)(DOMElement*, void*), void* userData) {
    if (root == NULL || callback == NULL) {
        return NULL; // Error handling for null pointers
    }

    RxUeInformationList* list = malloc(sizeof(RxUeInformationList));
    if (list == NULL) {
        return NULL; // Memory allocation error
    }
    list->tags = NULL;
    list->count = 0;

    traverseDOMHelper(root, callback, userData, list);

    return list;
}

void traverseDOMHelper(DOMElement* element, void (*callback)(DOMElement*, void*), void* userData, RxUeInformationList* list) {
    if (element == NULL || callback == NULL || list == NULL) {
        return; // Error handling for null pointers
    }

    int result = processElement(element, callback, userData);
    if (result > 0) {
        list->count++;
        list->tags = realloc(list->tags, list->count * sizeof(RxUeInformationTag*));
        if (list->tags == NULL) {
            list->count--; // Revert count on memory allocation failure
            return; // Memory allocation error
        }
        list->tags[list->count - 1] = element->tag;
    }

    for (int i = 0; i < element->childCount; i++) {
        traverseDOMHelper(element->children[i], callback, userData, list);
    }
}

void freeRxUeInformationList(RxUeInformationList* list) {
    if (list == NULL) {
        return; // Error handling for null pointers
    }

    for (int i = 0; i < list->count; i++) {
        free(list->tags[i]);
    }
    free(list->tags);
    free(list);
}
