#define MAX_IP_LENGTH 16

typedef struct {
    int flowID;
    char sourceIP[MAX_IP_LENGTH];
    char destinationIP[MAX_IP_LENGTH];
    int packetSize;
} NetworkFlow;

int generateRandomPacketSize(int min, int max) {
    return rand() % (max - min + 1) + min;
}

void initializeNetworkFlows(NetworkFlow **flows, int *numFlows, int maxSize) {
    srand(time(NULL));
    *numFlows = 0;
    while (*numFlows < maxSize / sizeof(NetworkFlow)) {
        NetworkFlow newFlow;
        newFlow.flowID = *numFlows + 1;
        snprintf(newFlow.sourceIP, MAX_IP_LENGTH, "192.168.%d.%d", rand() % 256, rand() % 256);
        snprintf(newFlow.destinationIP, MAX_IP_LENGTH, "10.0.%d.%d", rand() % 256, rand() % 256);
        newFlow.packetSize = generateRandomPacketSize(100, 1000);

        int unique = 1;
        for (int i = 0; i < *numFlows; i++) {
            if (strcmp((*flows)[i].sourceIP, newFlow.sourceIP) == 0 ||
                strcmp((*flows)[i].destinationIP, newFlow.destinationIP) == 0) {
                unique = 0;
                break;
            }
        }

        if (unique) {
            (*flows)[*numFlows] = newFlow;
            (*numFlows)++;
        } else {
            // Handle IP collision or other error
            printf("IP collision detected, retrying...\n");
        }
    }
}

void printNetworkFlows(NetworkFlow *flows, int numFlows) {
    for (int i = 0; i < numFlows; i++) {
        printf("Flow ID: %d, Source IP: %s, Destination IP: %s, Packet Size: %d\n",
               flows[i].flowID, flows[i].sourceIP, flows[i].destinationIP, flows[i].packetSize);
    }
}

int main() {
    int maxSize = 1024 * sizeof(NetworkFlow); // Example max size
    NetworkFlow *flows = (NetworkFlow *)malloc(maxSize);
    if (!flows) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    int numFlows;
    initializeNetworkFlows(&flows, &numFlows, maxSize);

    printNetworkFlows(flows, numFlows);

    free(flows);
    return 0;
}
