#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000

typedef struct {
    int RNTI;
    time_t timestamp;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *buffer;
    size_t head;
    size_t tail;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t not_full;
    pthread_cond_t not_empty;
} CircularBuffer;

CircularBuffer* create_buffer(size_t initial_capacity) {
    CircularBuffer *cb = (CircularBuffer*)malloc(sizeof(CircularBuffer));
    if (!cb) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    cb->buffer = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!cb->buffer) {
        free(cb);
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->capacity = initial_capacity;
    pthread_mutex_init(&cb->mutex, NULL);
    pthread_cond_init(&cb->not_full, NULL);
    pthread_cond_init(&cb->not_empty, NULL);
    return cb;
}

void destroy_buffer(CircularBuffer *cb) {
    free(cb->buffer);
    pthread_mutex_destroy(&cb->mutex);
    pthread_cond_destroy(&cb->not_full);
    pthread_cond_destroy(&cb->not_empty);
    free(cb);
}

int enqueue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == cb->capacity) {
        pthread_cond_wait(&cb->not_full, &cb->mutex);
    }
    cb->buffer[cb->tail] = item;
    cb->tail = (cb->tail + 1) % cb->capacity;
    cb->count++;
    pthread_cond_signal(&cb->not_empty);
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

int dequeue(CircularBuffer *cb, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&cb->mutex);
    while (cb->count == 0) {
        pthread_cond_wait(&cb->not_empty, &cb->mutex);
    }
    *item = cb->buffer[cb->head];
    cb->head = (cb->head + 1) % cb->capacity;
    cb->count--;
    pthread_cond_signal(&cb->not_full);
    pthread_mutex_unlock(&cb->mutex);
    return 0;
}

int main() {
    CircularBuffer *cb = create_buffer(1024);
    if (!cb) {
        return 1;
    }

    NFAPI_CRC_INDICATION_PDU_T item;
    item.RNTI = 12345;
    time(&item.timestamp);
    srand(time(NULL));
    item.CRCFLAG = rand() % 2;

    enqueue(cb, item);

    NFAPI_CRC_INDICATION_PDU_T received_item;
    dequeue(cb, &received_item);

    destroy_buffer(cb);
    return 0;
}
