    LTE_UE_List* list = (LTE_UE_List*)malloc(sizeof(LTE_UE_List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    return list;
}

void destroy_list(LTE_UE_List* list) {
    LTE_UE_Context* current = list->head;
    while (current) {
        LTE_UE_Context* next = current->next;
        free(current->DL_Grant);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

LTE_UE_Context* create_context(int MAC_ID, int RAID, size_t DL_Grant_Size) {
    LTE_UE_Context* context = (LTE_UE_Context*)malloc(sizeof(LTE_UE_Context));
    if (!context) return NULL;
    context->MAC_ID = MAC_ID;
    context->RAID = RAID;
    context->DL_Grant = (char*)malloc(DL_Grant_Size);
    if (!context->DL_Grant) {
        free(context);
        return NULL;
    }
    context->DL_Grant_Size = DL_Grant_Size;
    context->next = NULL;
    return context;
}

void add_context(LTE_UE_List* list, LTE_UE_Context* context) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= MAX_CONTEXTS) {
        // Implement LRU-based deletion here
    }
    context->next = list->head;
    list->head = context;
    list->count++;
    pthread_mutex_unlock(&list->lock);
}

void delete_context(LTE_UE_List* list, int MAC_ID) {
    pthread_mutex_lock(&list->lock);
    LTE_UE_Context** current = &list->head;
    while (*current) {
        if ((*current)->MAC_ID == MAC_ID) {
            LTE_UE_Context* temp = *current;
            *current = (*current)->next;
            free(temp->DL_Grant);
            free(temp);
            list->count--;
            break;
        }
        current = &(*current)->next;
    }
    pthread_mutex_unlock(&list->lock);
}
