    pthread_mutex_t mutex;
    struct UE_Credentials *next;
} UE_Credentials;

UE_Credentials *ue_list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void add_session(int ue_id, int session_id) {
    pthread_mutex_lock(&list_mutex);
    UE_Credentials *current = ue_list;
    while (current != NULL) {
        if (current->ue_id == ue_id) {
            Session *new_session = (Session *)malloc(sizeof(Session));
            new_session->session_id = session_id;
            new_session->next = current->active_sessions;
            current->active_sessions = new_session;
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

void remove_expired_sessions(int ue_id) {
    pthread_mutex_lock(&list_mutex);
    UE_Credentials *current = ue_list;
    while (current != NULL) {
        if (current->ue_id == ue_id) {
            Session **session_ptr = &current->active_sessions;
            while (*session_ptr != NULL) {
                Session *session = *session_ptr;
                // Check if session is expired
                if (is_session_expired(session)) {
                    *session_ptr = session->next;
                    free(session);
                } else {
                    session_ptr = &session->next;
                }
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

void update_session(int ue_id, int session_id) {
    pthread_mutex_lock(&list_mutex);
    UE_Credentials *current = ue_list;
    while (current != NULL) {
        if (current->ue_id == ue_id) {
            Session *session = current->active_sessions;
            while (session != NULL) {
                if (session->session_id == session_id) {
                    // Update session information
                    update_session_info(session);
                    pthread_mutex_unlock(&list_mutex);
                    return;
                }
                session = session->next;
            }
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_mutex);
}

void add_ue_credentials(int ue_id, const char *imsi) {
    pthread_mutex_lock(&list_mutex);
    UE_Credentials *new_ue = (UE_Credentials *)malloc(sizeof(UE_Credentials));
    new_ue->ue_id = ue_id;
    strcpy(new_ue->imsi, imsi);
    new_ue->active_sessions = NULL;
    pthread_mutex_init(&new_ue->mutex, NULL);
    new_ue->next = ue_list;
    ue_list = new_ue;
    pthread_mutex_unlock(&list_mutex);
}

void free_ue_credentials() {
    pthread_mutex_lock(&list_mutex);
    UE_Credentials *current = ue_list;
    while (current != NULL) {
        Session *session = current->active_sessions;
        while (session != NULL) {
            Session *next_session = session->next;
            free(session);
            session = next_session;
        }
        pthread_mutex_destroy(&current->mutex);
        UE_Credentials *next_ue = current->next;
        free(current);
        current = next_ue;
    }
    ue_list = NULL;
    pthread_mutex_unlock(&list_mutex);
}
