typedef struct Session {
    int session_id;
    time_t expiration_time;
    int resource_usage;
} Session;

typedef struct UECredential {
    int ueid;
    char imsi[20];
    Session *active_sessions;
    size_t num_active_sessions;
    int max_sessions;
} UECredential;

UECredential *ue_credentials = NULL;
size_t num_ue_credentials = 0;
pthread_mutex_t credential_lock = PTHREAD_MUTEX_INITIALIZER;

void* initialize_ue_credentials(size_t initial_capacity) {
    // Allocate memory for the initial capacity of UE credentials
    ue_credentials = (UECredential*)malloc(initial_capacity * sizeof(UECredential));
    if (!ue_credentials) {
        perror("Failed to allocate memory for UE credentials");
        return NULL;
    }
    num_ue_credentials = initial_capacity;
    return ue_credentials;
}

void add_new_session(int ueid, int session_id, time_t expiration_time, int resource_usage) {
    pthread_mutex_lock(&credential_lock);
    UECredential *uec = get_ue_credential_by_ueid(ueid);
    if (!uec || uec->num_active_sessions >= uec->max_sessions) {
        pthread_mutex_unlock(&credential_lock);
        return;
    }
    Session new_session = {session_id, expiration_time, resource_usage};
    uec->active_sessions[uec->num_active_sessions++] = new_session;
    pthread_mutex_unlock(&credential_lock);
}

void remove_expired_sessions(int ueid) {
    pthread_mutex_lock(&credential_lock);
    UECredential *uec = get_ue_credential_by_ueid(ueid);
    if (!uec) {
        pthread_mutex_unlock(&credential_lock);
        return;
    }
    for (size_t i = 0; i < uec->num_active_sessions; ) {
        if (time(NULL) >= uec->active_sessions[i].expiration_time) {
            // Shift elements to remove the expired session
            memmove(&uec->active_sessions[i], &uec->active_sessions[i + 1], (uec->num_active_sessions - i - 1) * sizeof(Session));
            uec->num_active_sessions--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&credential_lock);
}

void update_session_info(int ueid, int session_id, time_t new_expiration_time, int new_resource_usage) {
    pthread_mutex_lock(&credential_lock);
    UECredential *uec = get_ue_credential_by_ueid(ueid);
    if (!uec) {
        pthread_mutex_unlock(&credential_lock);
        return;
    }
    for (size_t i = 0; i < uec->num_active_sessions; i++) {
        if (uec->active_sessions[i].session_id == session_id) {
            uec->active_sessions[i].expiration_time = new_expiration_time;
            uec->active_sessions[i].resource_usage = new_resource_usage;
            break;
        }
    }
    pthread_mutex_unlock(&credential_lock);
}

UECredential* get_ue_credential_by_ueid(int ueid) {
    for (size_t i = 0; i < num_ue_credentials; i++) {
        if (ue_credentials[i].ueid == ueid) {
            return &ue_credentials[i];
        }
    }
    return NULL;
}

bool is_session_active(int ueid, int session_id) {
    pthread_mutex_lock(&credential_lock);
    UECredential *uec = get_ue_credential_by_ueid(ueid);
    if (!uec) {
        pthread_mutex_unlock(&credential_lock);
        return false;
    }
    for (size_t i = 0; i < uec->num_active_sessions; i++) {
        if (uec->active_sessions[i].session_id == session_id) {
            pthread_mutex_unlock(&credential_lock);
            return true;
        }
    }
    pthread_mutex_unlock(&credential_lock);
    return false;
}
