#define MAX_STATIONS 1000
#define MAX_READINGS 10000

typedef struct {
    char timestamp[20];
    int locationID;
    float temperature;
} TemperatureReading;

TemperatureReading* readTemperatureReadings(const char* filename, int* count) {
    FILE* file = fopen(filename, "r");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    TemperatureReading* readings = (TemperatureReading*)malloc(MAX_READINGS * sizeof(TemperatureReading));
    if (!readings) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), file)) {
        if (i >= MAX_READINGS) {
            fprintf(stderr, "Too many readings\n");
            free(readings);
            fclose(file);
            return NULL;
        }
        sscanf(line, "%[^,],%d,%f", readings[i].timestamp, &readings[i].locationID, &readings[i].temperature);
        i++;
    }

    *count = i;
    fclose(file);
    return readings;
}

float findHighestTemperature(TemperatureReading* readings, int count) {
    float highest = -100.0; // Assuming temperatures are in Celsius
    for (int i = 0; i < count; i++) {
        if (readings[i].temperature > highest) {
            highest = readings[i].temperature;
        }
    }
    return highest;
}

int main() {
    int count1, count2;
    TemperatureReading* readings1 = readTemperatureReadings("station1.csv", &count1);
    TemperatureReading* readings2 = readTemperatureReadings("station2.csv", &count2);

    if (!readings1 || !readings2) {
        return 1;
    }

    float highest1 = findHighestTemperature(readings1, count1);
    float highest2 = findHighestTemperature(readings2, count2);

    printf("Highest temperature from station 1: %.2f\n", highest1);
    printf("Highest temperature from station 2: %.2f\n", highest2);

    free(readings1);
    free(readings2);

    return 0;
}
