        pthread_mutex_lock(&nfaapi_mutex);
        if (nfaapi_count < MAX_NFAPI_STRUCTS) {
            nfaapi_structs[nfaapi_count].RX_UE_INFORMATION_TAG = rand() % 100;
            nfaapi_structs[nfaapi_count].RNTI = rand() % 1000;
