#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int customRandom(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

NFAPI_CRC_INDICATION_PDU_T* createNFAPICRCArray(int N, int seed, int maxRNTI) {
    if (N <= 0 || N > 1000 || maxRNTI < 1 || maxRNTI > 65535) {
        printf("Invalid input parameters.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    srand(seed);
    int* rntiSet = (int*)calloc(maxRNTI, sizeof(int));
    if (!rntiSet) {
        free(array);
        printf("Memory allocation failed for RNTI set.\n");
        return NULL;
    }

    int uniqueCount = 0;
    while (uniqueCount < N) {
        int rnti = customRandom(1, maxRNTI);
        if (!rntiSet[rnti]) {
            array[uniqueCount].RX_UE_INFORMATION_TAG = uniqueCount + 1;
            array[uniqueCount].RNTI = rnti;
            array[uniqueCount].CRC_INDICATION_REL8_TAG = customRandom(0, 1);
            array[uniqueCount].CRCFLAG = customRandom(0, 1);
            rntiSet[rnti] = 1;
            uniqueCount++;
        }
    }

    free(rntiSet);
    return array;
}

void freeNFAPICRCArray(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        free(array);
    }
}
