#include <pthread.h>

#define RRC_COMMAND_TAG 1
#define MEASUREMENT_REPORT_TAG 2
#define PHICH_CONFIGURATION_TAG 3

typedef struct {
    int tag;
    // Add other fields as needed for UMTS_RRC_MESSAGE
} UMTS_RRC_MESSAGE;

typedef struct {
    UMTS_RRC_MESSAGE *messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->messages = (UMTS_RRC_MESSAGE*)calloc(initial_capacity, sizeof(UMTS_RRC_MESSAGE));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->messages);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_message(DynamicArray *array, UMTS_RRC_MESSAGE message) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        array->messages = (UMTS_RRC_MESSAGE*)realloc(array->messages, new_capacity * sizeof(UMTS_RRC_MESSAGE));
        array->capacity = new_capacity;
    }
    array->messages[array->size++] = message;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_message(DynamicArray *array, int index) {
    if (index < 0 || index >= array->size) {
        return -1; // Invalid index
    }
    pthread_mutex_lock(&array->mutex);
    for (size_t i = index; i < array->size - 1; ++i) {
        array->messages[i] = array->messages[i + 1];
    }
    array->size--;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

UMTS_RRC_MESSAGE* get_message(DynamicArray *array, int index) {
    if (index < 0 || index >= array->size) {
        return NULL; // Invalid index
    }
    pthread_mutex_lock(&array->mutex);
    UMTS_RRC_MESSAGE *message = &array->messages[index];
    pthread_mutex_unlock(&array->mutex);
    return message;
}

int main() {
    DynamicArray *array = create_dynamic_array(10);

    UMTS_RRC_MESSAGE msg1 = {RRC_COMMAND_TAG};
    UMTS_RRC_MESSAGE msg2 = {MEASUREMENT_REPORT_TAG};

    add_message(array, msg1);
    add_message(array, msg2);

    UMTS_RRC_MESSAGE *msg = get_message(array, 0);
    if (msg) {
        printf("Tag: %d\n", msg->tag);
    }

    remove_message(array, 0);

    destroy_dynamic_array(array);

    return 0;
}
