typedef struct {
    UMTS_RRC_MESSAGE messages[MAX_MESSAGES];
    atomic_int next_index;
    pthread_mutex_t lock;
} MESSAGE_QUEUE;

void init_message_queue(MESSAGE_QUEUE *queue) {
    queue->next_index = 0;
    pthread_mutex_init(&queue->lock, NULL);
}

int enqueue_message(MESSAGE_QUEUE *queue, UMTS_RRC_MESSAGE message) {
    pthread_mutex_lock(&queue->lock);
    int index = atomic_fetch_add(&queue->next_index, 1);
    if (index >= MAX_MESSAGES) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is full
    }
    queue->messages[index] = message;
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

int dequeue_message(MESSAGE_QUEUE *queue, UMTS_RRC_MESSAGE *message) {
    pthread_mutex_lock(&queue->lock);
    if (atomic_load(&queue->next_index) == 0) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }
    int index = atomic_fetch_sub(&queue->next_index, 1);
    *message = queue->messages[index];
    pthread_mutex_unlock(&queue->lock);
    return 0;
}

void destroy_message_queue(MESSAGE_QUEUE *queue) {
    pthread_mutex_destroy(&queue->lock);
}
