} LTE_DL_FRAME_STRUCT;

typedef struct {
    LTE_DL_FRAME_STRUCT *frames;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} FrameList;

void init_frame_list(FrameList *list) {
    list->frames = malloc(MAX_FRAMES * sizeof(LTE_DL_FRAME_STRUCT));
    if (list->frames == NULL) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = MAX_FRAMES;
    pthread_mutex_init(&list->lock, NULL);
}

void free_frame_list(FrameList *list) {
    pthread_mutex_lock(&list->lock);
    free(list->frames);
    list->frames = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}

int add_frame(FrameList *list, LTE_DL_FRAME_STRUCT frame) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        // Handle buffer overflow
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->frames[list->count++] = frame;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int update_frame(FrameList *list, int index, LTE_DL_FRAME_STRUCT new_frame) {
    pthread_mutex_lock(&list->lock);
    if (index < 0 || index >= list->count) {
        // Handle invalid frame index
        pthread_mutex_unlock(&list->lock);
        return -1;
    }
    list->frames[index] = new_frame;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

