#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int custom_random(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_indications(int N, int seed, int max_rnti) {
    if (N < 1 || N > 1000) {
        fprintf(stderr, "Invalid number of structures. Must be between 1 and 1000.\n");
        return NULL;
    }
    if (max_rnti < 1 || max_rnti > 65535) {
        fprintf(stderr, "Invalid RNTI range. Must be between 1 and 65535.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        fprintf(stderr, "Memory allocation failed.\n");
        return NULL;
    }

    srand(seed);
    int* rnti_set = (int*)calloc(max_rnti + 1, sizeof(int));
    if (!rnti_set) {
        free(array);
        fprintf(stderr, "Memory allocation failed for RNTI set.\n");
        return NULL;
    }

    int count = 0;
    while (count < N) {
        int rnti = custom_random(1, max_rnti);
        if (!rnti_set[rnti]) {
            array[count].RX_UE_INFORMATION_TAG = count + 1;
            array[count].RNTI = rnti;
            array[count].CRC_INDICATION_REL8_TAG = count + 1;
            array[count].CRCFLAG = custom_random(0, 1);
            rnti_set[rnti] = 1;
            count++;
        }
    }

    free(rnti_set);
    return array;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array) {
        free(array);
    }
}
