#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct UELinkedList {
    int rnti;
    char *downlinkBuffer;
    struct UELinkedList *uplinkRequests;
    struct UELinkedList *next;
} UELinkedList;

typedef struct UEContext {
    int rnti;
    char *downlinkBuffer;
    UELinkedList *uplinkRequests;
    pthread_mutex_t mutex;
} UEContext;

UEContext* createUEContext(int rnti, size_t buffer_size) {
    UEContext *ue = (UEContext *)malloc(sizeof(UEContext));
    if (!ue) return NULL;
    ue->rnti = rnti;
    ue->downlinkBuffer = (char *)malloc(buffer_size);
    if (!ue->downlinkBuffer) {
        free(ue);
        return NULL;
    }
    ue->uplinkRequests = NULL;
    pthread_mutex_init(&ue->mutex, NULL);
    return ue;
}

void destroyUEContext(UEContext *ue) {
    if (ue->downlinkBuffer) free(ue->downlinkBuffer);
    UELinkedList *current = ue->uplinkRequests;
    while (current) {
        UELinkedList *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&ue->mutex);
    free(ue);
}

void addOrUpdateUEContext(UEContext **head, int rnti, size_t buffer_size) {
    UEContext *current = *head;
    while (current) {
        if (current->rnti == rnti) {
            pthread_mutex_lock(&current->mutex);
            free(current->downlinkBuffer);
            current->downlinkBuffer = (char *)malloc(buffer_size);
            pthread_mutex_unlock(&current->mutex);
            return;
        }
        current = current->next;
    }
    UEContext *newUE = createUEContext(rnti, buffer_size);
    if (!newUE) return;
    newUE->next = *head;
    *head = newUE;
}

UEContext* getUEContext(UEContext *head, int rnti) {
    UEContext *current = head;
    while (current) {
        if (current->rnti == rnti) {
            pthread_mutex_lock(&current->mutex);
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void* signalingProtocolStack(void *arg) {
    // Simulate signaling protocol stack interaction
    UEContext **head = (UEContext **)arg;
    for (int i = 0; i < 100; i++) {
        addOrUpdateUEContext(head, i, 1024);
        UEContext *ue = getUEContext(*head, i);
        if (ue) {
            // Perform operations with the UE context
            free(ue->downlinkBuffer);
            destroyUEContext(ue);
        }
    }
    return NULL;
}

int main() {
    UEContext *head = NULL;
    pthread_t thread1, thread2;

    pthread_create(&thread1, NULL, signalingProtocolStack, &head);
    pthread_create(&thread2, NULL, signalingProtocolStack, &head);

    pthread_join(thread1, NULL);
    pthread_join(thread2, NULL);

    return 0;
}
```

This code provides a basic structure for managing UE contexts in a C library. It includes functions to create and destroy UE contexts, add or update existing ones, and retrieve specific UE contexts by their RNTI. The `signalingProtocolStack` function simulates interaction with an external signaling protocol stack, demonstrating how the library can be used in a multi-threaded environment.']

