void process_input(int *input_size, int **numbers) {
    printf("Enter the number of integers: ");
    if (scanf("%d", input_size) != 1 || *input_size <= 0) {
        fprintf(stderr, "Invalid input for number of integers.\n");
        exit(EXIT_FAILURE);
    }

    *numbers = (int *)malloc(*input_size * sizeof(int));
    if (*numbers == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter the integers:\n");
    for (int i = 0; i < *input_size; i++) {
        if (scanf("%d", &(*numbers)[i]) != 1) {
            fprintf(stderr, "Invalid input for integer at position %d.\n", i);
            free(*numbers);
            exit(EXIT_FAILURE);
        }
    }
}

void find_largest(int size, int *numbers) {
    int largest = numbers[0];
    for (int i = 1; i < size; i++) {
        if (numbers[i] > largest) {
            largest = numbers[i];
        }
    }
    printf("Largest integer: %d\n", largest);
}

double calculate_average(int size, int *numbers) {
    double sum = 0;
    for (int i = 0; i < size; i++) {
        sum += numbers[i];
    }
    return sum / size;
}

void process_duplicates_and_negatives(int size, int *numbers) {
    printf("Duplicates and negative numbers:\n");
    for (int i = 0; i < size; i++) {
        if (numbers[i] <= 0) {
            printf("%d ", numbers[i]);
        }
    }
    printf("\n");
}

void free_memory(int **numbers) {
    free(*numbers);
    *numbers = NULL;
}

int main() {
    int input_size, *numbers;

    process_input(&input_size, &numbers);

    find_largest(input_size, numbers);
    double average = calculate_average(input_size, numbers);
    printf("Average: %.2f\n", average);
    process_duplicates_and_negatives(input_size, numbers);

    free_memory(&numbers);

    return 0;
}
