#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_QUEUE_SIZE 1024

typedef struct {
    int pdcp_sn;
    RRC_PDU_TAG rrc_pdu_tag;
} NFAPI_MESSAGE_T;

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} MessageQueue;

void init_message_queue(MessageQueue *queue, size_t initial_capacity) {
    queue->messages = (NFAPI_MESSAGE_T *)malloc(initial_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!queue->messages) {
        perror("Failed to allocate memory for message queue");
        exit(EXIT_FAILURE);
    }
    queue->capacity = initial_capacity;
    queue->size = 0;
    pthread_mutex_init(&queue->mutex, NULL);
}

void resize_message_queue(MessageQueue *queue, size_t new_capacity) {
    NFAPI_MESSAGE_T *new_messages = (NFAPI_MESSAGE_T *)realloc(queue->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
    if (!new_messages) {
        perror("Failed to reallocate memory for message queue");
        exit(EXIT_FAILURE);
    }
    queue->messages = new_messages;
    queue->capacity = new_capacity;
}

void enqueue_message(MessageQueue *queue, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size == queue->capacity) {
        resize_message_queue(queue, queue->capacity * 2);
    }
    queue->messages[queue->size++] = message;
    pthread_mutex_unlock(&queue->mutex);
}

NFAPI_MESSAGE_T dequeue_message(MessageQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    if (queue->size == 0) {
        NFAPI_MESSAGE_T empty_message = {0};
        pthread_mutex_unlock(&queue->mutex);
        return empty_message;
    }
    NFAPI_MESSAGE_T message = queue->messages[0];
    for (size_t i = 1; i < queue->size; ++i) {
        queue->messages[i - 1] = queue->messages[i];
    }
    --queue->size;
    pthread_mutex_unlock(&queue->mutex);
    return message;
}

void validate_message_queue(MessageQueue *queue) {
    for (size_t i = 0; i < queue->size - 1; ++i) {
        if (queue->messages[i].pdcp_sn == queue->messages[i + 1].pdcp_sn) {
            fprintf(stderr, "Error: Duplicate PDCP_SN found in message queue\n");
            exit(EXIT_FAILURE);
        }
    }
}

void cleanup_message_queue(MessageQueue *queue) {
    pthread_mutex_lock(&queue->mutex);
    free(queue->messages);
    queue->messages = NULL;
    queue->capacity = 0;
    queue->size = 0;
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
}

int main() {
    MessageQueue queue;
    init_message_queue(&queue, MAX_QUEUE_SIZE);

    // Example usage
    NFAPI_MESSAGE_T message = {rand(), generate_rrc_pdu_tag()};
    enqueue_message(&queue, message);

    NFAPI_MESSAGE_T received_message = dequeue_message(&queue);
    validate_message_queue(&queue);

    cleanup_message_queue(&queue);
    return 0;
}
```

This code snippet provides a basic implementation of a thread-safe message queue for handling `NFAPI_MESSAGE_T` structures. It includes functions for initializing, resizing, enqueuing, dequeuing, validating, and cleaning up the message queue. The example usage in the `main` function demonstrates how to use these functions. Note that this code is a simplified version and may need further enhancements based on specific requirements and constraints.']

