typedef struct {
    uint32_t sequence_number;
    uint32_t acknowledgment_number;
    // Add other necessary fields for TCP segment metadata
} TCP_SEGMENT;

typedef struct {
    TCP_SEGMENT *segment;
    int socket_metadata; // Example metadata, adjust as needed
} TCP_MESSAGE_T;

TCP_MESSAGE_T** manage_tcp_messages(int initial_size) {
    if (initial_size <= 0) {
        return NULL; // Handle edge case where size is zero or negative
    }

    TCP_MESSAGE_T **messages = (TCP_MESSAGE_T**)malloc(initial_size * sizeof(TCP_MESSAGE_T*));
    if (!messages) {
        return NULL; // Handle memory allocation failure
    }

    for (int i = 0; i < initial_size; i++) {
        messages[i] = (TCP_MESSAGE_T*)malloc(sizeof(TCP_MESSAGE_T));
        if (!messages[i]) {
            // Free previously allocated memory on failure
            for (int j = 0; j < i; j++) {
                free(messages[j]);
            }
            free(messages);
            return NULL;
        }

        messages[i]->segment = (TCP_SEGMENT*)malloc(sizeof(TCP_SEGMENT));
        if (!messages[i]->segment) {
            // Free previously allocated memory on failure
            for (int j = 0; j <= i; j++) {
                free(messages[j]->segment);
                free(messages[j]);
            }
            free(messages);
            return NULL;
        }

        // Initialize segment and metadata as needed
    }

    return messages;
}

void free_tcp_messages(TCP_MESSAGE_T **messages, int size) {
    if (!messages || size <= 0) {
        return; // Handle edge case where size is zero or negative
    }

    for (int i = 0; i < size; i++) {
        if (messages[i]) {
            free(messages[i]->segment);
            free(messages[i]);
        }
    }

    free(messages);
}
