#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct Service {
    char *name;
    int status; // 0: inactive, 1: active
    void *config; // Pointer to service configuration data
} Service;

typedef struct DeviceCredential {
    char *deviceID;
    char *deviceType;
    Service **services;
    int numServices;
    pthread_mutex_t lock;
} DeviceCredential;

DeviceCredential* createDeviceCredential(char *deviceID, char *deviceType) {
    DeviceCredential *dc = (DeviceCredential*)malloc(sizeof(DeviceCredential));
    dc->deviceID = strdup(deviceID);
    dc->deviceType = strdup(deviceType);
    dc->services = NULL;
    dc->numServices = 0;
    pthread_mutex_init(&dc->lock, NULL);
    return dc;
}

void addService(DeviceCredential *dc, char *serviceName, int status, void *config) {
    pthread_mutex_lock(&dc->lock);
    Service *newService = (Service*)malloc(sizeof(Service));
    newService->name = strdup(serviceName);
    newService->status = status;
    newService->config = config;

    dc->services = realloc(dc->services, (dc->numServices + 1) * sizeof(Service*));
    dc->services[dc->numServices++] = newService;
    pthread_mutex_unlock(&dc->lock);
}

void removeInactiveServices(DeviceCredential *dc) {
    pthread_mutex_lock(&dc->lock);
    int i = 0, j = 0;
    while (i < dc->numServices) {
        if (dc->services[i]->status == 0) {
            free(dc->services[i]->name);
            free(dc->services[i]);
            memmove(&dc->services[j], &dc->services[i + 1], (dc->numServices - i - 1) * sizeof(Service*));
            dc->numServices--;
        } else {
            i++;
            j++;
        }
    }
    pthread_mutex_unlock(&dc->lock);
}

void updateServiceConfig(DeviceCredential *dc, char *serviceName, void *newConfig) {
    pthread_mutex_lock(&dc->lock);
    for (int i = 0; i < dc->numServices; i++) {
        if (strcmp(dc->services[i]->name, serviceName) == 0) {
            free(dc->services[i]->config);
            dc->services[i]->config = newConfig;
            break;
        }
    }
    pthread_mutex_unlock(&dc->lock);
}

void destroyDeviceCredential(DeviceCredential *dc) {
    for (int i = 0; i < dc->numServices; i++) {
        free(dc->services[i]->name);
        free(dc->services[i]);
    }
    free(dc->services);
    free(dc->deviceID);
    free(dc->deviceType);
    pthread_mutex_destroy(&dc->lock);
    free(dc);
}
