#else
    sem_t* handle;
#endif
} Semaphore;

void log_metrics(Semaphore* sem, const char* operation) {
    // Implement custom logging mechanism here
}

Semaphore* create_semaphore(int initial_value) {
    Semaphore* sem = (Semaphore*)malloc(sizeof(Semaphore));
#ifdef _WIN32
    sem->handle = CreateSemaphore(NULL, initial_value, 1000, NULL);
#else
    if (sem_init(&sem->handle, 0, initial_value) != 0) {
        free(sem);
        return NULL;
    }
#endif
    return sem;
}

void destroy_semaphore(Semaphore* sem) {
#ifdef _WIN32
    CloseHandle(sem->handle);
#else
    sem_destroy(sem->handle);
#endif
    free(sem);
}

int semaphore_wait(Semaphore* sem) {
#ifdef _WIN32
    if (WaitForSingleObject(sem->handle, INFINITE) != WAIT_OBJECT_0) {
        return -1;
    }
#else
    if (sem_wait(sem->handle) == -1) {
        return -1;
    }
#endif
    log_metrics(sem, "wait");
    return 0;
}

int semaphore_signal(Semaphore* sem) {
#ifdef _WIN32
    if (!ReleaseSemaphore(sem->handle, 1, NULL)) {
        return -1;
    }
#else
    if (sem_post(sem->handle) == -1) {
        return -1;
    }
#endif
    log_metrics(sem, "signal");
    return 0;
}

int main() {
    Semaphore* sem = create_semaphore(1);
    if (!sem) {
        fprintf(stderr, "Failed to create semaphore\n");
        return 1;
    }

    // Simulate semaphore usage
    for (int i = 0; i < 5; ++i) {
        if (semaphore_wait(sem) == -1) {
            fprintf(stderr, "Semaphore wait failed\n");
            destroy_semaphore(sem);
            return 1;
        }
        printf("Thread %d acquired semaphore\n", i);

        // Simulate some work
        sleep(1);

        if (semaphore_signal(sem) == -1) {
            fprintf(stderr, "Semaphore signal failed\n");
            destroy_semaphore(sem);
            return 1;
        }
        printf("Thread %d released semaphore\n", i);
    }

    destroy_semaphore(sem);
    return 0;
}
