use std::fs;
use std::path::Path;
use llvm_ir::{Module, Function, BasicBlock};
use lexer::Lexer;
use parser::Parser;

fn generate_llvm_ir(file_path: &str) -> Result<(), Box<dyn std::error::Error>> {
    let content = fs::read_to_string(Path::new(file_path))?;
    let mut lexer = Lexer::new(&content);
    let mut parser = Parser::new(&mut lexer);

    let module = Module::new("generated_module");
    let function = Function::new("main", &module, llvm_ir::FunctionType::void());
    let basic_block = BasicBlock::new("entry", &function);

    // Parse the input file and generate LLVM IR code
    while let Some(node) = parser.parse_next_node() {
        match node {
            Node::Expression(expr) => {
                // Generate LLVM IR for the expression
                expr.generate_llvm_ir(&basic_block);
            }
            Node::Statement(stmt) => {
                // Generate LLVM IR for the statement
                stmt.generate_llvm_ir(&basic_block);
            }
            _ => {}
        }
    }

    // Print the parsed nodes and generated LLVM IR code
    println!("Parsed Nodes: {:?}", parser.parsed_nodes());
    println!("Generated LLVM IR:\n{}", module.to_string());

    Ok(())
}
