    public ConfigManager()
    {
        ueContexts = new ConcurrentDictionary<int, UEContext>();
    }

    public void LoadConfigFromXml(string filePath)
    {
        XDocument doc = XDocument.Load(filePath);
        foreach (var element in doc.Root.Elements("UEContext"))
        {
            int ue_id = (int)element.Attribute("ue_id");
            RRMConfig rrm_config = new RRMConfig
            {
                // Initialize RRM configuration settings from XML
            };
            ConcurrentBag<MeasurementReport> measurements = new ConcurrentBag<MeasurementReport>();

            UEContext context = new UEContext
            {
                ue_id = ue_id,
                rrm_config = rrm_config,
                measurements = measurements
            };

            ueContexts.TryAdd(ue_id, context);
        }
    }

    public void AddOrUpdateUEContext(int ue_id, RRMConfig rrm_config)
    {
        UEContext context;
        if (ueContexts.TryGetValue(ue_id, out context))
        {
            context.rrm_config = rrm_config;
        }
        else
        {
            ConcurrentBag<MeasurementReport> measurements = new ConcurrentBag<MeasurementReport>();
            ueContexts.TryAdd(ue_id, new UEContext { ue_id = ue_id, rrm_config = rrm_config, measurements = measurements });
        }
    }

    public bool TryGetUEContext(int ue_id, out UEContext context)
