#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_CACHE_SIZE 100

typedef struct {
    char *key;
    time_t last_accessed;
    int access_frequency;
} CacheEntry;

CacheEntry cache[MAX_CACHE_SIZE];
int cache_size = 0;
int eviction_count = 0;

void add_entry(const char *key) {
    if (cache_size >= MAX_CACHE_SIZE) {
        evict_stale_entries();
    }
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].key, key) == 0) {
            cache[i].last_accessed = time(NULL);
            cache[i].access_frequency++;
            return;
        }
    }
    cache[cache_size].key = strdup(key);
    cache[cache_size].last_accessed = time(NULL);
    cache[cache_size].access_frequency = 1;
    cache_size++;
}

void update_entry(const char *key) {
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].key, key) == 0) {
            cache[i].last_accessed = time(NULL);
            cache[i].access_frequency++;
            return;
        }
    }
}

void evict_stale_entries() {
    int min_access_frequency = INT_MAX;
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].access_frequency < min_access_frequency) {
            min_access_frequency = cache[i].access_frequency;
        }
    }
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].access_frequency == min_access_frequency) {
            free(cache[i].key);
            memmove(&cache[i], &cache[i + 1], sizeof(CacheEntry) * (cache_size - i - 1));
            cache_size--;
            eviction_count++;
            break;
        }
    }
}

const char* get_most_frequently_accessed_entry() {
    int max_access_frequency = 0;
    const char *most_frequent_key = NULL;
    for (int i = 0; i < cache_size; i++) {
        if (cache[i].access_frequency > max_access_frequency) {
            max_access_frequency = cache[i].access_frequency;
            most_frequent_key = cache[i].key;
        }
    }
    return most_frequent_key;
}

void reset_eviction_count() {
    eviction_count = 0;
}

int get_cache_size() {
    return cache_size;
}

int get_eviction_count() {
    return eviction_count;
}
