LineData* readAndProcessFile(const char *filename);
void appendToFile(LineData *line, const char *outputFilename);
void freeLineData(LineData *line);

int main(int argc, char *argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <file1> <file2> ...\n", argv[0]);
        return 1;
    }

    LineData *head = NULL;

    for (int i = 1; i < argc; ++i) {
        LineData *line = readAndProcessFile(argv[i]);
        if (line != NULL) {
            line->next = head;
            head = line;
        }
    }

    // Process the linked list and append to output file
    FILE *outputFile = fopen("output.txt", "a");
    if (outputFile == NULL) {
        perror("Failed to open output file");
        return 1;
    }

    LineData *current = head;
    while (current != NULL) {
        appendToFile(current, "output.txt");
        current = current->next;
    }

    // Free allocated memory
    current = head;
    while (current != NULL) {
        freeLineData(current);
        LineData *temp = current;
        current = current->next;
        free(temp);
    }

    fclose(outputFile);
    return 0;
}

