    if (file == NULL) {
        perror("Failed to open output file for appending");
        return;
    }

    // Write the modified line data to the file
    // ...

    fclose(file);
}

// Function to free allocated memory for a LineData structure
void freeLineData(LineData *line) {
    free(line->data);
    free(line->fields);
}
