#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Function prototypes
void* convert_image_to_pdf(void* arg);
int execute_conversion_command(const char* source_file, const char* destination_file, int compression_level, const char* metadata_file);

// Structure to hold conversion parameters
typedef struct {
    char* source_file;
    char* destination_file;
    int compression_level;
    char* metadata_file;
} ConversionParams;

int main(int argc, char* argv[]) {
    if (argc < 4) {
        fprintf(stderr, "Usage: %s <source_file> <destination_file> <compression_level> [<metadata_file>]\n", argv[0]);
        return 1;
    }

    ConversionParams params = {
        .source_file = argv[1],
        .destination_file = argv[2],
        .compression_level = atoi(argv[3]),
        .metadata_file = argc > 4 ? argv[4] : NULL
    };

    pthread_t thread_id;
    if (pthread_create(&thread_id, NULL, convert_image_to_pdf, &params) != 0) {
        perror("Failed to create thread");
        return 1;
    }

    pthread_join(thread_id, NULL);
    return 0;
}

void* convert_image_to_pdf(void* arg) {
    ConversionParams* params = (ConversionParams*)arg;

    int result = execute_conversion_command(params->source_file, params->destination_file, params->compression_level, params->metadata_file);
    if (result != 0) {
        fprintf(stderr, "Conversion failed\n");
        return NULL;
    }

    printf("Conversion successful\n");
    return NULL;
}

int execute_conversion_command(const char* source_file, const char* destination_file, int compression_level, const char* metadata_file) {
    // Construct the command to convert JPEG to PDF
    char command[256];
    snprintf(command, sizeof(command), "convert -density 300 %s -quality %d %s", source_file, compression_level * 10, destination_file);

    if (metadata_file != NULL) {
        strncat(command, " -metadata @", sizeof(command) - strlen(command) - 1);
        strncat(command, metadata_file, sizeof(command) - strlen(command) - 1);
    }

    // Execute the command
    int result = system(command);
    if (result != 0) {
        fprintf(stderr, "Command execution failed with error code %d\n", result);
        return 1;
    }

    return 0;
}
```

