typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_memory(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void deallocate_memory(void* ptr) {
    free(ptr);
}

NFAPI_CRC_INDICATION_PDU_T* create_array(int size) {
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    return array;
}

void serialize_array(NFAPI_CRC_INDICATION_PDU_T* array, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        exit(EXIT_FAILURE);
    }
    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file);
    fclose(file);
}

NFAPI_CRC_INDICATION_PDU_T* deserialize_array(const char* filename, int* size) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        fprintf(stderr, "Failed to open file for reading\n");
        exit(EXIT_FAILURE);
    }
    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fseek(file, 0, SEEK_SET);
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)allocate_memory(*size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    fread(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *size, file);
    fclose(file);
    return array;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* array = create_array(MAX_ELEMENTS);
    serialize_array(array, MAX_ELEMENTS, "array.bin");
    int size;
    NFAPI_CRC_INDICATION_PDU_T* deserialized_array = deserialize_array("array.bin", &size);
    deallocate_memory(array);
    deallocate_memory(deserialized_array);
    return 0;
}
