using System;
using System.Collections.Generic;
using UnityEngine;

public class RangeConfig<T>
{
    public T Min { get; set; }
    public T Max { get; set; }

    public RangeConfig(T min = default(T), T max = default(T))
    {
        Min = min;
        Max = max;
    }
}

public static class ValueGenerator
{
    private static Dictionary<Type, RangeConfig<object>> defaultRanges = new Dictionary<Type, RangeConfig<object>>();
    private static ILogger logger;

    public static void SetDefaultRange<T>(T min, T max)
    {
        defaultRanges[typeof(T)] = new RangeConfig<T>(min, max);
    }

    public static void SetLogger(ILogger log)
    {
        logger = log;
    }

    public static int GenerateRandomInt(RangeConfig<int> range = null)
    {
        var config = range ?? GetDefaultRange<int>();
        int value = UnityEngine.Random.Range(config.Min, config.Max + 1);
        LogValue(value);
        return value;
    }

    public static float GenerateRandomFloat(RangeConfig<float> range = null)
    {
        var config = range ?? GetDefaultRange<float>();
        float value = UnityEngine.Random.Range(config.Min, config.Max);
        LogValue(value);
        return value;
    }

    private static T GetDefaultRange<T>()
    {
        if (defaultRanges.ContainsKey(typeof(T)))
            return (T)Convert.ChangeType(defaultRanges[typeof(T)].Min, typeof(T));
        throw new InvalidOperationException("No default range set for type " + typeof(T).Name);
    }

    private static void LogValue(object value)
    {
        if (logger != null)
            logger.Log(value);
    }
}

public interface ILogger
{
    void Log(object message);
}

public class FileLogger : ILogger
{
