typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->entries = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ENTRIES * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count = 0;
    array->capacity = MAX_ENTRIES;
    pthread_mutex_init(&array->mutex, NULL);
}

void freeDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    free(array->entries);
    pthread_mutex_unlock(&array->mutex);
    pthread_mutex_destroy(&array->mutex);
}

int addEntry(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }
    array->entries[array->count++] = entry;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int updateEntry(DynamicArray *array, int RNTI, NFAPI_CRC_INDICATION_PDU_T newEntry) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->entries[i].RNTI == RNTI) {
            array->entries[i] = newEntry;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Entry not found
}

void getStatistics(DynamicArray *array, int *totalCRCFLAG, int *maxCRCFLAG, double *avgCRCFLAG) {
    pthread_mutex_lock(&array->mutex);
    *totalCRCFLAG = 0;
    *maxCRCFLAG = 0;
    for (size_t i = 0; i < array->count; ++i) {
        *totalCRCFLAG += array->entries[i].CRCFLAG;
        if (array->entries[i].CRCFLAG > *maxCRCFLAG) {
            *maxCRCFLAG = array->entries[i].CRCFLAG;
        }
    }
    *avgCRCFLAG = (double)*totalCRCFLAG / array->count;
    pthread_mutex_unlock(&array->mutex);
}

int main() {
    DynamicArray array;
    initDynamicArray(&array);

    NFAPI_CRC_INDICATION_PDU_T entry = {1, 2, rand() % 2};
    addEntry(&array, entry);

    updateEntry(&array, 2, (NFAPI_CRC_INDICATION_PDU_T){1, 2, rand() % 2});

    int totalCRCFLAG, maxCRCFLAG;
    double avgCRCFLAG;
    getStatistics(&array, &totalCRCFLAG, &maxCRCFLAG, &avgCRCFLAG);

    printf("Total CRCFLAG: %d\n", totalCRCFLAG);
    printf("Max CRCFLAG: %d\n", maxCRCFLAG);
    printf("Average CRCFLAG: %.2f\n", avgCRCFLAG);

    freeDynamicArray(&array);
    return 0;
}
