    size_t size;
    size_t capacity;
    FILE *audit_log;
    pthread_mutex_t mutex;
} NFAPI_CRC_ARRAY_MANAGER_T;

void log_operation(NFAPI_CRC_ARRAY_MANAGER_T *manager, const char *operation) {
    if (manager->audit_log) {
        fprintf(manager->audit_log, "%s\n", operation);
        fflush(manager->audit_log);
    }
}

NFAPI_CRC_ARRAY_MANAGER_T* create_manager(size_t initial_capacity, const char *log_file_path) {
    NFAPI_CRC_ARRAY_MANAGER_T *manager = malloc(sizeof(NFAPI_CRC_ARRAY_MANAGER_T));
    if (!manager) return NULL;

    manager->array = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!manager->array) {
        free(manager);
        return NULL;
    }

    manager->size = 0;
    manager->capacity = initial_capacity;
    manager->audit_log = fopen(log_file_path, "a");
    if (!manager->audit_log) {
        free(manager->array);
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->mutex, NULL);

    log_operation(manager, "Manager created");

    return manager;
}

void destroy_manager(NFAPI_CRC_ARRAY_MANAGER_T *manager) {
    if (manager->array) {
        free(manager->array);
    }
    if (manager->audit_log) {
        fclose(manager->audit_log);
    }
    pthread_mutex_destroy(&manager->mutex);
    free(manager);

    log_operation(NULL, "Manager destroyed");
}

int add_element(NFAPI_CRC_ARRAY_MANAGER_T *manager, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&manager->mutex);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(manager->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            pthread_mutex_unlock(&manager->mutex);
            return -1; // Memory allocation failed
        }
        manager->array = new_array;
        manager->capacity = new_capacity;
    }

    manager->array[manager->size++] = element;

    log_operation(manager, "Element added");

    pthread_mutex_unlock(&manager->mutex);

    return 0;
}

int remove_element(NFAPI_CRC_ARRAY_MANAGER_T *manager, int RNTI) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->array[i].RNTI == RNTI) {
            for (size_t j = i; j < manager->size - 1; ++j) {
                manager->array[j] = manager->array[j + 1];
            }
            --manager->size;

            log_operation(manager, "Element removed");

            pthread_mutex_unlock(&manager->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->mutex);

    return -1; // Element not found
}

void process_elements(NFAPI_CRC_ARRAY_MANAGER_T *manager) {
    pthread_mutex_lock(&manager->mutex);

    for (size_t i = 0; i < manager->size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element = manager->array[i];
        // Process the element
        printf("Processing element with RNTI: %d\n", element.RNTI);
    }

    log_operation(manager, "Elements processed");

    pthread_mutex_unlock(&manager->mutex);
}
