int processMediaWithDependencies(int N, const char* inputJPEGFile, const char* outputPDFFile, const char* outputCRCFile, unsigned int* seed, const char* config) {
    NFAPI_CRC_INDICATION_PDU_T* crcArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crcArray) {
        perror("Failed to allocate memory for CRC array");
        return 1;
    }

    srand(*seed);
    for (int i = 0; i < N; ++i) {
        crcArray[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        crcArray[i].RNTI = rand() % 256;
        crcArray[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    char command[256];
    snprintf(command, sizeof(command), "%s -i %s -o %s", config, inputJPEGFile, outputPDFFile);
    int result = system(command);
    if (result != 0) {
        perror("Conversion failed");
        free(crcArray);
        return 1;
    }

    FILE* crcFile = fopen(outputCRCFile, "wb");
    if (!crcFile) {
        perror("Failed to open CRC file for writing");
        free(crcArray);
        return 1;
    }

    for (int i = 0; i < N; ++i) {
        fwrite(&crcArray[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, crcFile);
    }
    fclose(crcFile);

    free(crcArray);
    return 0;
}
