#include <stdlib.h>
#include <string.h>

typedef struct LTE_PHY_RX_TASK_PDU_T {
    PHY_RX_FRAME_INFO_TAG frame_info;
    RRC_CONNECTION_TAG rrc_connection;
} LTE_PHY_RX_TASK_PDU_T;

typedef struct ListNode {
    LTE_PHY_RX_TASK_PDU_T data;
    struct ListNode* next;
} ListNode;

typedef struct List {
    ListNode* head;
    size_t size;
} List;

List* list_create() {
    List* list = (List*)malloc(sizeof(List));
    if (list == NULL) {
        return NULL; // Handle memory allocation failure
    }
    list->head = NULL;
    list->size = 0;
    return list;
}

void list_destroy(List* list) {
    ListNode* current = list->head;
    while (current != NULL) {
        ListNode* next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

int list_add(List* list, LTE_PHY_RX_TASK_PDU_T data) {
    ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
    if (new_node == NULL) {
        return -1; // Handle memory allocation failure
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->size++;
    return 0;
}

int list_remove(List* list, float min_SINR, float max_RSRP, float max_RSRQ) {
    ListNode** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.frame_info.SINR < min_SINR ||
            (*current)->data.rrc_connection.RSRP > max_RSRP ||
            (*current)->data.rrc_connection.RSRQ > max_RSRQ) {
            ListNode* temp = *current;
            *current = (*current)->next;
            free(temp);
            list->size--;
        } else {
            current = &(*current)->next;
        }
    }
    return 0;
}

void list_process_packets(List* list, void (*process_packet)(LTE_PHY_RX_TASK_PDU_T*)) {
    ListNode* current = list->head;
    while (current != NULL) {
        process_packet(&current->data);
        current = current->next;
    }
}
