CRC_INDICATION_POOL* create_pool(int N) {
    if (N <= 0) return NULL;

    CRC_INDICATION_POOL* pool = malloc(sizeof(CRC_INDICATION_POOL));
    if (!pool) return NULL;

    pool->created_count = 0;
    pthread_mutex_init(&pool->mutex, NULL);

    // Allocate memory for the list of structures
    NFAPI_CRC_INDICATION_PDU_T** list = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) {
        free(pool);
        return NULL;
    }

    pool->list = list;

    return pool;
}

void destroy_pool(CRC_INDICATION_POOL* pool) {
    if (pool) {
        for (int i = 0; i < atomic_load(&pool->created_count); i++) {
            // Free each structure
            free(pool->list[i]);
        }
        free(pool->list);
        pthread_mutex_destroy(&pool->mutex);
        free(pool);
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_structure(CRC_INDICATION_POOL* pool) {
    if (!pool) return NULL;

    pthread_mutex_lock(&pool->mutex);

    if (atomic_load(&pool->created_count) >= N) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) {
        pthread_mutex_unlock(&pool->mutex);
        return NULL;
    }

    // Initialize the structure fields here
    // Generate a pseudo-random CRCFLAG and assign it to the structure

    atomic_fetch_add(&pool->created_count, 1);

    pthread_mutex_unlock(&pool->mutex);

    return structure;
}

int get_created_count(CRC_INDICATION_POOL* pool) {
    if (!pool) return -1;

    return atomic_load(&pool->created_count);
}
