#define MAX_STRING_LENGTH 256

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[MAX_STRING_LENGTH];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[MAX_STRING_LENGTH];
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_pdu(const char* rx_tag, int rnti, const char* crc_tag) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu == NULL) {
        perror("Memory allocation failed");
        return NULL;
    }
    strncpy(pdu->RX_UE_INFORMATION_TAG, rx_tag, MAX_STRING_LENGTH - 1);
    pdu->RNTI = rnti;
    strncpy(pdu->CRC_INDICATION_REL8_TAG, crc_tag, MAX_STRING_LENGTH - 1);
    pdu->next = NULL;
    return pdu;
}

void insert_pdu(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_pdu) {
    if (*head == NULL) {
        *head = new_pdu;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_pdu;
    }
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T* head = NULL;

    for (int i = 0; i < 1000; i++) {
        char rx_tag[MAX_STRING_LENGTH];
        char crc_tag[MAX_STRING_LENGTH];
        snprintf(rx_tag, MAX_STRING_LENGTH, "RX_UE_%d", i);
        snprintf(crc_tag, MAX_STRING_LENGTH, "CRC_%d", i);

        NFAPI_CRC_INDICATION_PDU_T* new_pdu = create_pdu(rx_tag, i * 10, crc_tag);
        if (new_pdu != NULL) {
            insert_pdu(&head, new_pdu);
        }
    }

    free_pdus(&head);

    return 0;
}
