#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_PACKET_LENGTH 1500
#define MAX_ACTION_TAG_LENGTH 256

typedef struct {
    time_t timestamp;
    char source_ip[40];
    char destination_ip[40];
    int packet_length;
    char action_tag[MAX_ACTION_TAG_LENGTH];
} PacketEvent;

typedef struct {
    PacketEvent *events;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer, size_t initial_capacity) {
    buffer->capacity = initial_capacity;
    buffer->size = 0;
    buffer->events = (PacketEvent *)malloc(initial_capacity * sizeof(PacketEvent));
    if (!buffer->events) {
        perror("Failed to allocate memory for log buffer");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&buffer->lock, NULL);
}

void destroy_log_buffer(LogBuffer *buffer) {
    free(buffer->events);
    pthread_mutex_destroy(&buffer->lock);
}

void add_event_to_log(LogBuffer *buffer, PacketEvent event) {
    pthread_mutex_lock(&buffer->lock);
    if (buffer->size >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        PacketEvent *new_events = (PacketEvent *)realloc(buffer->events, new_capacity * sizeof(PacketEvent));
        if (!new_events) {
            perror("Failed to reallocate memory for log buffer");
            exit(EXIT_FAILURE);
        }
        buffer->events = new_events;
        buffer->capacity = new_capacity;
    }
    buffer->events[buffer->size++] = event;
    pthread_mutex_unlock(&buffer->lock);
}

void *log_thread(void *arg) {
    LogBuffer *buffer = (LogBuffer *)arg;
    while (1) {
        pthread_mutex_lock(&buffer->lock);
        if (buffer->size > 0) {
            PacketEvent event = buffer->events[--buffer->size];
            // Process the event (e.g., write to file, send over network)
            printf("Logged: %s - Source IP: %s, Dest IP: %s, Length: %d, Action: %s\n",
                   ctime(&event.timestamp), event.source_ip, event.destination_ip,
                   event.packet_length, event.action_tag);
        }
        pthread_mutex_unlock(&buffer->lock);
    }
    return NULL;
}

