    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_MESSAGE_ARRAY_T;

NFAPI_MESSAGE_ARRAY_T* nfaapi_message_array_create(size_t initial_capacity) {
    NFAPI_MESSAGE_ARRAY_T* array = (NFAPI_MESSAGE_ARRAY_T*)malloc(sizeof(NFAPI_MESSAGE_ARRAY_T));
    if (!array) return NULL;

    array->messages = (NFAPI_MESSAGE_T**)calloc(initial_capacity, sizeof(NFAPI_MESSAGE_T*));
    if (!array->messages) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void nfaapi_message_array_destroy(NFAPI_MESSAGE_ARRAY_T* array) {
    if (!array) return;

    for (size_t i = 0; i < array->size; ++i) {
        free(array->messages[i]->extension_data);
        free(array->messages[i]);
    }

    free(array->messages);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int nfaapi_message_array_add(NFAPI_MESSAGE_ARRAY_T* array, NFAPI_MESSAGE_T* message) {
    if (!array || !message) return -1;

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_MESSAGE_T** new_messages = (NFAPI_MESSAGE_T**)realloc(array->messages, new_capacity * sizeof(NFAPI_MESSAGE_T*));
        if (!new_messages) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    array->messages[array->size++] = message;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

NFAPI_MESSAGE_T* nfaapi_message_array_get(NFAPI_MESSAGE_ARRAY_T* array, int id) {
    if (!array) return NULL;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i]->id == id) {
            NFAPI_MESSAGE_T* message = array->messages[i];
            pthread_mutex_unlock(&array->mutex);
            return message;
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return NULL;
}

int nfaapi_message_array_remove(NFAPI_MESSAGE_ARRAY_T* array, int id) {
    if (!array) return -1;

    pthread_mutex_lock(&array->mutex);

    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i]->id == id) {
            free(array->messages[i]->extension_data);
            free(array->messages[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->messages[j] = array->messages[j + 1];
            }
            --array->size;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&array->mutex);

    return -1;
}

