NFAPI_CRC_INDICATION_PDU_T* allocateNFABatch(size_t batch_size) {
    if (batch_size > MAX_BATCH_SIZE) {
        batch_size = MAX_BATCH_SIZE;
    }

    NFAPI_CRC_INDICATION_PDU_T* batch = malloc(batch_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!batch) {
        // Handle memory allocation failure
        return NULL;
    }

    for (size_t i = 0; i < batch_size; ++i) {
        // Initialize each element with valid data and probabilistically determined CRCFLAG
        batch[i].ue_info_tag = generateUEInfoTag();
        batch[i].RNTI = generateRNTI();
        batch[i].crc_indication.CRCFLAG = generateCRCFlag();
    }

    return batch;
}

// Thread-safe function to allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateNFABatchThreadSafe(size_t batch_size) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    NFAPI_CRC_INDICATION_PDU_T* batch = allocateNFABatch(batch_size);
    if (!batch) {
        // Fallback strategy: allocate a smaller batch size
        batch = allocateNFABatch(batch_size / 2);
    }

    pthread_mutex_unlock(&mutex);
    return batch;
}
