u_char* resolve_hostname_to_ip(const char* hostname, int* error_code) {
    struct addrinfo hints, *res, *p;
    int status;
    char ipstr[INET6_ADDRSTRLEN];
    u_char* result = NULL;

    memset(&hints, 0, sizeof hints);
    hints.ai_family = AF_UNSPEC; // AF_INET or AF_INET6 to force version
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        *error_code = status;
        return NULL;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        void* addr;
        char* ipver;

        // get the pointer to the address itself,
        // different fields in IPv4 and IPv6:
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            addr = &(ipv4->sin_addr);
            ipver = "IPv4";
        } else { // IPv6
            struct sockaddr_in6* ipv6 = (struct sockaddr_in6*)p->ai_addr;
            addr = &(ipv6->sin6_addr);
            ipver = "IPv6";
        }

        // convert the IP to a string and print it:
        inet_ntop(p->ai_family, addr, ipstr, sizeof ipstr);
        printf("  %s: %s\n", ipver, ipstr);

        // Allocate memory for NFAPI_CRC_INDICATION_PDU_T structures
        int num_structures = 5; // Example number of structures
        result = (u_char*)malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!result) {
            *error_code = ENOMEM;
            freeaddrinfo(res);
            return NULL;
        }

        // Populate the structures with random data
        for (int i = 0; i < num_structures; i++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)(result + i * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu->RX_UE_INFORMATION_TAG = rand() % 256;
            pdu->RNTI = rand() % 0xFFFF;
            pdu->CRC_INDICATION_REL8_TAG = rand() % 256;
            pdu->CRCFLAG = rand() % 2;
        }

        *error_code = 0;
        freeaddrinfo(res);
        return result;
    }

    *error_code = ENOENT;
    return NULL;
}
