#include <stdlib.h>
#include <pthread.h>

typedef struct NR_BWP {
    int id;
    // Other BWP configuration fields
} NR_BWP;

typedef struct UEContext {
    int identifier;
    RRCConnectionState state;
    NR_BWP** bwps;
    size_t num_bwps;
    pthread_mutex_t lock;
} UEContext;

UEContext* create_UEContext(int identifier, RRCConnectionState state) {
    UEContext* context = (UEContext*)malloc(sizeof(UEContext));
    if (!context) return NULL;

    context->identifier = identifier;
    context->state = state;
    context->bwps = NULL;
    context->num_bwps = 0;
    pthread_mutex_init(&context->lock, NULL);

    return context;
}

void destroy_UEContext(UEContext* context) {
    if (!context) return;

    for (size_t i = 0; i < context->num_bwps; ++i) {
        free(context->bwps[i]);
    }
    free(context->bwps);
    pthread_mutex_destroy(&context->lock);
    free(context);
}

int add_NR_BWP(UEContext* context, NR_BWP* bwp) {
    if (!context || !bwp) return -1;

    pthread_mutex_lock(&context->lock);

    NR_BWP** new_bwps = (NR_BWP**)realloc(context->bwps, (context->num_bwps + 1) * sizeof(NR_BWP*));
    if (!new_bwps) {
        pthread_mutex_unlock(&context->lock);
        return -1;
    }

    context->bwps = new_bwps;
    context->bwps[context->num_bwps++] = bwp;

    pthread_mutex_unlock(&context->lock);

    return 0;
}

NR_BWP* get_NR_BWP(UEContext* context, int bwp_id) {
    if (!context) return NULL;

    pthread_mutex_lock(&context->lock);

    for (size_t i = 0; i < context->num_bwps; ++i) {
        if (context->bwps[i]->id == bwp_id) {
            NR_BWP* result = context->bwps[i];
            pthread_mutex_unlock(&context->lock);
            return result;
        }
    }

    pthread_mutex_unlock(&context->lock);
    return NULL;
}
