#include <sys/wait.h>
#include <time.h>

#define MAX_COMMAND_LENGTH 256
#define API_URL "https://api.example.com/updates"
#define REQUEST_INTERVAL 60 // in seconds

void daemonize() {
    pid_t pid = fork();
    if (pid < 0) {
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        exit(EXIT_SUCCESS);
    }

    umask(0);

    pid_t sid = setsid();
    if (sid < 0) {
        exit(EXIT_FAILURE);
    }

    close(STDIN_FILENO);
    close(STDOUT_FILENO);
    close(STDERR_FILENO);
}

