#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} ConcurrentList;

ConcurrentList* create_concurrent_list() {
    ConcurrentList* list = (ConcurrentList*)malloc(sizeof(ConcurrentList));
    if (list == NULL) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_concurrent_list(ConcurrentList* list) {
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

bool is_unique(ConcurrentList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* current = list->head;
    while (current != NULL) {
        if (current->data.rx_ue_info_tag == data.rx_ue_info_tag &&
            current->data.rnti == data.rnti &&
            current->data.crc_indication_rel8_tag == data.crc_indication_rel8_tag) {
            return false;
        }
        current = current->next;
    }
    return true;
}

void insert_concurrent_list(ConcurrentList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (is_unique(list, data)) {
        Node* new_node = (Node*)malloc(sizeof(Node));
        if (new_node != NULL) {
            new_node->data = data;
            new_node->next = list->head;
            list->head = new_node;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

// Example usage
int main() {
    ConcurrentList* list = create_concurrent_list();
    if (list != NULL) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        // Initialize pdu with valid values
        insert_concurrent_list(list, pdu);
        destroy_concurrent_list(list);
    }
    return 0;
}
```

