    if (!array->array) {
        return -1; // Memory allocation failed
    }
    array->size = 0;
    array->capacity = MAX_NF_API_CRC_INDICATION_PDU_T;
    return 0;
}

int nfaapi_crc_indication_pdu_array_add(NFAPI_CRC_INDICATION_PDU_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T element) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_array) {
            return -1; // Memory reallocation failed
        }
        array->array = new_array;
        array->capacity = new_capacity;
    }
    array->array[array->size++] = element;
    return 0;
}

int nfaapi_crc_indication_pdu_array_remove(NFAPI_CRC_INDICATION_PDU_ARRAY_T *array, size_t index) {
    if (index >= array->size) {
        return -1; // Index out of bounds
    }
    for (size_t i = index; i < array->size - 1; ++i) {
        array->array[i] = array->array[i + 1];
    }
    --array->size;
    return 0;
}

