#define MAX_UE_ID 1000
#define MAX_MSG_TYPE 5

typedef enum {
    LTE_RRC_MSG_TYPE_TAG,
    // Add other message types here
} LTE_RRC_MSG_TYPE;

typedef struct {
    LTE_RRC_MSG_TYPE type;
    int UE_ID;
} NFAPI_MESSAGE_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
NFAPI_MESSAGE_T* messages = NULL;
int num_messages = 0;

void log_message(int level, const char* message) {
    // Implement logging logic here
}

void* initialize_nfaip_messages(void* arg) {
    int N = *(int*)arg;
    pthread_mutex_lock(&mutex);
    if (messages != NULL) {
        free(messages);
    }
    messages = (NFAPI_MESSAGE_T*)malloc(N * sizeof(NFAPI_MESSAGE_T));
    if (messages == NULL) {
        log_message(ERROR, "Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    num_messages = N;
    srand(time(NULL));
    for (int i = 0; i < N; i++) {
        messages[i].type = (LTE_RRC_MSG_TYPE)(rand() % MAX_MSG_TYPE);
        messages[i].UE_ID = rand() % MAX_UE_ID;
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void* manage_memory(void* arg) {
    int interval = *(int*)arg;
    while (1) {
        sleep(interval);
        pthread_mutex_lock(&mutex);
        if (num_messages > 0) {
            NFAPI_MESSAGE_T* new_messages = (NFAPI_MESSAGE_T*)realloc(messages, num_messages * sizeof(NFAPI_MESSAGE_T));
            if (new_messages == NULL) {
                log_message(ERROR, "Memory reallocation failed");
            } else {
                messages = new_messages;
            }
        }
        pthread_mutex_unlock(&mutex);
    }
    return NULL;
}

int main() {
    int N = 100;
    pthread_t init_thread, mem_thread;

    if (pthread_create(&init_thread, NULL, initialize_nfaip_messages, &N) != 0) {
        log_message(ERROR, "Failed to create initialization thread");
        return 1;
    }

    if (pthread_create(&mem_thread, NULL, manage_memory, &(int){60}) != 0) {
        log_message(ERROR, "Failed to create memory management thread");
        pthread_join(init_thread, NULL);
        return 1;
    }

    pthread_join(init_thread, NULL);
    pthread_join(mem_thread, NULL);

    free(messages);
    return 0;
}
