import java.io.BufferedReader;
import java.io.File;
import java.io.FileWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class DiskUsageChecker {

    public static void main(String[] args) {
        if (args.length != 1) {
            System.out.println("Usage: java DiskUsageChecker <directory>");
            return;
        }

        String directoryPath = args[0];
        File directory = new File(directoryPath);

        if (!directory.exists() || !directory.isDirectory()) {
            System.out.println("Directory does not exist or is not a valid directory.");
            return;
        }

        try {
            if (hasPermissionToExecuteCommand()) {
                double diskUsagePercentage = getDiskUsagePercentage(directory);
                logDiskUsage(diskUsagePercentage, directoryPath);
            } else {
                System.out.println("Insufficient permissions to execute the command.");
            }
        } catch (IOException e) {
            System.err.println("Error occurred while checking disk usage: " + e.getMessage());
        }
    }

    private static boolean hasPermissionToExecuteCommand() {
        // Implement permission check logic here
        return true; // Placeholder
    }

    private static double getDiskUsagePercentage(File directory) throws IOException {
        Process process = Runtime.getRuntime().exec("du -sh " + directory.getAbsolutePath());
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        String line = reader.readLine();
        if (line != null && !line.isEmpty()) {
            String[] parts = line.split("\\s+");
            long totalSize = parseSize(parts[0]);
            long usedSize = getTotalUsedSize(directory);
            return ((double) usedSize / totalSize) * 100;
        }
        return -1; // Error
    }

    private static long parseSize(String sizeString) {
        String[] units = {"K", "M", "G"};
        for (int i = 0; i < units.length; i++) {
            if (sizeString.endsWith(units[i])) {
                double value = Double.parseDouble(sizeString.substring(0, sizeString.length() - 1));
                return (long) (value * Math.pow(1024, i + 1));
            }
        }
        return Long.parseLong(sizeString);
    }

    private static long getTotalUsedSize(File directory) {
        long total = 0;
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    total += getTotalUsedSize(file);
                } else {
                    total += file.length();
                }
            }
        }
        return total;
    }

    private static void logDiskUsage(double diskUsagePercentage, String directoryPath) throws IOException {
        Path logFilePath = Paths.get("disk_usage.log");
        if (Files.exists(logFilePath)) {
            Files.delete(logFilePath);
        }

        try (FileWriter writer = new FileWriter(logFilePath.toFile())) {
            writer.write("Directory: " + directoryPath + "\n");
            writer.write("Disk Usage Percentage: " + diskUsagePercentage + "%\n");
        }
    }
}
