#include <stdlib.h>
#include <time.h>

typedef enum {
    LTE_RRC_MSG_TYPE_TAG,
    RX_UE_CONTEXT,
} LTE_RRC_MSG_TYPE;

typedef struct {
    LTE_RRC_MSG_TYPE type;
    union {
        struct {
            int UE_ID;
        } NFAPI_MESSAGE_T;
        struct {
            int RX_UE_CONTEXT;
            char* RRC_NAS_MESSAGE;
            size_t PDU_SIZE;
            unsigned char* PDU_DATA;
        } NFAPI_RX_PDU_T;
    };
} Message;

typedef struct {
    Message* messages;
    size_t capacity;
    size_t size;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;
    array->messages = (Message*)calloc(initial_capacity, sizeof(Message));
    if (!array->messages) {
        free(array);
        return NULL;
    }
    array->capacity = initial_capacity;
    array->size = 0;
    return array;
}

void destroy_dynamic_array(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        if (array->messages[i].type == RX_UE_CONTEXT) {
            free(array->messages[i].NFAPI_RX_PDU_T.PDU_DATA);
        }
    }
    free(array->messages);
    free(array);
}

int add_message(DynamicArray* array, LTE_RRC_MSG_TYPE type, ...) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Message* new_messages = (Message*)realloc(array->messages, new_capacity * sizeof(Message));
        if (!new_messages) return -1;
        array->messages = new_messages;
        array->capacity = new_capacity;
    }

    va_list args;
    va_start(args, type);
    switch (type) {
        case LTE_RRC_MSG_TYPE_TAG:
            array->messages[array->size].type = LTE_RRC_MSG_TYPE_TAG;
            array->messages[array->size].NFAPI_MESSAGE_T.UE_ID = va_arg(args, int);
            break;
        case RX_UE_CONTEXT:
            array->messages[array->size].type = RX_UE_CONTEXT;
            array->messages[array->size].NFAPI_RX_PDU_T.RX_UE_CONTEXT = va_arg(args, int);
            array->messages[array->size].NFAPI_RX_PDU_T.RRC_NAS_MESSAGE = va_arg(args, char*);
            array->messages[array->size].NFAPI_RX_PDU_T.PDU_SIZE = va_arg(args, size_t);
            array->messages[array->size].NFAPI_RX_PDU_T.PDU_DATA = (unsigned char*)malloc(array->messages[array->size].NFAPI_RX_PDU_T.PDU_SIZE);
            if (!array->messages[array->size].NFAPI_RX_PDU_T.PDU_DATA) {
                va_end(args);
                return -1;
            }
            // Initialize PDU data
            break;
        default:
            va_end(args);
            return -1;
    }
    va_end(args);

    array->size++;
    return 0;
}

void initialize_messages(DynamicArray* array, size_t batch_size) {
    srand(time(NULL));
    for (size_t i = 0; i < batch_size; ++i) {
        LTE_RRC_MSG_TYPE type = rand() % 2 == 0 ? LTE_RRC_MSG_TYPE_TAG : RX_UE_CONTEXT;
        if (type == LTE_RRC_MSG_TYPE_TAG) {
            add_message(array, LTE_RRC_MSG_TYPE_TAG, rand());
        } else {
            char* nas_msg = "NasMessage";
            size_t pdu_size = 128;
            unsigned char* pdu_data = (unsigned char*)malloc(pdu_size);
            if (!pdu_data) continue; // Handle memory allocation failure
            // Initialize PDU data
            add_message(array, RX_UE_CONTEXT, rand(), nas_msg, pdu_size, pdu_data);
        }
    }
}

// Additional functions for performance monitoring, error handling, and system integration can be added here.
