#define SHRINK_THRESHOLD 0.25

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DataManager;

DataManager* create_data_manager() {
    DataManager *manager = (DataManager*)malloc(sizeof(DataManager));
    manager->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(INITIAL_CAPACITY, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    manager->size = 0;
    manager->capacity = INITIAL_CAPACITY;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_data_manager(DataManager *manager) {
