    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

void add_to_manager(DataManager *manager, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size == manager->capacity) {
        size_t new_capacity = manager->capacity * GROWTH_FACTOR;
        manager->data = realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->capacity = new_capacity;
    }
    manager->data[manager->size++] = item;
    pthread_mutex_unlock(&manager->lock);
}

