    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->data[i].RX_UE_INFORMATION_TAG == tag) {
            manager->data[i] = manager->data[--manager->size];
            break;
        }
    }
    if (manager->size > 0 && manager->size <= manager->capacity * SHRINK_THRESHOLD) {
        size_t new_capacity = manager->capacity / GROWTH_FACTOR;
        manager->data = realloc(manager->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        manager->capacity = new_capacity;
    }
    pthread_mutex_unlock(&manager->lock);
}

