typedef void (*ApiErrorHandler)(const char*);

ConfigSetting* manageSettingsList(ConfigSetting* currentSettings, int numSettings, NetworkDeviceAPI* api, const char* lastProcessed, ApiErrorHandler errorHandler) {
    if (numSettings > 1024) return NULL; // Scalability constraint

    ConfigSetting** head = &currentSettings;
    while (*head != NULL && strcmp((*head)->name, lastProcessed) != 0) {
        head = &(*head)->next;
    }

    if (*head == NULL) return currentSettings; // No changes made

    ConfigSetting* newHead = (ConfigSetting*)malloc(numSettings * sizeof(ConfigSetting));
    if (newHead == NULL) {
        errorHandler("Memory allocation failed");
        return currentSettings;
    }

    for (int i = 0; i < numSettings; i++) {
        newHead[i].name = strdup((*head)->name);
        newHead[i].value = (*head)->value;
        newHead[i].next = NULL;
        if (i > 0) {
            newHead[i - 1].next = &newHead[i];
        }
    }

    (*head)->next = newHead;

    return currentSettings;
}
