#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct PduNode {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct PduNode* next;
} PduNode;

typedef struct {
    PduNode* head;
    pthread_mutex_t lock;
} PduList;

void initPduList(PduList* list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void addPduToList(PduList* list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    PduNode* newNode = (PduNode*)malloc(sizeof(PduNode));
    newNode->pdu = pdu;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
}

void serializePduList(PduList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    PduNode* current = list->head;
    while (current != NULL) {
        fwrite(&current->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void deserializePduList(PduList* list, FILE* file) {
    pthread_mutex_lock(&list->lock);
    PduNode* current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        addPduToList(list, pdu);
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void freePduList(PduList* list) {
    pthread_mutex_lock(&list->lock);
    PduNode* current = list->head;
    while (current != NULL) {
        PduNode* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}
