#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <string.h>
#include <time.h>

#define MAX_CONCURRENT_TASKS 100
#define CPU_USAGE_LIMIT 5
#define RETRY_COUNT 3

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicCollection;

void init_collection(DynamicCollection *collection) {
    collection->data = NULL;
    collection->size = 0;
    collection->capacity = 0;
    pthread_mutex_init(&collection->lock, NULL);
}

void add_to_collection(DynamicCollection *collection, NFAPI_CRC_INDICATION_PDU_T item) {
    pthread_mutex_lock(&collection->lock);
    if (collection->size >= collection->capacity) {
        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(collection->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            perror("Failed to allocate memory");
            pthread_mutex_unlock(&collection->lock);
            return;
        }
        collection->data = new_data;
        collection->capacity = new_capacity;
    }
    collection->data[collection->size++] = item;
    pthread_mutex_unlock(&collection->lock);
}

void process_collection(DynamicCollection *collection) {
    pthread_t threads[MAX_CONCURRENT_TASKS];
    int thread_count = 0;

    for (size_t i = 0; i < collection->size; ++i) {
        if (pthread_create(&threads[thread_count], NULL, hash_task, &collection->data[i]) != 0) {
            perror("Failed to create thread");
            continue;
        }
        if (++thread_count >= MAX_CONCURRENT_TASKS) {
            for (int j = 0; j < thread_count; ++j) {
                pthread_join(threads[j], NULL);
            }
            thread_count = 0;
        }
    }

    while (thread_count > 0) {
        pthread_join(threads[--thread_count], NULL);
    }
}

void *hash_task(void *arg) {
    NFAPI_CRC_INDICATION_PDU_T *item = (NFAPI_CRC_INDICATION_PDU_T *)arg;
    // Perform hash computation here
    printf("Hashing completed for item: %zu\n", item->ue_info);
    return NULL;
}

void cleanup_collection(DynamicCollection *collection) {
    pthread_mutex_lock(&collection->lock);
    free(collection->data);
    collection->data = NULL;
    collection->size = 0;
    collection->capacity = 0;
    pthread_mutex_unlock(&collection->lock);
    pthread_mutex_destroy(&collection->lock);
}

int main() {
    DynamicCollection collection;
    init_collection(&collection);

    // Add items to the collection
    NFAPI_CRC_INDICATION_PDU_T item1 = { /* initialize fields */ };
    add_to_collection(&collection, item1);

    process_collection(&collection);

    cleanup_collection(&collection);
    return 0;
}
