import hashlib
import os
import threading
from queue import Queue

def compute_hash(file_path, hash_type):
    hasher = hashlib.new(hash_type)
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            hasher.update(chunk)
    return hasher.hexdigest()

def process_files(file_paths, max_workers=10):
    results = {}
    queue = Queue()
    lock = threading.Lock()

    def worker():
        while True:
            file_path = queue.get()
            if file_path is None:
                break
            try:
                hash_value = compute_hash(file_path, 'md5')
                with lock:
                    results[file_path] = hash_value
            except (FileNotFoundError, IOError) as e:
                print(f"Error processing {file_path}: {e}")
            queue.task_done()

    threads = [threading.Thread(target=worker) for _ in range(max_workers)]
    for thread in threads:
        thread.start()

    for file_path in file_paths:
        queue.put(file_path)

    queue.join()
    for _ in range(max_workers):
        queue.put(None)
    for thread in threads:
        thread.join()

    return results

def validate_hashes(results, reference_hashes):
    validated = {}
    for file_path, computed_hash in results.items():
        if file_path in reference_hashes and computed_hash == reference_hashes[file_path]:
            validated[file_path] = True
        else:
            validated[file_path] = False
    return validated
```

