#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdatomic.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG ue_info_tag;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    atomic_int crcflag;
    struct NFAPI_CRC_INDICATION_PDU_T *prev, *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head, *tail;
    size_t count;
} CRC_LIST;

void init_crc_list(CRC_LIST *list) {
    list->head = list->tail = NULL;
    list->count = 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_crc_pdu(RX_UE_INFORMATION_TAG ue_info_tag, uint16_t RNTI, CRC_INDICATION_REL8_TAG crc_indication_rel8_tag) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (pdu) {
        pdu->ue_info_tag = ue_info_tag;
        pdu->RNTI = RNTI;
        pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
        atomic_init(&pdu->crcflag, rand() % 2); // Randomly generate CRCFLAG
        pdu->prev = pdu->next = NULL;
    }
    return pdu;
}

void add_crc_pdu(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    atomic_thread_fence(memory_order_acquire);
    if (list->tail) {
        list->tail->next = pdu;
        pdu->prev = list->tail;
    } else {
        list->head = pdu;
    }
    list->tail = pdu;
    atomic_fetch_add(&list->count, 1, memory_order_relaxed);
}

void remove_crc_pdu(CRC_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->prev) {
        pdu->prev->next = pdu->next;
    } else {
        list->head = pdu->next;
    }
    if (pdu->next) {
        pdu->next->prev = pdu->prev;
    } else {
        list->tail = pdu->prev;
    }
    atomic_fetch_sub(&list->count, 1, memory_order_relaxed);
    free(pdu);
}

void serialize_crc_list(CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file) {
        fwrite(&list->count, sizeof(size_t), 1, file);
        NFAPI_CRC_INDICATION_PDU_T *pdu = list->head;
        while (pdu) {
            fwrite(&pdu->ue_info_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
            fwrite(&pdu->RNTI, sizeof(uint16_t), 1, file);
            fwrite(&pdu->crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
            fwrite(&atomic_load(&pdu->crcflag), sizeof(int), 1, file);
            pdu = pdu->next;
        }
        fclose(file);
    }
}

void deserialize_crc_list(CRC_LIST *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file) {
        size_t count;
        fread(&count, sizeof(size_t), 1, file);
        for (size_t i = 0; i < count; ++i) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = create_crc_pdu(0, 0, 0); // Placeholder values
            if (pdu) {
                fread(&pdu->ue_info_tag, sizeof(RX_UE_INFORMATION_TAG), 1, file);
                fread(&pdu->RNTI, sizeof(uint16_t), 1, file);
                fread(&pdu->crc_indication_rel8_tag, sizeof(CRC_INDICATION_REL8_TAG), 1, file);
                int crcflag;
                fread(&crcflag, sizeof(int), 1, file);
                atomic_store(&pdu->crcflag, crcflag);
                add_crc_pdu(list, pdu);
            }
        }
        fclose(file);
    }
}
