    tasks[task_count++] = (Task){request, 0, PTHREAD_COND_INITIALIZER, PTHREAD_MUTEX_INITIALIZER};
    pthread_cond_signal(&queue_cond);
    pthread_mutex_unlock(&queue_mutex);
}

