    enqueue_request(request1);

    UserRequest request2 = {"user2", "user2@example.com", json_object_new_object()};
    enqueue_request(request2);

    // Wait for threads to finish
    for (int i = 0; i < MAX_CONCURRENT_TASKS; i++) {
