} DynamicLinkedList;

void init_list(DynamicLinkedList *list, int max_size) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
    list->size = 0;
    list->max_size = max_size;
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    return new_node;
}

void insert_element(DynamicLinkedList *list, int RX_UE_INFORMATION_TAG, int RNTI) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->max_size) {
        // Handle max size limit
        pthread_mutex_unlock(&list->lock);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(RX_UE_INFORMATION_TAG, RNTI);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void remove_element(DynamicLinkedList *list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (prev == NULL) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            if (current == list->tail) {
                list->tail = prev;
            }
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void destroy_list(DynamicLinkedList *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
}
