#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_CELLS 100000

typedef struct LTE_RRC_RECONFIGURATION_REQUEST {
    int cell_id;
    int* frequencies;
    size_t num_frequencies;
    time_t config_timestamp;
} LTE_RRC_RECONFIGURATION_REQUEST;

typedef struct CellNode {
    LTE_RRC_RECONFIGURATION_REQUEST data;
    struct CellNode* next;
} CellNode;

typedef struct DynamicArray {
    CellNode** cells;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->cells = (CellNode**)calloc(MAX_CELLS, sizeof(CellNode*));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void insert_cell(DynamicArray* array, LTE_RRC_RECONFIGURATION_REQUEST request) {
    pthread_mutex_lock(&array->lock);
    if (array->cells[request.cell_id] != NULL) {
        // Handle collision or update existing entry
        CellNode* current = array->cells[request.cell_id];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = (CellNode*)malloc(sizeof(CellNode));
        current->next->data = request;
        current->next->next = NULL;
    } else {
        array->cells[request.cell_id] = (CellNode*)malloc(sizeof(CellNode));
        array->cells[request.cell_id]->data = request;
        array->cells[request.cell_id]->next = NULL;
    }
    pthread_mutex_unlock(&array->lock);
}

void delete_cell(DynamicArray* array, int cell_id) {
    pthread_mutex_lock(&array->lock);
    if (array->cells[cell_id] != NULL) {
        CellNode* current = array->cells[cell_id];
        CellNode* prev = NULL;
        while (current != NULL) {
            if (prev == NULL) {
                array->cells[cell_id] = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        }
    }
    pthread_mutex_unlock(&array->lock);
}

LTE_RRC_RECONFIGURATION_REQUEST* get_cell(DynamicArray* array, int cell_id) {
    pthread_mutex_lock(&array->lock);
    LTE_RRC_RECONFIGURATION_REQUEST* request = NULL;
    if (array->cells[cell_id] != NULL) {
        CellNode* current = array->cells[cell_id];
        while (current != NULL) {
            request = &current->data;
            break; // Assuming we only need the first entry
            current = current->next;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return request;
}

void free_dynamic_array(DynamicArray* array) {
    for (int i = 0; i < MAX_CELLS; i++) {
        CellNode* current = array->cells[i];
        while (current != NULL) {
            CellNode* next = current->next;
            free(current);
            current = next;
        }
    }
    pthread_mutex_destroy(&array->lock);
    free(array->cells);
    free(array);
}
