#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 10000
#define POLYNOMIAL 0xEDB88320

typedef struct {
    uint64_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
    time_t last_cleanup;
} DynamicList;

DynamicList list = {0};

void initialize_list() {
    pthread_mutex_init(&list.lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_element(uint64_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!element) {
        perror("Memory allocation failed");
        return NULL;
    }
    element->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    element->RNTI = RNTI;
    element->CRCFLAG = calculate_crcflag(RX_UE_INFORMATION_TAG, RNTI);
    return element;
}

uint8_t calculate_crcflag(uint64_t tag, uint16_t rnti) {
    uint32_t crc = 0xFFFFFFFF;
    for (int i = 0; i < sizeof(tag); ++i) {
        crc ^= ((tag >> (i * 8)) & 0xFF);
        for (int j = 0; j < 8; ++j) {
            if (crc & 1) {
                crc = (crc >> 1) ^ POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    for (int i = 0; i < sizeof(rnti); ++i) {
        crc ^= ((rnti >> (i * 8)) & 0xFF);
        for (int j = 0; j < 8; ++j) {
            if (crc & 1) {
                crc = (crc >> 1) ^ POLYNOMIAL;
            } else {
                crc >>= 1;
            }
        }
    }
    return crc & 0xFF;
}

void add_element(uint64_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list.lock);
    if (list.count >= MAX_ELEMENTS) {
        printf("List is full\n");
        pthread_mutex_unlock(&list.lock);
        return;
    }
    NFAPI_CRC_INDICATION_PDU_T *element = create_element(RX_UE_INFORMATION_TAG, RNTI);
    if (!element) {
        pthread_mutex_unlock(&list.lock);
        return;
    }
    list.elements[list.count++] = element;
    time_t now = time(NULL);
    if (now - list.last_cleanup > 3600) {
        cleanup_list();
    }
    pthread_mutex_unlock(&list.lock);
}

void cleanup_list() {
    pthread_mutex_lock(&list.lock);
    for (size_t i = 0; i < list.count; ++i) {
        free(list.elements[i]);
    }
    list.count = 0;
    list.last_cleanup = time(NULL);
    pthread_mutex_unlock(&list.lock);
}

void export_to_file(const char *filename) {
    // Implement file export logic here
}

int main() {
    initialize_list();
    srand(time(NULL));
    for (size_t i = 0; i < 15000; ++i) {
        add_element(rand(), rand());
    }
    export_to_file("output.json");
    cleanup_list();
    return 0;
}
