} MAC_HEADER;

typedef struct {
    MAC_HEADER** elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->elements = (MAC_HEADER**)calloc(MAX_LIST_SIZE, sizeof(MAC_HEADER*));
    if (!list->elements) {
        free(list);
        return NULL;
    }
    list->count = 0;
    list->capacity = MAX_LIST_SIZE;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_dynamic_list(DynamicList* list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]->payload);
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_element(DynamicList* list, MAC_HEADER* element) {
    pthread_mutex_lock(&list->lock);
    if (list->count >= list->capacity) {
        pthread_mutex_unlock(&list->lock);
        return -1; // List is full
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

