#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

uint8_t* generateCRCIndicationsMD5(uint32_t numUEs, uint32_t* outLength) {
    if (numUEs <= 0) {
        *outLength = 0;
        return NULL;
    }

    size_t totalSize = numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T* crcIndications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(totalSize);
    if (!crcIndications) {
        *outLength = 0;
        return NULL;
    }

    uint8_t prevCRCFLAG = 0;
    for (uint32_t i = 0; i < numUEs; ++i) {
        crcIndications[i].RX_UE_INFORMATION_TAG = i + 1; // Unique tag
        crcIndications[i].RNTI = i * 2 + 1; // Unique RNTI
        do {
            crcIndications[i].CRCFLAG = rand() % 256;
        } while (crcIndications[i].CRCFLAG == prevCRCFLAG);
        prevCRCFLAG = crcIndications[i].CRCFLAG;
    }

    uint8_t* md5Hash = (uint8_t*)malloc(MD5_DIGEST_LENGTH);
    if (!md5Hash) {
        free(crcIndications);
        *outLength = 0;
        return NULL;
    }

    MD5_CTX md5Context;
    MD5_Init(&md5Context);
    for (uint32_t i = 0; i < numUEs; ++i) {
        MD5_Update(&md5Context, &crcIndications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    MD5_Final(md5Hash, &md5Context);

    *outLength = MD5_DIGEST_LENGTH;
    free(crcIndications);
    return md5Hash;
}
