#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/md5.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

unsigned char* generateCRCIndicationsMD5(int numUEs, int *ueTags, int *rntis) {
    if (numUEs <= 0 || ueTags == NULL || rntis == NULL) {
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *crcIndications = malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crcIndications == NULL) {
        return NULL; // Memory allocation failed
    }

    int crcFlag = 0;
    for (int i = 0; i < numUEs; i++) {
        crcIndications[i].RX_UE_INFORMATION_TAG = ueTags[i];
        crcIndications[i].RNTI = rntis[i];
        crcIndications[i].CRCFLAG = crcFlag;
        crcFlag = (crcFlag == 0) ? 1 : 0; // Toggle CRCFLAG
    }

