unsigned char* generateCRCIndicationsMD5(int numUEs, int *ueTags, int *rntis) {
    if (numUEs <= 0 || ueTags == NULL || rntis == NULL) {
        return NULL; // Invalid input
    }

    NFAPI_CRC_INDICATION_PDU_T *crcIndications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(numUEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crcIndications == NULL) {
        return NULL; // Memory allocation failed
    }

    int lastCRCFlag = -1;
    for (int i = 0; i < numUEs; i++) {
        crcIndications[i].RX_UE_INFORMATION_TAG = ueTags[i];
        crcIndications[i].RNTI = rntis[i];

        // Generate a unique CRCFLAG ensuring no two adjacent structures share the same value
        do {
            lastCRCFlag = (lastCRCFlag + 1) % 2; // Toggle between 0 and 1
        } while (i > 0 && crcIndications[i - 1].CRC_INDICATION_REL8_TAG == lastCRCFlag);
        crcIndications[i].CRC_INDICATION_REL8_TAG = lastCRCFlag;
    }

    unsigned char *md5Hash = (unsigned char *)malloc(MD5_DIGEST_LENGTH);
    if (md5Hash == NULL) {
        free(crcIndications);
        return NULL; // Memory allocation failed
    }

    MD5_CTX md5Context;
    MD5_Init(&md5Context);

    for (int i = 0; i < numUEs; i++) {
        MD5_Update(&md5Context, &crcIndications[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    MD5_Final(md5Hash, &md5Context);
    free(crcIndications);

    return md5Hash;
}
