#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NetworkEvent {
    int timestamp;
    char eventType[50];
    float* sensorData;
    size_t dataCount;
    int refCount;
    struct NetworkEvent* prev;
    struct NetworkEvent* next;
} NetworkEvent;

typedef struct DoublyLinkedList {
    NetworkEvent* head;
    NetworkEvent* tail;
    pthread_mutex_t lock;
} DoublyLinkedList;

void initDoublyLinkedList(DoublyLinkedList* list) {
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

void insertEvent(DoublyLinkedList* list, NetworkEvent* event) {
    pthread_mutex_lock(&list->lock);
    if (list->tail == NULL) {
        list->head = list->tail = event;
    } else {
        list->tail->next = event;
        event->prev = list->tail;
        list->tail = event;
    }
    pthread_mutex_unlock(&list->lock);
}

void removeEvent(DoublyLinkedList* list, NetworkEvent* event) {
    pthread_mutex_lock(&list->lock);
    if (event->prev != NULL) {
        event->prev->next = event->next;
    } else {
        list->head = event->next;
    }
    if (event->next != NULL) {
        event->next->prev = event->prev;
    } else {
        list->tail = event->prev;
    }
    pthread_mutex_unlock(&list->lock);
}

void mergeLists(DoublyLinkedList* dest, DoublyLinkedList* src) {
    pthread_mutex_lock(&dest->lock);
    pthread_mutex_lock(&src->lock);
    if (dest->head == NULL) {
        dest->head = src->head;
        dest->tail = src->tail;
    } else {
        dest->tail->next = src->head;
        src->head->prev = dest->tail;
        dest->tail = src->tail;
    }
    pthread_mutex_unlock(&src->lock);
    pthread_mutex_unlock(&dest->lock);
}

void cleanupExpiredEvents(DoublyLinkedList* list, int expirationTime) {
    pthread_mutex_lock(&list->lock);
    NetworkEvent* current = list->head;
    while (current != NULL) {
        if (current->timestamp + expirationTime < time(NULL)) {
            NetworkEvent* next = current->next;
            removeEvent(list, current);
            free(current->sensorData);
            free(current);
            current = next;
        } else {
            current = current->next;
        }
    }
    pthread_mutex_unlock(&list->lock);
}
