typedef struct NFAPILTEPDUArray {
    NFAPI_LTE_PDU_T **pdus;
    int count;
    pthread_mutex_t mutex;
} NFAPILTEPDUArray;

void initializeNetworkEvent(NetworkEvent *event, time_t timestamp, const char *eventType) {
    event->timestamp = timestamp;
    strcpy(event->eventType, eventType);
    event->sensorDataCount = 0;
    event->sensorData = NULL;
}

void addSensorDataToEvent(NetworkEvent *event, float data) {
    if (event->sensorData == NULL) {
        event->sensorData = malloc(sizeof(float));
    } else {
        event->sensorData = realloc(event->sensorData, (event->sensorDataCount + 1) * sizeof(float));
    }
    event->sensorData[event->sensorDataCount++] = data;
}

void initializeNFAPILTEPDUArray(NFAPILTEPDUArray *array, int initialCapacity) {
    array->pdus = malloc(initialCapacity * sizeof(NFAPI_LTE_PDU_T *));
    array->count = 0;
    pthread_mutex_init(&array->mutex, NULL);
}

void addNFAPILTEPDU(NFAPILTEPDUArray *array, NFAPI_LTE_PDU_T *pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->count == array->pdusCapacity) {
        array->pdus = realloc(array->pdus, (array->count + 1) * sizeof(NFAPI_LTE_PDU_T *));
        array->pdusCapacity++;
    }
    array->pdus[array->count++] = pdu;
    pthread_mutex_unlock(&array->mutex);
}

void removeNFAPILTEPDU(NFAPILTEPDUArray *array, int index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= 0 && index < array->count) {
        free(array->pdus[index]);
        for (int i = index; i < array->count - 1; i++) {
            array->pdus[i] = array->pdus[i + 1];
        }
        array->count--;
    }
    pthread_mutex_unlock(&array->mutex);
}

void cleanupExpiredEvents(EventList **head, time_t expirationTime) {
    EventList *current = *head;
    EventList *prev = NULL;

    while (current != NULL) {
        if (difftime(time(NULL), current->event.timestamp) > expirationTime) {
            if (prev == NULL) {
                *head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current->event.sensorData);
            free(current);
            current = prev->next;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

