#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <unistd.h>

#define MAX_FILES 10
#define MEMORY_BUDGET 100 * 1024 * 1024 // 100 MB
#define TIMEOUT_LIMIT 30

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    char* filename;
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t size;
    int processed;
} FileTask;

pthread_mutex_t queue_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t queue_cond = PTHREAD_COND_INITIALIZER;
FileTask file_queue[MAX_FILES];
int front = 0, rear = -1, count = 0;

void enqueue(FileTask task) {
    pthread_mutex_lock(&queue_mutex);
    while (count == MAX_FILES) {
        pthread_cond_wait(&queue_cond, &queue_mutex);
    }
    if (rear == -1) {
        front = rear = 0;
    } else {
        rear = (rear + 1) % MAX_FILES;
    }
    file_queue[rear] = task;
    count++;
    pthread_cond_signal(&queue_cond);
    pthread_mutex_unlock(&queue_mutex);
}

FileTask dequeue() {
    pthread_mutex_lock(&queue_mutex);
    while (count == 0) {
        pthread_cond_wait(&queue_cond, &queue_mutex);
    }
    FileTask task = file_queue[front];
    if (front == rear) {
        front = rear = -1;
    } else {
        front = (front + 1) % MAX_FILES;
    }
    count--;
    pthread_cond_signal(&queue_cond);
    pthread_mutex_unlock(&queue_mutex);
    return task;
}

void* process_file(void* arg) {
    FileTask task = *(FileTask*)arg;
    FILE* file = fopen(task.filename, "rb");
    if (!file) {
        perror("Failed to open file");
        return NULL;
    }

    size_t total_size = 0;
    while (total_size < MEMORY_BUDGET && !feof(file)) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        size_t bytes_read = fread(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (bytes_read != 1) {
            break;
        }
        task.data[total_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)] = pdu;
        total_size += bytes_read * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }

    fclose(file);
    task.size = total_size;
    task.processed = 1;

    return NULL;
}

void processNFAPIIndications() {
    pthread_t threads[MAX_FILES];
    for (int i = 0; i < MAX_FILES; i++) {
        FileTask task = {NULL, NULL, 0, 0};
        enqueue(task);
    }

    for (int i = 0; i < MAX_FILES; i++) {
        pthread_create(&threads[i], NULL, process_file, &file_queue[front]);
        dequeue();
    }

    for (int i = 0; i < MAX_FILES; i++) {
        pthread_join(threads[i], NULL);
    }
}
