int allocateAndPopulateArray(int N, NFAPI_CRC_INDICATION_PDU_T **array) {
    *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        perror("Memory allocation failed");
        return -1;
    }

    int rntiValues[MAX_RNTI + 1] = {0};
    for (int i = 0; i < N; i++) {
        do {
            (*array)[i].RNTI = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
        } while (rntiValues[(*array)[i].RNTI] != 0);
        rntiValues[(*array)[i].RNTI] = 1;

        (*array)[i].RX_UE_INFORMATION_TAG = rand() % N; // Unique within the array
        (*array)[i].CRC_INDICATION_REL8_TAG = generateRandomCRCFlag();
