#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    time_t timestamp;
    double throughput;
    double error_rate;
} UEStatsRecord;

typedef struct {
    UEStatsRecord *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEStatsManager;

UEStatsManager* create_manager(size_t initial_capacity) {
    UEStatsManager *manager = (UEStatsManager*)malloc(sizeof(UEStatsManager));
    if (!manager) return NULL;

    manager->records = (UEStatsRecord*)calloc(initial_capacity, sizeof(UEStatsRecord));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(UEStatsManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(UEStatsManager *manager, UEStatsRecord record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEStatsRecord *new_records = (UEStatsRecord*)realloc(manager->records, new_capacity * sizeof(UEStatsRecord));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }
        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->size++] = record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_record(UEStatsManager *manager, int ue_id, UEStatsRecord new_record) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].ue_id == ue_id) {
            manager->records[i] = new_record;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Record not found
}

int get_record(UEStatsManager *manager, int ue_id, UEStatsRecord *record) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].ue_id == ue_id) {
            *record = manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Record not found
}

// Example usage:
int main() {
    UEStatsManager *manager = create_manager(10);
    if (!manager) {
        fprintf(stderr, "Failed to create manager\n");
        return 1;
    }

    UEStatsRecord record = {12345, time(NULL), 1.5, 0.01};
    if (add_record(manager, record) != 0) {
        fprintf(stderr, "Failed to add record\n");
        destroy_manager(manager);
        return 1;
    }

    UEStatsRecord retrieved_record;
    if (get_record(manager, 12345, &retrieved_record) == 0) {
        printf("Retrieved throughput: %f, error rate: %f\n", retrieved_record.throughput, retrieved_record.error_rate);
    } else {
        fprintf(stderr, "Failed to retrieve record\n");
    }

    destroy_manager(manager);
    return 0;
}
```

This code provides a basic implementation of a `UEStatsManager` structure that manages a dynamically allocated array of `UEStatsRecord` structures. It includes functions for creating and destroying the manager, adding new records, updating existing ones based on the UE identifier, and retrieving statistics for a given UE identifier. The solution uses mutex locks to ensure thread safety during concurrent access.']

