#define MAX_STRUCTS 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T pdu_list[MAX_STRUCTS];
int current_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_error(const char* message) {
    fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

int is_rnti_unique(int rnti) {
    for (int i = 0; i < current_count; i++) {
        if (pdu_list[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&mutex);
    if (current_count >= MAX_STRUCTS) {
        log_error("Maximum number of structures reached");
    }
    if (!is_rnti_unique(pdu.RNTI)) {
        log_error("Duplicate RNTI detected");
    }
    pdu_list[current_count++] = pdu;
    pthread_mutex_unlock(&mutex);
}

void serialize_to_binary(const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        log_error("Failed to open file for writing");
    }
    fwrite(pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), current_count, file);
    fclose(file);
}

void serialize_to_json(const char* filename) {
    FILE* file = fopen(filename, "w");
    if (!file) {
        log_error("Failed to open file for writing");
    }
    fprintf(file, "[\n");
    for (int i = 0; i < current_count; i++) {
        if (i > 0) fprintf(file, ",\n");
        fprintf(file, "  {\"RX_UE_INFORMATION_TAG\": %d, \"RNTI\": %d, \"CRC_INDICATION_REL8_TAG\": %d, \"CRCFLAG\": %d}",
                pdu_list[i].RX_UE_INFORMATION_TAG,
                pdu_list[i].RNTI,
                pdu_list[i].CRC_INDICATION_REL8_TAG,
                pdu_list[i].CRCFLAG);
    }
    fprintf(file, "\n]\n");
    fclose(file);
}

int main() {
    // Example usage
    NFAPI_CRC_INDICATION_PDU_T example_pdu = {1, 2, 3, rand() % 2};
    add_pdu_to_list(example_pdu);

    serialize_to_binary("pdu_list.bin");
    serialize_to_json("pdu_list.json");

    return 0;
}
