import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.util.HashMap;
import java.util.Map;

public class ObjectDeserializer {

    private static final Map<String, Class<?>> classCache = new HashMap<>();
    private static long totalMemoryFootprint = 0;
    private static int objectCount = 0;
    private static final long MONITORING_PERIOD = 60 * 1000; // 1 minute
    private static final double MEMORY_USAGE_LIMIT = 50.0; // 50 MB average

    public static <T> T deserialize(byte[] data, Class<T> expectedClass) throws RuntimeException {
        try (ObjectInputStream ois = new ObjectInputStream(new ByteArrayInputStream(data))) {
            Object obj = ois.readObject();
            if (!expectedClass.isInstance(obj)) {
                throw new IllegalArgumentException("Deserialized object is not an instance of " + expectedClass.getName());
            }
            trackMemoryFootprint(obj);
            return expectedClass.cast(obj);
        } catch (IOException | ClassNotFoundException e) {
            throw new RuntimeException("Failed to deserialize object", e);
        }
    }

    private static void trackMemoryFootprint(Object obj) {
        long memoryUsage = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
        totalMemoryFootprint += memoryUsage;
        objectCount++;
        if (System.currentTimeMillis() % MONITORING_PERIOD == 0) {
            double averageMemoryUsage = (double) totalMemoryFootprint / objectCount / 1024 / 1024; // Convert to MB
            if (averageMemoryUsage > MEMORY_USAGE_LIMIT) {
                System.err.println("Alert: Average memory usage exceeds limit of " + MEMORY_USAGE_LIMIT + " MB");
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        try {
            byte[] serializedData = ...; // Obtain serialized data from external source
            MyClass deserializedObject = deserialize(serializedData, MyClass.class);
            System.out.println("Deserialized object: " + deserializedObject);
