#define MAX_UE_INFO 1000
#define RNTI_RANGE_MIN 1
#define RNTI_RANGE_MAX 65535

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

int generate_random_crc_flag() {
    return rand() % 2; // Randomly set to 0 or 1
}

int get_unique_rx_ue_info_tag(int *used_tags, int used_count) {
    int tag;
    do {
        tag = rand() % MAX_UE_INFO + 1;
    } while (tag <= used_count && used_tags[tag - 1]);
    return tag;
}

int validate_rnti(int rnti) {
    if (rnti < RNTI_RANGE_MIN || rnti > RNTI_RANGE_MAX) {
        // Log error
        return -1; // Invalid RNTI
    }
    return 0; // Valid RNTI
}

int populate_array(NFAPI_CRC_INDICATION_PDU_T **array, int *N, int *used_tags, int used_count) {
    pthread_mutex_lock(&mutex);
    if (*N >= MAX_UE_INFO) {
        pthread_mutex_unlock(&mutex);
        return -1; // Array is full
    }

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(*array, (*N + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&mutex);
        return -2; // Memory allocation failed
    }
    *array = new_array;

    int rnti;
    do {
        rnti = rand() % (RNTI_RANGE_MAX - RNTI_RANGE_MIN + 1) + RNTI_RANGE_MIN;
    } while (validate_rnti(rnti) != 0);

    (*array)[*N].RX_UE_INFORMATION_TAG = get_unique_rx_ue_info_tag(used_tags, used_count);
    if ((*array)[*N].RX_UE_INFORMATION_TAG <= used_count) {
        pthread_mutex_unlock(&mutex);
        return -3; // Failed to get unique RX_UE_INFORMATION_TAG
    }

    (*array)[*N].RNTI = rnti;
    (*array)[*N].CRC_INDICATION_REL8_TAG = generate_random_crc_flag();
    (*N)++;
    used_tags[(*array)[*N - 1].RX_UE_INFORMATION_TAG - 1] = 1;

    pthread_mutex_unlock(&mutex);
    return 0; // Success
}

void free_array(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    free(array);
}
