#define NR_NAS_MESSAGE_T 1024

typedef struct {
    NAS_PDU pdu;
    uint16_t sequence_number;
} NAS_Message;

NAS_Message *message_pool[NR_NAS_MESSAGE_T];
int pool_index = 0;
pthread_mutex_t pool_lock;

void initialize_message_pool() {
    for (int i = 0; i < NR_NAS_MESSAGE_T; i++) {
        message_pool[i] = malloc(sizeof(NAS_Message));
    }
    pthread_mutex_init(&pool_lock, NULL);
}

NAS_Message *get_message_from_pool() {
    NAS_Message *msg;
    pthread_mutex_lock(&pool_lock);
    if (pool_index > 0) {
        msg = message_pool[--pool_index];
    } else {
        msg = malloc(sizeof(NAS_Message));
    }
    pthread_mutex_unlock(&pool_lock);
    return msg;
}

void release_message_to_pool(NAS_Message *msg) {
    pthread_mutex_lock(&pool_lock);
    if (pool_index < NR_NAS_MESSAGE_T) {
        message_pool[pool_index++] = msg;
    } else {
        free(msg);
    }
    pthread_mutex_unlock(&pool_lock);
}
