#include <openssl/evp.h>
#include <openssl/rand.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RNTI;
    // Other fields...
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
    pthread_mutex_t lock;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t list_lock;
} LinkedList;

void initialize_cipher(const char* password, EVP_CIPHER_CTX** ctx) {
    unsigned char key[32], iv[16];
    SHA1((unsigned char*)password, strlen(password), key);
    RAND_bytes(iv, sizeof(iv));
    *ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(*ctx, EVP_aes_256_cbc(), NULL, key, iv);
}

void cleanup_cipher(EVP_CIPHER_CTX* ctx) {
    EVP_CIPHER_CTX_free(ctx);
}

int add_to_list(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->list_lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->list_lock);
        return -1;
    }
    new_node->data = data;
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->list_lock);
    return 0;
}

int validate_and_add(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    if (data.RNTI < 1 || data.RNTI > 64535) {
        return -1; // Invalid RNTI value
    }
    pthread_mutex_lock(&list->list_lock);
    Node* current = list->head;
    while (current) {
        pthread_mutex_lock(&current->lock);
        if (current->data.RNTI == data.RNTI) {
            pthread_mutex_unlock(&current->lock);
            pthread_mutex_unlock(&list->list_lock);
            return -1; // Duplicate RNTI
        }
        pthread_mutex_unlock(&current->lock);
        current = current->next;
    }
    int result = add_to_list(list, data);
    pthread_mutex_unlock(&list->list_lock);
    return result;
}

void* handle_callback(void* arg) {
    LinkedList* list = (LinkedList*)arg;
    // Simulate receiving data from external source
    NFAPI_CRC_INDICATION_PDU_T data = { /* Initialize with received data */ };
    validate_and_add(list, data);
    return NULL;
}

int main() {
    EVP_CIPHER_CTX* ctx;
    initialize_cipher("password", &ctx);

    LinkedList list;
    pthread_mutex_init(&list.list_lock, NULL);
    list.head = NULL;

    // Simulate handling multiple callbacks
    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, handle_callback, &list);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    cleanup_cipher(ctx);
    return 0;
}
```

This code provides a basic structure for managing a dynamic linked list of `NFAPI_CRC_INDICATION_PDU_T` structures, integrating with an external data source via asynchronous callbacks. It includes functions to initialize and clean up an AES-256-CBC cipher using OpenSSL, add new nodes to the list while ensuring thread safety and uniqueness, and handle multiple concurrent updates efficiently. The code also demonstrates how to use pthreads for concurrency and mutexes for synchronization.']

