#include <stdio.h>

typedef struct {
    char src_ip[16];
    char dst_ip[16];
    uint32_t seq_num;
} Packet;

typedef struct {
    Packet* packets;
    size_t capacity;
    size_t size;
} PacketArray;

void packet_array_init(PacketArray* array, size_t initial_capacity) {
    array->packets = (Packet*)malloc(initial_capacity * sizeof(Packet));
    if (!array->packets) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->capacity = initial_capacity;
    array->size = 0;
}

void packet_array_add(PacketArray* array, const Packet* packet) {
    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        Packet* new_packets = (Packet*)realloc(array->packets, new_capacity * sizeof(Packet));
        if (!new_packets) {
            fprintf(stderr, "Memory reallocation failed\n");
            exit(EXIT_FAILURE);
        }
        array->packets = new_packets;
        array->capacity = new_capacity;
    }
    memcpy(&array->packets[array->size], packet, sizeof(Packet));
    array->size++;
}

Packet* packet_array_get(const PacketArray* array, size_t index) {
    if (index >= array->size) {
        fprintf(stderr, "Invalid index access\n");
        return NULL;
    }
    return &array->packets[index];
}

void packet_array_iterate(const PacketArray* array, void (*callback)(const Packet*)) {
    for (size_t i = 0; i < array->size; i++) {
        callback(&array->packets[i]);
    }
}

void packet_array_free(PacketArray* array) {
    free(array->packets);
    array->packets = NULL;
    array->capacity = 0;
    array->size = 0;
}
