['```rust
use tokio::sync::{mpsc, RwLock};
use std::collections::BinaryHeap;
use std::cmp::Reverse;
use std::time::{Duration, Instant};
use log::{info, error};

#[derive(Copy, Clone, Eq, PartialEq)]
struct Task {
    priority: u32,
    id: u64,
    created_at: Instant,
}

impl Ord for Task {
    fn cmp(&self, other: &Self) -> std::cmp::Ordering {
        self.priority.cmp(&other.priority)
    }
}

impl PartialOrd for Task {
    fn partial_cmp(&self, other: &Self) -> Option<std::cmp::Ordering> {
        Some(self.cmp(other))
    }
}

struct ThreadPool {
    workers: Vec<tokio::task::JoinHandle<()>>,
    task_queue: mpsc::Sender<Task>,
    shutdown_rx: mpsc::Receiver<()>,
}

impl ThreadPool {
    async fn new(initial_workers: usize, max_capacity: usize) -> Self {
        let (tx, rx) = mpsc::channel(max_capacity);
        let (shutdown_tx, shutdown_rx) = mpsc::channel(1);

        let workers = (0..initial_workers)
            .map(|_| {
                tokio::spawn(async move {
                    while let Some(task) = rx.recv().await {
                        // Process task
                        info!("Processing task {:?}", task);
                    }
                })
            })
            .collect();

        ThreadPool {
            workers,
            task_queue: tx,
            shutdown_rx,
        }
    }

    async fn submit_task(&self, task: Task) -> Result<(), mpsc::error::SendError<Task>> {
        self.task_queue.send(task).await
    }

    async fn shutdown(self) {
        for _ in 0..self.workers.len() {
            self.shutdown_tx.send(()).await.unwrap();
        }
        for worker in self.workers {
            worker.await.unwrap();
        }
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        eprintln!("Usage: {} <initial_workers> <max_capacity>", args[0]);
        return Ok(());
    }

    let initial_workers: usize = args[1].parse()?;
    let max_capacity: usize = args[2].parse()?;

    let pool = ThreadPool::new(initial_workers, max_capacity).await;

    // Example task submission
    for i in 0..10 {
        let task = Task {
            priority: i % 3,
            id: i as u64,
            created_at: Instant::now(),
        };
        pool.submit_task(task).await?;
    }

    // Graceful shutdown
    pool.shutdown().await;

    Ok(())
}
