void init_crc_list(CRC_LIST *list) {
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T* create_new_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    NFAPI_CRC_INDICATION_PDU_T *new_entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_entry->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_entry->RNTI = RNTI;
    new_entry->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_entry->CRCFLAG = CRCFLAG;
    new_entry->next = NULL;
    return new_entry;
}

void add_entry(CRC_LIST *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_entry = create_new_entry(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG, CRCFLAG);
    new_entry->next = list->head;
    list->head = new_entry;
    pthread_mutex_unlock(&list->lock);
}

