#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_RECORDS 100000
#define MAX_OPERATORS 10

typedef struct {
    char ue_id[20];
    int stats;
} UEStatsRecord;

typedef struct {
    pthread_mutex_t lock;
    UEStatsRecord records[MAX_UE_RECORDS];
    int record_count;
} OperatorNamespace;

OperatorNamespace operators[MAX_OPERATORS];

void init_operator_namespace(int operator_id) {
    pthread_mutex_init(&operators[operator_id].lock, NULL);
    memset(operators[operator_id].records, 0, sizeof(UEStatsRecord) * MAX_UE_RECORDS);
    operators[operator_id].record_count = 0;
}

int add_or_update_record(int operator_id, const char* ue_id, int stats) {
    pthread_mutex_lock(&operators[operator_id].lock);
    for (int i = 0; i < operators[operator_id].record_count; ++i) {
        if (strcmp(operators[operator_id].records[i].ue_id, ue_id) == 0) {
            operators[operator_id].records[i].stats += stats;
            pthread_mutex_unlock(&operators[operator_id].lock);
            return 1;
        }
    }
    if (operators[operator_id].record_count < MAX_UE_RECORDS) {
        strcpy(operators[operator_id].records[operators[operator_id].record_count].ue_id, ue_id);
        operators[operator_id].records[operators[operator_id].record_count].stats = stats;
        ++operators[operator_id].record_count;
    }
    pthread_mutex_unlock(&operators[operator_id].lock);
    return 0;
}

UEStatsRecord* get_record(int operator_id, const char* ue_id) {
    pthread_mutex_lock(&operators[operator_id].lock);
    for (int i = 0; i < operators[operator_id].record_count; ++i) {
        if (strcmp(operators[operator_id].records[i].ue_id, ue_id) == 0) {
            UEStatsRecord* record = &operators[operator_id].records[i];
            pthread_mutex_unlock(&operators[operator_id].lock);
            return record;
        }
    }
    pthread_mutex_unlock(&operators[operator_id].lock);
    return NULL;
}

void merge_namespaces(int target_operator, int source_operator) {
    pthread_mutex_lock(&operators[target_operator].lock);
    pthread_mutex_lock(&operators[source_operator].lock);
    for (int i = 0; i < operators[source_operator].record_count; ++i) {
        add_or_update_record(target_operator, operators[source_operator].records[i].ue_id, operators[source_operator].records[i].stats);
    }
    pthread_mutex_unlock(&operators[source_operator].lock);
    pthread_mutex_unlock(&operators[target_operator].lock);
}

void cleanup() {
    for (int i = 0; i < MAX_OPERATORS; ++i) {
        pthread_mutex_destroy(&operators[i].lock);
    }
}

// External logging service integration functions
void flush_statistics(int operator_id) {
    // Implementation to flush statistics to external logging service
}

void handle_logging_failure() {
    // Implementation for handling logging failures with local storage buffering
}
