#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int ue_id;
    long timestamp;
    double throughput;
    double error_rate;
} UEStatsRecord;

typedef struct {
    UEStatsRecord *records;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UEStatsManager;

UEStatsManager* create_manager(size_t initial_capacity) {
    UEStatsManager *manager = (UEStatsManager*)malloc(sizeof(UEStatsManager));
    if (!manager) return NULL;

    manager->records = (UEStatsRecord*)calloc(initial_capacity, sizeof(UEStatsRecord));
    if (!manager->records) {
        free(manager);
        return NULL;
    }

    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroy_manager(UEStatsManager *manager) {
    pthread_mutex_lock(&manager->lock);
    free(manager->records);
    pthread_mutex_unlock(&manager->lock);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_record(UEStatsManager *manager, UEStatsRecord record) {
    pthread_mutex_lock(&manager->lock);

    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity * 2;
        UEStatsRecord *new_records = (UEStatsRecord*)realloc(manager->records, new_capacity * sizeof(UEStatsRecord));
        if (!new_records) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Memory allocation failed
        }

        manager->records = new_records;
        manager->capacity = new_capacity;
    }

    manager->records[manager->size++] = record;

    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_record(UEStatsManager *manager, int ue_id, UEStatsRecord new_record) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].ue_id == ue_id) {
            manager->records[i] = new_record;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Record not found
}

int get_record(UEStatsManager *manager, int ue_id, UEStatsRecord *record) {
    pthread_mutex_lock(&manager->lock);

    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->records[i].ue_id == ue_id) {
            *record = manager->records[i];
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }

    pthread_mutex_unlock(&manager->lock);
    return -1; // Record not found
}

// Additional functions for handling external data source, batch processing, anomaly detection, etc.
