typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus[MAX_PDUS];
    int count;
    pthread_mutex_t mutex;
} PduList;

void init_pdu_list(PduList *list) {
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int insert_pdu(PduList *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_PDUS) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    list->pdus[list->count++] = pdu;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_pdu(PduList *list, int index) {
    if (index < 0 || index >= list->count) {
        return NULL; // Invalid index
    }
    return list->pdus[index];
}

void reset_counter(PduList *list) {
    pthread_mutex_lock(&list->mutex);
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    PduList pdu_list;
    init_pdu_list(&pdu_list);

