    for (int i = 0; i < MAX_PDUS; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = get_pdu(&pdu_list, i);
        if (pdu != NULL) {
            process_pdu(pdu);
        } else {
            printf("Failed to retrieve PDU\n");
            break;
        }
    }

    reset_counter(&pdu_list);

    return 0;
}
