int initialize_and_populate(NFAPI_LTE_RX_FRAME_T *frames, int N) {
    if (N > MAX_FRAMES) {
        return -1; // Error: Exceeds maximum allowed frames
    }

    for (int i = 0; i < N; i++) {
        frames[i].rf_rx_frame_info = malloc(sizeof(RF_RX_FRAME_INFO));
        frames[i].ue_context_info_tag = malloc(sizeof(UE_CONTEXT_INFO_TAG));

        if (!frames[i].rf_rx_frame_info || !frames[i].ue_context_info_tag) {
            return -2; // Error: Memory allocation failed
        }

        // Populate RF_RX_FRAME_INFO and UE_CONTEXT_INFO_TAG

        frames[i].mac_rx_pdu_list = malloc(sizeof(MAC_RX_PDU_T) * 10); // Example size
        if (!frames[i].mac_rx_pdu_list) {
            return -3; // Error: Memory allocation failed
        }

        for (int j = 0; j < 10; j++) {
            frames[i].mac_rx_pdu_list[j] = malloc(sizeof(MAC_RX_PDU_T));
            if (!frames[i].mac_rx_pdu_list[j]) {
                return -4; // Error: Memory allocation failed
            }
            // Populate MAC_RX_PDU_T elements
        }

        NFAPI_CRC_INDICATION_PDU_T *crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!crc_indication) {
            return -5; // Error: Memory allocation failed
        }

        crc_indication->rx_ue_information_tag = malloc(sizeof(RX_UE_INFORMATION_TAG));
        crc_indication->rnti = rand() % 65536; // Example RNTI generation

        CRC_INDICATION_REL8_TAG *crc_rel8 = malloc(sizeof(CRC_INDICATION_REL8_TAG));
        if (!crc_rel8) {
            return -6; // Error: Memory allocation failed
        }

        crc_rel8->crcflag = rand() % 2; // Randomly set CRCFLAG
        crc_indication->crc_indication_rel8_tag = crc_rel8;

        // Populate NFAPI_CRC_INDICATION_PDU_T elements

        free(crc_indication);
    }

    return 0; // Success
}

int resolve_dns(const char *hostname, u_char *ip_address) {
    struct addrinfo hints, *res;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET; // IPv4

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1; // Error: DNS resolution failed
    }

    struct sockaddr_in *ipv4 = (struct sockaddr_in *)res->ai_addr;
    memcpy(ip_address, &(ipv4->sin_addr), sizeof(u_char) * 4);

    freeaddrinfo(res);
    return 0; // Success
}
