typedef struct NFAPI_MESSAGE_T {
    struct NFAPI_MESSAGE_T* prev;
    struct NFAPI_MESSAGE_T* next;
    RX_UE_CONTEXT rx_ue_context;
    RRC_MESSAGE rrc_message;
} NFAPI_MESSAGE_T;

NFAPI_MESSAGE_T* create_nfaapi_message(RX_UE_CONTEXT* rx_ue_context, RRC_MESSAGE* rrc_message) {
    NFAPI_MESSAGE_T* message = (NFAPI_MESSAGE_T*)malloc(sizeof(NFAPI_MESSAGE_T));
    if (message == NULL) {
        // Handle memory allocation failure
        return NULL;
    }
    memcpy(&message->rx_ue_context, rx_ue_context, sizeof(RX_UE_CONTEXT));
    memcpy(&message->rrc_message, rrc_message, sizeof(RRC_MESSAGE));
    message->prev = NULL;
    message->next = NULL;
    return message;
}

void append_to_list(NFAPI_MESSAGE_T** head, NFAPI_MESSAGE_T* new_message) {
    if (*head == NULL) {
        *head = new_message;
    } else {
        NFAPI_MESSAGE_T* current = *head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_message;
        new_message->prev = current;
    }
}

void prepend_to_list(NFAPI_MESSAGE_T** head, NFAPI_MESSAGE_T* new_message) {
    if (*head == NULL) {
        *head = new_message;
    } else {
        new_message->next = *head;
        (*head)->prev = new_message;
        *head = new_message;
    }
}

void free_list(NFAPI_MESSAGE_T** head) {
    NFAPI_MESSAGE_T* current = *head;
    while (current != NULL) {
        NFAPI_MESSAGE_T* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
