#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_MESSAGE_T {
    struct RX_UE_CONTEXT *ue_context;
    void *rrc_message;
    size_t payload_size;
} NFAPI_MESSAGE_T;

typedef struct MemoryPool {
    void *pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->block_size = block_size;
    mp->num_blocks = num_blocks;
    mp->free_index = 0;
    mp->pool = malloc(block_size * num_blocks);
    return mp;
}

void* allocate_block(MemoryPool *mp) {
    if (mp->free_index >= mp->num_blocks) {
        return NULL; // Out of memory
    }
    void *block = ((char*)mp->pool) + mp->free_index * mp->block_size;
    mp->free_index++;
    return block;
}

void deallocate_block(MemoryPool *mp, void *block) {
    size_t index = ((char*)block - (char*)mp->pool) / mp->block_size;
    if (index < mp->num_blocks && index >= mp->free_index) {
        mp->free_index = index + 1;
    }
}

typedef struct NFAPI_LIST_NODE {
    NFAPI_MESSAGE_T message;
    struct NFAPI_LIST_NODE *next;
    struct NFAPI_LIST_NODE *prev;
} NFAPI_LIST_NODE;

typedef struct NFAPI_LIST {
    NFAPI_LIST_NODE *head;
    NFAPI_LIST_NODE *tail;
    MemoryPool *memory_pool;
} NFAPI_LIST;

NFAPI_LIST* create_list() {
    NFAPI_LIST *list = (NFAPI_LIST*)malloc(sizeof(NFAPI_LIST));
    list->head = NULL;
    list->tail = NULL;
    list->memory_pool = create_memory_pool(sizeof(NFAPI_MESSAGE_T), 1024); // Initial capacity
    return list;
}

void insert_message(NFAPI_LIST *list, NFAPI_MESSAGE_T message) {
    NFAPI_LIST_NODE *node = (NFAPI_LIST_NODE*)allocate_block(list->memory_pool);
    if (node == NULL) {
        // Handle memory allocation failure
        return;
    }
    node->message = message;
    node->next = NULL;
    node->prev = list->tail;

    if (list->tail != NULL) {
        list->tail->next = node;
    } else {
        list->head = node;
    }
    list->tail = node;
}

void remove_message_by_index(NFAPI_LIST *list, size_t index) {
    NFAPI_LIST_NODE *current = list->head;
    for (size_t i = 0; current != NULL && i < index; i++) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle invalid index
        return;
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    deallocate_block(list->memory_pool, current);
}

void remove_message_by_ue_context(NFAPI_LIST *list, struct RX_UE_CONTEXT *ue_context) {
    NFAPI_LIST_NODE *current = list->head;
    while (current != NULL && current->message.ue_context != ue_context) {
        current = current->next;
    }
    if (current == NULL) {
        // Handle message not found
        return;
    }

    if (current->prev != NULL) {
        current->prev->next = current->next;
    } else {
        list->head = current->next;
    }

    if (current->next != NULL) {
        current->next->prev = current->prev;
    } else {
        list->tail = current->prev;
    }

    deallocate_block(list->memory_pool, current);
}

void iterate_forward(NFAPI_LIST *list) {
    NFAPI_LIST_NODE *current = list->head;
    while (current != NULL) {
        // Process message
        current = current->next;
    }
}

void iterate_backward(NFAPI_LIST *list) {
    NFAPI_LIST_NODE *current = list->tail;
    while (current != NULL) {
        // Process message
        current = current->prev;
    }
}

void destroy_list(NFAPI_LIST *list) {
    NFAPI_LIST_NODE *current = list->head;
    while (current != NULL) {
        NFAPI_LIST_NODE *next = current->next;
        deallocate_block(list->memory_pool, current);
        current = next;
    }
    free(list->memory_pool->pool);
    free(list->memory_pool);
    free(list);
}
