#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t size;
    size_t used;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t size) {
    MemoryPool *mp = (MemoryPool*)malloc(sizeof(MemoryPool));
    mp->pool = (NFAPI_CRC_INDICATION_PDU_T*)calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    mp->size = size;
    mp->used = 0;
    pthread_mutex_init(&mp->lock, NULL);
    return mp;
}

void destroy_memory_pool(MemoryPool *mp) {
    free(mp->pool);
    pthread_mutex_destroy(&mp->lock);
    free(mp);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_from_pool(MemoryPool *mp) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;
    pthread_mutex_lock(&mp->lock);
    if (mp->used < mp->size) {
        pdu = &mp->pool[mp->used++];
    }
    pthread_mutex_unlock(&mp->lock);
    return pdu;
}

void deallocate_to_pool(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->used; ++i) {
        if (&mp->pool[i] == pdu) {
            mp->pool[i] = mp->pool[--mp->used];
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
}

NFAPI_CRC_INDICATION_PDU_T* create_nfaapi_pdu(MemoryPool *mp, int RX_UE_INFORMATION_TAG, int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_from_pool(mp);
    if (pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
    return pdu;
}

void free_nfaapi_pdu(MemoryPool *mp, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    deallocate_to_pool(mp, pdu);
}
