typedef struct {
    // Define the structure fields here
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* array;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} CRCArray;

CRCArray* create_crc_array(size_t initial_capacity) {
    CRCArray* crc_array = (CRCArray*)malloc(sizeof(CRCArray));
    if (!crc_array) return NULL;

    crc_array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_array->array) {
        free(crc_array);
        return NULL;
    }

    crc_array->capacity = initial_capacity;
    crc_array->size = 0;
    pthread_mutex_init(&crc_array->mutex, NULL);

    return crc_array;
}

void destroy_crc_array(CRCArray* crc_array) {
    if (crc_array) {
        free(crc_array->array);
        pthread_mutex_destroy(&crc_array->mutex);
        free(crc_array);
    }
}

int resize_crc_array(CRCArray* crc_array, size_t new_capacity) {
    pthread_mutex_lock(&crc_array->mutex);

    NFAPI_CRC_INDICATION_PDU_T* new_array = (NFAPI_CRC_INDICATION_PDU_T*)realloc(crc_array->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_array) {
        pthread_mutex_unlock(&crc_array->mutex);
        return -1;
    }

    crc_array->array = new_array;
    crc_array->capacity = new_capacity;

    pthread_mutex_unlock(&crc_array->mutex);
    return 0;
}

int add_to_crc_array(CRCArray* crc_array, RX_UE_INFORMATION_TAG ue_tag, RNTI rnti) {
    pthread_mutex_lock(&crc_array->mutex);

    if (crc_array->size >= crc_array->capacity) {
        size_t new_capacity = crc_array->capacity == 0 ? 1 : crc_array->capacity * 2;
        if (resize_crc_array(crc_array, new_capacity) != 0) {
            pthread_mutex_unlock(&crc_array->mutex);
            return -1;
        }
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu = &crc_array->array[crc_array->size++];
    // Initialize the structure fields here
    pdu->RX_UE_INFORMATION_TAG = ue_tag;
    pdu->RNTI = rnti;
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2; // Randomly generate CRCFLAG

    pthread_mutex_unlock(&crc_array->mutex);
    return 0;
}
