    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        printf("Failed to open log file.\n");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "[%s] %s\n", ctime(&now), message);

    fclose(log_file);

    // Check and truncate log file if it exceeds the maximum size
    FILE* check_log_file = fopen(LOG_FILE, "r");
    fseek(check_log_file, 0, SEEK_END);
    long file_size = ftell(check_log_file);
    fclose(check_log_file);

    if (file_size > MAX_LOG_SIZE) {
        FILE* truncate_log_file = fopen(LOG_FILE, "w");
        fclose(truncate_log_file);
