#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define M 100

typedef struct WebEntity {
    char url[256];
    time_t lastAccessed;
    int statusFlags;
} WebEntity;

typedef struct MemoryPool {
    WebEntity *entities;
    size_t size;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

void initMemoryPool(MemoryPool *pool, size_t size) {
    pool->entities = (WebEntity *)malloc(size * sizeof(WebEntity));
    if (!pool->entities) {
        perror("Failed to allocate memory for memory pool");
        exit(EXIT_FAILURE);
    }
    pool->size = size;
    pool->count = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void destroyMemoryPool(MemoryPool *pool) {
    free(pool->entities);
    pthread_mutex_destroy(&pool->lock);
}

int addWebEntity(MemoryPool *pool, const char *url, int statusFlags) {
    pthread_mutex_lock(&pool->lock);
    if (pool->count >= pool->size) {
        pthread_mutex_unlock(&pool->lock);
        return -1; // Pool is full
    }
    WebEntity *entity = &pool->entities[pool->count++];
    snprintf(entity->url, sizeof(entity->url), "%s", url);
    entity->lastAccessed = time(NULL);
    entity->statusFlags = statusFlags;
    pthread_mutex_unlock(&pool->lock);
    return 0;
}

void manageWebDirectory(MemoryPool *pool, size_t M) {
    if (M > pool->size) {
        fprintf(stderr, "Error: M exceeds the memory pool size\n");
        return;
    }

    // Simulate adding web entities
    for (size_t i = 0; i < M; ++i) {
        addWebEntity(pool, "http://example.com/page", 0);
    }
}

int main() {
    MemoryPool pool;
    initMemoryPool(&pool, M);

    manageWebDirectory(&pool, M);

    destroyMemoryPool(&pool);
    return 0;
}
