#define MAX_FRAMES 1000000

typedef struct {
    int id;
    // Other fields of NFAPI_L2_RX_FRAME structure
} NFAPI_L2_RX_FRAME;

NFAPI_L2_RX_FRAME frames[MAX_FRAMES];
int frame_count = 0;
sem_t frame_semaphore;

void* process_frames(void* arg) {
    while (1) {
        sem_wait(&frame_semaphore);
