#define NFAPI_CRC_INDICATION_PDU_T struct { int RX_UE_INFORMATION_TAG; int RNTI; int CRCFLAG; }
#define LOG_BUFFER_SIZE 100

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
    int count;
    int head;
    int tail;
} LogBuffer;

void init_log_buffer(LogBuffer *buffer, int size) {
    buffer->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!buffer->data) {
        fprintf(stderr, "Memory allocation failed for log buffer\n");
        exit(EXIT_FAILURE);
    }
    buffer->size = size;
    buffer->count = 0;
    buffer->head = 0;
    buffer->tail = 0;
}

void free_log_buffer(LogBuffer *buffer) {
    free(buffer->data);
    buffer->data = NULL;
    buffer->size = 0;
    buffer->count = 0;
    buffer->head = 0;
    buffer->tail = 0;
}

int log_event(LogBuffer *buffer, NFAPI_CRC_INDICATION_PDU_T event) {
    if (buffer->count == buffer->size) {
        buffer->head = (buffer->head + 1) % buffer->size;
    } else {
        buffer->count++;
    }
    buffer->data[buffer->tail] = event;
    buffer->tail = (buffer->tail + 1) % buffer->size;
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *create_nfaapi_pdu(int N, int enable_logging, LogBuffer *log_buffer) {
    if (N <= 0) {
        fprintf(stderr, "Invalid input: N must be greater than 0\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *pdu_array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        fprintf(stderr, "Memory allocation failed for PDU array\n");
        return NULL;
    }

    srand(time(NULL)); // Seed the random number generator

    for (int i = 0; i < N; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = i + 1; // Incremental sequence number
        pdu_array[i].RNTI = rand() % 1024; // Random RNTI
        pdu_array[i].CRCFLAG = rand() % 2; // Random CRCFLAG

        if (enable_logging) {
            NFAPI_CRC_INDICATION_PDU_T log_event = pdu_array[i];
            log_event.RX_UE_INFORMATION_TAG = i + 1; // Incremental sequence number for logging
            log_event.RNTI = rand() % 1024; // Random RNTI for logging
            log_event.CRCFLAG = rand() % 2; // Random CRCFLAG for logging
            if (log_buffer) {
                log_event(log_buffer, log_event);
            }
        }
    }

    return pdu_array;
}

void free_nfaapi_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu_array) {
