typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct List {
    Node* head;
    pthread_mutex_t mutex;
    int max_size;
    int current_size;
} List;

List* create_list(int max_size) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    list->max_size = max_size;
    list->current_size = 0;
    return list;
}

void destroy_list(List* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->current_size >= list->max_size) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    list->current_size++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

NFAPI_CRC_INDICATION_PDU_T* get_from_list(List* list, int RNTI) {
