#include <stdio.h>
#include <stdlib.h>

typedef struct LTE_RRC_MESSAGE {
    int RRU_CELL_ID;
    char RRC_MESSAGE_TYPE[50];
    int SEQUENCE_NUMBER;
    struct LTE_RRC_MESSAGE *next;
} LTE_RRC_MESSAGE;

LTE_RRC_MESSAGE* initializeLinkedList(int cellID, const char* messageType, int sequenceNumber) {
    LTE_RRC_MESSAGE* newNode = (LTE_RRC_MESSAGE*)malloc(sizeof(LTE_RRC_MESSAGE));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    newNode->RRU_CELL_ID = cellID;
    strcpy(newNode->RRC_MESSAGE_TYPE, messageType);
    newNode->SEQUENCE_NUMBER = sequenceNumber;
    newNode->next = NULL;

    return newNode;
}

LTE_RRC_MESSAGE* insertInOrder(LTE_RRC_MESSAGE* head, int cellID, const char* messageType, int sequenceNumber) {
    LTE_RRC_MESSAGE* newNode = initializeLinkedList(cellID, messageType, sequenceNumber);
    if (newNode == NULL) {
        return head; // Return original head on failure
    }

    if (head == NULL || newNode->SEQUENCE_NUMBER < head->SEQUENCE_NUMBER) {
        newNode->next = head;
        return newNode;
    }

    LTE_RRC_MESSAGE* current = head;
    while (current->next != NULL && current->next->SEQUENCE_NUMBER <= newNode->SEQUENCE_NUMBER) {
        current = current->next;
    }

    newNode->next = current->next;
    current->next = newNode;

    return head;
}

void freeLinkedList(LTE_RRC_MESSAGE* head) {
    LTE_RRC_MESSAGE* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    LTE_RRC_MESSAGE* listHead = NULL;

    // Example usage
    listHead = insertInOrder(listHead, 101, "SetupRequest", 5);
    listHead = insertInOrder(listHead, 102, "HandoverRequest", 3);
    listHead = insertInOrder(listHead, 103, "ReleaseRequest", 7);

    // Free the allocated memory
    freeLinkedList(listHead);

    return 0;
}
```

This code snippet provides a basic implementation of a linked list for `LTE_RRC_MESSAGE` structures. It includes functions to initialize a new node, insert nodes in order based on sequence numbers, and free the entire list when done. The example usage in the `main` function demonstrates how to add messages to the list while maintaining their order by sequence number.']

