#define MAX_UE_CONTEXTS 1024

typedef struct LTE_RRC_MESSAGE {
    int RRU_CELL_ID;
    int RRC_MESSAGE_TYPE;
    int SEQUENCE_NUMBER;
} LTE_RRC_MESSAGE;

typedef struct NFAPI_RRC_MESSAGE_T {
    int UE_CONTEXT_TAG;
    // SRS资源配置 and PHY_LAYER_STATS fields
} NFAPI_RRC_MESSAGE_T;

typedef struct LinkedListNode {
    LTE_RRC_MESSAGE *data;
    struct LinkedListNode *next;
} LinkedListNode;

LinkedListNode* initializeLinkedList(int size) {
    LinkedListNode *head = NULL;
    for (int i = 0; i < size; i++) {
        LinkedListNode *newNode = (LinkedListNode*)malloc(sizeof(LinkedListNode));
        if (!newNode) {
            fprintf(stderr, "Memory allocation failed\n");
            return head;
        }
        newNode->data = (LTE_RRC_MESSAGE*)malloc(sizeof(LTE_RRC_MESSAGE));
        if (!newNode->data) {
            free(newNode);
            fprintf(stderr, "Memory allocation failed\n");
            return head;
        }
        // Initialize data
        newNode->data->RRU_CELL_ID = i + 1;
        newNode->data->RRC_MESSAGE_TYPE = i % 2 == 0 ? 1 : 2;
        newNode->data->SEQUENCE_NUMBER = i * 10;
        newNode->next = head;
        head = newNode;
    }
    return head;
}

int validateAndAdjustSequence(LinkedListNode *head) {
    int prevSequence = -1;
    while (head) {
        if (head->data->SEQUENCE_NUMBER <= prevSequence) {
            head->data->SEQUENCE_NUMBER = prevSequence + 1;
        }
        prevSequence = head->data->SEQUENCE_NUMBER;
        head = head->next;
    }
    return 0;
}

int initializeNFAPIArray(NFAPI_RRC_MESSAGE_T *array, int size, int *ueContextTags) {
    for (int i = 0; i < size; i++) {
        array[i].UE_CONTEXT_TAG = ueContextTags[i];
        // Initialize SRS资源配置 and PHY_LAYER_STATS fields
        if (i > 0 && array[i].UE_CONTEXT_TAG == array[i - 1].UE_CONTEXT_TAG) {
            fprintf(stderr, "Duplicate UE_CONTEXT_TAG detected\n");
            return -1;
        }
    }
    return 0;
}

void logError(const char *message) {
    // Thread-safe logging mechanism
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);
    fprintf(stderr, "%s\n", message);
    pthread_mutex_unlock(&mutex);
}

int main() {
    int listSize = 100;
    LinkedListNode *listHead = initializeLinkedList(listSize);
    if (listHead) {
        validateAndAdjustSequence(listHead);

        NFAPI_RRC_MESSAGE_T nfapiArray[MAX_UE_CONTEXTS];
        int ueContextTags[] = {1, 2, 3, 4, 5};
        int arraySize = sizeof(ueContextTags) / sizeof(ueContextTags[0]);
        if (initializeNFAPIArray(nfapiArray, arraySize, ueContextTags) != 0) {
            logError("Failed to initialize NFAPI array");
        }

        // Free allocated memory
        while (listHead) {
            LinkedListNode *temp = listHead;
            free(temp->data);
            listHead = temp->next;
            free(temp);
        }
    }

    return 0;
}
