#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct TCP_PACKET {
    char SOURCE_IP[16];
    char DESTINATION_IP[16];
    int PACKET_SIZE;
    long TRANSMISSION_TIMESTAMP;
    struct TCP_PACKET *next;
} TCP_PACKET;

typedef struct QUEUE_NODE {
    TCP_PACKET *packet;
    struct QUEUE_NODE *next;
} QUEUE_NODE;

typedef struct QUEUE {
    QUEUE_NODE *front;
    QUEUE_NODE *rear;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} QUEUE;

QUEUE* create_queue() {
    QUEUE *queue = (QUEUE*)malloc(sizeof(QUEUE));
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
    return queue;
}

void enqueue(QUEUE *queue, TCP_PACKET *packet) {
    pthread_mutex_lock(&queue->mutex);
    QUEUE_NODE *new_node = (QUEUE_NODE*)malloc(sizeof(QUEUE_NODE));
    new_node->packet = packet;
    new_node->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = new_node;
    } else {
        queue->rear->next = new_node;
        queue->rear = new_node;
    }
    pthread_cond_signal(&queue->cond);
    pthread_mutex_unlock(&queue->mutex);
}

TCP_PACKET* dequeue(QUEUE *queue) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->front == NULL) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }

    QUEUE_NODE *temp = queue->front;
    TCP_PACKET *packet = temp->packet;
    queue->front = queue->front->next;

    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    pthread_mutex_unlock(&queue->mutex);
    return packet;
}

void destroy_queue(QUEUE *queue) {
    pthread_mutex_lock(&queue->mutex);
    QUEUE_NODE *current = queue->front;
    while (current != NULL) {
        QUEUE_NODE *temp = current;
        current = current->next;
        free(temp->packet);
        free(temp);
    }
    queue->front = queue->rear = NULL;
    pthread_mutex_unlock(&queue->mutex);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
    free(queue);
}
