    if (current_size >= MAX_STRUCTS) {
        fprintf(stderr, "Error: Maximum number of structures reached.\n");
        exit(EXIT_FAILURE);
    }
    NFAPI_CRC_INDICATION_PDU_T *new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        perror("Failed to allocate memory for new structure.");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    // Initialize new_struct with random values and unique RNTI
    // ...
    struct_list[current_size++] = new_struct;
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void serialize_to_binary() {
    FILE *file = fopen("output.bin", "wb");
    if (!file) {
        perror("Failed to open file for binary output.");
        return;
    }
    fwrite(struct_list, sizeof(NFAPI_CRC_INDICATION_PDU_T), current_size, file);
    fclose(file);
}

void serialize_to_json() {
    FILE *file = fopen("output.json", "w");
    if (!file) {
        perror("Failed to open file for JSON output.");
        return;
    }
    fprintf(file, "[\n");
    for (int i = 0; i < current_size; i++) {
        fprintf(file, "{\"ue_info\": %d, \"RNTI\": %d, \"crc_indication\": %d}",
                struct_list[i]->ue_info, struct_list[i]->RNTI, struct_list[i]->crc_indication);
        if (i < current_size - 1) fprintf(file, ",\n");
    }
    fprintf(file, "\n]\n");
    fclose(file);
}

int main() {
    pthread_t threads[MAX_STRUCTS];
    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_create(&threads[i], NULL, add_struct, NULL);
    }
    for (int i = 0; i < MAX_STRUCTS; i++) {
        pthread_join(threads[i], NULL);
    }
    serialize_to_binary();
    serialize_to_json();
    return 0;
}
