    if (node == NULL) return NULL;
    node->data = data;
    node->next = NULL;
    return node;
}

int add_to_list(List* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->head != NULL && list->head->data.RNTI == data.RNTI) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    Node* new_node = create_node(data);
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void* fetch_checksum(void* arg) {
    // Simulate fetching checksum from external data source
    sleep(2); // Simulate network latency
    int checksum = rand() % 100; // Simplified checksum for demonstration
    *(int*)arg = checksum;
    return NULL;
}

NFAPI_CRC_INDICATION_PDU_T* process_data(List* list, const char* input_string) {
    if (input_string == NULL) return NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head != NULL && list->head->data.RNTI == 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T data = {1, rand() % 100, rand() % 2};
    if (add_to_list(list, data) != 0) {
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    int checksum;
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, fetch_checksum, &checksum);
    pthread_join(thread_id, NULL);

    if (data.CRC_INDICATION_REL8_TAG != checksum) {
        printf("Checksum validation failed for RNTI: %d\n", data.RNTI);
        pthread_mutex_unlock(&list->mutex);
        return NULL;
    }

    pthread_mutex_unlock(&list->mutex);
    return &data;
}

int main() {
    List* list = create_list();
    if (list == NULL) {
        printf("Failed to create list\n");
        return 1;
    }

    const char* input_string = "example";
    NFAPI_CRC_INDICATION_PDU_T* result = process_data(list, input_string);
    if (result != NULL) {
        printf("Processed data: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRC_INDICATION_REL8_TAG=%d\n",
               result->RX_UE_INFORMATION_TAG, result->RNTI, result->CRC_INDICATION_REL8_TAG);
    } else {
        printf("Failed to process data\n");
    }

    destroy_list(list);
    return 0;
}
