typedef struct MemoryPool {
    void* pool;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;

    pool->pool = malloc(block_size * num_blocks);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    return pool;
}

void destroy_memory_pool(MemoryPool* pool) {
    free(pool->pool);
    free(pool);
}

void* allocate_from_pool(MemoryPool* pool) {
    if (pool->free_index >= pool->num_blocks) return NULL;
    void* block = (char*)pool->pool + pool->block_size * pool->free_index;
    pool->free_index++;
    return block;
}

void deallocate_to_pool(MemoryPool* pool, void* block) {
    size_t index = ((char*)block - (char*)pool->pool) / pool->block_size;
    if (index < pool->free_index && index >= 0) {
        pool->free_index--;
    }
}

int validate_header(const PacketHeader* header) {
    // Implement validation logic here
    return 1; // Return 1 for valid, 0 for invalid
}

PacketHeader* initialize_packet_array(size_t num_packets, MemoryPool* pool) {
    PacketHeader* array = (PacketHeader*)allocate_from_pool(pool);
    if (!array) return NULL;

    for (size_t i = 0; i < num_packets; i++) {
        // Initialize each packet header here
        if (!validate_header(&array[i])) {
            deallocate_to_pool(pool, array);
            return NULL;
        }
    }

    return array;
}

void free_packet_array(PacketHeader* array, MemoryPool* pool) {
    for (size_t i = 0; i < num_packets; i++) {
        // Clean up each packet header here
    }
    deallocate_to_pool(pool, array);
}
