typedef struct {
    UE_CREDENTIAL ue_credential;
    NFAPI_CRC_INDICATION_PDU_T *crc_indication_list;
    int crc_count;
    pthread_mutex_t mutex;
} UE_SESSION;

UE_SESSION *ue_sessions[MAX_UE_SESSIONS];
int session_count = 0;
pthread_mutex_t global_mutex;

void initialize_system() {
    for (int i = 0; i < MAX_UE_SESSIONS; i++) {
        ue_sessions[i] = NULL;
    }
    pthread_mutex_init(&global_mutex, NULL);
}

void add_session(UE_CREDENTIAL *ue_credential) {
    pthread_mutex_lock(&global_mutex);
    if (session_count >= MAX_UE_SESSIONS) {
        printf("Maximum number of sessions reached.\n");
        pthread_mutex_unlock(&global_mutex);
        return;
    }
    UE_SESSION *new_session = (UE_SESSION *)malloc(sizeof(UE_SESSION));
    new_session->ue_credential = *ue_credential;
    new_session->crc_indication_list = NULL;
    new_session->crc_count = 0;
    pthread_mutex_init(&new_session->mutex, NULL);
    ue_sessions[session_count++] = new_session;
    pthread_mutex_unlock(&global_mutex);
}

void remove_session(int RNTI) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < session_count; i++) {
        if (ue_sessions[i]->ue_credential.RNTI == RNTI) {
            free(ue_sessions[i]->crc_indication_list);
            pthread_mutex_destroy(&ue_sessions[i]->mutex);
            free(ue_sessions[i]);
            for (int j = i; j < session_count - 1; j++) {
                ue_sessions[j] = ue_sessions[j + 1];
            }
            session_count--;
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

void update_session(int RNTI, UE_CREDENTIAL *new_credential) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < session_count; i++) {
        if (ue_sessions[i]->ue_credential.RNTI == RNTI) {
            ue_sessions[i]->ue_credential = *new_credential;
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

void add_crc_indication(int RNTI, NFAPI_CRC_INDICATION_PDU_T *crc_indication) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < session_count; i++) {
        if (ue_sessions[i]->ue_credential.RNTI == RNTI) {
            pthread_mutex_lock(&ue_sessions[i]->mutex);
            NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(ue_sessions[i]->crc_indication_list, (ue_sessions[i]->crc_count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_list == NULL) {
                printf("Memory allocation failed.\n");
                pthread_mutex_unlock(&ue_sessions[i]->mutex);
                pthread_mutex_unlock(&global_mutex);
                return;
            }
            ue_sessions[i]->crc_indication_list = new_list;
            ue_sessions[i]->crc_indication_list[ue_sessions[i]->crc_count++] = *crc_indication;
            pthread_mutex_unlock(&ue_sessions[i]->mutex);
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

void remove_crc_indication(int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&global_mutex);
    for (int i = 0; i < session_count; i++) {
        if (ue_sessions[i]->ue_credential.RNTI == RNTI) {
            pthread_mutex_lock(&ue_sessions[i]->mutex);
            for (int j = 0; j < ue_sessions[i]->crc_count; j++) {
                if (ue_sessions[i]->crc_indication_list[j].CRC_INDICATION_REL8_TAG == CRC_INDICATION_REL8_TAG) {
                    for (int k = j; k < ue_sessions[i]->crc_count - 1; k++) {
                        ue_sessions[i]->crc_indication_list[k] = ue_sessions[i]->crc_indication_list[k + 1];
                    }
                    ue_sessions[i]->crc_count--;
                    break;
                }
            }
            pthread_mutex_unlock(&ue_sessions[i]->mutex);
            break;
        }
    }
    pthread_mutex_unlock(&global_mutex);
}

void *session_cleanup_thread(void *arg) {
    while (1) {
        sleep(60); // Check every minute
        pthread_mutex_lock(&global_mutex);
        for (int i = 0; i < session_count; i++) {
            if (is_session_expired(ue_sessions[i])) {
                remove_session(ue_sessions[i]->ue_credential.RNTI);
            }
        }
        pthread_mutex_unlock(&global_mutex);
    }
    return NULL;
}

void start_cleanup_thread() {
    pthread_t thread_id;
    pthread_create(&thread_id, NULL, session_cleanup_thread, NULL);
}

int main() {
    initialize_system();
    start_cleanup_thread();

    // Example usage
    UE_CREDENTIAL ue_credential = {12345, 67890};
    NFAPI_CRC_INDICATION_PDU_T crc_indication = {1, rand() % 2};

    add_session(&ue_credential);
    add_crc_indication(67890, &crc_indication);

    update_session(67890, &ue_credential);
    remove_crc_indication(67890, crc_indication.CRC_INDICATION_REL8_TAG);
    remove_session(67890);

    return 0;
}
