#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_PACKETS 1024
#define DEFAULT_RATE_LIMIT 1000 // packets per second

typedef struct {
    uint32_t ip_src;
    uint32_t ip_dst;
    uint16_t tcp_src_port;
    uint16_t tcp_dst_port;
    uint16_t udp_src_port;
    uint16_t udp_dst_port;
} PacketHeader;

typedef struct {
    PacketHeader *headers;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
    clock_t last_processed_time;
    int packet_size_average;
    int rate_limit;
} PacketArray;

void init_packet_array(PacketArray *array, int initial_capacity) {
    array->headers = (PacketHeader *)malloc(initial_capacity * sizeof(PacketHeader));
    if (!array->headers) {
        perror("Failed to allocate memory for packet headers");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = initial_capacity;
    pthread_mutex_init(&array->lock, NULL);
    array->last_processed_time = clock();
    array->packet_size_average = 0;
    array->rate_limit = DEFAULT_RATE_LIMIT;
}

void free_packet_array(PacketArray *array) {
    pthread_mutex_lock(&array->lock);
    free(array->headers);
    pthread_mutex_unlock(&array->lock);
    pthread_mutex_destroy(&array->lock);
}

int add_packet_header(PacketArray *array, PacketHeader header) {
    pthread_mutex_lock(&array->lock);
    if (array->count >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        PacketHeader *new_headers = (PacketHeader *)realloc(array->headers, new_capacity * sizeof(PacketHeader));
        if (!new_headers) {
            perror("Failed to reallocate memory for packet headers");
            pthread_mutex_unlock(&array->lock);
            return -1;
        }
        array->headers = new_headers;
        array->capacity = new_capacity;
    }
    array->headers[array->count++] = header;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

void process_packets(PacketArray *array) {
    clock_t current_time = clock();
    double elapsed_time = (double)(current_time - array->last_processed_time) / CLOCKS_PER_SEC;
    if (elapsed_time < 1.0 / array->rate_limit) {
        return; // Rate limiting
    }
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->count; ++i) {
        // Process packet header here
        printf("Processing packet: IP src=%u, dst=%u\n", array->headers[i].ip_src, array->headers[i].ip_dst);
    }
    array->last_processed_time = current_time;
    pthread_mutex_unlock(&array->lock);
