#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CONNECTIONS 1000
#define IDLE_TIMEOUT 60

typedef struct {
    int id;
    char ip[16];
    int port;
    time_t last_activity;
} Connection;

typedef struct {
    Connection connections[MAX_CONNECTIONS];
    int count;
    pthread_mutex_t lock;
    pthread_cond_t cond;
} ConnectionManager;

void init_manager(ConnectionManager *manager) {
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    pthread_cond_init(&manager->cond, NULL);
}

int add_connection(ConnectionManager *manager, int id, char *ip, int port) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->connections[i].id == id) {
            pthread_mutex_unlock(&manager->lock);
            return -1; // Duplicate entry
        }
    }
    if (manager->count >= MAX_CONNECTIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -2; // Manager full
    }
    manager->connections[manager->count].id = id;
    strcpy(manager->connections[manager->count].ip, ip);
    manager->connections[manager->count].port = port;
    manager->connections[manager->count].last_activity = time(NULL);
    manager->count++;
    pthread_cond_signal(&manager->cond);
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int remove_connection(ConnectionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->connections[i].id == id) {
            for (int j = i; j < manager->count - 1; j++) {
                manager->connections[j] = manager->connections[j + 1];
            }
            manager->count--;
            pthread_cond_signal(&manager->cond);
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Connection not found
}

Connection *get_connection(ConnectionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; i++) {
        if (manager->connections[i].id == id) {
            manager->connections[i].last_activity = time(NULL);
            pthread_mutex_unlock(&manager->lock);
            return &manager->connections[i];
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void *connection_cleanup(void *arg) {
    ConnectionManager *manager = (ConnectionManager *)arg;
    while (1) {
        pthread_mutex_lock(&manager->lock);
        while (manager->count == 0) {
            pthread_cond_wait(&manager->cond, &manager->lock);
        }
        for (int i = 0; i < manager->count; i++) {
            if (time(NULL) - manager->connections[i].last_activity > IDLE_TIMEOUT) {
                printf("Connection %d timed out and removed\n", manager->connections[i].id);
                for (int j = i; j < manager->count - 1; j++) {
                    manager->connections[j] = manager->connections[j + 1];
                }
                manager->count--;
                pthread_cond_signal(&manager->cond);
            }
        }
        pthread_mutex_unlock(&manager->lock);
    }
}

int main() {
    ConnectionManager manager;
    init_manager(&manager);

    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, connection_cleanup, &manager);

    // Example usage
    add_connection(&manager, 1, "192.168.1.1", 8080);
    Connection *conn = get_connection(&manager, 1);
    if (conn != NULL) {
        printf("Connection ID: %d, IP: %s, Port: %d\n", conn->id, conn->ip, conn->port);
    }

    pthread_join(cleanup_thread, NULL);

    return 0;
}
