} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* initializeLinkedList(int N) {
    if (N <= 0) return NULL;

    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T *head = NULL, *current = NULL;
    int sequenceNumber = 1;

    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T *newNode = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newNode) {
            printf("Memory allocation failed. Initializing with partial data.\n");
            break;
        }

        newNode->RX_UE_INFORMATION_TAG = sequenceNumber++;
        newNode->RNTI = rand() % 1024; // Random RNTI
        newNode->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG (0 or 1)
        newNode->next = NULL;

        if (!head) {
            head = newNode;
            current = newNode;
        } else {
            current->next = newNode;
            current = newNode;
        }
    }

    return head;
}

void printLinkedList(NFAPI_CRC_INDICATION_PDU_T *head) {
    NFAPI_CRC_INDICATION_PDU_T *current = head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
               current->RX_UE_INFORMATION_TAG, current->RNTI, current->CRC_INDICATION_REL8_TAG);
        current = current->next;
    }
}

int main() {
    int N = 10; // Number of nodes in the linked list
    NFAPI_CRC_INDICATION_PDU_T *head = initializeLinkedList(N);
    printLinkedList(head);

    // Free allocated memory
    NFAPI_CRC_INDICATION_PDU_T *current, *next;
    current = head;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }

    return 0;
}
