    pthread_mutex_lock(&manager->pools[pool_index].lock);
    if (find_connection(manager->pools[pool_index], conn.id) == -1) {
        manager->pools[pool_index].connections[manager->pools[pool_index].count++] = conn;
    }
    pthread_mutex_unlock(&manager->pools[pool_index].lock);
    pthread_mutex_unlock(&manager->pool_lock);
}

void remove_connection(ConnectionManager *manager, int id) {
    pthread_mutex_lock(&manager->pool_lock);
    for (int i = 0; i < POOL_SIZE; i++) {
        pthread_mutex_lock(&manager->pools[i].lock);
        int index = find_connection(manager->pools[i], id);
        if (index != -1) {
            manager->pools[i].count--;
            memmove(&manager->pools[i].connections[index], &manager->pools[i].connections[index + 1], sizeof(TCPConnection) * (manager->pools[i].count - index));
            break;
        }
        pthread_mutex_unlock(&manager->pools[i].lock);
    }
    pthread_mutex_unlock(&manager->pool_lock);
}

