typedef enum {
    TCP,
    UDP,
    ICMP
} ProtocolType;

typedef struct NetworkSessionRecord {
    ProtocolType protocol;
    char *source_ip;
    int source_port;
    char *destination_ip;
    int destination_port;
    // Add other fields as needed
} NetworkSessionRecord;

typedef struct MemoryPool {
    size_t block_size;
    size_t num_blocks;
    void **blocks;
    size_t free_index;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool *pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->blocks = (void**)malloc(num_blocks * sizeof(void*));
    for (size_t i = 0; i < num_blocks; ++i) {
        pool->blocks[i] = malloc(block_size);
    }
    pool->free_index = 0;
    return pool;
}

NetworkSessionRecord* allocate_record(MemoryPool *pool) {
    if (pool->free_index == pool->num_blocks) {
        // Handle memory allocation failure
        return NULL;
    }
    NetworkSessionRecord *record = (NetworkSessionRecord*)pool->blocks[pool->free_index];
    ++pool->free_index;
    return record;
}

void deallocate_record(MemoryPool *pool, NetworkSessionRecord *record) {
    size_t index = ((char*)record - (char*)pool->blocks) / pool->block_size;
    if (index >= pool->num_blocks || index < pool->free_index) {
        // Handle invalid deallocation
        return;
    }
    pool->blocks[index] = record;
    --pool->free_index;
}

void free_memory_pool(MemoryPool *pool) {
    for (size_t i = 0; i < pool->num_blocks; ++i) {
        free(pool->blocks[i]);
    }
    free(pool->blocks);
    free(pool);
}
