#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/rand.h>

#define MAX_UEs 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

int populateAndDecrypt(NFAPI_CRC_INDICATION_PDU_T **pduArray, int *numPDUs,
                       const unsigned char *ciphertexts[], const int ciphertextLengths[],
                       const unsigned char *key, const unsigned char *iv,
                       int bufferSize) {
    if (!pduArray || !numPDUs || !ciphertexts || !ciphertextLengths || !key || !iv) {
        return -1; // Invalid input parameters
    }

    *numPDUs = 0;
    *pduArray = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_UEs * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*pduArray) {
        return -2; // Memory allocation failed
    }

    for (int i = 0; i < MAX_UEs && ciphertexts[i]; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &(*pduArray)[i];
        pdu->RX_UE_INFORMATION_TAG = rand() % 1024;
        pdu->RNTI = rand() % 65536;
        pdu->CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Random CRC flag

        EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
        if (!ctx) {
            free(*pduArray);
            return -3; // OpenSSL context creation failed
        }

        if (1 != EVP_DecryptInit_ex(ctx, EVP_aes_128_cbc(), NULL, key, iv)) {
            EVP_CIPHER_CTX_free(ctx);
            continue; // Decryption initialization failed
        }

        unsigned char *plaintext = (unsigned char *)malloc(bufferSize);
        if (!plaintext) {
            EVP_CIPHER_CTX_free(ctx);
            free(*pduArray);
            return -4; // Memory allocation for plaintext failed
        }

        int len, plen;
        if (1 != EVP_DecryptUpdate(ctx, plaintext, &len, ciphertexts[i], ciphertextLengths[i])) {
            free(plaintext);
            EVP_CIPHER_CTX_free(ctx);
            continue; // Decryption update failed
        }
        plen = len;

        if (1 != EVP_DecryptFinal_ex(ctx, plaintext + len, &len)) {
            free(plaintext);
            EVP_CIPHER_CTX_free(ctx);
            continue; // Decryption finalization failed
        }
        plen += len;

        memcpy(pdu->CRC_INDICATION_REL8_TAG, plaintext, plen);
        free(plaintext);
        EVP_CIPHER_CTX_free(ctx);

        (*numPDUs)++;
    }

    return 0; // Success
}
