#include <stdlib.h>
#include <stdint.h>

#define MAX_RNTI_POOL 1000

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *list;
    size_t count;
    size_t capacity;
    uint32_t seed;
    uint16_t rnti_pool[MAX_RNTI_POOL];
    size_t rnti_index;
} NFAPI_CRC_LIST_MANAGER_T;

int nfaapi_crc_list_manager_init(NFAPI_CRC_LIST_MANAGER_T *manager, uint32_t seed) {
    manager->list = NULL;
    manager->count = 0;
    manager->capacity = 0;
    manager->seed = seed;
    manager->rnti_index = 0;

    for (size_t i = 0; i < MAX_RNTI_POOL; ++i) {
        manager->rnti_pool[i] = (uint16_t)(seed + i);
    }

    return 0;
}

int nfaapi_crc_list_manager_add(NFAPI_CRC_LIST_MANAGER_T *manager, uint32_t RX_UE_INFORMATION_TAG) {
    if (manager->count >= MAX_RNTI_POOL) {
        // Reset RNTI pool
        for (size_t i = 0; i < MAX_RNTI_POOL; ++i) {
            manager->rnti_pool[i] = (uint16_t)(manager->seed + i);
        }
        manager->rnti_index = 0;
    }

    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(manager->list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            return -1; // Memory allocation failed
        }
        manager->list = new_list;
        manager->capacity = new_capacity;
    }

    NFAPI_CRC_INDICATION_PDU_T *new_item = &manager->list[manager->count];
    new_item->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_item->RNTI = manager->rnti_pool[manager->rnti_index++];
    new_item->CRC_INDICATION_REL8_TAG = (uint8_t)(new_item->RNTI ^ manager->seed);

    return 0;
}

void nfaapi_crc_list_manager_free(NFAPI_CRC_LIST_MANAGER_T *manager) {
    free(manager->list);
    manager->list = NULL;
    manager->count = 0;
    manager->capacity = 0;
}
