typedef struct {
    int UE_Index;
    int RRC_Connection_ID;
    int Timing_Advancement;
} LTE_Uplink_SchedRequest;

LTE_Uplink_SchedRequest* dynamic_array = NULL;
int array_size = 0;
int max_size = 10; // Initial capacity

void resize_array() {
    max_size *= 2;
    LTE_Uplink_SchedRequest* new_array = realloc(dynamic_array, max_size * sizeof(LTE_Uplink_SchedRequest));
    if (new_array == NULL) {
        // Handle memory allocation failure
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    dynamic_array = new_array;
}

void update_timing_advancement(int index, int offset, int min_value, int max_value) {
    if (index < 0 || index >= array_size) {
        // Handle invalid index
        fprintf(stderr, "Invalid index\n");
        return;
    }

    LTE_Uplink_SchedRequest* request = &dynamic_array[index];
    request->Timing_Advancement += offset;

    // Ensure the updated value stays within the specified range
    if (request->Timing_Advancement < min_value) {
        request->Timing_Advancement = min_value;
    } else if (request->Timing_Advancement > max_value) {
        request->Timing_Advancement = max_value;
    }
}

void add_request(int UE_Index, int RRC_Connection_ID, int Timing_Advancement) {
    if (array_size == max_size) {
        resize_array();
    }

    LTE_Uplink_SchedRequest new_request = {UE_Index, RRC_Connection_ID, Timing_Advancement};
    dynamic_array[array_size++] = new_request;
}

void free_dynamic_array() {
    free(dynamic_array);
}
