int initialize_pool(size_t N) {
    pthread_mutex_lock(&pool.mutex);
    if (N > MAX_STRUCTURES) {
        log_operation("Attempted to initialize pool with too many structures");
        pthread_mutex_unlock(&pool.mutex);
        return -1;
    }
    pool.array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool.array) {
