    if (count > MAX_STRUCTURES) {
        return -1;
    }
    pthread_mutex_lock(&pool.mutex);
    for (size_t i = 0; i < count; ++i) {
        pool.array[pool.count].RX_UE_INFORMATION_TAG = indicators[i].RX_UE_INFORMATION_TAG;
        pool.array[pool.count].RNTI = indicators[i].RNTI;
        pool.array[pool.count].CRC_INDICATION_REL8_TAG = indicators[i].CRC_INDICATION_REL8_TAG;
        pool.array[pool.count].CRCFLAG = rand() % 2; // Randomly generate CRCFLAG
        ++pool.count;
    }
    log_operation("Batch processed N CRC indications");
    pthread_mutex_unlock(&pool.mutex);
    return 0;
}

void free_pool() {
    pthread_mutex_lock(&pool.mutex);
    if (pool.array) {
        free(pool.array);
        pool.array = NULL;
        pool.count = 0;
        log_operation("Pool freed");
    }
    pthread_mutex_unlock(&pool.mutex);
