typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} CustomMemoryPool;

void custom_memory_pool_init(CustomMemoryPool *pool, size_t initial_size) {
    pool->data = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->data) {
        // Handle memory allocation failure
        exit(EXIT_FAILURE);
    }
    pool->allocated_size = initial_size;
    pool->used_size = 0;
    pthread_mutex_init(&pool->lock, NULL);
}

void custom_memory_pool_free(CustomMemoryPool *pool) {
    free(pool->data);
    pthread_mutex_destroy(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T *custom_memory_pool_alloc(CustomMemoryPool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_size >= pool->allocated_size) {
        size_t new_size = pool->allocated_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T *)realloc(pool->data, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            // Handle memory allocation failure
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        pool->data = new_data;
        pool->allocated_size = new_size;
    }
    NFAPI_CRC_INDICATION_PDU_T *result = &pool->data[pool->used_size++];
    pthread_mutex_unlock(&pool->lock);
    return result;
}

void generate_crc_indication_pdus(CustomMemoryPool *pool, int N, unsigned int seed, int max_rnti) {
    srand(seed);
    for (int i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = custom_memory_pool_alloc(pool);
        if (!pdu) {
            // Handle allocation failure
            continue;
        }
        pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag generation
        int rnti;
        do {
            rnti = rand() % (max_rnti + 1);
        } while (is_rnti_used(rnti)); // Assume is_rnti_used checks if RNTI is already used
        pdu->RNTI = rnti;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
    }
}

void serialize_pdus_to_file(NFAPI_CRC_INDICATION_PDU_T *pdus, size_t count, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        // Handle file opening failure
        return;
    }
    size_t written = fwrite(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    if (written != count) {
        // Handle partial write
    }
    fclose(file);
}

void *generate_crc_indication_pdus_thread(void *arg) {
    CustomMemoryPool *pool = (CustomMemoryPool *)arg;
    int N = 100; // Example number of structures
    unsigned int seed = time(NULL);
    int max_rnti = 4095; // Example maximum RNTI value
    generate_crc_indication_pdus(pool, N, seed, max_rnti);
    return NULL;
}

int main() {
