#include <stdlib.h>
#include <string.h>

#define MAX_RNTI_POOL_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    int next_rnti;
} NFAPI_CRC_INDICATION_POOL_T;

int nfapi_crc_indication_pool_init(NFAPI_CRC_INDICATION_POOL_T *pool, size_t initial_size) {
    if (initial_size > MAX_RNTI_POOL_SIZE) return -1; // Error: Initial size exceeds maximum allowed
    pool->pool = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) return -2; // Error: Memory allocation failed
    pool->pool_size = initial_size;
    pool->used_count = 0;
    pool->next_rnti = 0;
    return 0; // Success
}

int nfapi_crc_indication_pool_add(NFAPI_CRC_INDICATION_POOL_T *pool, int rx_tag, int seed) {
    if (pool->used_count >= pool->pool_size) {
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(pool->pool, 2 * pool->pool_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) return -3; // Error: Memory reallocation failed
        pool->pool = new_pool;
        pool->pool_size *= 2;
    }
    int rnti = (seed + pool->next_rnti++) % MAX_RNTI_POOL_SIZE;
    while (rnti < pool->used_count && pool->pool[rnti].RNTI != -1) {
        rnti = (rnti + 1) % MAX_RNTI_POOL_SIZE;
    }
    if (rnti >= pool->used_count) return -4; // Error: RNTI pool exhausted
    pool->pool[rnti].RX_UE_INFORMATION_TAG = rx_tag;
    pool->pool[rnti].RNTI = rnti;
    pool->pool[rnti].CRC_INDICATION_REL8_TAG = (seed + rnti) % 2; // Example CRCFLAG calculation
    pool->used_count++;
    return 0; // Success
}

void nfapi_crc_indication_pool_reset(NFAPI_CRC_INDICATION_POOL_T *pool) {
    for (size_t i = 0; i < pool->used_count; i++) {
        pool->pool[i].RNTI = -1;
    }
    pool->next_rnti = 0;
}

void nfapi_crc_indication_pool_free(NFAPI_CRC_INDICATION_POOL_T *pool) {
    free(pool->pool);
    pool->pool = NULL;
    pool->pool_size = 0;
    pool->used_count = 0;
}
