        size_t new_capacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        LogEntry **new_entries = (LogEntry**)realloc(collection->entries, new_capacity * sizeof(LogEntry*));
        if (!new_entries) return -1;
        collection->entries = new_entries;
        collection->capacity = new_capacity;
    }

    LogEntry *entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!entry) return -1;
    entry->id = id;
    entry->timestamp = time(NULL);
    entry->message = strdup(message);
    if (!entry->message) {
        free(entry);
        return -1;
    }

    collection->entries[collection->count++] = entry;
    return 0;
}

void print_log_collection(LogCollection *collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        printf("ID: %d, Timestamp: %s, Message: %s\n", 
               collection->entries[i]->id, 
               ctime(&collection->entries[i]->timestamp), 
               collection->entries[i]->message);
    }
}

int main() {
    LogCollection *log_collection = create_log_collection();

    add_log_entry(log_collection, 1, "Network connection established");
    add_log_entry(log_collection, 2, "Error: Failed to connect to database");

    print_log_collection(log_collection);

    destroy_log_collection(log_collection);

    return 0;
}
