#include <stdlib.h>
#include <pthread.h>
#include <stdint.h>
#include <string.h>

#define NFAPI_CRC_INDICATION_PDU_T struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} __attribute__((aligned(64)));

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} NFAPI_CRC_POOL;

NFAPI_CRC_POOL* create_crc_pool(size_t initial_size) {
    NFAPI_CRC_POOL *pool = (NFAPI_CRC_POOL*)malloc(sizeof(NFAPI_CRC_POOL));
    if (!pool) return NULL;

    pool->pool = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        free(pool);
        return NULL;
    }

    pool->pool_size = initial_size;
    pool->used_count = 0;
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_crc(NFAPI_CRC_POOL *pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->used_count >= pool->pool_size) {
        size_t new_size = pool->pool_size * 2;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = (NFAPI_CRC_INDICATION_PDU_T*)aligned_alloc(64, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_pool) {
            pthread_mutex_unlock(&pool->lock);
            return NULL;
        }
        memcpy(new_pool, pool->pool, pool->used_count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(pool->pool);
        pool->pool = new_pool;
        pool->pool_size = new_size;
    }

    NFAPI_CRC_INDICATION_PDU_T *result = &pool->pool[pool->used_count++];
    pthread_mutex_unlock(&pool->lock);

    // Initialize with pseudo-random data
    result->RX_UE_INFORMATION_TAG = rand();
    result->RNTI = (uint16_t)rand();
    result->CRC_INDICATION_REL8_TAG = (uint8_t)(rand() % 2); // Simplified CRC flag

    return result;
}

void free_crc_pool(NFAPI_CRC_POOL *pool) {
    pthread_mutex_lock(&pool->lock);
    free(pool->pool);
    pthread_mutex_unlock(&pool->lock);
    free(pool);
}
