#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    void* memory;
    size_t block_size;
    size_t num_blocks;
    size_t free_index;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool* create_memory_pool(size_t block_size, size_t num_blocks) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    pool->memory = malloc(block_size * num_blocks);
    pool->block_size = block_size;
    pool->num_blocks = num_blocks;
    pool->free_index = 0;
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

void* allocate_from_pool(MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->free_index >= pool->num_blocks) {
        pthread_mutex_unlock(&pool->lock);
        return NULL; // Pool is full
    }
    void* block = (char*)pool->memory + pool->block_size * pool->free_index;
    pool->free_index++;
    pthread_mutex_unlock(&pool->lock);
    return block;
}

void deallocate_to_pool(MemoryPool* pool, void* block) {
    pthread_mutex_lock(&pool->lock);
    size_t index = ((char*)block - (char*)pool->memory) / pool->block_size;
    if (index < pool->free_index && index >= 0) {
        pool->free_index--;
    }
    pthread_mutex_unlock(&pool->lock);
}

NFAPI_CRC_INDICATION_PDU_T* generate_crc_indication_pdu(MemoryPool* pool, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)allocate_from_pool(pool);
    if (pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pdu->RNTI = RNTI;
        pdu->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
    return pdu;
}

void destroy_memory_pool(MemoryPool* pool) {
    pthread_mutex_destroy(&pool->lock);
    free(pool->memory);
    free(pool);
}
