#define MAX_MAC_PDUS 1000

typedef struct {
    uint8_t SAP_ID;
    uint16_t Sequence_Number;
} MAC_Header;

typedef struct {
    char* Payload;
    size_t Length;
} MAC_Payload;

typedef struct {
    MAC_Header Header;
    MAC_Payload Payload;
} MAC_PDU;

pthread_mutex_t pdu_mutex = PTHREAD_MUTEX_INITIALIZER;
int total_pdus_created = 0;
size_t total_payload_length = 0;

void generate_random_string(char* buffer, size_t length) {
    static const char charset[] = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
    for (size_t i = 0; i < length; ++i) {
        buffer[i] = charset[rand() % sizeof(charset)];
    }
    buffer[length] = '\0';
}

void initialize_mac_pdu_list(MAC_PDU* pdu_list, int num_elements) {
    pthread_mutex_lock(&pdu_mutex);
    for (int i = 0; i < num_elements; ++i) {
        pdu_list[i].Header.SAP_ID = rand() % 256;
        pdu_list[i].Header.Sequence_Number = i + 1;
        generate_random_string(pdu_list[i].Payload.Payload, 100); // Example payload length
        pdu_list[i].Payload.Length = strlen(pdu_list[i].Payload.Payload);
        total_payload_length += pdu_list[i].Payload.Length;
    }
    total_pdus_created += num_elements;
    pthread_mutex_unlock(&pdu_mutex);

    double average_payload_length = (double)total_payload_length / total_pdus_created;
    printf("Total PDUs Created: %d\n", total_pdus_created);
    printf("Average Payload Length: %.2f\n", average_payload_length);
}

int main() {
    srand(time(NULL));
    MAC_PDU pdu_list[MAX_MAC_PDUS];
    int num_elements = 500; // Example number of elements

    clock_t start_time = clock();
    initialize_mac_pdu_list(pdu_list, num_elements);
    clock_t end_time = clock();

    double execution_time = (double)(end_time - start_time) / CLOCKS_PER_SEC;
    printf("Execution Time: %.2f ms\n", execution_time * 1000);

    return 0;
}
