#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>
#include <pthread.h>

#define MAX_LOG_SIZE 1024 * 1024 // 1MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_memory(int N) {
    if (N <= 0) {
        fprintf(stderr, "Invalid number of elements\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        array[i].RNTI = rand() % 1000;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return array;
}

void configure_logging(const char* log_dir) {
    struct stat st = {0};
    if (stat(log_dir, &st) == -1) {
        mkdir(log_dir, 0755);
    }

    FILE* log_file = fopen("log.txt", "w");
    if (!log_file) {
        perror("Failed to open log file");
        return;
    }
    fclose(log_file);
}

void thread_safe_logging(const char* message) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    FILE* log_file = fopen("log.txt", "a");
    if (log_file) {
        fprintf(log_file, "%s\n", message);
        fclose(log_file);
    }

    pthread_mutex_unlock(&mutex);
}

void cache_memory(NFAPI_CRC_INDICATION_PDU_T** cache, int N) {
    static NFAPI_CRC_INDICATION_PDU_T* cached_array = NULL;
    if (cached_array) {
        free(cached_array);
    }
    cached_array = allocate_memory(N);
