    Node* newNode = createNode(data);
    if (newNode == NULL) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&list->lock);
        return;
    }
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
