#include <stdlib.h>
#include <pthread.h>

#define INITIAL_CAPACITY 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_STATUS;
} NFAPI_RX_FRAME_INFO;

typedef struct {
    NFAPI_RX_FRAME_INFO *frames;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} FrameBuffer;

FrameBuffer* create_frame_buffer() {
    FrameBuffer *buffer = (FrameBuffer*)malloc(sizeof(FrameBuffer));
    if (!buffer) return NULL;

    buffer->capacity = INITIAL_CAPACITY;
    buffer->size = 0;
    buffer->frames = (NFAPI_RX_FRAME_INFO*)calloc(buffer->capacity, sizeof(NFAPI_RX_FRAME_INFO));
    if (!buffer->frames) {
        free(buffer);
        return NULL;
    }

    pthread_mutex_init(&buffer->mutex, NULL);

    return buffer;
}

void destroy_frame_buffer(FrameBuffer *buffer) {
    if (buffer) {
        pthread_mutex_lock(&buffer->mutex);
        free(buffer->frames);
        pthread_mutex_unlock(&buffer->mutex);
        pthread_mutex_destroy(&buffer->mutex);
        free(buffer);
    }
}

int add_frame(FrameBuffer *buffer, NFAPI_RX_FRAME_INFO frame) {
    pthread_mutex_lock(&buffer->mutex);

    if (buffer->size >= buffer->capacity) {
        size_t new_capacity = buffer->capacity * 2;
        NFAPI_RX_FRAME_INFO *new_frames = (NFAPI_RX_FRAME_INFO*)realloc(buffer->frames, new_capacity * sizeof(NFAPI_RX_FRAME_INFO));
        if (!new_frames) {
            pthread_mutex_unlock(&buffer->mutex);
            return -1; // Memory allocation failed
        }
        buffer->frames = new_frames;
        buffer->capacity = new_capacity;
    }

    buffer->frames[buffer->size++] = frame;

    pthread_mutex_unlock(&buffer->mutex);

    return 0;
}

void reset_frame_buffer(FrameBuffer *buffer) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->size = 0;
    pthread_mutex_unlock(&buffer->mutex);
}
