#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int UserID;
    int SessionID;
    double DataTransferRate;
    HTTP_REQUEST_T request;
    HTTP_RESPONSE_T response;
} UserSession;

typedef struct {
    UserSession *sessions;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} UserSessionManager;

UserSessionManager* create_user_session_manager(size_t initial_capacity) {
    UserSessionManager *manager = (UserSessionManager*)malloc(sizeof(UserSessionManager));
    manager->sessions = (UserSession*)calloc(initial_capacity, sizeof(UserSession));
    manager->capacity = initial_capacity;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_user_session_manager(UserSessionManager *manager) {
    free(manager->sessions);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_user_session(UserSessionManager *manager, UserSession session) {
    pthread_mutex_lock(&manager->lock);
    if (manager->size >= manager->capacity) {
        manager->capacity *= 2;
        manager->sessions = realloc(manager->sessions, manager->capacity * sizeof(UserSession));
    }
    manager->sessions[manager->size++] = session;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

int update_user_session(UserSessionManager *manager, int UserID, UserSession new_session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].UserID == UserID) {
            manager->sessions[i] = new_session;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1;
}

UserSession* get_user_session(UserSessionManager *manager, int UserID) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->sessions[i].UserID == UserID) {
            UserSession *session = &manager->sessions[i];
            pthread_mutex_unlock(&manager->lock);
            return session;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

// Additional functions for load balancing, union-find, resource monitoring, and unit tests would be implemented here.
