#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>

#define MAX_SESSIONS 1000000

typedef struct {
    char id[32];
    char ip[16];
    time_t last_activity;
} Session;

typedef struct {
    Session sessions[MAX_SESSIONS];
    pthread_mutex_t lock;
    int next_id;
} SessionManager;

SessionManager* init_session_manager() {
    SessionManager *manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->next_id = 0;
    pthread_mutex_init(&manager->lock, NULL);

    for (int i = 0; i < MAX_SESSIONS; i++) {
        memset(&manager->sessions[i], 0, sizeof(Session));
    }

    return manager;
}

void destroy_session_manager(SessionManager *manager) {
    if (!manager) return;

    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int create_session(SessionManager *manager, const char *ip) {
    pthread_mutex_lock(&manager->lock);

    int id = manager->next_id++;
    if (id >= MAX_SESSIONS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Max sessions reached
    }

    Session *session = &manager->sessions[id];
    snprintf(session->id, sizeof(session->id), "%d", id);
    strncpy(session->ip, ip, sizeof(session->ip));
    session->last_activity = time(NULL);

    pthread_mutex_unlock(&manager->lock);
    return id;
}

void update_session(SessionManager *manager, int id) {
    pthread_mutex_lock(&manager->lock);

    if (id >= 0 && id < MAX_SESSIONS) {
        manager->sessions[id].last_activity = time(NULL);
    }

    pthread_mutex_unlock(&manager->lock);
}

void purge_inactive_sessions(SessionManager *manager, time_t timeout) {
    pthread_mutex_lock(&manager->lock);

    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (time(NULL) - manager->sessions[i].last_activity > timeout) {
            memset(&manager->sessions[i], 0, sizeof(Session));
        }
    }

    pthread_mutex_unlock(&manager->lock);
}
