int populateNFAPCRCIndication(int N, int seed) {
    if (N <= 0 || N > 1000) {
        printf("Error: Invalid number of structures. Must be between 1 and 1000.\n");
        return -1;
    }

    NFAPI_CRC_INDICATION_PDU_T *array = (NFAPI_CRC_INDICATION_PDU_T *)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        printf("Error: Memory allocation failed.\n");
        return -2;
    }

    srand(seed);
    int rnti_set[65536] = {0};
    int unique_rntis = 0;

    for (int i = 0; i < N; i++) {
        while (1) {
            int rnti = rand() % 65536;
            if (rnti_set[rnti] == 0) {
                array[i].RNTI = rnti;
                rnti_set[rnti] = 1;
                unique_rntis++;
                break;
            }
        }

        array[i].RX_UE_INFORMATION_TAG = i + 1;
        array[i].CRC_INDICATION_REL8_TAG = rand() % 256;
        array[i].CRCFLAG = rand() % 2; // Non-standard random number generator for CRCFLAG
    }

    printf("Successfully populated NFAPI_CRC_INDICATION_PDU_T array with %d unique RNTIs.\n", unique_rntis);

    free(array);
    return 0;
}
