#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_TRANSACTIONS 20000

typedef struct {
    int id;
    time_t timestamp;
    double weight;
    int priority;
} Transaction;

typedef struct {
    Transaction transactions[MAX_TRANSACTIONS];
    int count;
    pthread_mutex_t lock;
} TransactionQueue;

TransactionQueue transaction_queue;

void init_transaction_queue() {
    pthread_mutex_init(&transaction_queue.lock, NULL);
    transaction_queue.count = 0;
}

void enqueue_transaction(Transaction transaction) {
    pthread_mutex_lock(&transaction_queue.lock);
    if (transaction_queue.count < MAX_TRANSACTIONS) {
        transaction_queue.transactions[transaction_queue.count++] = transaction;
    }
    pthread_mutex_unlock(&transaction_queue.lock);
}

Transaction dequeue_transaction() {
    Transaction transaction;
    pthread_mutex_lock(&transaction_queue.lock);
    if (transaction_queue.count > 0) {
        transaction = transaction_queue.transactions[--transaction_queue.count];
    } else {
        // Handle empty queue
        transaction.id = -1;
        transaction.timestamp = 0;
        transaction.weight = 0;
        transaction.priority = 0;
    }
    pthread_mutex_unlock(&transaction_queue.lock);
    return transaction;
}

void* process_transactions(void* arg) {
    while (1) {
        Transaction transaction = dequeue_transaction();
        if (transaction.id == -1) {
            break; // Exit thread
        }
        // Process the transaction
        printf("Processing transaction %d\n", transaction.id);
    }
    return NULL;
}

int main() {
    init_transaction_queue();

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, process_transactions, NULL);
    }

    // Simulate transaction processing
    for (int i = 0; i < MAX_TRANSACTIONS; i++) {
        Transaction transaction;
        transaction.id = i;
        transaction.timestamp = time(NULL);
        transaction.weight = rand() % 100;
        transaction.priority = rand() % 5;
        enqueue_transaction(transaction);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
