typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[EVP_MAX_BLOCK_LENGTH];
} CipherContext;

CipherContext* create_cipher_context() {
    CipherContext *ctx = (CipherContext*)malloc(sizeof(CipherContext));
    ctx->ctx = EVP_CIPHER_CTX_new();
    return ctx;
}

void destroy_cipher_context(CipherContext *ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int init_cipher_context(CipherContext *ctx, const unsigned char *key, int key_len, const unsigned char *iv) {
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, iv)) {
        return -1;
    }
    return 0;
}

int encrypt_data(CipherContext *ctx, const unsigned char *plaintext, int plaintext_len, unsigned char *ciphertext) {
    int len;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        return -1;
    }
    int ciphertext_len = len;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + len, &len)) {
        return -1;
    }
    ciphertext_len += len;
    return ciphertext_len;
}

int decrypt_data(CipherContext *ctx, const unsigned char *ciphertext, int ciphertext_len, unsigned char *plaintext) {
    int len;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        return -1;
    }
    int plaintext_len = len;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + len, &len)) {
        return -1;
    }
    plaintext_len += len;
    return plaintext_len;
}

int generate_iv(unsigned char *iv) {
    if (!RAND_bytes(iv, EVP_MAX_BLOCK_LENGTH)) {
        return -1;
    }
    return 0;
}
