int move_files_by_type(int user_id, const char *source_path, const char *target_path, const char *file_extension) {
    DIR *dir;
    struct dirent *entry;
    int retries = 0;

    if (mkdir(target_path, 0755) != 0 && errno != EEXIST) {
        perror("Failed to create target directory");
        return -1;
    }

    while ((dir = opendir(source_path)) == NULL && retries < MAX_RETRIES) {
        perror("Failed to open source directory");
        usleep(RETRY_DELAY * 1000);
        retries++;
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "Max retries reached for opening source directory\n");
        return -1;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char full_path[256];
        snprintf(full_path, sizeof(full_path), "%s/%s", source_path, entry->d_name);

        struct stat file_stat;
        if (stat(full_path, &file_stat) != 0) {
            perror("Failed to get file stats");
            continue;
        }

        if (S_ISREG(file_stat.st_mode) && strstr(entry->d_name, file_extension)) {
            int fd = open(full_path, O_RDONLY);
            if (fd == -1) {
                perror("Failed to open file for locking");
                continue;
            }

            struct flock lock;
            memset(&lock, 0, sizeof(lock));
            lock.l_type = F_WRLCK;
            lock.l_whence = SEEK_SET;

            retries = 0;
            while (fcntl(fd, F_SETLK, &lock) == -1 && errno == EAGAIN && retries < MAX_RETRIES) {
                perror("Failed to lock file");
                usleep(RETRY_DELAY * 1000);
                retries++;
            }

            if (retries >= MAX_RETRIES) {
                fprintf(stderr, "Max retries reached for locking file\n");
                close(fd);
                continue;
            }

            char target_full_path[256];
            snprintf(target_full_path, sizeof(target_full_path), "%s/%s", target_path, entry->d_name);

            if (rename(full_path, target_full_path) != 0) {
                perror("Failed to move file");
                fcntl(fd, F_UNLCK, &lock);
                close(fd);
                continue;
            }

            fcntl(fd, F_UNLCK, &lock);
            close(fd);
        }
    }

    closedir(dir);
    return 0;
}
