#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_MESSAGES 10000

typedef struct {
    int SEQUENCE_NUMBER;
    float TRANSMISSION_POWER;
    char MODULATION_SCHEME[20];
} PHY_FRAME_PARAMETERS;

typedef struct {
    // Define fields for PHY_MESSAGE_HEADER
} PHY_MESSAGE_HEADER;

typedef struct {
    // Define fields for PHY_LAYER_INFORMATION
} PHY_LAYER_INFORMATION;

typedef struct PHY_MESSAGE {
    PHY_MESSAGE_HEADER header;
    PHY_LAYER_INFORMATION layer_info;
    PHY_FRAME_PARAMETERS frame_params;
    struct PHY_MESSAGE *next;
} PHY_MESSAGE;

typedef struct {
    PHY_MESSAGE *head;
    pthread_mutex_t lock;
} PHY_LIST;

PHY_LIST* create_list() {
    PHY_LIST *list = (PHY_LIST*)malloc(sizeof(PHY_LIST));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_list(PHY_LIST *list) {
    pthread_mutex_lock(&list->lock);
    PHY_MESSAGE *current = list->head;
    while (current) {
        PHY_MESSAGE *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_unlock(&list->lock);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_message(PHY_LIST *list, PHY_FRAME_PARAMETERS params) {
    pthread_mutex_lock(&list->lock);
    PHY_MESSAGE *new_msg = (PHY_MESSAGE*)malloc(sizeof(PHY_MESSAGE));
    if (!new_msg) {
        pthread_mutex_unlock(&list->lock);
        return -1; // Memory allocation failed
    }
    new_msg->frame_params = params;
    new_msg->next = list->head;
    list->head = new_msg;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int remove_message(PHY_LIST *list, int sequence_number) {
    pthread_mutex_lock(&list->lock);
    PHY_MESSAGE *current = list->head;
    PHY_MESSAGE *prev = NULL;
    while (current) {
        if (current->frame_params.SEQUENCE_NUMBER == sequence_number) {
            if (prev) prev->next = current->next;
            else list->head = current->next;
            free(current);
            pthread_mutex_unlock(&list->lock);
            return 0; // Message removed successfully
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return -1; // Message not found
}

PHY_MESSAGE* query_message(PHY_LIST *list, int sequence_number) {
    pthread_mutex_lock(&list->lock);
    PHY_MESSAGE *current = list->head;
    while (current) {
        if (current->frame_params.SEQUENCE_NUMBER == sequence_number) {
            pthread_mutex_unlock(&list->lock);
            return current; // Message found
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return NULL; // Message not found
}

void clear_list(PHY_LIST *list) {
    pthread_mutex_lock(&list->lock);
    PHY_MESSAGE *current = list->head;
    while (current) {
        PHY_MESSAGE *next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    pthread_mutex_unlock(&list->lock);
}

int main() {
    PHY_LIST *list = create_list();
    if (!list) return 1;

    // Example usage
    PHY_FRAME_PARAMETERS params = { /* Initialize parameters */ };
    add_message(list, params);

    PHY_MESSAGE *msg = query_message(list, 12345);
    if (msg) {
        printf("Found message with sequence number %d\n", msg->frame_params.SEQUENCE_NUMBER);
    }

    remove_message(list, 12345);

    clear_list(list);
    destroy_list(list);

    return 0;
}
