NFAPI_CRC_INDICATION_PDU_T* generate_crc_indications(int num_ues) {
    if (num_ues <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ues * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        // Handle memory allocation failure
        return NULL;
    }

    int rnti_set[num_ues];
    for (int i = 0; i < num_ues; ++i) {
        do {
            array[i].RNTI = rand() % 65536; // Assuming RNTI is a 16-bit unsigned integer
        } while (is_rnti_used(array, i, rnti_set));
        rnti_set[i] = array[i].RNTI;

        array[i].RX_UE_INFORMATION_TAG = rand() % 1024; // Assuming RX_UE_INFORMATION_TAG is a 10-bit unsigned integer
        array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        time_t current_time;
        if (time(&current_time) == -1) {
            // Handle error in getting current time
            free(array);
            return NULL;
        }
        array[i].CRC_INDICATION_REL8_TAG.timestamp = current_time;

        // Simulate fetching UE information from an external data source
        if (!fetch_ue_info(array[i])) {
            // Handle failure to fetch UE info
            free(array);
            return NULL;
        }
    }

    return array;
}

int is_rnti_used(NFAPI_CRC_INDICATION_PDU_T* array, int index, int* rnti_set) {
    for (int i = 0; i < index; ++i) {
        if (array[i].RNTI == rnti_set[index]) return 1;
    }
    return 0;
}

int fetch_ue_info(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simulate fetching UE info with varying response times and reliability
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        return 0; // Handle error in getting current time
    }
    // Simulate delay based on the RNTI value
    int delay = pdu->RNTI % 1000;
    struct timespec req = {delay / 1000, (delay % 1000) * 1000000};
    if (nanosleep(&req, NULL) == -1) {
        return 0; // Handle error in nanosleep
    }
    return 1;
}
