#include <stdlib.h>
#include <time.h>

typedef struct {
    int tag;
    int sequenceNumber;
    time_t expirationTimestamp;
} TX_MESSAGE;

typedef struct Node {
    TX_MESSAGE data;
    struct Node* next;
} NODE;

typedef struct {
    NODE* head;
    size_t count;
} MESSAGE_LIST;

void initMessageList(MESSAGE_LIST* list) {
    list->head = NULL;
    list->count = 0;
}

void addMessage(MESSAGE_LIST* list, TX_MESSAGE message) {
    NODE* newNode = (NODE*)malloc(sizeof(NODE));
    newNode->data = message;
    newNode->next = list->head;
    list->head = newNode;
    list->count++;
}

void removeExpiredMessages(MESSAGE_LIST* list) {
    time_t now = time(NULL);
    NODE** current = &list->head;
    while (*current != NULL) {
        if ((*current)->data.expirationTimestamp < now) {
            NODE* temp = *current;
            *current = (*current)->next;
            free(temp);
            list->count--;
        } else {
            current = &(*current)->next;
        }
    }
}

void updateMessagePriority(MESSAGE_LIST* list, int tag, int newSequenceNumber) {
    NODE* current = list->head;
    while (current != NULL) {
        if (current->data.tag == tag) {
            current->data.sequenceNumber = newSequenceNumber;
            break;
        }
        current = current->next;
    }
}

void freeMessageList(MESSAGE_LIST* list) {
    NODE* current = list->head;
    while (current != NULL) {
        NODE* temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->count = 0;
}
