#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 10000
#define RESIZE_THRESHOLD 75

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} DynamicArray;

void initDynamicArray(DynamicArray *array) {
    array->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(MAX_ELEMENTS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->elements) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array->count = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);
    pthread_cond_init(&array->cond, NULL);
}

void destroyDynamicArray(DynamicArray *array) {
    free(array->elements);
    pthread_mutex_destroy(&array->mutex);
    pthread_cond_destroy(&array->cond);
}

int addElement(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        size_t newCapacity = array->capacity * 2;
        if (newCapacity > MAX_ELEMENTS) {
            fprintf(stderr, "Array capacity exceeded\n");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        NFAPI_CRC_INDICATION_PDU_T *newElements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(array->elements, newCapacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!newElements) {
            fprintf(stderr, "Memory reallocation failed\n");
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->elements = newElements;
        array->capacity = newCapacity;
    }
    array->elements[array->count++] = element;
    pthread_cond_signal(&array->cond);
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int removeElementByIndex(DynamicArray *array, size_t index) {
    pthread_mutex_lock(&array->mutex);
    if (index >= array->count) {
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    for (size_t i = index; i < array->count - 1; ++i) {
        array->elements[i] = array->elements[i + 1];
    }
    --array->count;
    pthread_cond_signal(&array->cond);
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int removeElementByRNTI(DynamicArray *array, int RNTI) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->elements[i].RNTI == RNTI) {
            removeElementByIndex(array, i);
            break;
        }
    }
    pthread_cond_signal(&array->cond);
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void clearDynamicArray(DynamicArray *array) {
    pthread_mutex_lock(&array->mutex);
    array->count = 0;
    pthread_cond_signal(&array->cond);
    pthread_mutex_unlock(&array->mutex);
}

void iterateDynamicArray(DynamicArray *array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        callback(&array->elements[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}

void logArrayChange(DynamicArray *array, const char *action, size_t index, int RNTI) {
    time_t now = time(NULL);
    printf("[%ld] %s at index %zu with RNTI %d\n", now, action, index, RNTI);
}
