    for (size_t i = index; i < da->size - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }

    --da->size;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void dynamic_array_iterate(DynamicArray *da, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    if (!callback) return;

    pthread_mutex_lock(&da->mutex);

    for (size_t i = 0; i < da->size; ++i) {
        callback(da->array[i]);
    }

    pthread_mutex_unlock(&da->mutex);
}
