#define MAX_MAC_PDU 1000

typedef struct {
    unsigned char src_addr[6];
    unsigned char dst_addr[6];
    unsigned short type;
} MAC_HEADER;

typedef struct {
    unsigned char data[256];
    size_t length;
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
} MAC_PDU;

void generate_random_mac_address(unsigned char *mac) {
    srand(time(NULL));
    for (int i = 0; i < 6; i++) {
        mac[i] = rand() % 256;
    }
}

void initialize_mac_pdu(MAC_PDU *pdu) {
    generate_random_mac_address(pdu->header.src_addr);
    generate_random_mac_address(pdu->header.dst_addr);
    pdu->header.type = (unsigned short)(rand() % 0xFFFF);
    for (int i = 0; i < sizeof(pdu->payload.data); i++) {
        pdu->payload.data[i] = rand() % 256;
    }
    pdu->payload.length = sizeof(pdu->payload.data);
}

MAC_PDU* create_mac_pdu_array(size_t size) {
    if (size > MAX_MAC_PDU) {
        fprintf(stderr, "Error: Requested size exceeds maximum allowed.\n");
        return NULL;
    }

    MAC_PDU *array = (MAC_PDU *)malloc(size * sizeof(MAC_PDU));
    if (!array) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < size; i++) {
        initialize_mac_pdu(&array[i]);
    }

    return array;
}

void free_mac_pdu_array(MAC_PDU *array, size_t size) {
