void process_media_packets(PacketProcessor *processor) {
    time_t current_time = time(NULL);
    for (size_t i = 0; i < processor->count; ++i) {
        MEDIA_PACKET_T packet = processor->packets[i];
        if (packet.checksum != calculate_checksum(packet.payload, sizeof(packet.payload)) ||
            abs(difftime(current_time, packet.timestamp)) > 5) {
            processor->invalid_packet_count.fetch_add(1);
            continue;
        }
        // Process valid packet
    }

    if (processor->invalid_packet_count.load() > INVALID_PACKET_THRESHOLD) {
        log_alert("High rate of invalid packets detected");
    }
}

uint16_t calculate_checksum(const uint8_t *data, size_t length) {
    uint16_t checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += data[i];
    }
    return checksum;
}

