NFAPI_CRC_INDICATION_PDU_T* create_node(int index, unsigned long seed) {
    NFAPI_CRC_INDICATION_PDU_T* node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    node->RX_UE_INFORMATION_TAG = index;
    node->RNTI = seed % 65536; // Assuming RNTI is a 16-bit value
    node->CRCFLAG = (index + time(NULL)) % 2 == 0;
    node->next = NULL;
    return node;
}

NFAPI_CRC_INDICATION_PDU_T* create_linked_list(int N, unsigned long seed) {
    if (N > MAX_NODES) {
        fprintf(stderr, "Error: Maximum number of nodes exceeded\n");
        return NULL;
    }
    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T* head = create_node(0, seed);
    if (head == NULL) {
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* current = head;
    for (int i = 1; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* new_node = create_node(i, seed);
        if (new_node == NULL) {
            free_list(head);
            return NULL;
        }
        current->next = new_node;
        current = new_node;
    }
    return head;
}

void free_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp;
    while (head != NULL) {
        temp = head;
        head = head->next;
        free(temp);
    }
}

int main() {
    unsigned long seed = time(NULL);
    NFAPI_CRC_INDICATION_PDU_T* list = create_linked_list(5, seed);
    if (list != NULL) {
        // Traverse and use the linked list
        free_list(list);
    }
    return 0;
}
