NFAPI_CRC_INDICATION_PDU_T* allocate_and_initialize_array(size_t size) {
    if (size == 0) {
        fprintf(stderr, "Error: Size must be greater than zero.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        array[i].tag = RX_UE_INFORMATION_TAG;
        array[i].rnti = RNTI;
        array[i].crcflag = rand() % 256; // Randomly set CRCFLAG
    }

    return array;
}

void serialize_to_file(const NFAPI_CRC_INDICATION_PDU_T* array, size_t size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) {
        perror("Failed to open file for writing");
        return;
    }

    if (fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), size, file) != size) {
        perror("Error writing to file");
    }

    fclose(file);
}

int deserialize_from_file(NFAPI_CRC_INDICATION_PDU_T** array, size_t* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        perror("Failed to open file for reading");
        return -1;
    }

    fseek(file, 0, SEEK_END);
    *size = ftell(file) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    fseek(file, 0, SEEK_SET);

    *array = realloc(*array, *size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*array) {
        perror("Failed to reallocate memory");
        fclose(file);
        return -1;
    }

    if (fread(*array, sizeof(NFAPI_CRC_INDICATION_PDU_T), *size, file) != *size) {
        perror("Error reading from file");
        free(*array);
        *array = NULL;
        fclose(file);
        return -1;
    }

    fclose(file);
    return 0;
}

int main() {
    size_t size = 1000; // Example size
    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_initialize_array(size);

    if (array) {
        serialize_to_file(array, size, "crc_data.bin");

        NFAPI_CRC_INDICATION_PDU_T* deserialized_array = NULL;
        size_t deserialized_size;

        if (deserialize_from_file(&deserialized_array, &deserialized_size, "crc_data.bin") == 0) {
            // Process deserialized data
            free(deserialized_array);
        }

        free(array);
    }

    return 0;
}
