#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_PHY_RX_PDU_T {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    PHY_RX_PDU_REL15_TAG pdu_tag;
    ModulationScheme modulation_scheme;
    int SQI;
} LTE_PHY_RX_PDU_T;

typedef struct DynamicArray {
    LTE_PHY_RX_PDU_T* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* dynamic_array_init(size_t initial_capacity) {
    DynamicArray* array = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!array) return NULL;

    array->data = (LTE_PHY_RX_PDU_T*)calloc(initial_capacity, sizeof(LTE_PHY_RX_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }

    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->mutex, NULL);

    return array;
}

void dynamic_array_free(DynamicArray* array) {
    if (array) {
        pthread_mutex_lock(&array->mutex);
        free(array->data);
        pthread_mutex_unlock(&array->mutex);
        pthread_mutex_destroy(&array->mutex);
        free(array);
    }
}

int dynamic_array_append(DynamicArray* array, LTE_PHY_RX_PDU_T item) {
    if (!array || !array->data) return -1;

    pthread_mutex_lock(&array->mutex);

    if (array->size >= array->capacity) {
        size_t new_capacity = array->capacity * 2;
        LTE_PHY_RX_PDU_T* new_data = (LTE_PHY_RX_PDU_T*)realloc(array->data, new_capacity * sizeof(LTE_PHY_RX_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->data = new_data;
        array->capacity = new_capacity;
    }

    array->data[array->size++] = item;

    pthread_mutex_unlock(&array->mutex);

    return 0;
}

LTE_PHY_RX_PDU_T dynamic_array_get(DynamicArray* array, size_t index) {
    LTE_PHY_RX_PDU_T result = {0};
    if (!array || !array->data || index >= array->size) return result;

    pthread_mutex_lock(&array->mutex);
    result = array->data[index];
    pthread_mutex_unlock(&array->mutex);

    return result;
}
