import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class FileProcessor {
    private static final int MAX_RETRIES = 3;
    private static final long BACKOFF_MULTIPLIER = 2000; // milliseconds

    public static void main(String[] args) {
        String configFilePath = "path/to/config/file";
        Path directoryPath = Paths.get("path/to/directory");

        try {
            List<Operation> operations = loadOperations(configFilePath);
            processDirectory(directoryPath, operations);
        } catch (IOException e) {
            System.err.println("Error processing files: " + e.getMessage());
        }
    }

    private static List<Operation> loadOperations(String configFilePath) throws IOException {
        List<Operation> operations = new ArrayList<>();
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(configFilePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                if (!line.startsWith("#")) { // Ignore comments
                    String[] parts = line.split("\\s+");
                    Operation operation = new Operation(parts[0], parts[1]);
                    operations.add(operation);
                }
            }
        }
        return operations;
    }

    private static void processDirectory(Path directoryPath, List<Operation> operations) {
        try (Stream<Path> paths = Files.walk(directoryPath)) {
            paths.filter(Files::isRegularFile)
                 .forEach(file -> executeOperationsOnFile(file, operations));
        } catch (IOException e) {
            System.err.println("Error walking through directory: " + e.getMessage());
        }
    }

    private static void executeOperationsOnFile(Path file, List<Operation> operations) {
        for (Operation operation : operations) {
            int retries = 0;
            while (retries < MAX_RETRIES) {
                try {
                    if (operation.shouldExecute(file)) {
                        Process process = Runtime.getRuntime().exec(operation.getCommand());
                        captureStreams(process);
                        System.out.println("Successfully executed: " + operation.getCommand());
                        break; // Success, no need to retry
                    }
                } catch (IOException e) {
                    retries++;
                    long backoffTime = BACKOFF_MULTIPLIER * (1 << retries);
                    try {
                        Thread.sleep(backoffTime);
                    } catch (InterruptedException ie) {
                        Thread.currentThread().interrupt();
                        System.err.println("Interrupted while waiting for retry: " + e.getMessage());
                    }
                }
            }
        }
    }

    private static void captureStreams(Process process) throws IOException {
        StreamGobbler errorGobbler = new StreamGobbler(process.getErrorStream(), "ERROR");
        StreamGobbler outputGobbler = new StreamGobbler(process.getInputStream(), "OUTPUT");

        errorGobbler.start();
        outputGobbler.start();

        try {
            int exitCode = process.waitFor();
            System.out.println("Process exited with code: " + exitCode);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            System.err.println("Interrupted while waiting for process to finish: " + e.getMessage());
        }

        errorGobbler.join();
        outputGobbler.join();
    }

    static class Operation {
        private String command;
        private String condition;

        public Operation(String command, String condition) {
            this.command = command;
            this.condition = condition;
        }

        public boolean shouldExecute(Path file) throws IOException {
            // Implement logic to check if the operation should be executed based on the file and condition
            return true; // Placeholder
        }

        public String getCommand() {
            return command;
        }
    }

    static class StreamGobbler extends Thread {
        private InputStream inputStream;
        private String streamType;

        public StreamGobbler(InputStream inputStream, String streamType) {
            this.inputStream = inputStream;
            this.streamType = streamType;
        }

        @Override
        public void run() {
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(inputStream))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    System.out.println(streamType + ": " + line);
