typedef struct {
    NFAPI_MESSAGE_T* messages;
    size_t count;
    size_t allocated_count;
    pthread_mutex_t mutex;
} NFAPI_MESSAGE_ARRAY;

NFAPI_MESSAGE_ARRAY* init_NFAPI_message_array(size_t num_messages, LTE_RRC_MSG_TYPE* message_types, size_t type_count) {
    NFAPI_MESSAGE_ARRAY* array = (NFAPI_MESSAGE_ARRAY*)malloc(sizeof(NFAPI_MESSAGE_ARRAY));
    if (!array) {
        perror("Failed to allocate memory for NFAPI_MESSAGE_ARRAY");
        return NULL;
    }

    pthread_mutex_init(&array->mutex, NULL);
    array->messages = (NFAPI_MESSAGE_T*)calloc(num_messages, sizeof(NFAPI_MESSAGE_T));
    if (!array->messages) {
        perror("Failed to allocate memory for messages");
        free(array);
        return NULL;
    }
    array->count = num_messages;
    array->allocated_count = num_messages;

    for (size_t i = 0; i < num_messages; ++i) {
        pthread_mutex_lock(&array->mutex);
        if (i >= MAX_UE_ID) {
            fprintf(stderr, "Exhausted UE_ID range\n");
            break;
        }
        array->messages[i].tag = LTE_RRC_MSG_TYPE_TAG;
        array->messages[i].UE_ID = i + 1; // Unique UE_ID within the specified range
        if (type_count > 0) {
            array->messages[i].msg_type = message_types[rand() % type_count];
        } else {
            array->messages[i].msg_type = LTE_RRC_MSG_TYPE_PAGING; // Default message type
        }
        pthread_mutex_unlock(&array->mutex);
    }

    return array;
}
