#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <time.h>

typedef struct {
    int value;
} record;

int process_pipeline(int input_size, int record_count, int record_position) {
    long *offsets = (long *)malloc(input_size * sizeof(long));
    int *keys = (int *)malloc(input_size * sizeof(int));
    record *records = (record *)malloc(record_count * sizeof(record));

    if (!offsets || !keys || !records) {
        perror("Memory allocation failed");
        return -1;
    }

    srand(time(NULL));
    for (int i = 0; i < input_size; ++i) {
        offsets[i] = rand();
        keys[i] = rand() % 1000;
        records[i].value = rand() % 10000;
    }

    char *file_name = "temp_file.txt";
    int file_fd = open(file_name, O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (file_fd == -1) {
        perror("Failed to create file");
        free(offsets);
        free(keys);
        free(records);
        return -1;
    }

    close(file_fd);

    char *input_sequence = (char *)malloc(input_size * sizeof(char));
    printf("Enter %d integers: ", input_size);
    scanf("%s", input_sequence);

    int max_input = atoi(strtok(input_sequence, " "));
    for (int i = 1; i < input_size; ++i) {
        int num = atoi(strtok(NULL, " "));
        if (num > max_input) {
            max_input = num;
        }
    }

    free(input_sequence);

    char *max_record_str = (char *)malloc(20 * sizeof(char));
    sprintf(max_record_str, "%d", records[record_position].value);
    int max_record = atoi(max_record_str);

    if (max_record > max_input) {
        printf("Max record value: %s\n", max_record_str);
    } else {
        printf("Max input value: %d\n", max_input);
    }

    free(offsets);
    free(keys);
    free(records);
    free(max_record_str);

    return max_record > max_input ? records[record_position].value : max_input;
}
