typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t size;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicArray;

void init_dynamic_array(DynamicArray *da) {
    da->array = NULL;
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_init(&da->mutex, NULL);
}

void free_dynamic_array(DynamicArray *da) {
    pthread_mutex_lock(&da->mutex);
    if (da->array != NULL) {
        free(da->array);
        da->array = NULL;
    }
    da->size = 0;
    da->capacity = 0;
    pthread_mutex_unlock(&da->mutex);
    pthread_mutex_destroy(&da->mutex);
}

bool resize_dynamic_array(DynamicArray *da, size_t new_capacity) {
    if (new_capacity <= da->capacity) return true;

    NFAPI_CRC_INDICATION_PDU_T *new_array = realloc(da->array, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_array == NULL) return false;

    memset(new_array + da->size, 0, (new_capacity - da->size) * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    pthread_mutex_lock(&da->mutex);
    da->array = new_array;
    da->capacity = new_capacity;
    pthread_mutex_unlock(&da->mutex);

    return true;
}

bool add_element_to_dynamic_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T element) {
    if (da->size >= da->capacity && !resize_dynamic_array(da, da->capacity * 2)) return false;

    pthread_mutex_lock(&da->mutex);
    da->array[da->size++] = element;
    pthread_mutex_unlock(&da->mutex);

    return true;
}

