// PokemonService.java
public class PokemonService {
    private final PokemonApiClient apiClient;
    private final PokemonDatabase db;
    private final Configuration config;

    public PokemonService(PokemonApiClient apiClient, PokemonDatabase db, Configuration config) {
        this.apiClient = apiClient;
        this.db = db;
        this.config = config;
    }

    public Report generateReport(List<Pokemon> pokemons) {
        // Fetch typing data from API
        Map<String, TypingData> typeData = apiClient.fetchTypingData();

        // Fetch historical and evolution data from database
        Map<String, PokemonInfo> dbData = db.fetchPokemonInfo(pokemons);

        // Process each Pokemon to generate detailed report
        List<ReportEntry> entries = pokemons.stream()
            .map(pokemon -> {
                String name = pokemon.getName();
                TypingData typing = typeData.get(name);
                PokemonInfo info = dbData.get(name);

                if (typing == null || info == null) {
                    return new ReportEntry(name, "Error: Data not available");
                }

                // Generate report entry
                return new ReportEntry(
                    name,
                    typing.getWeaknesses(),
                    typing.getTypes(),
                    info.getCounters()
                );
            })
            .collect(Collectors.toList());

        return new Report(entries);
    }
}

