import java.io.*;
import java.nio.file.*;
import java.util.concurrent.*;

public class StateLoader {

    private static final Map<String, Future<State>> cache = new ConcurrentHashMap<>();
    private static final long CACHE_EXPIRY_TIME = TimeUnit.MINUTES.toMillis(10);

    public static State loadState(String filePath) {
        try {
            Path path = Paths.get(filePath);
            if (!Files.exists(path)) {
                System.err.println("File not found: " + filePath);
                return null;
            }

            Future<State> future = cache.computeIfAbsent(filePath, k -> CompletableFuture.supplyAsync(() -> {
                try (ObjectInputStream ois = new ObjectInputStream(Files.newInputStream(path))) {
                    State state = (State) ois.readObject();
                    if (!(state instanceof MoSTState || state instanceof ExtendedMoSTState)) {
                        System.err.println("Invalid object type: " + state.getClass().getName());
                        return null;
                    }
                    validateState(state);
                    return state;
                } catch (IOException | ClassNotFoundException e) {
                    System.err.println("Deserialization error: " + e.getMessage());
                    return null;
                }
            }, Executors.newSingleThreadExecutor()));

            State state = future.get();
            if (state != null && isCacheExpired(filePath)) {
                cache.remove(filePath);
                return loadState(filePath); // Reload
            }

            return state;
        } catch (InterruptedException | ExecutionException e) {
            System.err.println("Error loading state: " + e.getMessage());
            return null;
        }
    }

    private static boolean isCacheExpired(String filePath) {
        long lastModified = Files.getLastModifiedTime(Paths.get(filePath)).toMillis();
        long currentTime = System.currentTimeMillis();
        return (currentTime - lastModified) > CACHE_EXPIRY_TIME;
    }

    private static void validateState(State state) {
        // Add validation logic here
    }
}

abstract class State {}

class MoSTState extends State {}

class ExtendedMoSTState extends State {}
