public class StateLoaderTest {

    @Test
    public void testLoadStateFileNotFound() {
        assertNull(StateLoader.loadState("nonexistentfile.ser"));
    }

    @Test
    public void testLoadStateDeserializationError() throws IOException, ClassNotFoundException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("temp.ser"))) {
            oos.writeObject(new Object()); // Invalid object type
        }
        assertNull(StateLoader.loadState("temp.ser"));
    }

    @Test
    public void testLoadStateInvalidObject() throws IOException, ClassNotFoundException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("temp.ser"))) {
            oos.writeObject(new State()); // Invalid object type
        }
        assertNull(StateLoader.loadState("temp.ser"));
    }

    @Test
    public void testLoadStateValidObject() throws IOException, ClassNotFoundException {
        MoSTState state = new MoSTState();
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("temp.ser"))) {
            oos.writeObject(state);
        }
        State loadedState = StateLoader.loadState("temp.ser");
        assertNotNull(loadedState);
        assertTrue(loadedState instanceof MoSTState);
    }

    @Test
    public void testCacheExpiry() throws IOException, ClassNotFoundException, InterruptedException {
        MoSTState state = new MoSTState();
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("temp.ser"))) {
            oos.writeObject(state);
        }
        State loadedState = StateLoader.loadState("temp.ser");
        assertNotNull(loadedState);

        Thread.sleep(StateLoader.CACHE_EXPIRY_TIME + 1000); // Wait for cache to expire
        loadedState = StateLoader.loadState("temp.ser");
        assertNotNull(loadedState);
    }

    @AfterAll
    public static void tearDown() {
        try (FileOutputStream fos = new FileOutputStream("temp.ser")) {
            fos.write(new byte[0]); // Clear file
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}
