import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class DisjointPairCounter {

    private final ConcurrentHashMap<Integer, Integer> parentMap = new ConcurrentHashMap<>();
    private final AtomicInteger pairCount = new AtomicInteger(0);

    public void process(int[] data) {
        if (data == null || data.length == 0) {
            throw new IllegalArgumentException("Data cannot be null or empty");
        }

        for (int num : data) {
            union(num, num + 1);
        }
    }

    private int find(int x) {
        Integer parent = parentMap.get(x);
        if (parent == null || parent == x) {
            return x;
        }
        return find(parent);
    }

    private void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX != rootY) {
            parentMap.put(rootX, rootY);
            pairCount.incrementAndGet();
        }
    }

    public int getPairCount() {
        return pairCount.get();
    }

    public static void main(String[] args) {
