// Function to fetch data from API with failover and rate limiting
function fetchData($apiUrl, $apiKey, $failoverUrl = null) {
    static $requestCount = [];
    $currentTime = time();

    // Rate limiting
    if (!isset($requestCount[$apiUrl]) || $currentTime - $requestCount[$apiUrl] > $rateLimit['interval']) {
        $requestCount[$apiUrl] = $currentTime;
    } else {
        throw new Exception("Rate limit exceeded for {$apiUrl}");
    }

    // Fetch data from primary API
    try {
        $response = file_get_contents($apiUrl . '?key=' . urlencode($apiKey));
        if ($response === false) {
            throw new Exception("Failed to fetch data from primary API");
        }
        return json_decode($response, true);
    } catch (Exception $e) {
        // Fallback to backup API
        if ($failoverUrl !== null) {
            try {
                $response = file_get_contents($failoverUrl . '?key=' . urlencode($apiKey));
                if ($response === false) {
                    throw new Exception("Failed to fetch data from backup API");
                }
                return json_decode($response, true);
            } catch (Exception $e) {
                throw new Exception("Failed to fetch data from both primary and backup APIs: " . $e->getMessage());
            }
        } else {
            throw $e;
        }
    }
}

