#include <vector>
#include <mutex>
#include <atomic>
#include <unordered_map>

template<typename T>
class SpatialHashGrid {
public:
    struct Cell {
        std::vector<T*> objects;
        std::mutex lock;
    };

    SpatialHashGrid(float cellSize, int capacity)
        : cellSize(cellSize), capacity(capacity) {}

    void insert(const T& obj, const glm::vec3& position) {
        auto [cellX, cellY, cellZ] = getCellIndices(position);
        std::lock_guard<std::mutex> lock(grid[cellX][cellY][cellZ].lock);
        if (grid[cellX][cellY][cellZ].objects.size() < capacity) {
            grid[cellX][cellY][cellZ].objects.push_back(const_cast<T*>(&obj));
        }
    }

    void remove(T& obj, const glm::vec3& position) {
        auto [cellX, cellY, cellZ] = getCellIndices(position);
        std::lock_guard<std::mutex> lock(grid[cellX][cellY][cellZ].lock);
        grid[cellX][cellY][cellZ].objects.erase(std::remove(grid[cellX][cellY][cellZ].objects.begin(), 
                                                           grid[cellX][cellY][cellZ].objects.end(), &obj), 
                                               grid[cellX][cellY][cellZ].objects.end());
    }

    std::vector<T*> query(const glm::vec3& min, const glm::vec3& max) {
        std::vector<T*> results;
        auto [minCellX, minCellY, minCellZ] = getCellIndices(min);
        auto [maxCellX, maxCellY, maxCellZ] = getCellIndices(max);

        for (int x = minCellX; x <= maxCellX; ++x) {
            for (int y = minCellY; y <= maxCellY; ++y) {
                for (int z = minCellZ; z <= maxCellZ; ++z) {
                    std::lock_guard<std::mutex> lock(grid[x][y][z].lock);
                    results.insert(results.end(), grid[x][y][z].objects.begin(), 
                                   grid[x][y][z].objects.end());
                }
            }
        }

        return results;
    }

private:
    float cellSize;
    int capacity;
    std::vector<std::vector<std::vector<Cell>>> grid;

    std::tuple<int, int, int> getCellIndices(const glm::vec3& position) {
        int x = static_cast<int>(position.x / cellSize);
        int y = static_cast<int>(position.y / cellSize);
        int z = static_cast<int>(position.z / cellSize);
        return {x, y, z};
    }
};
