async function asyncReduce(numbers, initialValue, callback) {
  let accumulator = initialValue;
  const totalNumbers = numbers.length;

  for (let i = 0; i < totalNumbers; i++) {
    try {
      const result = await callback(accumulator, numbers[i]);
      accumulator = result;
      updateProgress((i + 1) / totalNumbers);
    } catch (error) {
      logError(error);
      return Promise.reject(error);
    }
  }

  return accumulator;
}

function updateProgress(percentage) {
  console.log(`Progress: ${Math.round(percentage * 100)}%`);
}

function logError(error) {
  console.error('Error:', error.message);
}

// Example usage:
const numbers = [1, 2, 3, 4, 5];
const initialValue = 0;
const callback = async (acc, num) => {
  // Simulate an asynchronous operation
  return new Promise((resolve) => setTimeout(() => resolve(acc + num), 100));
};

asyncReduce(numbers, initialValue, callback)
  .then(result => console.log('Final result:', result))
  .catch(error => console.error('Reduction failed:', error));
```

