typedef struct {
    int width;
    int height;
    char color_space[20];
    int quality_level;
    float artifact_presence;
} ImageMetadata;

ImageMetadata parse_jpeg(const char* filename) {
    ImageMetadata metadata = {0};
    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *infile;

    if ((infile = fopen(filename, "rb")) == NULL) {
        fprintf(stderr, "Cannot open %s\n", filename);
        exit(1);
    }

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, infile);

    if (jpeg_read_header(&cinfo, TRUE) != JPEG_HEADER_OK) {
        fprintf(stderr, "Cannot read header from %s\n", filename);
        fclose(infile);
        exit(1);
    }

    jpeg_start_decompress(&cinfo);

    metadata.width = cinfo.output_width;
    metadata.height = cinfo.output_height;

    switch (cinfo.out_color_space) {
        case JCS_GRAYSCALE:
            strcpy(metadata.color_space, "Grayscale");
            break;
        case JCS_RGB:
            strcpy(metadata.color_space, "RGB");
            break;
        case JCS_YCbCr:
            strcpy(metadata.color_space, "YCbCr");
            break;
        default:
            strcpy(metadata.color_space, "Unknown");
            break;
    }

    metadata.quality_level = cinfo.dct_method;

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    // Placeholder for artifact detection logic
    metadata.artifact_presence = 0.0; // Implement actual artifact detection here

    return metadata;
}

int main() {
    ImageMetadata metadata = parse_jpeg("example.jpg");
    printf("Width: %d\n", metadata.width);
    printf("Height: %d\n", metadata.height);
    printf("Color Space: %s\n", metadata.color_space);
    printf("Quality Level: %d\n", metadata.quality_level);
    printf("Artifact Presence: %.2f%%\n", metadata.artifact_presence * 100);

    return 0;
}
