typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t capacity;
    size_t size;
} PDUList;

PDUList* create_pdu_list(size_t initial_capacity) {
    if (initial_capacity == 0) return NULL;
    PDUList *list = malloc(sizeof(PDUList));
    if (!list) return NULL;
    list->pdus = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->pdus) {
        free(list);
        return NULL;
    }
    list->capacity = initial_capacity;
    list->size = 0;
    return list;
}

void destroy_pdu_list(PDUList *list) {
    if (list) {
        free(list->pdus);
        free(list);
    }
}

int add_pdu(PDUList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || list->size >= list->capacity) return -1;
    list->pdus[list->size++] = pdu;
    return 0;
}

void resize_pdu_list(PDUList *list, size_t new_capacity) {
    if (!list || new_capacity <= list->capacity) return;
    NFAPI_CRC_INDICATION_PDU_T *new_pdus = realloc(list->pdus, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_pdus) {
        list->pdus = new_pdus;
        list->capacity = new_capacity;
    }
}

void reset_pdu_list(PDUList *list) {
    if (!list) return;
    list->size = 0;
}
