const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');
const axios = require('axios');

class CommandExecutor {
  constructor(restrictedDir, timeoutMap, logServiceUrl) {
    this.restrictedDir = restrictedDir;
    this.timeoutMap = timeoutMap;
    this.logServiceUrl = logServiceUrl;
  }

  async execute(command, args, user, overrideSecurity = false) {
    if (!overrideSecurity && !this.isSafePath(path.resolve(this.restrictedDir, command))) {
      throw new Error('Unauthorized access to system files');
    }

    const startTime = Date.now();
    return new Promise((resolve, reject) => {
      execFile(command, args, { timeout: this.timeoutMap[command] || 5000 }, (error, stdout, stderr) => {
        if (error) {
          error.stdout = stdout;
          error.stderr = stderr;
          error.timestamp = startTime;
          error.exitCode = error.code;
          reject(error);
        } else {
          const endTime = Date.now();
          const logData = {
            command,
            args,
            user,
            timestamp: startTime,
            exitCode: 0,
            duration: endTime - startTime,
            stdout,
            stderr
          };
          this.logCommand(logData);
          resolve({ stdout, stderr });
        }
      });
    });
  }

  isSafePath(targetPath) {
    const absolutePath = path.resolve(this.restrictedDir, targetPath);
    return absolutePath.startsWith(path.resolve(this.restrictedDir));
  }

  async logCommand(logData) {
    try {
      await axios.post(this.logServiceUrl, logData);
    } catch (error) {
      console.error('Failed to log command:', error);
    }
  }
}

// Example usage:
const executor = new CommandExecutor('/safe/directory', { 'ls': 1000 }, 'http://log-service.com/log');
executor.execute('ls', ['-l'], 'user1')
  .then(result => console.log(result))
  .catch(error => console.error(error));
```

This code snippet provides a basic structure for the `CommandExecutor` class, which includes methods to execute commands within a restricted environment, handle timeouts, log commands, and integrate with an external log service. The example usage demonstrates how to create an instance of the executor and execute a command."]

