#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_N 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t pool_size;
    size_t used_count;
    pthread_mutex_t lock;
} MemoryPool;

MemoryPool memory_pool = {NULL, 0, 0, PTHREAD_MUTEX_INITIALIZER};

int validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T *indication) {
    // Custom validation logic here
    return indication->CRC_INDICATION_REL8_TAG >= 0 && indication->CRC_INDICATION_REL8_TAG <= 1;
}

void* allocate_and_initialize_nfaapi_crc_indications(int N) {
    if (N > MAX_N) {
        fprintf(stderr, "Error: Requested number of instances exceeds maximum limit.\n");
        return NULL;
    }

    pthread_mutex_lock(&memory_pool.lock);
    if (memory_pool.pool == NULL || memory_pool.used_count + N > memory_pool.pool_size) {
        size_t new_size = memory_pool.pool ? memory_pool.pool_size * 2 : N;
        NFAPI_CRC_INDICATION_PDU_T *new_pool = realloc(memory_pool.pool, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_pool == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return NULL;
        }
        memory_pool.pool = new_pool;
        memory_pool.pool_size = new_size;
    }

    for (int i = 0; i < N; i++) {
        memory_pool.pool[memory_pool.used_count + i].RX_UE_INFORMATION_TAG = rand() % 1024;
        memory_pool.pool[memory_pool.used_count + i].RNTI = rand() % 65536;
        do {
            memory_pool.pool[memory_pool.used_count + i].CRC_INDICATION_REL8_TAG = rand() % 2;
        } while (!validate_crc_indication(&memory_pool.pool[memory_pool.used_count + i]));
    }

    memory_pool.used_count += N;
    pthread_mutex_unlock(&memory_pool.lock);

    return memory_pool.pool + (memory_pool.used_count - N);
}

void deallocate_nfaapi_crc_indications(void *ptr, int N) {
    pthread_mutex_lock(&memory_pool.lock);
    if (ptr >= memory_pool.pool && ptr < memory_pool.pool + memory_pool.used_count) {
        size_t index = (char *)ptr - (char *)memory_pool.pool;
        if (index + N > memory_pool.used_count) {
            fprintf(stderr, "Error: Invalid deallocation range.\n");
            pthread_mutex_unlock(&memory_pool.lock);
            return;
        }
        memory_pool.used_count -= N;
    } else {
        fprintf(stderr, "Error: Invalid pointer for deallocation.\n");
    }
    pthread_mutex_unlock(&memory_pool.lock);
}
