typedef struct {
    int timestamp;
    int id;
    int payloadSize;
    char *payload;
} DataPacket;

typedef struct Node {
    DataPacket data;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    Node *tail;
    int size;
} DynamicArray;

DynamicArray* createDynamicArray() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->head = NULL;
    array->tail = NULL;
    array->size = 0;
    return array;
}

void addPacket(DynamicArray *array, DataPacket packet) {
    Node *newNode = (Node*)malloc(sizeof(Node));
    newNode->data = packet;
    newNode->next = NULL;

    if (array->head == NULL) {
        array->head = newNode;
        array->tail = newNode;
    } else {
        array->tail->next = newNode;
        array->tail = newNode;
    }
    array->size++;
}

void updatePacket(DynamicArray *array, int id, DataPacket newPacket) {
    Node *current = array->head;
    while (current != NULL) {
        if (current->data.id == id) {
            current->data = newPacket;
            return;
        }
        current = current->next;
    }
}

void removePackets(DynamicArray *array, int minTimestamp, int maxTimestamp) {
    Node *current = array->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data.timestamp < minTimestamp || current->data.timestamp > maxTimestamp) {
            if (prev == NULL) {
                array->head = current->next;
            } else {
                prev->next = current->next;
            }
            Node *temp = current;
            current = current->next;
            free(temp);
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void processIncomingPackets(DynamicArray *array, DataPacket *incomingPackets, int count) {
    for (int i = 0; i < count; i++) {
        addPacket(array, incomingPackets[i]);
    }
}

void updateLegacySystem(DynamicArray *array) {
