    pthread_mutex_t lock;
} CRC_LIST_T;

CRC_LIST_T* create_crc_list(size_t initial_capacity) {
    CRC_LIST_T *list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    list->data = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRC_LIST_T *list) {
    free(list->data);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_indication(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->lock);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_data = (NFAPI_CRC_INDICATION_PDU_T*)realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->size++] = pdu;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int validate_crc_indication(CRC_LIST_T *list, uint16_t rnti) {
