import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.concurrent.ConcurrentHashMap;

public class HashService {
    private static final int MAX_INPUT_LENGTH = 1024;
    private static final ConcurrentHashMap<String, String> cache = new ConcurrentHashMap<>();

    public static String hashString(String input) throws IllegalArgumentException, NoSuchAlgorithmException {
        if (input == null || input.length() > MAX_INPUT_LENGTH) {
            throw new IllegalArgumentException("Input must be non-null and not exceed " + MAX_INPUT_LENGTH + " characters.");
        }

        for (char c : input.toCharArray()) {
            if (!isAsciiPrintable(c)) {
                throw new IllegalArgumentException("Input must contain only ASCII printable characters.");
            }
        }

        return cache.computeIfAbsent(input, HashService::computeHash);
    }

    private static String computeHash(String input) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(input.getBytes());
        StringBuilder hexString = new StringBuilder();
        for (byte b : hashBytes) {
            String hex = Integer.toHexString(0xff & b);
            if (hex.length() == 1) hexString.append('0');
            hexString.append(hex);
        }
        return hexString.toString();
    }

    private static boolean isAsciiPrintable(char c) {
        return c >= 32 && c <= 126;
    }
}
