#include <pthread.h>
#include <stdlib.h>

typedef struct {
    int SE_ID;
    int PDU_SESSION_ID;
    int SM_CONTEXT_ID;
} PDU_SESSION_STATUS_UPDATE_INDication;

typedef struct QueueNode {
    PDU_SESSION_STATUS_UPDATE_INDication data;
    struct QueueNode* next;
} QueueNode;

typedef struct {
    QueueNode* front;
    QueueNode* rear;
    pthread_mutex_t mutex;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    int capacity;
    int size;
} ThreadSafeQueue;

ThreadSafeQueue* create_queue(int initial_capacity) {
    ThreadSafeQueue* queue = (ThreadSafeQueue*)malloc(sizeof(ThreadSafeQueue));
    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    queue->capacity = initial_capacity;
    queue->size = 0;
    return queue;
}

void enqueue(ThreadSafeQueue* queue, PDU_SESSION_STATUS_UPDATE_INDication data) {
    QueueNode* new_node = (QueueNode*)malloc(sizeof(QueueNode));
    new_node->data = data;
    new_node->next = NULL;

    pthread_mutex_lock(&queue->mutex);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->mutex);
    }

    if (queue->rear != NULL) {
        queue->rear->next = new_node;
    } else {
        queue->front = new_node;
    }
    queue->rear = new_node;
    queue->size++;
    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->mutex);
}

PDU_SESSION_STATUS_UPDATE_INDication dequeue(ThreadSafeQueue* queue) {
    PDU_SESSION_STATUS_UPDATE_INDication data;

    pthread_mutex_lock(&queue->mutex);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->mutex);
    }

    QueueNode* temp = queue->front;
    data = temp->data;
    if (queue->front == queue->rear) {
        queue->front = queue->rear = NULL;
    } else {
        queue->front = queue->front->next;
    }
    free(temp);
    queue->size--;
    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->mutex);

    return data;
}

void destroy_queue(ThreadSafeQueue* queue) {
    QueueNode* current = queue->front;
    while (current != NULL) {
        QueueNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}
