typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *array;
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
    FILE *log_file;
} NFAPI_CRC_ARRAY_T;

NFAPI_CRC_ARRAY_T* create_array() {
    NFAPI_CRC_ARRAY_T *array = (NFAPI_CRC_ARRAY_T*)malloc(sizeof(NFAPI_CRC_ARRAY_T));
    array->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->count = 0;
    array->capacity = MAX_ELEMENTS;
    pthread_mutex_init(&array->mutex, NULL);
    array->log_file = fopen("nfaapi_crc_log.txt", "w");
    return array;
}

void destroy_array(NFAPI_CRC_ARRAY_T *array) {
    free(array->array);
    fclose(array->log_file);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_element(NFAPI_CRC_ARRAY_T *array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= array->capacity) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }
    array->array[array->count++] = element;
    fprintf(array->log_file, "Added element: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d\n", 
            element.RX_UE_INFORMATION_TAG, element.RNTI, element.CRCFLAG);
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int remove_element(NFAPI_CRC_ARRAY_T *array, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        if (array->array[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            for (size_t j = i; j < array->count - 1; ++j) {
                array->array[j] = array->array[j + 1];
            }
            array->count--;
            fprintf(array->log_file, "Removed element with RX_UE_INFORMATION_TAG=%d\n", RX_UE_INFORMATION_TAG);
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Element not found
}

void iterate_array(NFAPI_CRC_ARRAY_T *array, void (*process_element)(NFAPI_CRC_INDICATION_PDU_T)) {
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->count; ++i) {
        process_element(array->array[i]);
    }
    pthread_mutex_unlock(&array->mutex);
}

void compact_array(NFAPI_CRC_ARRAY_T *array) {
    pthread_mutex_lock(&array->mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(array->count, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (size_t i = 0; i < array->count; ++i) {
        new_array[i] = array->array[i];
    }
    free(array->array);
    array->array = new_array;
    array->capacity = array->count;
    pthread_mutex_unlock(&array->mutex);
}

void log_performance(NFAPI_CRC_ARRAY_T *array, double add_time, double remove_time, double iterate_time) {
    fprintf(array->log_file, "Performance Metrics: Add=%.2fms, Remove=%.2fms, Iterate=%.2fms\n", 
            add_time, remove_time, iterate_time);
}

