void dynamic_array_free(DynamicArray* array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->frames[i]);
    }
    free(array->frames);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int dynamic_array_add(DynamicArray* array, WLAN_RX_FRAME_T* frame) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity * 2;
        WLAN_RX_FRAME_T** new_frames = (WLAN_RX_FRAME_T**)realloc(array->frames, new_capacity * sizeof(WLAN_RX_FRAME_T*));
        if (!new_frames) {
            pthread_mutex_unlock(&array->mutex);
            return -1; // Allocation failure
        }
        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    array->frames[array->size++] = frame;

    pthread_mutex_unlock(&array->mutex);
    return 0;
}

WLAN_RX_FRAME_T* dynamic_array_get(DynamicArray* array, size_t index) {
    if (index >= array->size) return NULL;

    pthread_mutex_lock(&array->mutex);
    WLAN_RX_FRAME_T* frame = array->frames[index];
    pthread_mutex_unlock(&array->mutex);

    return frame;
}

