void insert_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (list->head == NULL) {
        list->head = node;
        list->tail = node;
    } else {
        list->tail->next = node;
        node->prev = list->tail;
        list->tail = node;
    }
    list->size++;
}

void delete_node(DoublyLinkedList* list, NFAPI_CRC_INDICATION_PDU_T* node) {
    if (node->prev != NULL)
        node->prev->next = node->next;
    else
        list->head = node->next;

    if (node->next != NULL)
        node->next->prev = node->prev;
    else
        list->tail = node->prev;

    free(node);
    list->size--;
}

void traverse_list(DoublyLinkedList* list) {
    NFAPI_CRC_INDICATION_PDU_T* current = list->head;
    while (current != NULL) {
        // Process each node
        current = current->next;
    }
