NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
int entry_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    // Log the details of the created entry
}

void log_error(const char *message) {
    // Log error messages
}

int create_entries(int batch_size, int rnti_start) {
    pthread_mutex_lock(&mutex);
    if (entry_count + batch_size > MAX_ENTRIES) {
        log_error("Not enough space to create entries");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < batch_size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_entry) {
            log_error("Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        new_entry->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
        new_entry->RNTI = rnti_start + i;
        new_entry->CRC_INDICATION_REL8_TAG = rand() % 256; // Example value
        new_entry->CRCFLAG = rand() % 2; // Randomly set CRCFLAG

        if (entry_count > 0) {
            for (int j = 0; j < entry_count; j++) {
                if (entries[j]->RNTI == new_entry->RNTI) {
                    log_error("Duplicate RNTI value detected");
                    free(new_entry);
                    pthread_mutex_unlock(&mutex);
                    return -1;
                }
            }
        }

        entries[entry_count++] = new_entry;
        log_entry(new_entry);
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

void *worker_thread(void *arg) {
    int batch_size = *(int *)arg;
    free(arg);

    for (int rnti_start = 0; rnti_start < 10000; rnti_start += batch_size) {
        if (create_entries(batch_size, rnti_start) != 0) {
            break;
        }
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    int *batch_sizes = malloc(10 * sizeof(int));
    for (int i = 0; i < 10; i++) {
        batch_sizes[i] = rand() % 100 + 1; // Random batch size between 1 and 100
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        if (pthread_create(&threads[i], NULL, worker_thread, &batch_sizes[i]) != 0) {
            log_error("Failed to create thread");
            return -1;
        }
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    free(batch_sizes);

    // Clean up allocated memory
    for (int i = 0; i < entry_count; i++) {
        free(entries[i]);
    }

    return 0;
}
