                validated_transaction = future.result()
                net_balance = calculate_net_balance(validated_transaction)
                currency_pair = f"{validated_transaction['currency']}_USD"
                conversion_rate = fetch_currency_conversion_rate(currency_pair)
                results.append({
                    'transaction_id': validated_transaction['id'],
                    'net_balance': net_balance * conversion_rate,
                    'status': 'success'
                })
            except Exception as e:
                results.append({
                    'transaction_id': futures[future],
                    'error_message': str(e),
                    'status': 'failure'
                })
    return results
