// Function to allocate and populate CRC indications with thread safety and memory management considerations
NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_crc_indications(int N, size_t *allocated_size) {
    if (N <= 0) {
        return NULL; // Handle invalid input gracefully
    }

    NFAPI_CRC_INDICATION_PDU_T *crc_indications = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!crc_indications) {
        return NULL; // Return NULL if memory allocation fails
    }

    srand(time(NULL)); // Seed the random number generator for RNTI generation

    int rnti_values[N];
    bool used_rntis[N] = {false};
    size_t count = 0;

    while (count < N) {
        int rnti;
        do {
            rnti = rand() % 1000 + 1; // Generate a random RNTI within the range [1, 1000]
        } while (used_rntis[rnti - 1]); // Ensure no duplicates

        used_rntis[rnti - 1] = true;
        rnti_values[count] = rnti;

        crc_indications[count].RX_UE_INFORMATION_TAG = count + 1; // Initialize RX_UE_INFORMATION_TAG
        crc_indications[count].RNTI = rnti_values[count]; // Assign RNTI
        crc_indications[count].CRC_INDICATION_REL8_TAG = (crc_indications[count].RX_UE_INFORMATION_TAG + crc_indications[count].RNTI) % 5 == 0; // Set CRCFLAG based on sum

        count++;
    }

    *allocated_size = N;
    return crc_indications;
}

// Function to free allocated memory
void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T *crc_indications, size_t size) {
    if (crc_indications) {
        free(crc_indications);
    }
}
