typedef struct {
    int timestamp;
    float signal_strength;
} FrameMetadata;

typedef struct {
    // Define ChannelQualityIndication structure here
} ChannelQualityIndication;

typedef struct Node {
    FrameMetadata metadata;
    ChannelQualityIndication *channel_quality_indications;
    struct Node *next;
} Node;

typedef struct {
    Node *head;
    size_t count;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->head = NULL;
    array->count = 0;
    return array;
}

void add_or_update_metadata(DynamicArray *array, int unique_id, FrameMetadata metadata, ChannelQualityIndication *channel_quality_indications) {
    Node *current = array->head;
    while (current != NULL) {
        if (current->metadata.timestamp == unique_id) {
            // Update existing entry
            current->metadata = metadata;
            free(current->channel_quality_indications);
            current->channel_quality_indications = channel_quality_indications;
            return;
        }
        current = current->next;
    }
    // Add new entry
    Node *new_node = (Node*)malloc(sizeof(Node));
    new_node->metadata = metadata;
    new_node->channel_quality_indications = channel_quality_indications;
    new_node->next = array->head;
    array->head = new_node;
    array->count++;
}

void iterate_over_entries(DynamicArray *array, void (*callback)(FrameMetadata, ChannelQualityIndication *)) {
    Node *current = array->head;
    while (current != NULL) {
        callback(current->metadata, current->channel_quality_indications);
        current = current->next;
    }
}

// Example usage
void print_metadata(FrameMetadata metadata, ChannelQualityIndication *channel_quality_indications) {
    printf("Timestamp: %d, Signal Strength: %.2f\n", metadata.timestamp, metadata.signal_strength);
}

int main() {
    DynamicArray *array = create_dynamic_array();

    FrameMetadata metadata1 = {1633072800, 95.5};
    ChannelQualityIndication *channel_quality_indications1 = (ChannelQualityIndication*)malloc(sizeof(ChannelQualityIndication));
    add_or_update_metadata(array, 1, metadata1, channel_quality_indications1);

    FrameMetadata metadata2 = {1633072805, 94.0};
    ChannelQualityIndication *channel_quality_indications2 = (ChannelQualityIndication*)malloc(sizeof(ChannelQualityIndication));
    add_or_update_metadata(array, 2, metadata2, channel_quality_indications2);

    iterate_over_entries(array, print_metadata);

    // Clean up
    Node *current = array->head;
    while (current != NULL) {
        Node *next = current->next;
        free(current->channel_quality_indications);
        free(current);
        current = next;
    }
    free(array);

    return 0;
}
