    if (N <= 0 || N > 1000 || max_rnti < 1 || max_rnti > 65535) {
        return NULL;
    }

    srand(seed);
    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (array == NULL) {
        return NULL;
    }

    int rnti_values[65536] = {0};
    int unique_rntis = 0;

    while (unique_rntis < N) {
        int rnti = custom_random(1, max_rnti);
        if (!rnti_values[rnti]) {
            array[unique_rntis].RX_UE_INFORMATION_TAG = custom_random(1, 100);
            array[unique_rntis].RNTI = rnti;
            array[unique_rntis].CRC_INDICATION_REL8_TAG = custom_random(0, 1);
            rnti_values[rnti] = 1;
            unique_rntis++;
