void logNetworkEvents(int N) {
    if (N > MAX_ENTRIES) {
        N = MAX_ENTRIES; // Limit to prevent resource exhaustion
    }

    NetworkEventLogEntry** entries = malloc(N * sizeof(NetworkEventLogEntry*));
    if (!entries) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < N; i++) {
        entries[i] = malloc(sizeof(NetworkEventLogEntry));
        if (!entries[i]) {
            fprintf(stderr, "Memory allocation failed for entry %d\n", i);
            // Free previously allocated entries
            for (int j = 0; j < i; j++) {
                free(entries[j]);
            }
            free(entries);
            return;
        }

        // Generate timestamp and event type
        time_t now = time(NULL);
        entries[i]->timestamp = now + rand() % 3600; // Random timestamp within the next hour
        entries[i]->eventType = rand() % 5; // Random event type

        // Allocate memory for message
        int messageLength = rand() % 100 + 1; // Random length between 1 and 100 characters
        entries[i]->message = malloc(messageLength * sizeof(char));
        if (!entries[i]->message) {
            fprintf(stderr, "Memory allocation failed for message in entry %d\n", i);
            // Free previously allocated entries
            for (int j = 0; j <= i; j++) {
                free(entries[j]->message);
                free(entries[j]);
            }
            free(entries);
            return;
        }

        // Generate random message
        for (int j = 0; j < messageLength - 1; j++) {
            entries[i]->message[j] = 'a' + rand() % 26;
        }
        entries[i]->message[messageLength - 1] = '\0';
