    (*array)->messages = (Message*)calloc(initial_capacity, sizeof(Message));
    if ((*array)->messages == NULL) {
        free(*array);
        return -1;
    }

    (*array)->capacity = initial_capacity;
    (*array)->size = 0;
    pthread_mutex_init(&(*array)->lock, NULL);

    (*array)->log_file = fopen("error_log.txt", "a");
    if ((*array)->log_file == NULL) {
        free((*array)->messages);
        free(*array);
        return -1;
    }

    return 0;
}
