#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int id;
    time_t timestamp;
    int priority;
    char payload[256];
} NetMessage;

typedef struct Node {
    NetMessage message;
    struct Node* next;
} Node;

typedef struct {
    Node* front;
    Node* rear;
    pthread_mutex_t lock;
    pthread_cond_t not_empty;
    pthread_cond_t not_full;
    int capacity;
    int size;
} MessageQueue;

MessageQueue* createMessageQueue(int capacity) {
    MessageQueue* queue = (MessageQueue*)malloc(sizeof(MessageQueue));
    if (!queue) return NULL;

    queue->front = queue->rear = NULL;
    pthread_mutex_init(&queue->lock, NULL);
    pthread_cond_init(&queue->not_empty, NULL);
    pthread_cond_init(&queue->not_full, NULL);
    queue->capacity = capacity;
    queue->size = 0;

    return queue;
}

void destroyMessageQueue(MessageQueue* queue) {
    Node* current = queue->front;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&queue->lock);
    pthread_cond_destroy(&queue->not_empty);
    pthread_cond_destroy(&queue->not_full);
    free(queue);
}

void enqueue(MessageQueue* queue, NetMessage message) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == queue->capacity) {
        pthread_cond_wait(&queue->not_full, &queue->lock);
    }

    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        // Handle memory allocation failure
        pthread_mutex_unlock(&queue->lock);
        return;
    }
    newNode->message = message;
    newNode->next = NULL;

    if (queue->rear == NULL) {
        queue->front = queue->rear = newNode;
    } else {
        queue->rear->next = newNode;
        queue->rear = newNode;
    }
    queue->size++;

    pthread_cond_signal(&queue->not_empty);
    pthread_mutex_unlock(&queue->lock);
}

int dequeue(MessageQueue* queue, NetMessage* message) {
    pthread_mutex_lock(&queue->lock);
    while (queue->size == 0) {
        pthread_cond_wait(&queue->not_empty, &queue->lock);
    }

    if (queue->front == NULL) {
        pthread_mutex_unlock(&queue->lock);
        return -1; // Queue is empty
    }

    Node* temp = queue->front;
    *message = temp->message;
    queue->front = temp->next;
    if (queue->front == NULL) {
        queue->rear = NULL;
    }
    free(temp);
    queue->size--;

    pthread_cond_signal(&queue->not_full);
    pthread_mutex_unlock(&queue->lock);

    return 0; // Success
}
