#include <string.h>
#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>

#define MAX_IP_LEN 16

typedef struct {
    u_char ip[MAX_IP_LEN];
} IPAddress;

int resolve_hostname(const char *hostname, IPAddress *ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return -1;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in *ipv4 = (struct sockaddr_in *)p->ai_addr;
            inet_ntop(AF_INET, &(ipv4->sin_addr), ip_address->ip, INET_ADDRSTRLEN);
            freeaddrinfo(res); // Free the linked list
            return 0;
        }
    }

    freeaddrinfo(res); // Free the linked list if no IPv4 address found
    fprintf(stderr, "No valid IP address found for hostname\n");
    return -1;
}

int main() {
    IPAddress ip_address;
    const char *hostname = "example.com";

    if (resolve_hostname(hostname, &ip_address) == 0) {
        printf("IP Address: %s\n", ip_address.ip);
    } else {
        printf("Failed to resolve hostname\n");
    }

    return 0;
}
