#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the NetworkNode structure
typedef struct NetworkNode {
    int id;
    float x, y; // Location coordinates
    struct PeerNode *peers;
    int peerCount;
} NetworkNode;

// Define the PeerNode structure
typedef struct PeerNode {
    int nodeId;
    struct PeerNode *next;
} PeerNode;

// Function to add a new network node
void addNetworkNode(NetworkNode **nodes, int id, float x, float y) {
    NetworkNode *newNode = (NetworkNode *)malloc(sizeof(NetworkNode));
    newNode->id = id;
    newNode->x = x;
    newNode->y = y;
    newNode->peers = NULL;
    newNode->peerCount = 0;

    // Add the new node to the list
    if (*nodes == NULL) {
        *nodes = newNode;
    } else {
        NetworkNode *current = *nodes;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }
}

// Function to update an existing network node
void updateNetworkNode(NetworkNode **nodes, int id, float x, float y) {
    NetworkNode *current = *nodes;
    while (current != NULL) {
        if (current->id == id) {
            current->x = x;
            current->y = y;
            return;
        }
        current = current->next;
    }
}

// Function to add a peer connection between two nodes
void addPeerConnection(NetworkNode **nodes, int nodeId1, int nodeId2) {
    NetworkNode *node1 = *nodes;
    while (node1 != NULL && node1->id != nodeId1) {
        node1 = node1->next;
    }

    NetworkNode *node2 = *nodes;
    while (node2 != NULL && node2->id != nodeId2) {
        node2 = node2->next;
    }

    if (node1 != NULL && node2 != NULL) {
        PeerNode *newPeer = (PeerNode *)malloc(sizeof(PeerNode));
        newPeer->nodeId = nodeId2;
        newPeer->next = node1->peers;
        node1->peers = newPeer;
        node1->peerCount++;

        newPeer = (PeerNode *)malloc(sizeof(PeerNode));
        newPeer->nodeId = nodeId1;
        newPeer->next = node2->peers;
        node2->peers = newPeer;
        node2->peerCount++;
    }
}

// Function to free the memory allocated for network nodes
void freeNetworkNodes(NetworkNode *nodes) {
    NetworkNode *current = nodes;
    while (current != NULL) {
        PeerNode *tempPeer = current->peers;
        while (tempPeer != NULL) {
            PeerNode *nextPeer = tempPeer->next;
            free(tempPeer);
            tempPeer = nextPeer;
        }
        NetworkNode *nextNode = current->next;
        free(current);
        current = nextNode;
    }
}

int main() {
    NetworkNode *networkNodes = NULL;

    // Add network nodes
    addNetworkNode(&networkNodes, 1, 0.0, 0.0);
    addNetworkNode(&networkNodes, 2, 1.0, 1.0);
    addNetworkNode(&networkNodes, 3, 2.0, 2.0);

    // Add peer connections
    addPeerConnection(&networkNodes, 1, 2);
    addPeerConnection(&networkNodes, 2, 3);
    addPeerConnection(&networkNodes, 3, 1);

    // Update a network node
    updateNetworkNode(&networkNodes, 2, 1.5, 1.5);

    // Free the allocated memory
    freeNetworkNodes(networkNodes);

    return 0;
}
