#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    pthread_mutex_t lock;
} NFAPI_LINKED_LIST_T;

NFAPI_LINKED_LIST_T* create_linked_list() {
    NFAPI_LINKED_LIST_T *list = (NFAPI_LINKED_LIST_T*)malloc(sizeof(NFAPI_LINKED_LIST_T));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(NFAPI_LINKED_LIST_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node) return NULL;
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->next = NULL;
    return node;
}

void insert_node(NFAPI_LINKED_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *new_node = create_node(RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

NFAPI_CRC_INDICATION_PDU_T* find_node(NFAPI_LINKED_LIST_T *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current && current->RNTI != RNTI) {
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return current;
}

void remove_node(NFAPI_LINKED_LIST_T *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    NFAPI_CRC_INDICATION_PDU_T *prev = NULL;
    while (current && current->RNTI != RNTI) {
        prev = current;
        current = current->next;
    }
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (prev) {
        prev->next = current->next;
    } else {
        list->head = current->next;
    }
    free(current);
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(NFAPI_LINKED_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (!file) return;

    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        fwrite(&current->RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        fwrite(&current->RNTI, sizeof(int), 1, file);
        fwrite(&current->CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
        current = current->next;
    }

    fclose(file);
}

void deserialize_list(NFAPI_LINKED_LIST_T *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) return;

    while (1) {
        int RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG;
        size_t result = fread(&RX_UE_INFORMATION_TAG, sizeof(int), 1, file);
        if (result != 1) break;
        result = fread(&RNTI, sizeof(int), 1, file);
        if (result != 1) break;
        result = fread(&CRC_INDICATION_REL8_TAG, sizeof(int), 1, file);
        if (result != 1) break;

        insert_node(list, RX_UE_INFORMATION_TAG, RNTI, CRC_INDICATION_REL8_TAG);
    }

    fclose(file);
}

int validate_list(NFAPI_LINKED_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        if (current->RX_UE_INFORMATION_TAG < 0 || current->RNTI < 0 || current->CRC_INDICATION_REL8_TAG != 0 && current->CRC_INDICATION_REL8_TAG != 1) {
            pthread_mutex_unlock(&list->lock);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 1;
}
