#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/pbkdf2.h>
#include <string.h>

#define SALT_LEN 16
#define IV_LEN 16

typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char key[32];
} AESCipher;

int init_cipher(AESCipher *cipher, const char *password, size_t password_len, int mode) {
    unsigned char salt[SALT_LEN];
    if (!RAND_bytes(salt, SALT_LEN)) return -1;

    if (PBKDF2_HMAC_SHA256((unsigned char *)password, password_len, salt, SALT_LEN, 10000, cipher->key, sizeof(cipher->key)) != 1) {
        return -1;
    }

    EVP_CIPHER *evp_cipher = NULL;
    switch (mode) {
        case AES_128_CBC:
            evp_cipher = EVP_aes_128_cbc();
            break;
        case AES_256_CBC:
            evp_cipher = EVP_aes_256_cbc();
            break;
        case AES_192_CBC:
            evp_cipher = EVP_aes_192_cbc();
            break;
        default:
            return -1;
    }

    if (!(cipher->ctx = EVP_CIPHER_CTX_new())) return -1;

    if (EVP_EncryptInit_ex(cipher->ctx, evp_cipher, NULL, cipher->key, salt) != 1) {
        EVP_CIPHER_CTX_free(cipher->ctx);
        return -1;
    }

    return 0;
}

