#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct LTE_PDCP_PDU {
    uint32_t TEID;
    uint16_t SN;
    char* payload;
    size_t payload_size;
} LTE_PDCP_PDU;

typedef struct Node {
    LTE_PDCP_PDU data;
    struct Node* next;
} Node;

typedef struct LinkedList {
    Node* head;
    pthread_mutex_t lock;
} LinkedList;

LinkedList* create_linked_list() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_linked_list(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current->data.payload);
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void insert_node(LinkedList* list, LTE_PDCP_PDU data) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = data;
    new_node->next = list->head;
    list->head = new_node;
    pthread_mutex_unlock(&list->lock);
}

void delete_node(LinkedList* list, uint32_t TEID) {
    pthread_mutex_lock(&list->lock);
    Node* current = list->head;
    Node* prev = NULL;
    while (current) {
        if (current->data.TEID == TEID) {
            if (prev) {
                prev->next = current->next;
            } else {
                list->head = current->next;
            }
            free(current->data.payload);
            free(current);
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_linked_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;

    Node* current = list->head;
    while (current) {
        fwrite(&current->data.TEID, sizeof(uint32_t), 1, file);
        fwrite(&current->data.SN, sizeof(uint16_t), 1, file);
        fwrite(current->data.payload, sizeof(char), current->data.payload_size, file);
        current = current->next;
    }

    fclose(file);
}

void deserialize_linked_list(LinkedList* list, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;

    uint32_t TEID;
    uint16_t SN;
    size_t payload_size;
    char* payload;

    while (fread(&TEID, sizeof(uint32_t), 1, file)) {
        fread(&SN, sizeof(uint16_t), 1, file);
        fread(&payload_size, sizeof(size_t), 1, file);

        payload = (char*)malloc(payload_size);
        if (!payload) continue;

        fread(payload, sizeof(char), payload_size, file);

        LTE_PDCP_PDU data = {TEID, SN, payload, payload_size};
        insert_node(list, data);
    }

    fclose(file);
}
