import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.concurrent.*;

public class CommandExecutor {

    private static final Logger logger = LoggerFactory.getLogger(CommandExecutor.class);
    private ExecutorService executorService;

    public CommandExecutor(int maxThreads) {
        this.executorService = Executors.newFixedThreadPool(maxThreads, new ThreadFactory() {
            @Override
            public Thread newThread(Runnable r) {
                Thread thread = new Thread(r);
                thread.setDaemon(true);
                return thread;
            }
        });
    }

    public void executeCommand(String command, long timeout, TimeUnit unit) throws InterruptedException, ExecutionException, TimeoutException {
        Future<String> future = executorService.submit(() -> {
            Process process = Runtime.getRuntime().exec(command);
            StringBuilder output = new StringBuilder();
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()))) {
                String line;
                while ((line = reader.readLine()) != null) {
                    output.append(line).append("\n");
                }
            } catch (IOException e) {
                logger.error("Error reading command output", e);
            }
            int exitCode = process.waitFor();
            return "Exit Code: " + exitCode + "\nOutput:\n" + output.toString();
        });

        try {
            String result = future.get(timeout, unit);
            logger.info(result);
        } catch (TimeoutException e) {
            future.cancel(true);
            logger.warn("Command execution timed out");
        }
    }

    public void shutdown() {
        executorService.shutdown();
        try {
            if (!executorService.awaitTermination(60, TimeUnit.SECONDS)) {
                executorService.shutdownNow();
            }
        } catch (InterruptedException e) {
            executorService.shutdownNow();
        }
    }

    public static void main(String[] args) {
        CommandExecutor executor = new CommandExecutor(10);
        try {
            executor.executeCommand("ls -la", 5, TimeUnit.SECONDS);
        } catch (Exception e) {
            logger.error("Error executing command", e);
        } finally {
            executor.shutdown();
        }
    }
}
```

This code snippet provides a basic structure for a Java application that executes system commands using `Runtime.getRuntime().exec()`. It includes a fixed thread pool for managing concurrent command executions, a timeout mechanism to handle signal interrupts gracefully, and a simple logging framework. The `executeCommand` method submits tasks to the executor service, waits for their completion with a specified timeout, and handles exceptions appropriately. The `shutdown` method ensures proper termination of the executor service when the application is closing.']

