void initRecordCollection(RecordCollection* collection, size_t initialCapacity) {
    collection->records = (Record*)malloc(initialCapacity * sizeof(Record));
    if (collection->records == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    collection->count = 0;
    collection->capacity = initialCapacity;
}

void freeRecordCollection(RecordCollection* collection) {
    free(collection->records);
    collection->records = NULL;
    collection->count = 0;
    collection->capacity = 0;
}

int addRecord(RecordCollection* collection, int value, int key, size_t offset) {
    if (collection->count >= collection->capacity) {
        size_t newCapacity = collection->capacity == 0 ? 1 : collection->capacity * 2;
        Record* newRecords = (Record*)realloc(collection->records, newCapacity * sizeof(Record));
        if (newRecords == NULL) {
            fprintf(stderr, "Memory reallocation failed\n");
            return -1;
        }
        collection->records = newRecords;
        collection->capacity = newCapacity;
    }
    collection->records[collection->count].value = value;
    collection->records[collection->count].key = key;
    collection->records[collection->count].offset = offset;
    collection->count++;
    return 0;
}

int updateRecord(RecordCollection* collection, int key, int newValue) {
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            collection->records[i].value = newValue;
            return 0;
        }
    }
    return -1;
}

int deleteRecord(RecordCollection* collection, int key) {
    for (size_t i = 0; i < collection->count; i++) {
        if (collection->records[i].key == key) {
            memmove(&collection->records[i], &collection->records[i + 1], (collection->count - i - 1) * sizeof(Record));
            collection->count--;
            return 0;
        }
    }
    return -1;
}

