    *dataSize = collection->count * sizeof(Record);
    *serializedData = (char*)malloc(*dataSize);
    if (*serializedData == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }
    memcpy(*serializedData, collection->records, *dataSize);
    return 0;
}

