int addEntry(DynamicArray *array, NFAPI_CRC_INDICATION_PDU_T entry) {
    pthread_mutex_lock(&array->mutex);
    if (array->count >= MAX_ENTRIES) {
        pthread_mutex_unlock(&array->mutex);
        return -1; // Array is full
    }
    array->entries[array->count++] = entry;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int updateEntry(DynamicArray *array, int RNTI, NFAPI_CRC_INDICATION_PDU_T newEntry) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->count; i++) {
        if (array->entries[i].RNTI == RNTI) {
            array->entries[i] = newEntry;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Entry not found
}

int removeEntry(DynamicArray *array, int RNTI) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->count; i++) {
        if (array->entries[i].RNTI == RNTI) {
            memmove(&array->entries[i], &array->entries[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->count - i - 1));
            array->count--;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1; // Entry not found
