        fprintf(stderr, "Error: Memory allocation failed.\n");
        return -1;
    }

    srand(time(NULL)); // Seed for random number generation

    int uniqueRNTIs[MAX_STRUCTURES] = {0};
    int count = 0;

    while (count < requestedCount && count < MAX_STRUCTURES) {
        unsigned short rnti = rand() % 65536;
        if (!uniqueRNTIs[rnti]) {
            uniqueRNTIs[rnti] = 1;
            (*outputArray)[count].RX_UE_INFORMATION_TAG = count + 1;
            (*outputArray)[count].RNTI = rnti;
            (*outputArray)[count].CRC_INDICATION_REL8_TAG = rand() % 2; // Randomly set CRCFLAG
            (*outputArray)[count].timestamp = time(NULL);
            count++;
        }
