typedef struct {
    time_t timestamp;
    int session_id;
    char event_type[50];
} Message;

typedef struct {
    Message* messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} MessageQueue;

void init_message_queue(MessageQueue* queue, size_t initial_capacity) {
    queue->messages = (Message*)malloc(initial_capacity * sizeof(Message));
    if (!queue->messages) {
        fprintf(stderr, "Failed to allocate memory for message queue\n");
        exit(EXIT_FAILURE);
    }
    queue->capacity = initial_capacity;
    queue->count = 0;
    pthread_mutex_init(&queue->mutex, NULL);
    pthread_cond_init(&queue->cond, NULL);
}

void enqueue_message(MessageQueue* queue, Message msg) {
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == queue->capacity) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    if (queue->count < queue->capacity) {
        queue->messages[queue->count++] = msg;
        pthread_cond_signal(&queue->cond);
    }
    pthread_mutex_unlock(&queue->mutex);
}

Message dequeue_message(MessageQueue* queue) {
    Message msg = {0};
    pthread_mutex_lock(&queue->mutex);
    while (queue->count == 0) {
        pthread_cond_wait(&queue->cond, &queue->mutex);
    }
    if (queue->count > 0) {
        msg = queue->messages[--queue->count];
        pthread_cond_signal(&queue->cond);
    }
    pthread_mutex_unlock(&queue->mutex);
    return msg;
}

void destroy_message_queue(MessageQueue* queue) {
    free(queue->messages);
    pthread_mutex_destroy(&queue->mutex);
    pthread_cond_destroy(&queue->cond);
}
