    NFAPI_CRC_INDICATION_PDU_T *value;
    struct HashTableEntry *next;
} HashTableEntry;

typedef struct {
    HashTableEntry **buckets;
    size_t size, count;
    pthread_mutex_t lock;
} HashTable;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T *node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    node->RNTI = RNTI;
    node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    node->prev = node->next = NULL;
    return node;
}

void hash_table_init(HashTable *ht, size_t size) {
    ht->buckets = (HashTableEntry**)calloc(size, sizeof(HashTableEntry*));
    ht->size = size;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);
}

unsigned int hash_function(int key, size_t size) {
    return abs(key % size);
}

void hash_table_insert(HashTable *ht, NFAPI_CRC_INDICATION_PDU_T *node) {
    unsigned int index = hash_function(node->RNTI, ht->size);
    pthread_mutex_lock(&ht->lock);
    node->next = ht->buckets[index];
    if (ht->buckets[index]) ht->buckets[index]->prev = node;
    ht->buckets[index] = node;
    ht->count++;
    pthread_mutex_unlock(&ht->lock);
}

NFAPI_CRC_INDICATION_PDU_T* hash_table_lookup(HashTable *ht, int RNTI) {
    unsigned int index = hash_function(RNTI, ht->size);
    pthread_mutex_lock(&ht->lock);
    HashTableEntry *entry = ht->buckets[index];
    while (entry) {
        if (entry->value->RNTI == RNTI) {
            pthread_mutex_unlock(&ht->lock);
            return entry->value;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->lock);
    return NULL;
}

void hash_table_remove(HashTable *ht, int RNTI) {
    unsigned int index = hash_function(RNTI, ht->size);
    pthread_mutex_lock(&ht->lock);
    HashTableEntry *entry = ht->buckets[index];
    while (entry) {
        if (entry->value->RNTI == RNTI) {
            if (entry->prev) entry->prev->next = entry->next;
            if (entry->next) entry->next->prev = entry->prev;
            free(entry);
            ht->count--;
            break;
        }
        entry = entry->next;
    }
    pthread_mutex_unlock(&ht->lock);
}

void hash_table_destroy(HashTable *ht) {
    for (size_t i = 0; i < ht->size; i++) {
        HashTableEntry *entry = ht->buckets[i];
        while (entry) {
            HashTableEntry *next = entry->next;
            free(entry);
            entry = next;
        }
    }
    free(ht->buckets);
    pthread_mutex_destroy(&ht->lock);
}

