bool addFrame(FrameList* list, NFAPI_RX_FRAME_PDU_T frame) {
    pthread_mutex_lock(&list->lock);
    FrameNode* newNode = (FrameNode*)malloc(sizeof(FrameNode));
    if (!newNode) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    newNode->frame = frame;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->lock);
    return true;
}

