#define MAX_CONNECTIONS 100000

typedef struct {
    int UE_ID;
    int CELL_ID;
    char *DATA_CONTENT;
    size_t DATA_LENGTH;
} UE_CONNECTION_RECORD;

typedef struct {
    UE_CONNECTION_RECORD *records;
    size_t count;
    size_t capacity;
} ConnectionManager;

ConnectionManager* create_connection_manager() {
    ConnectionManager *manager = (ConnectionManager*)malloc(sizeof(ConnectionManager));
    manager->records = NULL;
    manager->count = 0;
    manager->capacity = 0;
    return manager;
}

void destroy_connection_manager(ConnectionManager *manager) {
    for (size_t i = 0; i < manager->count; ++i) {
        free(manager->records[i].DATA_CONTENT);
    }
    free(manager->records);
    free(manager);
}

int add_connection(ConnectionManager *manager, int UE_ID, int CELL_ID, const char *DATA_CONTENT, size_t DATA_LENGTH) {
    if (manager->count >= manager->capacity) {
        size_t new_capacity = manager->capacity == 0 ? 1 : manager->capacity * 2;
        UE_CONNECTION_RECORD *new_records = realloc(manager->records, new_capacity * sizeof(UE_CONNECTION_RECORD));
        if (!new_records) return -1; // Memory allocation failed
        manager->records = new_records;
        manager->capacity = new_capacity;
    }
    manager->records[manager->count].UE_ID = UE_ID;
    manager->records[manager->count].CELL_ID = CELL_ID;
    manager->records[manager->count].DATA_CONTENT = (char*)malloc(DATA_LENGTH + 1);
    if (!manager->records[manager->count].DATA_CONTENT) return -1; // Memory allocation failed
    strncpy(manager->records[manager->count].DATA_CONTENT, DATA_CONTENT, DATA_LENGTH);
    manager->records[manager->count].DATA_CONTENT[DATA_LENGTH] = '\0';
    manager->records[manager->count].DATA_LENGTH = DATA_LENGTH;
    ++manager->count;
    return 0;
}

int update_connection(ConnectionManager *manager, int UE_ID, const char *new_DATA_CONTENT, size_t new_DATA_LENGTH) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].UE_ID == UE_ID) {
            free(manager->records[i].DATA_CONTENT);
            manager->records[i].DATA_CONTENT = (char*)realloc(manager->records[i].DATA_CONTENT, new_DATA_LENGTH + 1);
            if (!manager->records[i].DATA_CONTENT) return -1; // Memory allocation failed
            strncpy(manager->records[i].DATA_CONTENT, new_DATA_CONTENT, new_DATA_LENGTH);
            manager->records[i].DATA_CONTENT[new_DATA_LENGTH] = '\0';
            manager->records[i].DATA_LENGTH = new_DATA_LENGTH;
            return 0;
        }
    }
    return -1; // UE_ID not found
}

int remove_connection(ConnectionManager *manager, int UE_ID) {
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->records[i].UE_ID == UE_ID) {
            free(manager->records[i].DATA_CONTENT);
            for (size_t j = i; j < manager->count - 1; ++j) {
                manager->records[j] = manager->records[j + 1];
            }
            --manager->count;
            return 0;
        }
    }
    return -1; // UE_ID not found
}
