void add_entry(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    if (current_index >= array_size) {
        NFAPI_CRC_INDICATION_PDU_T* new_array = realloc(dynamic_array, (array_size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_array == NULL) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(1);
        }
        dynamic_array = new_array;
        array_size++;
    }
    dynamic_array[current_index].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    dynamic_array[current_index].RNTI = RNTI;
    dynamic_array[current_index].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    current_index++;
}

void update_entry(int RNTI, int new_CRC_INDICATION_REL8_TAG) {
    for (int i = 0; i < current_index; i++) {
        if (dynamic_array[i].RNTI == RNTI) {
            dynamic_array[i].CRC_INDICATION_REL8_TAG = new_CRC_INDICATION_REL8_TAG;
            return;
        }
    }
    fprintf(stderr, "Entry with RNTI %d not found\n", RNTI);
}

void remove_entry(int RNTI) {
    for (int i = 0; i < current_index; i++) {
        if (dynamic_array[i].RNTI == RNTI) {
            for (int j = i; j < current_index - 1; j++) {
                dynamic_array[j] = dynamic_array[j + 1];
            }
            current_index--;
            return;
        }
    }
    fprintf(stderr, "Entry with RNTI %d not found\n", RNTI);
}

void free_memory() {
    if (dynamic_array != NULL) {
        free(dynamic_array);
        dynamic_array = NULL;
        array_size = 0;
        current_index = 0;
    }
}
