#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_ELEMENTS 1024

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements[MAX_ELEMENTS];
    size_t count;
    pthread_mutex_t lock;
    uint32_t rolling_checksum;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T crc_list = {0};

void init_crc_list() {
    pthread_mutex_init(&crc_list.lock, NULL);
}

int add_to_crc_list(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&crc_list.lock);
    if (crc_list.count >= MAX_ELEMENTS) {
        pthread_mutex_unlock(&crc_list.lock);
        return -1; // List is full
    }
    crc_list.elements[crc_list.count++] = pdu;
    crc_list.rolling_checksum += pdu->crc_indication.crcflag;
    pthread_mutex_unlock(&crc_list.lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* get_from_crc_list(size_t index) {
    if (index >= crc_list.count) {
        return NULL; // Index out of bounds
    }
    return crc_list.elements[index];
}

void update_crc_flag(NFAPI_CRC_INDICATION_PDU_T *pdu, uint8_t new_crcflag) {
    pthread_mutex_lock(&crc_list.lock);
    crc_list.rolling_checksum -= pdu->crc_indication.crcflag;
    pdu->crc_indication.crcflag = new_crcflag;
    crc_list.rolling_checksum += new_crcflag;
    pthread_mutex_unlock(&crc_list.lock);
}

void destroy_crc_list() {
    pthread_mutex_lock(&crc_list.lock);
    for (size_t i = 0; i < crc_list.count; ++i) {
        free(crc_list.elements[i]);
    }
    crc_list.count = 0;
    pthread_mutex_unlock(&crc_list.lock);
    pthread_mutex_destroy(&crc_list.lock);
}
```

