#include <time.h>
#include <pthread.h>

#define MAX_ELEMENTS 1024
#define MAX_RETRIES 5

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    pthread_mutex_t mutex;
} LinkedList;

LinkedList* createList() {
    LinkedList* list = (LinkedList*)malloc(sizeof(LinkedList));
    if (!list) return NULL;
    list->head = NULL;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void freeList(LinkedList* list) {
    Node* current = list->head;
    while (current) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int insertElement(LinkedList* list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    Node* newNode = (Node*)malloc(sizeof(Node));
    if (!newNode) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    newNode->data = element;
    newNode->next = list->head;
    list->head = newNode;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int main() {
    LinkedList* list = createList();
    if (!list) {
        fprintf(stderr, "Failed to create list\n");
        return 1;
    }

    srand(time(NULL));
    for (int i = 0; i < MAX_ELEMENTS; ++i) {
        NFAPI_CRC_INDICATION_PDU_T element;
        element.RX_UE_INFORMATION_TAG = rand();
        element.RNTI = (uint16_t)(rand() % 65536);
        element.CRCFLAG = (uint8_t)(rand() % 2);

        if (insertElement(list, element) != 0) {
            fprintf(stderr, "Failed to insert element\n");
            freeList(list);
            return 1;
        }
    }

    freeList(list);
    return 0;
}
