async function insertWidgets(widgets, containerId) {
    const container = document.getElementById(containerId);
    if (!container) {
        console.error('Container element not found');
        return { success: false, message: 'Container element not found' };
    }

    let allSuccess = true;
    for (const widget of widgets) {
        try {
            const html = await generateWidgetHTML(widget);
            container.innerHTML += html;
        } catch (error) {
            console.error(`Failed to insert widget: ${error.message}`);
            allSuccess = false;
        }
    }

    return { success: allSuccess, message: allSuccess ? 'All widgets inserted successfully' : 'Some widgets failed to insert' };
}

async function generateWidgetHTML(widget) {
    // Simulate fetching data from an external API
    const response = await fetch('https://api.example.com/widgets', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(widget)
    });

    if (!response.ok) {
        throw new Error(`Failed to fetch widget data: ${response.statusText}`);
    }

    const data = await response.json();
    // Simulate rendering the widget HTML
    return `<div class="widget" id="${data.id}">${data.content}</div>`;
}
