typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

int hash_function(int tag, int rnti) {
    return (tag * 31 + rnti) % 1000; // Simplified hash function for demonstration
}

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate_array(int N, int* tags, int* rntis, int num_tags) {
    if (num_tags < N) {
        printf("Error: Not enough unique RX_UE_INFORMATION_TAG and RNTI combinations available.\n");
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    int retry_count = 0;
    while (retry_count < MAX_RETRIES) {
        for (int i = 0; i < N; ++i) {
            int tag_index = rand() % num_tags;
            array[i].RX_UE_INFORMATION_TAG = tags[tag_index];
            array[i].RNTI = rntis[tag_index];

            // Simulate API call with potential errors
            if (rand() % 10 == 0) { // 10% chance of failure
                printf("API call failed, retrying...\n");
                free(array);
                array = NULL;
                break;
            }

            array[i].CRCFLAG = hash_function(array[i].RX_UE_INFORMATION_TAG, array[i].RNTI);
        }
        if (array) {
            break;
        }
        retry_count++;
        sleep(retry_count * BACKOFF_FACTOR); // Exponential backoff
    }

    if (!array) {
        printf("Error: Failed to allocate and populate array after %d retries.\n", MAX_RETRIES);
    } else {
        printf("Array allocated and populated successfully.\n");
    }

    return array;
}

