    int tags[] = {10, 20, 30, 40, 50};
    int rntis[] = {100, 200, 300, 400, 500};
    int N = 3;

    NFAPI_CRC_INDICATION_PDU_T* array = allocate_and_populate_array(N, tags, rntis, sizeof(tags) / sizeof(tags[0]));
    if (array) {
        // Use the array as needed
        free(array);
    }

    return 0;
}
