#include <stdlib.h>
#include <pthread.h>

typedef enum {
    RRC_CONNECTED,
    RRC_IDLE
} RRCState;

typedef struct PDU {
    int pduId;
    // Other PDU fields
    time_t expirationTime;
    struct PDU *next;
} PDU;

typedef struct BufferList {
    PDU *head;
    pthread_mutex_t lock;
} BufferList;

typedef struct UEContext {
    int ueId;
    RRCState rrcState;
    BufferList bufferList;
} UEContext;

UEContext* initUEContext(int ueId, RRCState rrcState) {
    UEContext *ueContext = (UEContext*)malloc(sizeof(UEContext));
    if (!ueContext) return NULL;

    ueContext->ueId = ueId;
    ueContext->rrcState = rrcState;
    pthread_mutex_init(&ueContext->bufferList.lock, NULL);
    ueContext->bufferList.head = NULL;

    return ueContext;
}

void addPDU(UEContext *ueContext, int pduId, time_t expirationTime) {
    PDU *newPDU = (PDU*)malloc(sizeof(PDU));
    if (!newPDU) return;

    newPDU->pduId = pduId;
    newPDU->expirationTime = expirationTime;
    newPDU->next = NULL;

    pthread_mutex_lock(&ueContext->bufferList.lock);
    newPDU->next = ueContext->bufferList.head;
    ueContext->bufferList.head = newPDU;
    pthread_mutex_unlock(&ueContext->bufferList.lock);
}

void clearExpiredPDUs(UEContext *ueContext, time_t currentTime) {
    PDU *current = ueContext->bufferList.head;
    PDU *prev = NULL;

    while (current != NULL) {
        if (current->expirationTime < currentTime) {
            pthread_mutex_lock(&ueContext->bufferList.lock);
            if (prev == NULL) {
                ueContext->bufferList.head = current->next;
            } else {
                prev->next = current->next;
            }
            pthread_mutex_unlock(&ueContext->bufferList.lock);

            free(current);
            current = prev ? prev->next : NULL;
        } else {
            prev = current;
            current = current->next;
        }
    }
}

void destroyUEContext(UEContext *ueContext) {
    clearExpiredPDUs(ueContext, time(NULL));
    pthread_mutex_destroy(&ueContext->bufferList.lock);
    free(ueContext);
}
