    list->pdus = malloc(MAX_PDU_SIZE * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->count = 0;
    list->capacity = MAX_PDU_SIZE;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void destroy_pdu_list(PduList *list) {
    free(list->pdus);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

void add_pdu(PduList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    while (list->count == list->capacity) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    list->pdus[list->count++] = pdu;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
}

LogBuffer *create_log_buffer() {
    LogBuffer *buffer = malloc(sizeof(LogBuffer));
    buffer->head = 0;
    buffer->tail = 0;
    pthread_mutex_init(&buffer->log_mutex, NULL);
    pthread_cond_init(&buffer->log_cond, NULL);
    return buffer;
}

void destroy_log_buffer(LogBuffer *buffer) {
    pthread_mutex_destroy(&buffer->log_mutex);
    pthread_cond_destroy(&buffer->log_cond);
    free(buffer);
}

void log_entry(LogBuffer *buffer, const char *entry) {
    pthread_mutex_lock(&buffer->log_mutex);
    while ((buffer->tail + 1) % LOG_BUFFER_SIZE == buffer->head) {
        pthread_cond_wait(&buffer->log_cond, &buffer->log_mutex);
    }
    strcpy(buffer->buffer + (buffer->tail * sizeof(char)), entry);
    buffer->tail = (buffer->tail + 1) % LOG_BUFFER_SIZE;
    pthread_cond_signal(&buffer->log_cond);
    pthread_mutex_unlock(&buffer->log_mutex);
}

void flush_log(LogBuffer *buffer, FILE *file) {
    pthread_mutex_lock(&buffer->log_mutex);
    while (buffer->head != buffer->tail) {
        fprintf(file, "%s\n", buffer->buffer + (buffer->head * sizeof(char)));
        buffer->head = (buffer->head + 1) % LOG_BUFFER_SIZE;
    }
    pthread_mutex_unlock(&buffer->log_mutex);
}
