#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef enum {
    RRC_CONNECTED,
    RRC_IDLE
} RRCState;

typedef struct PDU {
    // Define the structure of a PDU object
    int pduId;
    time_t expirationTime;
    // Other fields as needed
} PDU;

typedef struct BufferList {
    PDU** pdus;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} BufferList;

typedef struct UEContext {
    int ueId;
    RRCState rrcState;
    BufferList bufferList;
} UEContext;

UEContext* initUEContext(int ueId, RRCState rrcState) {
    UEContext* context = (UEContext*)malloc(sizeof(UEContext));
    if (!context) return NULL;

    context->ueId = ueId;
    context->rrcState = rrcState;

    context->bufferList.capacity = 10;
    context->bufferList.size = 0;
    context->bufferList.pdus = (PDU**)malloc(context->bufferList.capacity * sizeof(PDU*));
    if (!context->bufferList.pdus) {
        free(context);
        return NULL;
    }

    pthread_mutex_init(&context->bufferList.lock, NULL);

    return context;
}

void addPDU(UEContext* context, PDU* pdu) {
    pthread_mutex_lock(&context->bufferList.lock);
    if (context->bufferList.size == context->bufferList.capacity) {
        // Resize the buffer list
        context->bufferList.capacity *= 2;
        context->bufferList.pdus = (PDU**)realloc(context->bufferList.pdus, context->bufferList.capacity * sizeof(PDU*));
    }
    context->bufferList.pdus[context->bufferList.size++] = pdu;
    pthread_mutex_unlock(&context->bufferList.lock);
}

void clearExpiredPDUs(UEContext* context, time_t currentTime) {
    pthread_mutex_lock(&context->bufferList.lock);
    for (size_t i = 0; i < context->bufferList.size;) {
        if (context->bufferList.pdus[i]->expirationTime <= currentTime) {
            free(context->bufferList.pdus[i]);
            memmove(&context->bufferList.pdus[i], &context->bufferList.pdus[i + 1], (context->bufferList.size - i - 1) * sizeof(PDU*));
            context->bufferList.size--;
        } else {
            i++;
        }
    }
    pthread_mutex_unlock(&context->bufferList.lock);
}

void freeUEContext(UEContext* context) {
    for (size_t i = 0; i < context->bufferList.size; i++) {
        free(context->bufferList.pdus[i]);
    }
    free(context->bufferList.pdus);
    pthread_mutex_destroy(&context->bufferList.lock);
    free(context);
}
