    int allocation_successes;
    int allocation_failures;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_ARRAY_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->size = 0;
    da->capacity = MAX_ARRAY_SIZE;
    pthread_mutex_init(&da->mutex, NULL);
    da->allocation_successes = 0;
    da->allocation_failures = 0;

    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->mutex);
        free(da);
    }
}

int add_to_array(DynamicArray *da, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        da->allocation_failures++;
        pthread_mutex_unlock(&da->mutex);
        return -1; // Array is full
    }

    da->array[da->size++] = pdu;
    da->allocation_successes++;

    pthread_mutex_unlock(&da->mutex);
    return 0;
}

void log_allocation_stats(DynamicArray *da) {
    printf("Allocation Successes: %d\n", da->allocation_successes);
    printf("Allocation Failures: %d\n", da->allocation_failures);
