#include <stdlib.h>
#include <pthread.h>

typedef struct PDUSession {
    int sessionId;
    // Other session data members
} PDUSession;

typedef struct UEContext {
    int ueId;
    int refCount;
    PDUSession** sessions;
    size_t numSessions;
    size_t maxSessions;
    pthread_mutex_t lock;
} UEContext;

typedef struct SessionManager {
    UEContext** ues;
    size_t numUES;
    size_t maxUES;
    pthread_mutex_t lock;
    int totalActiveSessions;
} SessionManager;

SessionManager* createSessionManager(size_t initialCapacity) {
    SessionManager* manager = (SessionManager*)malloc(sizeof(SessionManager));
    if (!manager) return NULL;

    manager->ues = (UEContext**)malloc(initialCapacity * sizeof(UEContext*));
    if (!manager->ues) {
        free(manager);
        return NULL;
    }

    manager->numUES = 0;
    manager->maxUES = initialCapacity;
    manager->totalActiveSessions = 0;
    pthread_mutex_init(&manager->lock, NULL);

    return manager;
}

void destroySessionManager(SessionManager* manager) {
    for (size_t i = 0; i < manager->numUES; ++i) {
        UEContext* ue = manager->ues[i];
        for (size_t j = 0; j < ue->numSessions; ++j) {
            free(ue->sessions[j]);
        }
        free(ue->sessions);
        pthread_mutex_destroy(&ue->lock);
        free(ue);
    }
    free(manager->ues);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

UEContext* createUEContext(int ueId, size_t initialSessionCapacity) {
    UEContext* ue = (UEContext*)malloc(sizeof(UEContext));
    if (!ue) return NULL;

    ue->ueId = ueId;
    ue->refCount = 1;
    ue->sessions = (PDUSession**)malloc(initialSessionCapacity * sizeof(PDUSession*));
    if (!ue->sessions) {
        free(ue);
        return NULL;
    }

    ue->numSessions = 0;
    ue->maxSessions = initialSessionCapacity;
    pthread_mutex_init(&ue->lock, NULL);

    return ue;
}

void destroyUEContext(UEContext* ue) {
    for (size_t i = 0; i < ue->numSessions; ++i) {
        free(ue->sessions[i]);
    }
    free(ue->sessions);
    pthread_mutex_destroy(&ue->lock);
    free(ue);
}

int addSessionToUE(SessionManager* manager, int ueId, PDUSession* session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->numUES; ++i) {
        if (manager->ues[i]->ueId == ueId) {
            pthread_mutex_lock(&manager->ues[i]->lock);
            if (manager->ues[i]->numSessions >= manager->ues[i]->maxSessions) {
                size_t newCapacity = manager->ues[i]->maxSessions * 2;
                PDUSession** newSessions = (PDUSession**)realloc(manager->ues[i]->sessions, newCapacity * sizeof(PDUSession*));
                if (!newSessions) {
                    pthread_mutex_unlock(&manager->ues[i]->lock);
                    pthread_mutex_unlock(&manager->lock);
                    return -1; // Memory allocation failed
                }
                manager->ues[i]->sessions = newSessions;
                manager->ues[i]->maxSessions = newCapacity;
            }
            manager->ues[i]->sessions[manager->ues[i]->numSessions++] = session;
            manager->totalActiveSessions++;
            pthread_mutex_unlock(&manager->ues[i]->lock);
            pthread_mutex_unlock(&manager->lock);
            return 0; // Session added successfully
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // UEContext not found
}

int removeSessionFromUE(SessionManager* manager, int ueId, PDUSession* session) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->numUES; ++i) {
        if (manager->ues[i]->ueId == ueId) {
            pthread_mutex_lock(&manager->ues[i]->lock);
            for (size_t j = 0; j < manager->ues[i]->numSessions; ++j) {
                if (manager->ues[i]->sessions[j] == session) {
                    free(session); // Assuming PDUSession is dynamically allocated
                    for (; j + 1 < manager->ues[i]->numSessions; ++j) {
                        manager->ues[i]->sessions[j] = manager->ues[i]->sessions[j + 1];
                    }
                    manager->ues[i]->numSessions--;
                    manager->totalActiveSessions--;
                    pthread_mutex_unlock(&manager->ues[i]->lock);
                    pthread_mutex_unlock(&manager->lock);
                    return 0; // Session removed successfully
                }
            }
            pthread_mutex_unlock(&manager->ues[i]->lock);
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}

int updateSessionInUE(SessionManager* manager, int ueId, PDUSession* oldSession, PDUSession* newSession) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->numUES; ++i) {
        if (manager->ues[i]->ueId == ueId) {
            pthread_mutex_lock(&manager->ues[i]->lock);
            for (size_t j = 0; j < manager->ues[i]->numSessions; ++j) {
                if (manager->ues[i]->sessions[j] == oldSession) {
                    free(oldSession); // Assuming PDUSession is dynamically allocated
                    manager->ues[i]->sessions[j] = newSession;
                    pthread_mutex_unlock(&manager->ues[i]->lock);
                    pthread_mutex_unlock(&manager->lock);
                    return 0; // Session updated successfully
                }
            }
            pthread_mutex_unlock(&manager->ues[i]->lock);
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Session not found
}
