    queue->pool_size = pool_size;
    queue->used_count = 0;
    queue->messages = (NFAPI_MESSAGE_T *)malloc(pool_size * sizeof(NFAPI_MESSAGE_T));
    pthread_mutex_init(&queue->lock, NULL);
}

