    free(queue->messages);
    pthread_mutex_destroy(&queue->lock);
}

NFAPI_MESSAGE_T *allocate_message(MessageQueue *queue) {
    NFAPI_MESSAGE_T *message = NULL;
    pthread_mutex_lock(&queue->lock);
    if (queue->used_count < queue->pool_size) {
        message = &queue->messages[queue->used_count++];
    }
    pthread_mutex_unlock(&queue->lock);
    return message;
}

void deallocate_message(MessageQueue *queue, NFAPI_MESSAGE_T *message) {
    pthread_mutex_lock(&queue->lock);
    // Assuming messages are allocated in order and can be freed in any order
    for (size_t i = 0; i < queue->used_count; ++i) {
        if (&queue->messages[i] == message) {
            queue->used_count--;
            break;
