#include <openssl/evp.h>
#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int N;
    int priority;
    int timeout;
    double load_balance_factor;
} Config;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    // Add other necessary fields
} PduEntry;

PduEntry* populateNFAPCRCIndication(Config config) {
    PduEntry* pdus = (PduEntry*)malloc(config.N * sizeof(PduEntry));
    if (!pdus) return NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int created_pdus = 0;
    clock_t start_time = clock();

    for (int i = 0; i < config.N; i++) {
        pthread_mutex_lock(&mutex);
        while (created_pdus >= config.load_balance_factor * config.N) {
            pthread_cond_wait(&cond, &mutex);
        }
        pthread_mutex_unlock(&mutex);

        // Populate PDU entry
        pdus[i].pdu.RX_UE_INFORMATION_TAG = i;
        pdus[i].pdu.RNTI = rand() % 65536; // Random RNTI
        pdus[i].pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) ? 1 : 0;

        // Initialize cryptographic operations
        EVP_add_cipher(EVP_aes_256_cbc());
        EVP_add_digest(EVP_sha256());
        EVP_add_digest_alias("sha256", "SHA-256");

        created_pdus++;
    }

    clock_t end_time = clock();
    double average_time = (double)(end_time - start_time) / CLOCKS_PER_SEC / config.N;

    // Log statistics
    printf("Average time per PDU: %f seconds\n", average_time);

    return pdus;
}
