            memmove(&pdu_list.pdus[i], &pdu_list.pdus[i+1], sizeof(NFAPI_CRC_INDICATION_PDU_T*) * (pdu_list.size - i - 1));
            pdu_list.size--;
            pthread_mutex_unlock(&pdu_list.lock);
            return pdu;
