NFAPI_CRC_INDICATION_PDU_T* initialize_and_populate_array(int N, int buffer_size) {
    if (N > buffer_size) {
        return NULL; // Error: Array exceeds buffer capacity
    }

    NFAPI_CRC_INDICATION_PDU_T* array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        return NULL; // Error: Memory allocation failed
    }

    srand(time(NULL)); // Seed for random number generation

    int rnti_set[buffer_size] = {0}; // Track RNTI values to avoid conflicts
    int unique_rnti_count = 0;

    for (int i = 0; i < N; ++i) {
        while (1) {
            array[i].RNTI = rand() % buffer_size + 1; // Generate a random RNTI value
            if (!rnti_set[array[i].RNTI - 1]) {
                rnti_set[array[i].RNTI - 1] = 1;
                unique_rnti_count++;
                break;
            }
        }

        array[i].RX_UE_INFORMATION_TAG = rand() % buffer_size + 1; // Generate a random RX_UE_INFORMATION_TAG
        array[i].CRC_INDICATION_REL8_TAG = rand() % buffer_size + 1; // Generate a random CRC_INDICATION_REL8_TAG
        array[i].CRCFLAG = (rand() % 2) ? 0 : 1; // Randomly set CRCFLAG to 0 or 1

        if (unique_rnti_count == buffer_size) {
            free(array);
            return NULL; // Error: All RNTI values are used
        }
    }

    return array;
}
