    pthread_mutex_t lock;
} MemoryPool;

UEContext* createUEContext(int ueId, int initialCapacity) {
    UEContext* context = (UEContext*)malloc(sizeof(UEContext));
    if (!context) return NULL;

    context->ueId = ueId;
    context->refCount = 1;
    context->sessions = (PDUSession**)malloc(initialCapacity * sizeof(PDUSession*));
    if (!context->sessions) {
        free(context);
        return NULL;
    }
    context->numSessions = 0;
    context->maxSessions = initialCapacity;
    pthread_mutex_init(&context->lock, NULL);

    return context;
}

void destroyUEContext(UEContext* context) {
    for (int i = 0; i < context->numSessions; ++i) {
        free(context->sessions[i]);
    }
    free(context->sessions);
    pthread_mutex_destroy(&context->lock);
    free(context);
}

MemoryPool* createMemoryPool(size_t blockSize, size_t initialSize) {
    MemoryPool* pool = (MemoryPool*)malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->blockSize = blockSize;
    pool->poolSize = initialSize * blockSize;
    pool->usedSize = 0;
    pool->pool = malloc(pool->poolSize);
    if (!pool->pool) {
        free(pool);
        return NULL;
    }
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void* allocateFromPool(MemoryPool* pool) {
    void* block = NULL;
    pthread_mutex_lock(&pool->lock);
    if (pool->usedSize + pool->blockSize <= pool->poolSize) {
        block = ((char*)pool->pool) + pool->usedSize;
        pool->usedSize += pool->blockSize;
    }
    pthread_mutex_unlock(&pool->lock);

    return block;
}

void deallocateToPool(MemoryPool* pool, void* block) {
    // No-op for simplicity
}

// Additional functions for managing PDUSessions and handling concurrency would go here

int main() {
    // Example usage of the above functions
    UEContext* context = createUEContext(12345, 10);
    if (context) {
        // Manage PDUSessions and handle concurrency
        destroyUEContext(context);
    }

    MemoryPool* pool = createMemoryPool(sizeof(PDUSession), 100);
    if (pool) {
        // Allocate and deallocate memory from the pool
        deallocateToPool(pool, allocateFromPool(pool));
        free(pool);
    }

    return 0;
}
