NFAPI_CRC_INDICATION_PDU_T* populate_nfapi_pdu_list(int N, int timeout_ms) {
    static NFAPI_CRC_INDICATION_PDU_T pdu_buffer[1024];
    static int buffer_index = 0;
    static int last_rnti = -1;
    static clock_t start_time = 0;

    if (start_time == 0) {
        start_time = clock();
    }

    if (buffer_index >= N) {
        return pdu_buffer;
    }

    if ((clock() - start_time) * 1000 / CLOCKS_PER_SEC > timeout_ms) {
        log_error("Timeout reached while populating PDU list");
        return NULL;
    }

    int current_rnti = last_rnti;
    while (current_rnti == last_rnti) {
        current_rnti = rand() % 1024; // Simulate RNTI generation
    }
    last_rnti = current_rnti;

    pdu_buffer[buffer_index].rx_ue_info.tag = RX_UE_INFORMATION_TAG_VALUE;
    pdu_buffer[buffer_index].rnti = current_rnti;
    pdu_buffer[buffer_index].crc_indication.tag = CRC_INDICATION_REL8_TAG_VALUE;
    pdu_buffer[buffer_index].crc_indication.crcflag = rand() % 2; // Randomly set CRCFLAG

    buffer_index++;
    return populate_nfapi_pdu_list(N, timeout_ms);
}
