struct NFAPI_CRC_INDICATION_PDU_T {
    std::string RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
};

void populateNFAPIRecord(NFAPI_CRC_INDICATION_PDU_T& record, const std::string& target, const std::string& replacement) {
    // Populate the NFAPI record with valid data
    record.RX_UE_INFORMATION_TAG = "RX_UE_INFO";
    record.RNTI = rand() % 1024;
    record.CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1
}

void insertOrAppend(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, const std::string& target, const std::string& replacement) {
    auto it = list.begin();
    while (it != list.end()) {
        if (it->RX_UE_INFORMATION_TAG == target) {
            NFAPI_CRC_INDICATION_PDU_T newRecord;
            populateNFAPIRecord(newRecord, target, replacement);
            list.insert_after(it, newRecord);
            return;
        }
        ++it;
    }
    NFAPI_CRC_INDICATION_PDU_T newRecord;
    populateNFAPIRecord(newRecord, target, replacement);
    list.push_front(newRecord);
}

void processAndPopulateData(std::forward_list<NFAPI_CRC_INDICATION_PDU_T>& list, const std::string& target, const std::string& replacement, const std::string& configFilePath) {
    // Read configuration file and populate data
    std::ifstream configFile(configFilePath);
    int rangeStart, rangeEnd;
    int insertPosition;
    configFile >> rangeStart >> rangeEnd >> insertPosition;

    // Populate the record array with random integers and a random alphanumeric string
    NFAPI_CRC_INDICATION_PDU_T* recordArray = new NFAPI_CRC_INDICATION_PDU_T[10]; // Example size
    for (int i = 0; i < 10; ++i) {
        populateNFAPIRecord(recordArray[i], target, replacement);
        if (i == insertPosition) {
            recordArray[i].RX_UE_INFORMATION_TAG += std::to_string(rand() % 94 + 33); // Random alphanumeric string
        }
    }

    // Find and print the maximum integer from both arrays
    int maxInt = INT_MIN;
    for (auto& record : list) {
        if (record.RNTI > maxInt) {
            maxInt = record.RNTI;
        }
    }
    for (int i = 0; i < 10; ++i) {
        if (recordArray[i].RNTI > maxInt) {
            maxInt = recordArray[i].RNTI;
        }
    }
    std::cout << "Maximum integer: " << maxInt << std::endl;

    // Insert or append the replacement string
    insertOrAppend(list, target, replacement);

    // Free allocated memory
    delete[] recordArray;
}

int main() {
    std::forward_list<NFAPI_CRC_INDICATION_PDU_T> list;
    processAndPopulateData(list, "targetString", "replacementString", "config.txt");
    return 0;
}
