// Simulated external configuration service
class ConfigService {
public:
    static int getDefaultThroughput() { return 100; }
    static int getPerformanceThreshold() { return 80; }
};

// Smart pointer for managing network stats map entries
using NetworkStatsEntry = std::shared_ptr<std::vector<int>>;

// Function to update network statistics
void updateNetworkStatsMap(std::map<std::string, NetworkStatsEntry>& statsMap,
                           const std::string& targetInterface,
                           int performanceThreshold) {
    static std::mutex mapMutex;
    std::lock_guard<std::mutex> lock(mapMutex);

    // Retrieve default values from external configuration service
    int defaultThroughput = ConfigService::getDefaultThroughput();
    int maxThroughput = 150; // Example maximum throughput limit

    if (statsMap.find(targetInterface) == statsMap.end()) {
        // Add new entry with default metrics
        NetworkStatsEntry newEntry = std::make_shared<std::vector<int>>(3, defaultThroughput);
        statsMap[targetInterface] = newEntry;
    }

    NetworkStatsEntry& entry = statsMap[targetInterface];
    int currentLatency = (*entry)[2];

    // Simulate probabilistic delay to reflect network jitter
    if (std::rand() % 10 == 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }

    // Update throughput based on performance threshold and maximum limit
    int currentThroughput = (*entry)[1];
    if (currentThroughput < performanceThreshold) {
        (*entry)[1] = std::min(currentThroughput + 1, maxThroughput);
    } else {
        (*entry)[1] = currentThroughput;
    }

    // Update latency using a sliding window average
    const int windowSize = 5;
    if (entry->size() > windowSize) {
        entry->erase(entry->begin());
    }
    entry->push_back(currentLatency);
}

int main() {
    std::map<std::string, NetworkStatsEntry> networkStats;

    // Simulate updating network stats for a target interface
    updateNetworkStatsMap(networkStats, "eth0", ConfigService::getPerformanceThreshold());

    return 0;
}
