int allocate_and_initialize_pdus(int N, NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (N <= 0 || pdus == NULL) {
        errno = EINVAL;
        return -1;
    }

    size_t total_size = N * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (total_size > MAX_BUFFER_SIZE) {
        errno = ENOMEM;
        return -1;
