    *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(total_size);
    if (*pdus == NULL) {
        return -1;
    }

    for (int i = 0; i < N; ++i) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = i + 1; // Example initialization
        (*pdus)[i].RNTI = i * 2 + 1;              // Example initialization
        (*pdus)[i].CRC_INDICATION_REL8_TAG = i * 3 + 1; // Example initialization
    }

    return N;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T **pdus) {
    if (pdus != NULL && *pdus != NULL) {
        free(*pdus);
        *pdus = NULL;
    }
}
