    if (!list) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_mutex_lock(&mutex);

    srand(time(NULL));

    for (int i = 0; i < N; i++) {
        list[i].RX_UE_INFORMATION_TAG = rand() % 1000;
        int rnti;
        do {
            rnti = rand() % 1000;
        } while (is_rnti_duplicate(list, i, rnti));
        list[i].RNTI = rnti;

        if (enable_logging) {
            printf("Structure %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d\n", i, list[i].RX_UE_INFORMATION_TAG, list[i].RNTI);
        }

        list[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    pthread_mutex_unlock(&mutex);

    return list;
}

int is_rnti_duplicate(NFAPI_CRC_INDICATION_PDU_T* list, int index, int rnti) {
