using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;
using System.Threading.Tasks;

public class OrderProcessor
{
    private readonly JsonSchema _orderSchema;
    private readonly IOrderValidator _orderValidator;
    private readonly ILogger _logger;

    public OrderProcessor(JsonSchema orderSchema, IOrderValidator orderValidator, ILogger logger)
    {
        _orderSchema = orderSchema;
        _orderValidator = orderValidator;
        _logger = logger;
    }

    public async Task<List<Order>> ProcessOrdersAsync(string json)
    {
        try
        {
            var options = new JsonSerializerOptions { AllowTrailingCommas = true };
            var orders = JsonSerializer.Deserialize<List<Order>>(json, options);

            var validOrders = new List<Order>();

            foreach (var order in orders)
            {
                if (!JsonDocument.ParseValue(order.ToString()).Validate(_orderSchema))
                {
                    _logger.LogWarning($"Order {order.OrderId} failed schema validation.");
                    continue;
                }

                if (!_orderValidator.Validate(order))
                {
                    _logger.LogWarning($"Order {order.OrderId} failed business criteria.");
                    continue;
                }

                validOrders.Add(order);
            }

            return validOrders;
        }
        catch (JsonException ex)
        {
            _logger.LogError(ex, "Error deserializing JSON orders.");
            throw;
        }
    }
}

public class Order
{
    public string OrderId { get; set; }
    // Other properties...
