#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_CACHE_SIZE 1024

typedef struct {
    char method[16];
    char path[256];
    char query[256];
    unsigned int hash;
} HeaderEntry;

typedef struct {
    HeaderEntry entries[MAX_CACHE_SIZE];
    int size;
    pthread_mutex_t lock;
} Cache;

unsigned int compute_hash(const char *method, const char *path, const char *query) {
    // Simple hash function for demonstration purposes
    return (strlen(method) + strlen(path) + strlen(query)) % MAX_CACHE_SIZE;
}

Cache* create_cache() {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    cache->size = 0;
    pthread_mutex_init(&cache->lock, NULL);
    return cache;
}

void add_header(Cache *cache, const char *method, const char *path, const char *query) {
    pthread_mutex_lock(&cache->lock);
    if (cache->size >= MAX_CACHE_SIZE) {
        // Implement LRU eviction policy
        // For simplicity, we'll just overwrite the first entry
        cache->entries[0] = (HeaderEntry){.hash = compute_hash(method, path, query)};
        strcpy(cache->entries[0].method, method);
        strcpy(cache->entries[0].path, path);
        strcpy(cache->entries[0].query, query);
    } else {
        cache->entries[cache->size] = (HeaderEntry){.hash = compute_hash(method, path, query)};
        strcpy(cache->entries[cache->size].method, method);
        strcpy(cache->entries[cache->size].path, path);
        strcpy(cache->entries[cache->size].query, query);
        cache->size++;
    }
    pthread_mutex_unlock(&cache->lock);
}

HeaderEntry* get_header(Cache *cache, const char *method, const char *path, const char *query) {
    pthread_mutex_lock(&cache->lock);
    for (int i = 0; i < cache->size; i++) {
        if (cache->entries[i].hash == compute_hash(method, path, query) &&
            strcmp(cache->entries[i].method, method) == 0 &&
            strcmp(cache->entries[i].path, path) == 0 &&
            strcmp(cache->entries[i].query, query) == 0) {
            pthread_mutex_unlock(&cache->lock);
            return &cache->entries[i];
        }
    }
    pthread_mutex_unlock(&cache->lock);
    return NULL;
}

void free_cache(Cache *cache) {
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}
```

This code provides a basic implementation of a dynamic cache for HTTP request headers. It includes functions to create, add, and retrieve headers, as well as a simple LRU eviction policy when the cache reaches its maximum size. The use of a mutex ensures thread safety during concurrent access."]

