public class MessageProcessor
{
    private readonly ConcurrentQueue<string> _messageBuffer = new ConcurrentQueue<string>();
    private readonly object _lockObject = new object();
    private byte[] _currentKey;
    private byte[] _currentIV;

    public void ProcessBatch(string[] base64Messages)
    {
        Parallel.ForEach(base64Messages, async message =>
        {
            try
            {
                if (!IsValidBase64(message))
                {
                    LogError("Invalid Base64 format", message);
                    return;
                }

                byte[] decryptedMessage = await DecryptAsync(message);
                ValidateIntegrity(decryptedMessage);

                lock (_lockObject)
                {
                    _messageBuffer.Enqueue(Encoding.UTF8.GetString(decryptedMessage));
                }
            }
            catch (Exception ex)
            {
                LogError(ex.Message, message);
            }
        });
    }

    private async Task<byte[]> DecryptAsync(string base64Message)
    {
        byte[] encryptedBytes = Convert.FromBase64String(base64Message);

        using (TripleDES tripleDes = TripleDES.Create())
        {
            tripleDes.Key = _currentKey;
            tripleDes.IV = _currentIV;

            ICryptoTransform decryptor = tripleDes.CreateDecryptor(tripleDes.Key, tripleDes.IV);
            using (MemoryStream msDecrypt = new MemoryStream(encryptedBytes))
            {
                using (CryptoStream csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (MemoryStream msOutput = new MemoryStream())
                    {
                        await csDecrypt.CopyToAsync(msOutput);
                        return msOutput.ToArray();
                    }
                }
            }
        }
    }

    private void ValidateIntegrity(byte[] decryptedMessage)
    {
        // Implement integrity validation logic here
    }

    private bool IsValidBase64(string base64String)
    {
        try
        {
            Convert.FromBase64String(base64String);
            return true;
        }
        catch (FormatException)
        {
            return false;
        }
    }

    private void LogError(string errorMessage, string message)
    {
        // Implement logging logic here, including timestamp and context information
    }

    public void RotateKeysAndIVs(byte[] newKey, byte[] newIV)
    {
        lock (_lockObject)
        {
            _currentKey = newKey;
            _currentIV = newIV;

            SecurelyDisposeOldKeysAndIVs();
        }
    }

    private void SecurelyDisposeOldKeysAndIVs()
    {
        // Implement secure disposal of old keys and IVs
    }

    public string[] GetProcessedMessages(int batchSize)
    {
        lock (_lockObject)
        {
            var messages = new List<string>();
            while (messages.Count < batchSize && _messageBuffer.TryDequeue(out string message))
            {
                messages.Add(message);
            }
            return messages.ToArray();
        }
    }
}
