    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list(size_t initial_size) {
    if (initial_size > MAX_ELEMENTS || initial_size == 0) {
        return NULL;
    }

    NFAPI_CRC_LIST_T *list = malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) {
        return NULL;
    }

    list->elements = malloc(initial_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }

    list->count = 0;
    list->capacity = initial_size;
    pthread_mutex_init(&list->mutex, NULL);

    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list) {
        pthread_mutex_lock(&list->mutex);
        free(list->elements);
        pthread_mutex_unlock(&list->mutex);
        pthread_mutex_destroy(&list->mutex);
        free(list);
    }
}

int add_to_crc_list(NFAPI_CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (!list || !list->elements) {
        return -1;
    }

    pthread_mutex_lock(&list->mutex);

    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 16;
        if (new_capacity > MAX_ELEMENTS) {
            new_capacity = MAX_ELEMENTS;
        }

        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_elements) {
            pthread_mutex_unlock(&list->mutex);
            return -1;
        }

        list->elements = new_elements;
        list->capacity = new_capacity;
    }

    list->elements[list->count++] = pdu;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

