#include <stdlib.h>
#include <pthread.h>

typedef struct {
    // Define MAC_HEADER structure
} MAC_HEADER;

typedef struct {
    // Define MAC_PAYLOAD structure
} MAC_PAYLOAD;

typedef struct {
    MAC_HEADER header;
    MAC_PAYLOAD payload;
    time_t timestamp;
} MAC_PDU;

typedef struct {
    MAC_PDU* array;
    size_t capacity;
    size_t size;
    size_t total_bytes_used;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray* da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;

    da->array = (MAC_PDU*)calloc(initial_capacity, sizeof(MAC_PDU));
    if (!da->array) {
        free(da);
        return NULL;
    }

    da->capacity = initial_capacity;
    da->size = 0;
    da->total_bytes_used = 0;
    pthread_mutex_init(&da->mutex, NULL);

    return da;
}

void destroy_dynamic_array(DynamicArray* da) {
    if (da->array) free(da->array);
    pthread_mutex_destroy(&da->mutex);
    free(da);
}

int insert_mac_pdu(DynamicArray* da, MAC_PDU pdu) {
    pthread_mutex_lock(&da->mutex);

    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        MAC_PDU* new_array = (MAC_PDU*)realloc(da->array, new_capacity * sizeof(MAC_PDU));
        if (!new_array) {
            pthread_mutex_unlock(&da->mutex);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }

    da->array[da->size++] = pdu;
    da->total_bytes_used += sizeof(MAC_PDU);

    pthread_mutex_unlock(&da->mutex);
    return 0; // Success
}

int delete_mac_pdu(DynamicArray* da, size_t index) {
    pthread_mutex_lock(&da->mutex);

    if (index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return -1; // Invalid index
    }

    for (size_t i = index; i < da->size - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }

    da->size--;
    da->total_bytes_used -= sizeof(MAC_PDU);

    pthread_mutex_unlock(&da->mutex);
    return 0; // Success
}

MAC_PDU* get_mac_pdu(DynamicArray* da, size_t index) {
    pthread_mutex_lock(&da->mutex);

    if (index >= da->size) {
        pthread_mutex_unlock(&da->mutex);
        return NULL; // Invalid index
    }

    MAC_PDU* pdu = &da->array[index];
    pthread_mutex_unlock(&da->mutex);
    return pdu;
}

void set_max_size(DynamicArray* da, size_t new_capacity) {
    pthread_mutex_lock(&da->mutex);

    if (new_capacity < da->size) {
        pthread_mutex_unlock(&da->mutex);
        return; // New capacity is smaller than current size
    }

    MAC_PDU* new_array = (MAC_PDU*)realloc(da->array, new_capacity * sizeof(MAC_PDU));
    if (!new_array) {
        pthread_mutex_unlock(&da->mutex);
        return; // Memory allocation failed
    }

    da->array = new_array;
    da->capacity = new_capacity;

    pthread_mutex_unlock(&da->mutex);
}
