typedef struct TCP_header {
    // Define fields for TCP header
} TCP_header;

typedef struct TCP_payload {
    // Define fields for TCP payload
} TCP_payload;

typedef struct TCP_segment {
    TCP_header header;
    TCP_payload payload;
    uint32_t ack_number;
    uint32_t seq_number;
    uint64_t timestamp;
    struct TCP_segment *next;
} TCP_segment;

typedef struct TCP_array {
    TCP_segment **segments;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} TCP_array;

TCP_array* tcp_array_create(size_t initial_capacity) {
    TCP_array *array = (TCP_array*)malloc(sizeof(TCP_array));
    array->segments = (TCP_segment**)calloc(initial_capacity, sizeof(TCP_segment*));
    array->capacity = initial_capacity;
    array->size = 0;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void tcp_array_destroy(TCP_array *array) {
    for (size_t i = 0; i < array->size; ++i) {
        free(array->segments[i]);
    }
    free(array->segments);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

int tcp_array_insert(TCP_array *array, TCP_segment *segment) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        size_t new_capacity = array->capacity ? array->capacity * 2 : 1;
        TCP_segment **new_segments = (TCP_segment**)realloc(array->segments, new_capacity * sizeof(TCP_segment*));
        if (!new_segments) {
            pthread_mutex_unlock(&array->lock);
            return -1; // Memory allocation failed
        }
        array->segments = new_segments;
        array->capacity = new_capacity;
    }
    array->segments[array->size++] = segment;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int tcp_array_delete(TCP_array *array, uint32_t seq_number) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->segments[i]->seq_number == seq_number) {
            free(array->segments[i]);
            for (size_t j = i; j < array->size - 1; ++j) {
                array->segments[j] = array->segments[j + 1];
            }
            --array->size;
            pthread_mutex_unlock(&array->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return -1; // Segment not found
}

TCP_segment* tcp_array_get(TCP_array *array, uint32_t seq_number) {
    pthread_mutex_lock(&array->lock);
    for (size_t i = 0; i < array->size; ++i) {
        if (array->segments[i]->seq_number == seq_number) {
            TCP_segment *segment = array->segments[i];
            pthread_mutex_unlock(&array->lock);
            return segment;
        }
    }
    pthread_mutex_unlock(&array->lock);
    return NULL; // Segment not found
}
