#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

#define MAX_THREADS 10000
#define MEMORY_THRESHOLD 500 * 1024 * 1024 // 500MB

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* head = NULL;
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
size_t total_memory_used = 0;

void* allocate_node(void) {
    Node* node = (Node*)malloc(sizeof(Node));
    if (!node) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_lock(&lock);
    total_memory_used += sizeof(Node);
    if (total_memory_used > MEMORY_THRESHOLD) {
        printf("Memory threshold exceeded. Performing garbage collection.\n");
        // Perform garbage collection here
        Node* current = head;
        while (current != NULL) {
            Node* next = current->next;
            free(current);
            total_memory_used -= sizeof(Node);
            current = next;
        }
        head = NULL;
    }
    pthread_mutex_unlock(&lock);
    return node;
}

void insert_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, int CRCFLAG) {
    Node* new_node = (Node*)allocate_node();
    new_node->data.RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->data.RNTI = RNTI;
    new_node->data.CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->data.CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;

    pthread_mutex_lock(&lock);
    if (head == NULL || head->data.RNTI > RNTI) {
        new_node->next = head;
        head = new_node;
    } else {
        Node* current = head;
        while (current->next != NULL && current->next->data.RNTI < RNTI) {
            current = current->next;
        }
        new_node->next = current->next;
        current->next = new_node;
    }
    pthread_mutex_unlock(&lock);
}

void* thread_function(void* arg) {
    int RX_UE_INFORMATION_TAG = *(int*)arg;
    insert_node(RX_UE_INFORMATION_TAG, rand() % 10000, rand() % 10000, rand() % 2);
    free(arg);
    return NULL;
}

int main() {
    pthread_t threads[MAX_THREADS];
    int thread_args[MAX_THREADS];

    for (int i = 0; i < MAX_THREADS; i++) {
        thread_args[i] = i;
        if (pthread_create(&threads[i], NULL, thread_function, &thread_args[i]) != 0) {
            fprintf(stderr, "Failed to create thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < MAX_THREADS; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
