            free(list->list[i]->pdcch_identifiers);
            free(list->list[i]);
            memmove(&list->list[i], &list->list[i + 1], (list->size - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU*));
            --list->size;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Entity not found
}

NFAPI_CRC_INDICATION_PDU* get_mac_entity(MAC_Entity_List *list, int mac_id) {
