        pthread_mutex_unlock(&list->lock);
        return;
    }
    new_node->data = user_context;
    new_node->prev = list->tail;
    new_node->next = NULL;

    if (list->tail != NULL) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    pthread_mutex_unlock(&list->lock);
