void addOrUpdateFlow(int sourceIP, int destinationIP, int packetCount) {
    for (int i = 0; i < flowCount; i++) {
        if (flowArray[i]->Traffic.SourceIP == sourceIP && flowArray[i]->Traffic.DestinationIP == destinationIP) {
            flowArray[i]->Traffic.PacketCount += packetCount;
            return;
        }
    }

    if (flowCount >= MAX_FLOWS) {
        printf("Flow array is full!\n");
        return;
