    newFlow->CRCFLAG = rand() % 2; // Randomly set CRC flag
    newFlow->Traffic.SourceIP = sourceIP;
    newFlow->Traffic.DestinationIP = destinationIP;
    newFlow->Traffic.PacketCount = packetCount;

    flowArray[flowCount++] = newFlow;
}

void printStatistics() {
    int totalPacketCount = 0;
    int maxPacketCount = 0;

    for (int i = 0; i < flowCount; i++) {
        totalPacketCount += flowArray[i]->Traffic.PacketCount;
        if (flowArray[i]->Traffic.PacketCount > maxPacketCount) {
            maxPacketCount = flowArray[i]->Traffic.PacketCount;
        }
    }

