#include <stdlib.h>
#include <stdio.h>

#define INITIAL_CAPACITY 10
#define GROWTH_FACTOR 2
#define MAX_REALLOCATIONS 100

typedef struct {
    int TX_UE_INFORMATION_TAG;
    int RNTI;
    int PHY_layer_indication_TAG;
} NFAPI_RX_PDU_T;

typedef struct {
    NFAPI_RX_PDU_T *array;
    size_t capacity;
    size_t size;
    size_t reallocations;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    da->array = (NFAPI_RX_PDU_T*)malloc(INITIAL_CAPACITY * sizeof(NFAPI_RX_PDU_T));
    da->capacity = INITIAL_CAPACITY;
    da->size = 0;
    da->reallocations = 0;
    return da;
}

void free_dynamic_array(DynamicArray *da) {
    free(da->array);
    free(da);
}

int is_rnti_unique(DynamicArray *da, int rnti) {
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == rnti) {
            return 0;
        }
    }
    return 1;
}

void insert_unique_rnti(DynamicArray *da, int tx_tag, int rnti, int phy_tag) {
    if (!is_rnti_unique(da, rnti)) {
        printf("Duplicate RNTI detected. Insertion failed.\n");
        return;
    }

    if (da->size == da->capacity) {
        if (da->reallocations >= MAX_REALLOCATIONS) {
            printf("Maximum reallocations reached. Cannot insert new element.\n");
            return;
        }
        size_t new_capacity = da->capacity * GROWTH_FACTOR;
        NFAPI_RX_PDU_T *new_array = (NFAPI_RX_PDU_T*)realloc(da->array, new_capacity * sizeof(NFAPI_RX_PDU_T));
        if (!new_array) {
            printf("Memory reallocation failed.\n");
            return;
        }
        da->array = new_array;
        da->capacity = new_capacity;
        ++da->reallocations;
    }

    da->array[da->size].TX_UE_INFORMATION_TAG = tx_tag;
    da->array[da->size].RNTI = rnti;
    da->array[da->size].PHY_layer_indication_TAG = phy_tag;
    ++da->size;
}

int main() {
    DynamicArray *da = create_dynamic_array();

    // Example usage
    insert_unique_rnti(da, 1, 1001, 20);
    insert_unique_rnti(da, 2, 1002, 30);

    free_dynamic_array(da);
    return 0;
}
