        fprintf(stderr, "Error: Failed to parse configuration file.\n");
        fclose(file);
        return NULL;
    }

    fclose(file);

    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        perror("Failed to allocate memory");
        return NULL;
