        pdu_list[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG + i % 100; // Example range
        pdu_list[i].RNTI = RNTI + i % 50; // Example range
        pdu_list[i].CRCFLAG = rand() % 2; // Random CRCFLAG
    }

    log_range(RX_UE_INFORMATION_TAG, RX_UE_INFORMATION_TAG + N - 1);
    log_range(RNTI, RNTI + N - 1);

