    inet_ntop(AF_INET, &(ipv4->sin_addr), ipstr, sizeof ipstr);
    printf("IP address: %s\n", ipstr);

    freeaddrinfo(res); // free the linked list

    // Free allocated memory
    free(frame_array);
    free(crc_list);

    return 0; // Success
