// C library implementation

#include <stdlib.h>
#include <string.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_node(int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    NFAPI_CRC_INDICATION_PDU_T* new_node = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        return NULL; // Handle memory allocation failure
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_node(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        NFAPI_CRC_INDICATION_PDU_T* temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
        new_node->prev = temp;
    }
}

void delete_node(NFAPI_CRC_INDICATION_PDU_T** head, NFAPI_CRC_INDICATION_PDU_T* node_to_delete) {
    if (*head == NULL || node_to_delete == NULL) {
        return; // Handle invalid input
    }
    if (node_to_delete->prev != NULL) {
        node_to_delete->prev->next = node_to_delete->next;
    } else {
        *head = node_to_delete->next;
    }
    if (node_to_delete->next != NULL) {
        node_to_delete->next->prev = node_to_delete->prev;
    }
    free(node_to_delete);
}

void traverse_list(NFAPI_CRC_INDICATION_PDU_T* head) {
    NFAPI_CRC_INDICATION_PDU_T* temp = head;
    while (temp != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %d\n",
               temp->RX_UE_INFORMATION_TAG, temp->RNTI, temp->CRC_INDICATION_REL8_TAG, temp->CRCFLAG);
        temp = temp->next;
    }
}

void free_list(NFAPI_CRC_INDICATION_PDU_T** head) {
    NFAPI_CRC_INDICATION_PDU_T* current = *head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T* next = current->next;
        free(current);
        current = next;
    }
    *head = NULL;
}
