} TaskManager;

TaskManager* create_task_manager() {
    TaskManager* manager = (TaskManager*)malloc(sizeof(TaskManager));
    if (!manager) return NULL;
    manager->count = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_task_manager(TaskManager* manager) {
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int add_task(TaskManager* manager, PHY_TASK_REQUEST task) {
    pthread_mutex_lock(&manager->lock);
    if (manager->count >= MAX_TASKS) {
        pthread_mutex_unlock(&manager->lock);
        return -1; // Error: Task list is full
    }
    manager->tasks[manager->count++] = task;
    pthread_mutex_unlock(&manager->lock);
    return 0; // Success
}

int update_task(TaskManager* manager, int subframe_number, PHY_TASK_REQUEST new_task) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->tasks[i].subframe_number == subframe_number) {
            manager->tasks[i] = new_task;
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return -1; // Error: Task not found
}

int get_task(TaskManager* manager, int subframe_number, PHY_TASK_REQUEST* task) {
    pthread_mutex_lock(&manager->lock);
    for (int i = 0; i < manager->count; ++i) {
        if (manager->tasks[i].subframe_number == subframe_number) {
            *task = manager->tasks[i];
            pthread_mutex_unlock(&manager->lock);
            return 0; // Success
        }
