    for (int i = 0; i < MAX_ELEMENTS; i++) {
        array[i].RX_UE_INFORMATION_TAG = rand();
        array[i].RNTI = rand();
        array[i].CRC_INDICATION_REL8_TAG = rand() % 2;
    }
    count = MAX_ELEMENTS;
    pthread_mutex_unlock(&mutex);
}

void serialize_array(const char* filename) {
    pthread_mutex_lock(&mutex);
    FILE* file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        pthread_mutex_unlock(&mutex);
        return;
    }
    fwrite(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), count, file);
    fclose(file);
    pthread_mutex_unlock(&mutex);
}

void deserialize_array(const char* filename) {
    pthread_mutex_lock(&mutex);
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        pthread_mutex_unlock(&mutex);
        return;
    }
