    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct ConnectionPoolEntry {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    ConnectionMetadata metadata;
    struct ConnectionPoolEntry *next;
} ConnectionPoolEntry;

ConnectionPoolEntry *connection_pool[MAX_CONNECTIONS];
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
time_t last_cleanup_time;

int generate_random_crcflag() {
    return rand() % 256; // Random CRC flag between 0 and 255
}

unsigned long generate_unique_rx_ue_information_tag() {
    static unsigned long tag = 1;
    return tag++;
}

unsigned short generate_unique_rnti() {
    static unsigned short rnti = 1;
    while (rnti == 0) { // Avoid RNTI value of 0
        rnti = rand() % 65536; // Random RNTI between 0 and 65535
    }
    return rnti;
}

int add_connection(ConnectionMetadata metadata, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connection_pool[i] == NULL) {
            connection_pool[i] = (ConnectionPoolEntry *)malloc(sizeof(ConnectionPoolEntry));
            if (connection_pool[i] == NULL) {
                pthread_mutex_unlock(&pool_lock);
                return -1; // Memory allocation failed
            }
            connection_pool[i]->metadata = metadata;
            connection_pool[i]->pdu = pdu;
            connection_pool[i]->next = NULL;
            pthread_mutex_unlock(&pool_lock);
            return 0; // Connection added successfully
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return -2; // No available slots in the pool
}

int remove_connection(int connection_id) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connection_pool[i] != NULL && connection_pool[i]->metadata.connection_id == connection_id) {
            free(connection_pool[i]);
            connection_pool[i] = NULL;
            pthread_mutex_unlock(&pool_lock);
            return 0; // Connection removed successfully
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return -1; // Connection not found
}

NFAPI_CRC_INDICATION_PDU_T *get_connection_pdu(int connection_id) {
    pthread_mutex_lock(&pool_lock);
    for (int i = 0; i < MAX_CONNECTIONS; i++) {
        if (connection_pool[i] != NULL && connection_pool[i]->metadata.connection_id == connection_id) {
            NFAPI_CRC_INDICATION_PDU_T *pdu = &connection_pool[i]->pdu;
            pthread_mutex_unlock(&pool_lock);
            return pdu; // Connection PDU retrieved successfully
        }
    }
    pthread_mutex_unlock(&pool_lock);
    return NULL; // Connection not found
}

void cleanup_old_connections() {
    time_t current_time = time(NULL);
    if (current_time - last_cleanup_time > TIMEOUT_SECONDS) {
        for (int i = 0; i < MAX_CONNECTIONS; i++) {
            if (connection_pool[i] != NULL && difftime(current_time, connection_pool[i]->metadata.last_activity) > TIMEOUT_SECONDS) {
                free(connection_pool[i]);
                connection_pool[i] = NULL;
            }
        }
        last_cleanup_time = current_time;
    }
}

void *pool_thread(void *arg) {
    while (1) {
        cleanup_old_connections();
        sleep(60); // Check for old connections every minute
    }
    return NULL;
}

int main() {
    pthread_t pool_tid;
    srand(time(NULL));
    last_cleanup_time = time(NULL);
    pthread_create(&pool_tid, NULL, pool_thread, NULL);

    ConnectionMetadata metadata = {1, "192.168.1.1", 8080, time(NULL)};
    NFAPI_CRC_INDICATION_PDU_T pdu = {
        generate_unique_rx_ue_information_tag(),
        generate_unique_rnti(),
        generate_random_crcflag()
    };

    if (add_connection(metadata, pdu) == 0) {
        printf("Connection added successfully.\n");
    } else {
        printf("Failed to add connection.\n");
    }

    NFAPI_CRC_INDICATION_PDU_T *retrieved_pdu = get_connection_pdu(1);
    if (retrieved_pdu != NULL) {
        printf("Retrieved CRC flag: %d\n", retrieved_pdu->CRCFLAG);
    } else {
        printf("Failed to retrieve connection.\n");
    }

    remove_connection(1);

    pthread_join(pool_tid, NULL);
    return 0;
}
