#define MAX_ITEMS 1000

typedef struct {
    float value;
    char identifier[2];
} Item;

Item* load_data(const char* source, int* count) {
    // Simulate data loading with potential errors
    FILE* file = fopen(source, "r");
    if (!file) {
        perror("Failed to open data source");
        return NULL;
    }

    *count = 0;
    Item* items = (Item*)malloc(MAX_ITEMS * sizeof(Item));
    if (!items) {
        perror("Memory allocation failed");
        fclose(file);
        return NULL;
    }

    while (*count < MAX_ITEMS && fscanf(file, "%f %s", &items[*count].value, items[*count].identifier) == 2) {
        (*count)++;
    }

    fclose(file);
    return items;
}

void sort_items(Item* items, int count) {
    // Implement a stable sorting algorithm (e.g., merge sort)
    // This is a placeholder for the actual sorting logic
    // For simplicity, we'll use qsort with a custom comparator
    qsort(items, count, sizeof(Item), [](const void* a, const void* b) {
        float diff = ((Item*)b)->value - ((Item*)a)->value;
        return (diff > 0) - (diff < 0);
    });
}

void export_data(const char* sink, Item* items, int count) {
    // Simulate data exporting with potential errors
    FILE* file = fopen(sink, "w");
    if (!file) {
        perror("Failed to open data sink");
        return;
    }

    for (int i = 0; i < count; i++) {
        fprintf(file, "%.2f %s\n", items[i].value, items[i].identifier);
    }

    fclose(file);
}

int main() {
    int itemCount;
    Item* items = load_data("input.txt", &itemCount);
    if (!items) {
        return 1;
    }

    sort_items(items, itemCount);

    export_data("output.txt", items, itemCount);

    free(items);
    return 0;
}
