void add_nic_config(MAC_ADDRESS mac, PORT_INFO port, VLAN_CONFIGURATION *vlans, int num_vlans) {
    if (nic_count >= MAX_NIC_CONFIGS) {
        fprintf(stderr, "Error: Maximum number of NIC configurations reached.\n");
        return;
    }

    for (int i = 0; i < nic_count; i++) {
        if (memcmp(&nic_configs[i].mac, &mac, sizeof(MAC_ADDRESS)) == 0) {
            // Handle duplicate MAC address
            fprintf(stderr, "Warning: Duplicate MAC address detected. Skipping.\n");
            return;
        }
    }

    memcpy(&nic_configs[nic_count].mac, &mac, sizeof(MAC_ADDRESS));
    nic_configs[nic_count].port = port;
    nic_configs[nic_count].vlans = malloc(num_vlans * sizeof(VLAN_CONFIGURATION));
    memcpy(nic_configs[nic_count].vlans, vlans, num_vlans * sizeof(VLAN_CONFIGURATION));
    nic_configs[nic_count].num_vlans = num_vlans;

    nic_count++;
}

void free_nic_configs() {
    for (int i = 0; i < nic_count; i++) {
        free(nic_configs[i].vlans);
    }
    nic_count = 0;
