using System;
using System.IO;
using System.Threading;

public class LogProcessor
{
    private readonly string _inputFilePath;
    private readonly string _outputFilePath;
    private readonly Func<string, string> _transformationFunction;
    private readonly ILogger _logger;
    private readonly CancellationTokenSource _cancellationTokenSource;

    public LogProcessor(string inputFilePath, string outputFilePath, Func<string, string> transformationFunction, ILogger logger)
    {
        _inputFilePath = inputFilePath;
        _outputFilePath = outputFilePath;
        _transformationFunction = transformationFunction;
        _logger = logger;
        _cancellationTokenSource = new CancellationTokenSource();
    }

    public void ProcessLog()
    {
        try
        {
            using (var reader = new StreamReader(_inputFilePath))
            using (var writer = new StreamWriter(_outputFilePath))
            {
                string line;
                int lineNumber = 0;

                while ((line = reader.ReadLine()) != null)
                {
                    _cancellationTokenSource.Token.ThrowIfCancellationRequested();

                    try
                    {
                        var transformedLine = _transformationFunction(line);
                        writer.WriteLine(transformedLine);
                        lineNumber++;
                    }
                    catch (Exception ex)
                    {
                        _logger.LogError($"Error processing line {lineNumber}: {ex.Message}");
                    }

                    if (lineNumber % 1000 == 0)
                    {
                        _logger.LogProgress($"{lineNumber} lines processed.");
                    }
                }

                _logger.LogInfo("Log processing completed successfully.");
            }
        }
        catch (OperationCanceledException)
        {
            _logger.LogWarning("Log processing was interrupted by the user.");
        }
        catch (Exception ex)
        {
            _logger.LogError($"An unexpected error occurred: {ex.Message}");
        }
        finally
        {
            _cancellationTokenSource.Dispose();
        }
    }

    public void CancelProcessing()
    {
        _cancellationTokenSource.Cancel();
    }
}

public interface ILogger
{
    void LogInfo(string message);
    void LogWarning(string message);
    void LogError(string message);
    void LogProgress(string message);
}
```

This code defines a `LogProcessor` class that processes a large log file line-by-line, applying a transformation function to each line and writing the transformed data to a new output file. It includes features for error handling, logging, progress tracking, and graceful interruption during processing. The `ILogger` interface allows for integration with an existing logging framework.']

