import yaml
import requests
from abc import ABC, abstractmethod

class ConfigManager(ABC):
    _factories = {}

    @classmethod
    def register_factory(cls, factory_id, factory_func):
        cls._factories[factory_id] = factory_func

    @classmethod
    def create_config(cls, factory_id, *args, **kwargs):
        if factory_id in cls._factories:
            return cls._factories[factory_id](*args, **kwargs)
        else:
            raise ValueError(f"Factory {factory_id} not registered")

    @abstractmethod
    def load_from_yaml(self, file_path):
        pass

    @abstractmethod
    def load_from_api(self, url):
        pass

    @abstractmethod
    def save_to_yaml(self, file_path):
        pass

    @abstractmethod
    def save_to_api(self, url):
        pass

    @staticmethod
    def merge_configs(*configs):
        merged_config = {}
        for config in configs:
            for key, value in config.items():
                if key in merged_config and isinstance(merged_config[key], dict) and isinstance(value, dict):
                    merged_config[key] = ConfigManager.merge_configs(merged_config[key], value)
                else:
                    merged_config[key] = value
        return merged_config

class LocalConfig(ConfigManager):
    def load_from_yaml(self, file_path):
        with open(file_path, 'r') as file:
            return yaml.safe_load(file)

    def save_to_yaml(self, file_path, config):
        with open(file_path, 'w') as file:
            yaml.dump(config, file)

class RemoteConfig(ConfigManager):
    def load_from_api(self, url):
        response = requests.get(url)
        if response.status_code == 200:
            return response.json()
        else:
            raise Exception(f"Failed to fetch config from {url}")

    def save_to_api(self, url, config):
        headers = {'Content-Type': 'application/json'}
        response = requests.put(url, json=config, headers=headers)
        if response.status_code != 200:
            raise Exception(f"Failed to save config to {url}")

# Example usage
ConfigManager.register_factory('local', LocalConfig)
ConfigManager.register_factory('remote', RemoteConfig)

local_config = ConfigManager.create_config('local')
remote_config = ConfigManager.create_config('remote')

local_data = local_config.load_from_yaml('config.yaml')
remote_data = remote_config.load_from_api('http://example.com/api/config')

merged_config = ConfigManager.merge_configs(local_data, remote_data)
print(merged_config)

# Save merged config back to local file
local_config.save_to_yaml('merged_config.yaml', merged_config)
