#define MAX_RNTI 5000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_and_populate_rnti(void* arg) {
    int start = *(int*)arg;
    int end = start + MAX_RNTI / 4; // Divide work among threads
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc((end - start) * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

    if (!array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = start; i < end; i++) {
        array[i - start] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!array[i - start]) {
            fprintf(stderr, "Memory allocation failed\n");
            free(array);
            return NULL;
        }

        // Populate structure with valid RNTI and random CRCFLAG
        array[i - start]->RX_UE_INFORMATION_TAG = i;
        array[i - start]->RNTI = rand() % MAX_RNTI + 1; // Valid RNTI range
        array[i - start]->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRCFLAG
    }

    *(NFAPI_CRC_INDICATION_PDU_T***)arg = array;
    return NULL;
}

int main() {
    pthread_t threads[4];
    int thread_args[4] = {0, MAX_RNTI / 4, MAX_RNTI / 2, 3 * MAX_RNTI / 4};
    NFAPI_CRC_INDICATION_PDU_T** array[4];

    srand(time(NULL));

    for (int i = 0; i < 4; i++) {
        if (pthread_create(&threads[i], NULL, allocate_and_populate_rnti, &thread_args[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            return 1;
        }
    }

    for (int i = 0; i < 4; i++) {
        pthread_join(threads[i], (void**)&array[i]);
    }

    // Process the array here

    for (int i = 0; i < 4; i++) {
        for (int j = 0; j < MAX_RNTI / 4; j++) {
            free(array[i][j]);
        }
        free(array[i]);
    }

    return 0;
}
