void initialize_dynamic_array(int size) {
    pthread_mutex_lock(&mutex);
    if (dynamic_array != NULL) {
        free(dynamic_array);
    }
    dynamic_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (dynamic_array == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    array_size = size;
    pthread_mutex_unlock(&mutex);
}

void populate_dynamic_array() {
    pthread_mutex_lock(&mutex);
