#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NetworkEvent {
    int Timestamp;
    char EventType[50];
    void* DataBuffer;
} NetworkEvent;

typedef struct EventNode {
    NetworkEvent event;
    struct EventNode* next;
} EventNode;

typedef struct EventManager {
    EventNode* head;
    pthread_mutex_t lock;
} EventManager;

EventManager* create_event_manager() {
    EventManager* manager = (EventManager*)malloc(sizeof(EventManager));
    if (manager == NULL) {
        return NULL; // Handle memory allocation failure
    }
    manager->head = NULL;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void add_event(EventManager* manager, NetworkEvent event) {
    pthread_mutex_lock(&manager->lock);
    EventNode* new_node = (EventNode*)malloc(sizeof(EventNode));
    if (new_node == NULL) {
        pthread_mutex_unlock(&manager->lock);
        return; // Handle memory allocation failure
    }
    new_node->event = event;
    new_node->next = manager->head;
    manager->head = new_node;
    pthread_mutex_unlock(&manager->lock);
}

NetworkEvent* get_event(EventManager* manager, int timestamp) {
    pthread_mutex_lock(&manager->lock);
    EventNode* current = manager->head;
    while (current != NULL) {
        if (current->event.Timestamp == timestamp) {
            NetworkEvent* event_copy = (NetworkEvent*)malloc(sizeof(NetworkEvent));
            if (event_copy == NULL) {
                pthread_mutex_unlock(&manager->lock);
                return NULL; // Handle memory allocation failure
            }
            *event_copy = current->event;
            pthread_mutex_unlock(&manager->lock);
            return event_copy;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

void remove_event(EventManager* manager, int timestamp) {
    pthread_mutex_lock(&manager->lock);
    EventNode* current = manager->head;
    EventNode* prev = NULL;
    while (current != NULL) {
        if (current->event.Timestamp == timestamp) {
            if (prev == NULL) {
                manager->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            pthread_mutex_unlock(&manager->lock);
            return;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&manager->lock);
}

void destroy_event_manager(EventManager* manager) {
    EventNode* current = manager->head;
    while (current != NULL) {
        EventNode* next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
