#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_NIC_CONFIGS 100
#define MIN_LATENCY 1
#define MAX_LATENCY 100

typedef struct {
    unsigned char mac_address[6];
} MAC_ADDRESS;

typedef struct {
    int port_number;
    // Add other PORT_INFO fields here
} PORT_INFO;

typedef struct {
    int vlan_id;
    int priority;
} VLAN_CONFIGURATION;

typedef struct {
    MAC_ADDRESS mac;
    PORT_INFO port;
    VLAN_CONFIGURATION *vlans;
    int num_vlans;
} NIC_CONFIG;

typedef struct {
    NIC_CONFIG nic_configs[MAX_NIC_CONFIGS];
    int num_nic_configs;
    int duplicate_handling_mode; // 0 for log, 1 for ignore
    int heuristic_severity;
    int logging_level;
} CONFIGURATION;

void simulate_latency() {
    int delay = MIN_LATENCY + rand() % (MAX_LATENCY - MIN_LATENCY + 1);
    usleep(delay * 1000); // Convert ms to microseconds
}

int is_mac_duplicate(CONFIGURATION *config, MAC_ADDRESS mac) {
    for (int i = 0; i < config->num_nic_configs; i++) {
        if (memcmp(&config->nic_configs[i].mac, &mac, sizeof(MAC_ADDRESS)) == 0) {
            return 1;
        }
    }
    return 0;
}

void add_nic(CONFIGURATION *config, MAC_ADDRESS mac, PORT_INFO port, VLAN_CONFIGURATION *vlans, int num_vlans) {
    if (is_mac_duplicate(config, mac)) {
        if (config->duplicate_handling_mode == 0) {
            printf("Warning: Duplicate MAC address detected. Skipping.\n");
        }
        return;
    }

    if (config->num_nic_configs >= MAX_NIC_CONFIGS) {
        printf("Error: Maximum number of NIC configurations reached.\n");
        return;
    }

    config->nic_configs[config->num_nic_configs].mac = mac;
    config->nic_configs[config->num_nic_configs].port = port;
    config->nic_configs[config->num_nic_configs].vlans = vlans;
    config->nic_configs[config->num_nic_configs].num_vlans = num_vlans;

    simulate_latency();
    config->num_nic_configs++;
}

void configure_system(CONFIGURATION *config, int duplicate_handling_mode, int heuristic_severity, int logging_level) {
    config->duplicate_handling_mode = duplicate_handling_mode;
    config->heuristic_severity = heuristic_severity;
    config->logging_level = logging_level;
}

// Example usage
int main() {
    srand(time(NULL));
    CONFIGURATION config;
    configure_system(&config, 0, 1, 2);

    MAC_ADDRESS mac1 = {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E};
    PORT_INFO port1 = {1};
    VLAN_CONFIGURATION vlans1[] = {{10, 1}, {20, 2}};
    add_nic(&config, mac1, port1, vlans1, 2);

    MAC_ADDRESS mac2 = {0x00, 0x1A, 0x2B, 0x3C, 0x4D, 0x5E}; // Duplicate
    PORT_INFO port2 = {2};
    VLAN_CONFIGURATION vlans2[] = {{30, 3}};
    add_nic(&config, mac2, port2, vlans2, 1);

    return 0;
}
