    MAC_PAYLOAD payload;
    time_t timestamp;
} MAC_PDU;

typedef struct {
    MAC_PDU *array;
    size_t size;
    size_t capacity;
    size_t total_bytes_used;
    pthread_mutex_t lock;
} DynamicArray;

void init_dynamic_array(DynamicArray *da, size_t initial_capacity) {
    da->array = (MAC_PDU *)malloc(initial_capacity * sizeof(MAC_PDU));
    da->size = 0;
    da->capacity = initial_capacity;
    da->total_bytes_used = 0;
    pthread_mutex_init(&da->lock, NULL);
}

void destroy_dynamic_array(DynamicArray *da) {
    free(da->array);
    pthread_mutex_destroy(&da->lock);
}

int insert_mac_pdu(DynamicArray *da, MAC_PDU pdu) {
    pthread_mutex_lock(&da->lock);
    if (da->size >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        da->array = (MAC_PDU *)realloc(da->array, new_capacity * sizeof(MAC_PDU));
        da->capacity = new_capacity;
    }
    da->array[da->size++] = pdu;
    da->total_bytes_used += sizeof(MAC_PDU);
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int delete_mac_pdu(DynamicArray *da, size_t index) {
    pthread_mutex_lock(&da->lock);
    if (index >= da->size) {
        pthread_mutex_unlock(&da->lock);
        return -1;
    }
    for (size_t i = index; i < da->size - 1; ++i) {
        da->array[i] = da->array[i + 1];
    }
    da->size--;
    da->total_bytes_used -= sizeof(MAC_PDU);
    pthread_mutex_unlock(&da->lock);
    return 0;
}

MAC_PDU *get_mac_pdu(DynamicArray *da, size_t index) {
    if (index >= da->size) {
        return NULL;
    }
    return &da->array[index];
}

