#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_STRUCTURES 10000
#define LOG_FILE "crc_log.txt"
#define LOG_SIZE_LIMIT 1024 * 1024 // 1 MB

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T** structures = NULL;
int structure_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

void log_message(const char* message) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        return;
    }

    time_t now = time(NULL);
    fprintf(log_file, "[%s] %s\n", ctime(&now), message);

    fclose(log_file);

    // Truncate log file if it exceeds the size limit
    FILE* temp_log_file = fopen("temp_crc_log.txt", "w");
    if (temp_log_file == NULL) {
        perror("Failed to open temporary log file");
        return;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    fseek(log_file, 0, SEEK_SET);

    if (file_size > LOG_SIZE_LIMIT) {
        fseek(log_file, file_size - LOG_SIZE_LIMIT, SEEK_SET);
    }

    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), log_file)) {
        fputs(buffer, temp_log_file);
    }

    fclose(log_file);
    fclose(temp_log_file);

    remove(LOG_FILE);
    rename("temp_crc_log.txt", LOG_FILE);
}

int allocate_structures(int N) {
    if (N > MAX_STRUCTURES) {
        log_message("Error: Requested number of structures exceeds maximum limit");
        return -1;
    }

    pthread_mutex_lock(&mutex);

    if (structures != NULL) {
        free(structures);
    }

    structures = (NFAPI_CRC_INDICATION_PDU_T**)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (structures == NULL) {
        log_message("Error: Memory allocation failed");
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    for (int i = 0; i < N; i++) {
        structures[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (structures[i] == NULL) {
            log_message("Error: Memory allocation failed");
            pthread_mutex_unlock(&mutex);
            return -1;
        }

        // Initialize structure with random values and unique tags
        structures[i]->RX_UE_INFORMATION_TAG = rand();
        structures[i]->RNTI = rand();
        structures[i]->CRC_INDICATION_REL8_TAG = rand();
        structures[i]->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to 0 or 1

        structure_count++;
    }

    pthread_mutex_unlock(&mutex);
    return 0;
}

int get_structure_count() {
    return structure_count;
}

void free_structures() {
    pthread_mutex_lock(&mutex);

    if (structures != NULL) {
        for (int i = 0; i < structure_count; i++) {
            free(structures[i]);
        }
        free(structures);
        structures = NULL;
        structure_count = 0;
    }

    pthread_mutex_unlock(&mutex);
}

void* monitor_performance(void* arg) {
    while (1) {
        // Implement performance monitoring logic here
        sleep(5); // Monitor every 5 seconds
    }
    return NULL;
}
