typedef struct {
    NFAPI_CRC_INDICATION_PDU_T **elements;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamic_list_create() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->elements = NULL;
    list->count = 0;
    list->capacity = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList *list) {
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]->crc_indication);
        free(list->elements[i]);
    }
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
    free(list);
}

void dynamic_list_insert(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *element) {
    pthread_mutex_lock(&list->lock);
    if (list->count == list->capacity) {
        size_t new_capacity = (list->capacity == 0) ? 1 : list->capacity * 2;
        list->elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        list->capacity = new_capacity;
    }
    list->elements[list->count++] = element;
    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_delete(DynamicList *list, size_t index) {
    pthread_mutex_lock(&list->lock);
    if (index < list->count) {
        free(list->elements[index]->crc_indication);
        free(list->elements[index]);
        for (size_t i = index; i < list->count - 1; ++i) {
            list->elements[i] = list->elements[i + 1];
        }
        --list->count;
    }
    pthread_mutex_unlock(&list->lock);
}

void dynamic_list_batch_update(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T **new_elements, size_t new_count) {
    pthread_mutex_lock(&list->lock);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->elements[i]->crc_indication);
        free(list->elements[i]);
    }
    free(list->elements);
    list->elements = realloc(new_elements, new_count * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    list->count = new_count;
    pthread_mutex_unlock(&list->lock);
}

