#include <stdlib.h>
#include <pthread.h>

#define MAX_SIZE 1000
#define BATCH_SIZE 100

typedef struct {
    RX_UE_INFORMATION_TAG ue_info;
    uint16_t RNTI;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data[MAX_SIZE];
    size_t count;
    size_t capacity;
    pthread_mutex_t mutex;
} DynamicList;

void init_list(DynamicList *list) {
    list->count = 0;
    list->capacity = BATCH_SIZE;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_to_list(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *item) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= list->capacity) {
        size_t new_capacity = list->capacity + BATCH_SIZE;
        NFAPI_CRC_INDICATION_PDU_T **new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T *));
        if (!new_data) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }
    list->data[list->count++] = item;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

void print_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        printf("UE Info: %d, RNTI: %u, CRC Flag: %d\n",
               list->data[i]->ue_info,
               list->data[i]->RNTI,
               list->data[i]->crc_indication.CRCFLAG);
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(DynamicList *list) {
    pthread_mutex_lock(&list->mutex);
    for (size_t i = 0; i < list->count; ++i) {
        free(list->data[i]);
    }
    free(list->data);
    pthread_mutex_destroy(&list->mutex);
}
