typedef struct {
    EVP_CIPHER *cipher;
    unsigned char key[16];
    unsigned char iv[8];
} CipherContext;

CipherContext* create_cipher_context(const char* cipher_name, const unsigned char* key, size_t key_len) {
    CipherContext* ctx = malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    EVP_CIPHER* cipher = EVP_get_cipherbyname(cipher_name);
    if (!cipher) {
        free(ctx);
        return NULL;
    }

    memcpy(ctx->key, key, key_len);
    memset(ctx->iv, 0, sizeof(ctx->iv));

    ctx->cipher = cipher;
    return ctx;
}

void encrypt_data(CipherContext* ctx, const unsigned char* plaintext, size_t plaintext_len, unsigned char* ciphertext) {
    EVP_CIPHER_CTX* evp_ctx = EVP_CIPHER_CTX_new();
    if (!evp_ctx) return;

    EVP_EncryptInit_ex(evp_ctx, ctx->cipher, NULL, ctx->key, ctx->iv);
    EVP_EncryptUpdate(evp_ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len);
    EVP_EncryptFinal_ex(evp_ctx, ciphertext + ciphertext_len, &ciphertext_len);

    EVP_CIPHER_CTX_free(evp_ctx);
}

void decrypt_data(CipherContext* ctx, const unsigned char* ciphertext, size_t ciphertext_len, unsigned char* plaintext) {
    EVP_CIPHER_CTX* evp_ctx = EVP_CIPHER_CTX_new();
    if (!evp_ctx) return;

    EVP_DecryptInit_ex(evp_ctx, ctx->cipher, NULL, ctx->key, ctx->iv);
    EVP_DecryptUpdate(evp_ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len);
    EVP_DecryptFinal_ex(evp_ctx, plaintext + plaintext_len, &plaintext_len);

    EVP_CIPHER_CTX_free(evp_ctx);
}

