#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_EVENTS 100000
#define WINDOW_SIZE 60

typedef struct {
    int id;
    time_t timestamp;
    float value;
} Event;

typedef struct {
    Event events[MAX_EVENTS];
    int front, rear;
    size_t count;
    float moving_average;
    int threshold;
} SensorDataProcessor;

void init_processor(SensorDataProcessor *processor, int threshold) {
    processor->front = 0;
    processor->rear = -1;
    processor->count = 0;
    processor->moving_average = 0.0f;
    processor->threshold = threshold;
}

int is_full(SensorDataProcessor *processor) {
    return processor->count == MAX_EVENTS;
}

int is_empty(SensorDataProcessor *processor) {
    return processor->count == 0;
}

void enqueue(SensorDataProcessor *processor, Event event) {
    if (is_full(processor)) {
        printf("Queue overflow\n");
        return;
    }
    processor->rear = (processor->rear + 1) % MAX_EVENTS;
    processor->events[processor->rear] = event;
    processor->count++;
}

Event dequeue(SensorDataProcessor *processor) {
    if (is_empty(processor)) {
        printf("Queue underflow\n");
        Event empty_event = {0};
        return empty_event;
    }
    Event event = processor->events[processor->front];
    processor->front = (processor->front + 1) % MAX_EVENTS;
    processor->count--;
    return event;
}

float calculate_moving_average(SensorDataProcessor *processor) {
    float sum = 0.0f;
    for (int i = 0; i < processor->count; i++) {
        sum += processor->events[(processor->front + i) % MAX_EVENTS].value;
    }
    return sum / processor->count;
}

void process_event(SensorDataProcessor *processor, Event event) {
    time_t current_time = time(NULL);
    if (event.timestamp < current_time - WINDOW_SIZE) {
        dequeue(processor);
    } else {
        enqueue(processor, event);
    }
    processor->moving_average = calculate_moving_average(processor);
}

void log_event(SensorDataProcessor *processor, Event event) {
    // Implement logging logic here
    printf("Event ID: %d, Timestamp: %ld, Value: %.2f\n", event.id, event.timestamp, event.value);
}

float get_highest_moving_average(SensorDataProcessor *processor) {
    return processor->moving_average;
}

int main() {
    SensorDataProcessor processor;
    init_processor(&processor, 10);

    // Simulate processing events
    for (int i = 0; i < 150; i++) {
        Event event = {i, time(NULL), (float)i};
        process_event(&processor, event);
        log_event(&processor, event);
    }

    printf("Highest Moving Average: %.2f\n", get_highest_moving_average(&processor));

    return 0;
}
