int encrypt_data(CipherContext *ctx, const unsigned char *plaintext, size_t plaintext_len, unsigned char *ciphertext, unsigned char *tag) {
    if (!EVP_EncryptInit_ex(ctx->ctx, EVP_aes_128_gcm(), NULL, ctx->key, ctx->iv)) return 0;
    if (!EVP_EncryptUpdate(ctx->ctx, ciphertext, &ciphertext_len, plaintext, plaintext_len)) return 0;
    if (!EVP_EncryptFinal_ex(ctx->ctx, ciphertext + ciphertext_len, &ciphertext_len)) return 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_GET_TAG, 16, tag)) return 0;
    return 1; // Return 1 on success
}

int decrypt_data(CipherContext *ctx, const unsigned char *ciphertext, size_t ciphertext_len, const unsigned char *tag, unsigned char *plaintext) {
    if (!EVP_DecryptInit_ex(ctx->ctx, EVP_aes_128_gcm(), NULL, ctx->key, ctx->iv)) return 0;
    if (!EVP_CIPHER_CTX_ctrl(ctx->ctx, EVP_CTRL_GCM_SET_TAG, 16, (void*)tag)) return 0;
    if (!EVP_DecryptUpdate(ctx->ctx, plaintext, &plaintext_len, ciphertext, ciphertext_len)) return 0;
    if (!EVP_DecryptFinal_ex(ctx->ctx, plaintext + plaintext_len, &plaintext_len)) return 0;
    return 1; // Return 1 on success
}

int reset_cipher_context(CipherContext *ctx) {
    EVP_CIPHER_CTX_reset(ctx->ctx);
    return 1; // Return 1 on success
}
