#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_SIZE 1000
#define BATCH_SIZE 50

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

typedef struct {
    Node* head;
    Node* tail;
    size_t count;
    pthread_mutex_t mutex;
} DynamicList;

void init_list(DynamicList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_element(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T data) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_SIZE) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // List is full
    }
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        pthread_mutex_unlock(&list->mutex);
        return -2; // Memory allocation failed
    }
    new_node->data = data;
    new_node->next = NULL;
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

void print_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n",
               current->data.RX_UE_INFORMATION_TAG,
               current->data.RNTI,
               current->data.CRCFLAG);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void free_list(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    Node* current = list->head;
    while (current != NULL) {
        Node* next = current->next;
        free(current);
        current = next;
    }
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

int main() {
    DynamicList list;
    init_list(&list);

    NFAPI_CRC_INDICATION_PDU_T data;
    srand(time(NULL));
    for (size_t i = 0; i < MAX_SIZE + BATCH_SIZE; ++i) {
        data.RX_UE_INFORMATION_TAG = rand();
        data.RNTI = rand();
        data.CRCFLAG = rand() % 2;
        if (add_element(&list, data) != 0) {
            printf("Failed to add element\n");
        }
    }

    print_list(&list);

    free_list(&list);
    return 0;
}
