#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

#define MAX_ENTRIES 10000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *entries[MAX_ENTRIES];
    int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList *list = (DynamicList*)malloc(sizeof(DynamicList));
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void add_entry(DynamicList *list, NFAPI_CRC_INDICATION_PDU_T *entry) {
    pthread_mutex_lock(&list->lock);
    if (list->size < MAX_ENTRIES) {
        list->entries[list->size++] = entry;
    }
    pthread_mutex_unlock(&list->lock);
}

void update_entry(DynamicList *list, int RNTI, NFAPI_CRC_INDICATION_PDU_T *new_entry) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->RNTI == RNTI) {
            free(list->entries[i]);
            list->entries[i] = new_entry;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_entry(DynamicList *list, int RNTI) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->size; i++) {
        if (list->entries[i]->RNTI == RNTI) {
            free(list->entries[i]);
            for (int j = i; j < list->size - 1; j++) {
                list->entries[j] = list->entries[j + 1];
            }
            list->size--;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
}

void serialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        perror("Failed to open file for writing");
        return;
    }
    fwrite(list->entries, sizeof(NFAPI_CRC_INDICATION_PDU_T*), list->size, file);
    fclose(file);
}

void deserialize_list(DynamicList *list, const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        perror("Failed to open file for reading");
        return;
    }
    int size;
    fread(&size, sizeof(int), 1, file);
    if (size > MAX_ENTRIES) {
        fprintf(stderr, "Deserialized list exceeds maximum entries\n");
        fclose(file);
        return;
    }
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *entry = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(entry, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        list->entries[list->size++] = entry;
    }
    pthread_mutex_unlock(&list->lock);
    fclose(file);
}

void generate_report(DynamicList *list) {
    // Implement report generation logic here
}
