#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/stat.h>

#define MAX_NFAPIS 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int *size) {
    NFAPI_CRC_INDICATION_PDU_T *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_NFAPIS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Failed to allocate memory");
        return NULL;
    }

    for (*size = 0; *size < MAX_NFAPIS; (*size)++) {
        list[*size].RX_UE_INFORMATION_TAG = rand() % 1000;
        list[*size].RNTI = rand() % 1000;
        list[*size].CRC_INDICATION_REL8_TAG = rand() % 2;
    }

    return list;
}

void execute_command(const char *command, const char *config_file) {
    struct stat file_stat;
    if (stat(config_file, &file_stat) == 0) {
        remove(config_file);
    }

    FILE *fp = popen(command, "r");
    if (!fp) {
        perror("Failed to execute command");
        return;
    }

    char buffer[128];
    while (fgets(buffer, sizeof(buffer), fp)) {
        printf("%s", buffer);
    }

    int status = pclose(fp);
    if (status == -1) {
        perror("Error in pclose");
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Command exited with error code %d\n", WEXITSTATUS(status));
    }
}

int main() {
    int size;
    NFAPI_CRC_INDICATION_PDU_T *list = create_and_populate_list(&size);
    if (!list) {
        return EXIT_FAILURE;
    }

    const char *command = "your_command_here";
    const char *config_file = "/path/to/config/file";

    execute_command(command, config_file);

    free(list);
    return EXIT_SUCCESS;
}
