['```rust
use tokio::sync::{mpsc, RwLock};
use std::collections::HashMap;
use std::error::Error;
use std::process;

#[derive(Debug)]
enum HealthCheck {
    Disk,
    Memory,
}

#[derive(Debug)]
enum Command {
    Start(HealthCheck),
    Stop(HealthCheck),
    Status(HealthCheck),
    Help,
}

struct HealthMonitor {
    tasks: RwLock<HashMap<HealthCheck, mpsc::Sender<String>>>,
}

impl HealthMonitor {
    async fn new() -> Self {
        HealthMonitor {
            tasks: RwLock::new(HashMap::new()),
        }
    }

    async fn start(&self, check: HealthCheck) -> Result<(), Box<dyn Error>> {
        let (tx, mut rx) = mpsc::channel(10);
        *self.tasks.write().await.entry(check).or_insert(tx) = tx;

        tokio::spawn(async move {
            loop {
                match check {
                    HealthCheck::Disk => {
                        // Perform disk usage check
                        let result = "Disk usage: 80%".to_string();
                        if let Err(_) = tx.send(result).await {
                            break;
                        }
                    }
                    HealthCheck::Memory => {
                        // Perform memory utilization check
                        let result = "Memory usage: 75%".to_string();
                        if let Err(_) = tx.send(result).await {
                            break;
                        }
                    }
                }

                tokio::time::sleep(tokio::time::Duration::from_secs(600)).await;
            }
        });

        Ok(())
    }

    async fn stop(&self, check: HealthCheck) -> Result<(), Box<dyn Error>> {
        if let Some(tx) = self.tasks.write().await.remove(&check) {
            drop(tx);
        }
        Ok(())
    }

    async fn status(&self, check: HealthCheck) -> Result<(), Box<dyn Error>> {
        if self.tasks.read().await.contains_key(&check) {
            println!("{} is active", check);
        } else {
            println!("{} is inactive", check);
        }
        Ok(())
    }

    async fn help(&self) {
        println!("Available commands:");
        println!("start <check> - Initiates a background task for the specified health check.");
        println!("stop <check> - Stops the specified health check task.");
        println!("status <check> - Displays the current status of the specified health check task.");
        println!("help - Provides a list of available commands.");
    }
}

#[tokio::main]
async fn main() {
    let monitor = HealthMonitor::new().await;

    let args: Vec<String> = std::env::args().collect();
    if args.len() < 2 {
        monitor.help().await;
        process::exit(1);
    }

    match args[1].as_str() {
        "start" => {
            if args.len() != 3 {
                println!("Usage: start <check>");
                process::exit(1);
            }
            let check = match args[2].as_str() {
                "disk" => HealthCheck::Disk,
                "memory" => HealthCheck::Memory,
                _ => {
                    println!("Invalid check type. Use 'disk' or 'memory'.");
                    process::exit(1);
                }
            };
            monitor.start(check).await.unwrap();
        }
        "stop" => {
            if args.len() != 3 {
                println!("Usage: stop <check>");
                process::exit(1);
            }
            let check = match args[2].as_str() {
                "disk" => HealthCheck::Disk,
                "memory" => HealthCheck::Memory,
                _ => {
                    println!("Invalid check type. Use 'disk' or 'memory'.");
                    process::exit(1);
                }
            };
            monitor.stop(check).await.unwrap();
        }
        "status" => {
            if args.len() != 3 {
                println!("Usage: status <check>");
                process::exit(1);
            }
            let check = match args[2].as_str() {
                "disk" => HealthCheck::Disk,
                "memory" => HealthCheck::Memory,
                _ => {
                    println!("Invalid check type. Use 'disk' or 'memory'.");
                    process::exit(1);
                }
            };
            monitor.status(check).await.unwrap();
        }
        "help" => monitor.help().await,
        _ => {
            println!("Unknown command.");
            monitor.help().await;
            process::exit(1);
        }
    }
}
