typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} ThreadSafeList;

void init_list(ThreadSafeList *list, size_t initial_capacity) {
    list->elements = (NFAPI_CRC_INDICATION_PDU_T *)malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        perror("Failed to allocate memory for list elements");
        exit(EXIT_FAILURE);
    }
    list->capacity = initial_capacity;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
}

void destroy_list(ThreadSafeList *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
}

void resize_list(ThreadSafeList *list, size_t new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_elements = (NFAPI_CRC_INDICATION_PDU_T *)realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_elements) {
        perror("Failed to reallocate memory for list elements");
        exit(EXIT_FAILURE);
    }
    list->elements = new_elements;
    list->capacity = new_capacity;
}

void add_element(ThreadSafeList *list, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&list->mutex);
    while (list->size == list->capacity) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    list->elements[list->size++] = element;
    if (list->size == list->capacity) {
        resize_list(list, list->capacity * 2);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_cond_signal(&list->cond);
}

NFAPI_CRC_INDICATION_PDU_T get_element(ThreadSafeList *list, size_t index) {
    NFAPI_CRC_INDICATION_PDU_T element;
    pthread_mutex_lock(&list->mutex);
    while (index >= list->size) {
        pthread_cond_wait(&list->cond, &list->mutex);
    }
    element = list->elements[index];
    pthread_mutex_unlock(&list->mutex);
    return element;
}

