use std::env;
use std::fs::{self, DirBuilder};
use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};
use log::{info, warn, error};

static DIRECTORY_LOCK: Mutex<()> = Mutex::new(());

fn manage_directory(path_str: &str, cleanup: bool) -> Result<(), String> {
    let path = Path::new(path_str);
    if !path.exists() || cleanup {
        let mut lock = DIRECTORY_LOCK.lock().map_err(|_| "Failed to acquire directory lock")?;
        if !path.exists() {
            info!("Creating directory: {:?}", path);
            DirBuilder::new()
                .recursive(true)
                .create(&path)
                .map_err(|e| format!("Failed to create directory: {}", e))?;
        }
    }

    let env_var_name = "MY_DIRECTORY_ENV";
    if cleanup {
        info!("Cleaning up environment variable");
        env::remove_var(env_var_name);
    } else {
        let current_path = path.canonicalize().map_err(|e| format!("Failed to canonicalize path: {}", e))?;
        info!("Setting environment variable {} to {:?}", env_var_name, current_path);
        env::set_var(env_var_name, &current_path.to_string_lossy());
    }

    Ok(())
}

fn main() {
    // Example usage
    if let Err(e) = manage_directory("/path/to/directory", false) {
        error!("Error managing directory: {}", e);
    }
}
```

