#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define MAX_UE_PER_OPERATOR 100000
#define MAX_OPERATORS 10

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} UEStatsRecord;

typedef struct {
    pthread_mutex_t lock;
    UEStatsRecord records[MAX_UE_PER_OPERATOR];
    int count;
} OperatorNamespace;

OperatorNamespace namespaces[MAX_OPERATORS];

void init_operator_namespace(int operator_id) {
    pthread_mutex_init(&namespaces[operator_id].lock, NULL);
    memset(namespaces[operator_id].records, 0, sizeof(UEStatsRecord) * MAX_UE_PER_OPERATOR);
    namespaces[operator_id].count = 0;
}

void add_or_update_ue_record(int operator_id, int ue_id, int rx_tag, int rnti) {
    pthread_mutex_lock(&namespaces[operator_id].lock);
    for (int i = 0; i < namespaces[operator_id].count; i++) {
        if (namespaces[operator_id].records[i].RX_UE_INFORMATION_TAG == ue_id) {
            namespaces[operator_id].records[i].RNTI = rnti;
            pthread_mutex_unlock(&namespaces[operator_id].lock);
            return;
        }
    }
    if (namespaces[operator_id].count < MAX_UE_PER_OPERATOR) {
        namespaces[operator_id].records[namespaces[operator_id].count].RX_UE_INFORMATION_TAG = ue_id;
        namespaces[operator_id].records[namespaces[operator_id].count].RNTI = rnti;
        namespaces[operator_id].count++;
    }
    pthread_mutex_unlock(&namespaces[operator_id].lock);
}

UEStatsRecord* get_ue_record(int operator_id, int ue_id) {
    pthread_mutex_lock(&namespaces[operator_id].lock);
    for (int i = 0; i < namespaces[operator_id].count; i++) {
        if (namespaces[operator_id].records[i].RX_UE_INFORMATION_TAG == ue_id) {
            UEStatsRecord* record = &namespaces[operator_id].records[i];
            pthread_mutex_unlock(&namespaces[operator_id].lock);
            return record;
        }
    }
    pthread_mutex_unlock(&namespaces[operator_id].lock);
    return NULL;
}

void merge_operator_namespaces(int operator1, int operator2) {
    pthread_mutex_lock(&namespaces[operator1].lock);
    pthread_mutex_lock(&namespaces[operator2].lock);
    for (int i = 0; i < namespaces[operator2].count; i++) {
        add_or_update_ue_record(operator1, namespaces[operator2].records[i].RX_UE_INFORMATION_TAG,
                                namespaces[operator2].records[i].RX_UE_INFORMATION_TAG,
                                namespaces[operator2].records[i].RNTI);
    }
    pthread_mutex_unlock(&namespaces[operator2].lock);
    pthread_mutex_unlock(&namespaces[operator1].lock);
}

void cleanup() {
    for (int i = 0; i < MAX_OPERATORS; i++) {
        pthread_mutex_destroy(&namespaces[i].lock);
    }
}
