    for (int i = 0; i < session_count; i++) {
        if (sessions[i]->device_id == device_id) {
            // Terminate pending transmissions and log
            free(sessions[i]);
            sessions = realloc(sessions, (session_count - 1) * sizeof(DeviceSession *));
            memmove(&sessions[i], &sessions[i + 1], (session_count - i - 1) * sizeof(DeviceSession *));
            session_count--;
            break;
        }
    }
