#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct TrafficVolume {
    int month;
    long bytes_used;
} TrafficVolume;

typedef struct NetworkEntityStats {
    int entity_id;
    time_t last_update_time;
    TrafficVolume *traffic_volume;
    struct NetworkEntityStats *next;
} NetworkEntityStats;

NetworkEntityStats* initialize_network_entity_stats(int entity_id, time_t last_update_time) {
    NetworkEntityStats *new_node = (NetworkEntityStats*)malloc(sizeof(NetworkEntityStats));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_node->entity_id = entity_id;
    new_node->last_update_time = last_update_time;
    new_node->traffic_volume = NULL;
    new_node->next = NULL;
    return new_node;
}

void add_traffic_volume(NetworkEntityStats *node, int month, long bytes_used) {
    TrafficVolume *new_tv = (TrafficVolume*)malloc(sizeof(TrafficVolume));
    if (new_tv == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(1);
    }
    new_tv->month = month;
    new_tv->bytes_used = bytes_used;
    new_tv->next = node->traffic_volume;
    node->traffic_volume = new_tv;
}

void update_network_entity_stats(NetworkEntityStats *head, int entity_id, time_t last_update_time) {
    NetworkEntityStats *current = head;
    while (current != NULL) {
        if (current->entity_id == entity_id) {
            current->last_update_time = last_update_time;
            return;
        }
        current = current->next;
    }
}

void cleanup_old_traffic(NetworkEntityStats *head, time_t retention_period) {
    NetworkEntityStats *current = head;
    NetworkEntityStats *prev = NULL;
    while (current != NULL) {
        if ((time(NULL) - current->last_update_time) > retention_period) {
            if (prev == NULL) {
                head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            current = prev->next;
        } else {
            TrafficVolume *tv_current = current->traffic_volume;
            TrafficVolume *tv_prev = NULL;
            while (tv_current != NULL) {
                if ((time(NULL) - tv_current->month) > retention_period) {
                    if (tv_prev == NULL) {
                        current->traffic_volume = tv_current->next;
                    } else {
                        tv_prev->next = tv_current->next;
                    }
                    free(tv_current);
                    tv_current = tv_prev->next;
                } else {
                    tv_prev = tv_current;
                    tv_current = tv_current->next;
                }
            }
            prev = current;
            current = current->next;
        }
    }
}

void free_network_entity_stats(NetworkEntityStats *head) {
    NetworkEntityStats *current = head;
    while (current != NULL) {
        TrafficVolume *tv_current = current->traffic_volume;
        while (tv_current != NULL) {
            TrafficVolume *temp = tv_current;
            tv_current = tv_current->next;
            free(temp);
        }
        NetworkEntityStats *temp = current;
        current = current->next;
        free(temp);
    }
}
