#include <time.h>

#define NFAPI_MESSAGE_T struct { RX_UE_INFORMATION_TAG ue_info; uint16_t RNTI; PHY_LAYER_STATUS_TAG status; }
#define CACHE_SIZE 1024

typedef struct {
    NFAPI_MESSAGE_T *messages;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
} Cache;

Cache* cache_create(size_t initial_capacity) {
    Cache *cache = (Cache*)malloc(sizeof(Cache));
    if (!cache) return NULL;

    cache->messages = (NFAPI_MESSAGE_T*)calloc(initial_capacity, sizeof(NFAPI_MESSAGE_T));
    if (!cache->messages) {
        free(cache);
        return NULL;
    }

    cache->size = 0;
    cache->capacity = initial_capacity;
    pthread_mutex_init(&cache->lock, NULL);

    return cache;
}

void cache_destroy(Cache *cache) {
    pthread_mutex_lock(&cache->lock);
    free(cache->messages);
    pthread_mutex_unlock(&cache->lock);
    pthread_mutex_destroy(&cache->lock);
    free(cache);
}

int cache_add(Cache *cache, NFAPI_MESSAGE_T message) {
    pthread_mutex_lock(&cache->lock);

    if (cache->size >= cache->capacity) {
        size_t new_capacity = cache->capacity * 2;
        NFAPI_MESSAGE_T *new_messages = (NFAPI_MESSAGE_T*)realloc(cache->messages, new_capacity * sizeof(NFAPI_MESSAGE_T));
        if (!new_messages) {
            pthread_mutex_unlock(&cache->lock);
            return -1; // Memory allocation failed
        }
        cache->messages = new_messages;
        cache->capacity = new_capacity;
    }

    cache->messages[cache->size++] = message;

    pthread_mutex_unlock(&cache->lock);
    return 0;
}

NFAPI_MESSAGE_T* cache_get(Cache *cache, size_t index) {
    if (index >= cache->size) return NULL;

    pthread_mutex_lock(&cache->lock);
    NFAPI_MESSAGE_T *message = &cache->messages[index];
    pthread_mutex_unlock(&cache->lock);

    return message;
}

// Example usage
int main() {
    Cache *cache = cache_create(CACHE_SIZE);
    if (!cache) return -1;

    // Populate the cache with random messages
    for (size_t i = 0; i < CACHE_SIZE; ++i) {
        NFAPI_MESSAGE_T message;
        // Initialize message fields here
        cache_add(cache, message);
    }

    // Retrieve and use a message from the cache
    NFAPI_MESSAGE_T *message = cache_get(cache, 0);
    if (message) {
        // Use the message
    }

    cache_destroy(cache);
    return 0;
}
