    if (ue_context_count < MAX_UE_CONTEXTS) {
        UEContext *new_context = malloc(sizeof(UEContext));
        new_context->ue_id = ue_id;
        new_context->rrm_config = rrm_config;
        new_context->measurement_reports = NULL;
        new_context->report_count = 0;
