    }
    pthread_mutex_unlock(&mutex);
}

void update_rrm_config(int ue_id, RadioResourceManager *new_rrm_config) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            free(ue_contexts[i]->rrm_config);
            ue_contexts[i]->rrm_config = new_rrm_config;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

MeasurementReport* get_latest_measurement(int ue_id) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id && ue_contexts[i]->report_count > 0) {
            return &ue_contexts[i]->measurement_reports[ue_contexts[i]->report_count - 1];
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}

void add_measurement_report(int ue_id, MeasurementReport *report) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < ue_context_count; i++) {
        if (ue_contexts[i]->ue_id == ue_id) {
            if (ue_contexts[i]->measurement_reports == NULL) {
                ue_contexts[i]->measurement_reports = malloc(sizeof(MeasurementReport));
                ue_contexts[i]->report_count = 1;
            } else {
                ue_contexts[i]->measurement_reports = realloc(ue_contexts[i]->measurement_reports, sizeof(MeasurementReport) * (ue_contexts[i]->report_count + 1));
                ue_contexts[i]->report_count++;
            }
            memcpy(&ue_contexts[i]->measurement_reports[ue_contexts[i]->report_count - 1], report, sizeof(MeasurementReport));
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

void generate_crc_indications() {
