    for (int i = 0; i < ue_context_count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        indication->rnti = ue_contexts[i]->ue_id;
        indication->crc_flag = rand() % 2; // Randomly set CRCFLAG
        // Add to some data structure or send over network
    }
    pthread_mutex_unlock(&mutex);
}

void *update_rrm_config_thread(void *arg) {
