    if (!list->elements) {
        log_error("Failed to allocate memory for CRC list");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->capacity = N;
    pthread_mutex_init(&list->lock, NULL);
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    free(list->elements);
    pthread_mutex_destroy(&list->lock);
}

int add_to_crc_list(NFAPI_CRC_LIST_T *list, RX_UE_INFORMATION_TAG ue_info, uint16_t RNTI) {
    pthread_mutex_lock(&list->lock);

    if (list->count >= list->capacity) {
        NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, 2 * list->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
