use std::env;
use std::fs::{self, DirBuilder};
use std::path::Path;
use std::sync::{Arc, Mutex};
use rand::Rng;

#[repr(C)]
struct NFAPI_CRC_INDICATION_PDU_T {
    rx_ue_information_tag: u32,
    rnti: u16,
    crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG,
}

#[repr(C)]
struct CRC_INDICATION_REL8_TAG {
    crcflag: bool,
}

fn create_and_populate_nfaapi_pdu_list(n: usize) -> Result<Vec<NFAPI_CRC_INDICATION_PDU_T>, Box<dyn std::error::Error>> {
    let mut pdu_list = Vec::with_capacity(n);

    for _ in 0..n {
        let rx_ue_information_tag = rand::thread_rng().gen();
        let rnti = rand::thread_rng().gen();
        let crcflag = rand::thread_rng().gen();

        let pdu = NFAPI_CRC_INDICATION_PDU_T {
            rx_ue_information_tag,
            rnti,
            crc_indication_rel8_tag: CRC_INDICATION_REL8_TAG { crcflag },
        };

        pdu_list.push(pdu);
    }

    Ok(pdu_list)
}

fn get_or_create_directory(name: &str) -> Result<String, Box<dyn std::error::Error>> {
    let env_var = "MY_DIRECTORY";
    if let Some(path_str) = env::var(env_var).ok() {
        let path = Path::new(&path_str);
        if path.exists() && path.is_dir() {
            return Ok(path_str);
        }
    }

    let mut dir_builder = DirBuilder::new();
    dir_builder.recursive(true);

    let temp_dir = tempfile::tempdir()?;
    let dir_path = temp_dir.path().to_string_lossy().into_owned();

    env::set_var(env_var, &dir_path)?;

    Ok(dir_path)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let n = 1000;
    let pdu_list = create_and_populate_nfaapi_pdu_list(n)?;
    println!("Created and populated {} PDUs", pdu_list.len());

    let dir_path = get_or_create_directory("my_directory")?;
    println!("Using directory: {}", dir_path);

    Ok(())
}
