#include <stdlib.h>
#include <pthread.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct {
        int PHY_RX_DCI_TAG;
        int DCI_INDEX;
    } dci_info;
} LTE_PHY_RX_UE_INFO_T;

typedef struct {
    LTE_PHY_RX_UE_INFO_T *array;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
    int insertions;
    int deletions;
} DynamicArray;

DynamicArray* create_dynamic_array(size_t initial_capacity) {
    DynamicArray *da = (DynamicArray*)malloc(sizeof(DynamicArray));
    if (!da) return NULL;
    da->array = (LTE_PHY_RX_UE_INFO_T*)calloc(initial_capacity, sizeof(LTE_PHY_RX_UE_INFO_T));
    if (!da->array) {
        free(da);
        return NULL;
    }
    da->capacity = initial_capacity;
    da->size = 0;
    pthread_mutex_init(&da->lock, NULL);
    da->insertions = 0;
    da->deletions = 0;
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    if (da) {
        free(da->array);
        pthread_mutex_destroy(&da->lock);
        free(da);
    }
}

int insert_into_array(DynamicArray *da, LTE_PHY_RX_UE_INFO_T info) {
    pthread_mutex_lock(&da->lock);
    if (da->size == da->capacity) {
        size_t new_capacity = da->capacity ? da->capacity * 2 : 1;
        LTE_PHY_RX_UE_INFO_T *new_array = (LTE_PHY_RX_UE_INFO_T*)realloc(da->array, new_capacity * sizeof(LTE_PHY_RX_UE_INFO_T));
        if (!new_array) {
            pthread_mutex_unlock(&da->lock);
            return -1; // Memory allocation failed
        }
        da->array = new_array;
        da->capacity = new_capacity;
    }
    da->array[da->size++] = info;
    da->insertions++;
    pthread_mutex_unlock(&da->lock);
    return 0;
}

int delete_from_array(DynamicArray *da, int RNTI) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->size; ++i) {
        if (da->array[i].RNTI == RNTI) {
            memmove(&da->array[i], &da->array[i + 1], (da->size - i - 1) * sizeof(LTE_PHY_RX_UE_INFO_T));
            da->size--;
            da->deletions++;
            pthread_mutex_unlock(&da->lock);
            return 0;
        }
    }
    pthread_mutex_unlock(&da->lock);
    return -1; // RNTI not found
}

void update_array_from_external_source(DynamicArray *da) {
    // Simulate external data source updates
    for (size_t i = 0; i < da->size; ++i) {
        // Update RNTI and DCI_INDEX based on external data
        da->array[i].RNTI += 1;
        da->array[i].dci_info.DCI_INDEX += 1;
    }
}

int get_insertion_count(DynamicArray *da) {
    return da->insertions;
}

int get_deletion_count(DynamicArray *da) {
    return da->deletions;
}
