    double crcFlagDistribution[2]; // [0] for false, [1] for true
} ConfigStruct;

int allocateNFAPIArray(int N, unsigned int seed, ConfigStruct config, NFAPI_CRC_INDICATION_PDU_T **array) {
    if (N <= 0 || N > 1000) {
        return -1; // Invalid input
    }

    *array = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (*array == NULL) {
        return -2; // Memory allocation failed
    }

    srand(seed);
    unsigned short rntiPool[65536];
    for (unsigned short i = 0; i < 65536; ++i) {
        rntiPool[i] = i;
    }
    shuffleArray(rntiPool, 65536);

    int crcFlagFalseCount = N * config.crcFlagDistribution[0];
    int crcFlagTrueCount = N - crcFlagFalseCount;

    for (int i = 0; i < N; ++i) {
        (*array)[i].RX_UE_INFORMATION_TAG = i + 1;
        (*array)[i].RNTI = rntiPool[i % 65536];
        if (i < crcFlagFalseCount) {
            (*array)[i].CRC_INDICATION_REL8_TAG = 0; // False
        } else {
            (*array)[i].CRC_INDICATION_REL8_TAG = 1; // True
        }
    }

    return 0;
}

void shuffleArray(unsigned short *array, size_t n) {
    for (size_t i = n - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);
        unsigned short temp = array[i];
        array[i] = array[j];
        array[j] = temp;
    }
}

void freeNFAPIArray(NFAPI_CRC_INDICATION_PDU_T *array, int N) {
    if (array != NULL) {
        free(array);
    }
}
