typedef struct MeasurementReport {
    int signal_strength;
    time_t timestamp;
} MeasurementReport;

typedef struct UEContext {
    int ue_id;
    RadioResourceManager *rrm_config;
    pthread_mutex_t report_lock;
    MeasurementReport *reports;
    size_t report_count;
} UEContext;

typedef struct DynamicArray {
    UEContext **array;
    size_t count;
    size_t capacity;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *da = malloc(sizeof(DynamicArray));
    da->array = NULL;
    da->count = 0;
    da->capacity = 0;
    pthread_mutex_init(&da->lock, NULL);
    return da;
}

void destroy_dynamic_array(DynamicArray *da) {
    for (size_t i = 0; i < da->count; ++i) {
        free(da->array[i]->reports);
        free(da->array[i]);
    }
    free(da->array);
    pthread_mutex_destroy(&da->lock);
    free(da);
}

UEContext* find_ue_context(DynamicArray *da, int ue_id) {
    pthread_mutex_lock(&da->lock);
    for (size_t i = 0; i < da->count; ++i) {
        if (da->array[i]->ue_id == ue_id) {
            pthread_mutex_unlock(&da->lock);
            return da->array[i];
        }
    }
    pthread_mutex_unlock(&da->lock);
    return NULL;
}

void add_or_update_ue_context(DynamicArray *da, int ue_id, RadioResourceManager *rrm_config) {
    UEContext *ue = find_ue_context(da, ue_id);
    if (ue == NULL) {
        pthread_mutex_lock(&da->lock);
        if (da->count >= da->capacity) {
            da->capacity = (da->capacity == 0) ? 1 : da->capacity * 2;
            da->array = realloc(da->array, da->capacity * sizeof(UEContext*));
        }
        ue = malloc(sizeof(UEContext));
        ue->ue_id = ue_id;
        ue->rrm_config = rrm_config;
        pthread_mutex_init(&ue->report_lock, NULL);
        ue->reports = NULL;
        ue->report_count = 0;
        da->array[da->count++] = ue;
        pthread_mutex_unlock(&da->lock);
    } else {
        pthread_mutex_lock(&ue->report_lock);
        // Update existing UEContext
        pthread_mutex_unlock(&ue->report_lock);
    }
}

void add_measurement_report(UEContext *ue, int signal_strength) {
    pthread_mutex_lock(&ue->report_lock);
    MeasurementReport *new_report = realloc(ue->reports, (ue->report_count + 1) * sizeof(MeasurementReport));
    new_report[ue->report_count].signal_strength = signal_strength;
    new_report[ue->report_count].timestamp = time(NULL);
    ue->reports = new_report;
    ++ue->report_count;
    pthread_mutex_unlock(&ue->report_lock);
}

MeasurementReport* get_latest_measurement(UEContext *ue) {
    pthread_mutex_lock(&ue->report_lock);
    if (ue->report_count > 0) {
        MeasurementReport *latest_report = &ue->reports[ue->report_count - 1];
        pthread_mutex_unlock(&ue->report_lock);
        return latest_report;
    }
    pthread_mutex_unlock(&ue->report_lock);
    return NULL;
}
