            current->data.CRCFLAG = new_CRCFLAG;
        }
        current = current->next;
    }
}

void iterate_and_update(DynamicList* list, int (*update_condition)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !update_condition) return;

    ListNode* current = list->head;
    while (current) {
        if (update_condition(current->data)) {
            // Perform bulk update operation
        }
        current = current->next;
    }
}

int serialize_list(DynamicList* list, FILE* file) {
    if (!list || !file) return -1;

    size_t written = fwrite(&list->count, sizeof(size_t), 1, file);
    if (written != 1) return -2;

    ListNode* current = list->head;
    while (current) {
        written = fwrite(&current->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (written != 1) return -3;
        current = current->next;
    }

    return 0;
}

int deserialize_list(DynamicList* list, FILE* file) {
    if (!list || !file) return -1;

    size_t count;
    size_t read = fread(&count, sizeof(size_t), 1, file);
    if (read != 1) return -2;

    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        read = fread(&data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        if (read != 1) return -3;

        ListNode* new_node = (ListNode*)malloc(sizeof(ListNode));
        if (!new_node) return -4;

        new_node->data = data;
        new_node->next = list->head;
        list->head = new_node;
    }

    list->count = count;
    return 0;
}
