#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>

typedef struct record {
    long offset;
    int key;
    struct record *next;
} Record;

Record* create_records(size_t size, int min, int max, size_t alignment) {
    if (size == 0 || min > max) return NULL;

    // Allocate memory for the records array
    void *aligned_mem = aligned_alloc(alignment, size * sizeof(Record));
    if (!aligned_mem) return NULL;

    Record *records = (Record *)aligned_mem;
    memset(records, 0, size * sizeof(Record));

    // Initialize random seed
    srand(time(NULL));

    // Allocate memory for keys array and initialize references
    int *keys = (int *)malloc(size * sizeof(int));
    if (!keys) {
        free(aligned_mem);
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i].offset = rand() % (max - min + 1) + min;
        records[i].key = keys[i] = rand() % (max - min + 1) + min;
        records[i].next = NULL;
    }

    // Ensure all keys are referenced by at least one record
    for (size_t i = 0; i < size; ++i) {
        int key = keys[i];
        Record *current = records;
        while (current && current->key != key) {
            current = current->next;
        }
        if (!current) {
            // Handle the case where a key is not referenced
            free(keys);
            free(aligned_mem);
            return NULL;
        }
    }

    // Free keys array as it's no longer needed
    free(keys);

    return records;
}

void verify_records(Record *records, size_t size) {
    int *key_count = (int *)calloc(size, sizeof(int));
    if (!key_count) return;

    for (size_t i = 0; i < size; ++i) {
        Record *current = &records[i];
        while (current) {
            key_count[current->key]++;
            current = current->next;
        }
    }

    for (size_t i = 0; i < size; ++i) {
        if (key_count[i] == 0) {
            // Handle the case where a key is not referenced
            free(key_count);
            return;
        }
    }

    free(key_count);
}
