    if (ue_contexts[index] != NULL) {
        // Handle error: Index already occupied
        pthread_mutex_unlock(&ue_contexts[index]->lock);
        return;
    }
    ue_contexts[index] = new_context;
    pthread_mutex_unlock(&ue_contexts[index]->lock);
}

