    pthread_mutex_lock(&context->lock);
    if (context->report_count == 0) {
        pthread_mutex_unlock(&context->lock);
        return NULL;
    }
    MeasurementReport *latest_report = &context->reports[context->report_count - 1];
    pthread_mutex_unlock(&context->lock);
    return latest_report;
