typedef struct {
    pthread_mutex_t lock;
    UEContext** contexts;
    size_t capacity;
    size_t size;
} UEContextManager;

UEContextManager* create_UEContextManager() {
    UEContextManager* manager = (UEContextManager*)malloc(sizeof(UEContextManager));
    if (!manager) return NULL;
    manager->contexts = NULL;
    manager->capacity = 0;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

void destroy_UEContextManager(UEContextManager* manager) {
    for (size_t i = 0; i < manager->size; ++i) {
        free(manager->contexts[i]);
    }
    free(manager->contexts);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int addOrUpdateUEContext(UEContextManager* manager, UEContext* context) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->ue_id == context->ue_id) {
            free(manager->contexts[i]);
            manager->contexts[i] = context;
            pthread_mutex_unlock(&manager->lock);
            return 0;
        }
    }
    if (manager->size >= manager->capacity) {
        size_t new_capacity = manager->capacity ? manager->capacity * 2 : 16;
        UEContext** new_contexts = (UEContext**)realloc(manager->contexts, new_capacity * sizeof(UEContext*));
        if (!new_contexts) {
            pthread_mutex_unlock(&manager->lock);
            return -1;
        }
        manager->contexts = new_contexts;
        manager->capacity = new_capacity;
    }
    manager->contexts[manager->size++] = context;
    pthread_mutex_unlock(&manager->lock);
    return 0;
}

MeasurementReport* getLatestMeasurement(UEContextManager* manager, int ue_id) {
    pthread_mutex_lock(&manager->lock);
    for (size_t i = 0; i < manager->size; ++i) {
        if (manager->contexts[i]->ue_id == ue_id) {
            // Assuming the latest measurement is at the end of the list
            MeasurementReport* report = &manager->contexts[i]->measurement_reports[manager->contexts[i]->num_reports - 1];
            pthread_mutex_unlock(&manager->lock);
            return report;
        }
    }
    pthread_mutex_unlock(&manager->lock);
    return NULL;
}

