#include <stdlib.h>
#include <string.h>
#include <errno.h>

typedef struct PHY_RX_FRAME_INFO_T {
    RX_FRAME_INFO_TAG tag;
    PHY_HEADER header;
    int signal_strength;
    uint8_t *raw_data;
    size_t raw_data_size;
} PHY_RX_FRAME_INFO_T;

typedef struct Node {
    PHY_RX_FRAME_INFO_T data;
    struct Node *next;
} Node;

typedef struct List {
    Node *head;
    Node *tail;
    size_t count;
} List;

List* list_create() {
    List *list = (List*)malloc(sizeof(List));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    return list;
}

void list_destroy(List *list) {
    Node *current = list->head;
    while (current) {
        Node *next = current->next;
        free(current->data.raw_data);
        free(current);
        current = next;
    }
    free(list);
}

int list_add(List *list, PHY_RX_FRAME_INFO_T data) {
    Node *new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) return -ENOMEM;

    new_node->data = data;
    new_node->next = NULL;

    if (list->tail) {
        list->tail->next = new_node;
        list->tail = new_node;
    } else {
        list->head = list->tail = new_node;
    }

    list->count++;
    return 0;
}

int list_update(List *list, RX_FRAME_INFO_TAG tag, PHY_RX_FRAME_INFO_T data) {
    Node *current = list->head;
    while (current) {
        if (current->data.tag == tag) {
            current->data = data;
            return 0;
        }
        current = current->next;
    }
    return -ENOENT;
}

int list_remove(List *list, RX_FRAME_INFO_TAG tag) {
    Node *current = list->head;
    Node *prev = NULL;

    while (current) {
        if (current->data.tag == tag) {
            if (prev) prev->next = current->next;
            else list->head = current->next;

            if (current == list->tail) list->tail = prev;

            free(current->data.raw_data);
            free(current);

            list->count--;
            return 0;
        }
        prev = current;
        current = current->next;
    }

    return -ENOENT;
}

