#include <semaphore.h>
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    sem_t *sem;
    pthread_mutex_t log_lock;
} SemaphoreManager;

SemaphoreManager* create_semaphore_manager(int initial_value) {
    SemaphoreManager *manager = (SemaphoreManager*)malloc(sizeof(SemaphoreManager));
    manager->sem = (sem_t*)malloc(sizeof(sem_t));
    if (sem_init(manager->sem, 0, initial_value) != 0) {
        perror("Failed to initialize semaphore");
        free(manager);
        return NULL;
    }
    pthread_mutex_init(&manager->log_lock, NULL);
    return manager;
}

void destroy_semaphore_manager(SemaphoreManager *manager) {
    if (sem_destroy(manager->sem) != 0) {
        perror("Failed to destroy semaphore");
    } else {
        free(manager->sem);
    }
    pthread_mutex_destroy(&manager->log_lock);
    free(manager);
}

int acquire_semaphore(SemaphoreManager *manager, int timeout_ms) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += timeout_ms / 1000;
    ts.tv_nsec += (timeout_ms % 1000) * 1000000;
    if (sem_timedwait(manager->sem, &ts) != 0) {
        perror("Failed to acquire semaphore");
        return -1;
    }
    log_semaphore_operation(manager, "acquire", pthread_self());
    return 0;
}

void release_semaphore(SemaphoreManager *manager) {
    sem_post(manager->sem);
    log_semaphore_operation(manager, "release", pthread_self());
}

void log_semaphore_operation(SemaphoreManager *manager, const char* operation, pthread_t thread_id) {
    pthread_mutex_lock(&manager->log_lock);
    time_t now = time(NULL);
    printf("Thread %lu at %s: Semaphore %s\n", thread_id, ctime(&now), operation);
    pthread_mutex_unlock(&manager->log_lock);
}

int main() {
    SemaphoreManager *manager = create_semaphore_manager(5);
    if (manager == NULL) {
        return 1;
    }

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, (void*)acquire_semaphore, manager);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_semaphore_manager(manager);
    return 0;
}
