const { Readable } = require('stream');

function copyBufferedData(chunks, numBytes) {
  let totalBytesRead = 0;
  const targetBuffer = Buffer.allocUnsafe(numBytes);

  return new Promise((resolve, reject) => {
    const stream = new Readable({
      read(size) {}
    });

    chunks.forEach(chunk => {
      if (totalBytesRead + chunk.length > numBytes) {
        chunk.copy(targetBuffer, totalBytesRead, 0, numBytes - totalBytesRead);
        totalBytesRead = numBytes;
      } else {
        chunk.copy(targetBuffer, totalBytesRead);
        totalBytesRead += chunk.length;
      }

      if (totalBytesRead === numBytes) {
        stream.push(null); // Signal end of data
      }
    });

    stream.on('data', chunk => {
      // Handle incoming data chunks
    });

    stream.on('end', () => {
      resolve(targetBuffer);
    });

    stream.on('error', err => {
      reject(err);
    });
  });
}

// Example usage:
const chunks = [Buffer.from('Hello'), Buffer.from('World')];
copyBufferedData(chunks, 10).then(buffer => {
  console.log(buffer.toString()); // Output: 'HelloWorld'
}).catch(err => {
  console.error(err);
});
