    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);

    FILE* infile = fopen(filename, "rb");
    if (!infile) {
        fprintf(stderr, "Error opening file\n");
        return metadata;
    }

    jpeg_stdio_src(&cinfo, infile);
    jpeg_read_header(&cinfo, TRUE);
    jpeg_start_decompress(&cinfo);

    metadata.width = cinfo.output_width;
    metadata.height = cinfo.output_height;

    switch (cinfo.out_color_space) {
        case JCS_GRAYSCALE:
            strcpy(metadata.color_space, "Grayscale");
            break;
        case JCS_RGB:
            strcpy(metadata.color_space, "RGB");
            break;
        case JCS_YCbCr:
            strcpy(metadata.color_space, "YCbCr");
            break;
        default:
            strcpy(metadata.color_space, "Unknown");
            break;
    }

    metadata.quality = cinfo.dct_method;

    jpeg_finish_decompress(&cinfo);
    jpeg_destroy_decompress(&cinfo);
    fclose(infile);

    return metadata;
}

int main() {
    JpegMetadata metadata = extract_jpeg_metadata("example.jpg");
    printf("Width: %d\n", metadata.width);
    printf("Height: %d\n", metadata.height);
    printf("Color Space: %s\n", metadata.color_space);
    printf("Quality: %d\n", metadata.quality);

    return 0;
}
