#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_BATCH_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_array;
    size_t allocated_size;
    size_t used_size;
    pthread_mutex_t lock;
} ThreadSafeAllocator;

ThreadSafeAllocator* create_allocator(size_t initial_size) {
    ThreadSafeAllocator *allocator = (ThreadSafeAllocator*)malloc(sizeof(ThreadSafeAllocator));
    allocator->pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    allocator->allocated_size = initial_size;
    allocator->used_size = 0;
    pthread_mutex_init(&allocator->lock, NULL);
    return allocator;
}

void destroy_allocator(ThreadSafeAllocator *allocator) {
    free(allocator->pdu_array);
    pthread_mutex_destroy(&allocator->lock);
    free(allocator);
}

NFAPI_CRC_INDICATION_PDU_T* allocate_pdu(ThreadSafeAllocator *allocator) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    pthread_mutex_lock(&allocator->lock);
    if (allocator->used_size == allocator->allocated_size) {
        size_t new_size = allocator->allocated_size * 2;
        allocator->pdu_array = realloc(allocator->pdu_array, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        allocator->allocated_size = new_size;
    }
    pdu = &allocator->pdu_array[allocator->used_size++];
    pthread_mutex_unlock(&allocator->lock);
    return pdu;
}

void populate_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example value
    pdu->RNTI = rand() % 256; // Example value
    pdu->CRC_INDICATION_REL8_TAG = (rand() % 2 == 0); // Randomly set CRCFLAG
}

void* generate_pdus(void *arg) {
    ThreadSafeAllocator *allocator = (ThreadSafeAllocator*)arg;
    for (int i = 0; i < MAX_BATCH_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = allocate_pdu(allocator);
        populate_pdu(pdu);
    }
    return NULL;
}

int main() {
    srand(time(NULL));
    ThreadSafeAllocator *allocator = create_allocator(100);

    pthread_t threads[10];
    for (int i = 0; i < 10; i++) {
        pthread_create(&threads[i], NULL, generate_pdus, allocator);
    }

    for (int i = 0; i < 10; i++) {
        pthread_join(threads[i], NULL);
    }

    destroy_allocator(allocator);
    return 0;
}
```

