CRC_LIST_T *create_crc_list() {
    CRC_LIST_T *list = (CRC_LIST_T *)malloc(sizeof(CRC_LIST_T));
    if (!list) {
        perror("Failed to allocate memory for CRC list");
        return NULL;
    }
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        free(list->list[i]);
    }
    pthread_mutex_unlock(&list->mutex);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_indication(CRC_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *indication) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_USERS) {
        fprintf(stderr, "CRC list is full\n");
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->list[list->size++] = indication;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

