typedef struct {
    long offset;
    int key;
    int value;
} long_offset;

typedef struct {
    int key;
    long_offset* offsets;
    int num_offsets;
} key_record;

typedef struct {
    int rnti;
    key_record** records;
    int num_records;
} record;

NFAPI_CRC_INDICATION_PDU_T* init_nfaapi_crc_indication_pdu(int n) {
    if (n > MAX_ELEMENTS) {
        // Log error and handle gracefully
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdus = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        // Log memory allocation failure
        return NULL;
    }

    srand(time(NULL));

    for (int i = 0; i < n; i++) {
        pdus[i].rx_ue_information_tag = rand() % 1000000;
        pdus[i].rnti = rand() % 65536;
        pdus[i].crc_indication_rel8_tag.crcflag = (rand() % 2) ? NFAPI_CRC_INDICATION_PASS : NFAPI_CRC_INDICATION_FAIL;

        int num_records = rand() % 10 + 1;
        key_record** records = malloc(num_records * sizeof(key_record*));
        if (!records) {
            // Log memory allocation failure
            free(pdus);
            return NULL;
        }

        for (int j = 0; j < num_records; j++) {
            key_record* record = malloc(sizeof(key_record));
            if (!record) {
                // Log memory allocation failure
                for (int k = 0; k < j; k++) {
                    free(records[k]);
                }
                free(records);
                free(pdus);
                return NULL;
            }

            record->key = rand() % 1000000;
            int num_offsets = rand() % 5 + 1;
            long_offset* offsets = malloc(num_offsets * sizeof(long_offset));
            if (!offsets) {
                // Log memory allocation failure
                free(record);
                for (int k = 0; k < j; k++) {
                    free(records[k]);
                }
                free(records);
                free(pdus);
                return NULL;
            }

            for (int k = 0; k < num_offsets; k++) {
                offsets[k].offset = rand() % THRESHOLD_SIZE;
                offsets[k].key = rand() % 1000000;
                offsets[k].value = rand() % 1000000;
            }

            record->offsets = offsets;
            record->num_offsets = num_offsets;
            records[j] = record;
        }

        pdus[i].crc_indication_rel8_tag.records = records;
        pdus[i].crc_indication_rel8_tag.num_records = num_records;
    }

    return pdus;
}

void free_nfaapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T* pdus, int n) {
    for (int i = 0; i < n; i++) {
        key_record** records = pdus[i].crc_indication_rel8_tag.records;
        for (int j = 0; j < pdus[i].crc_indication_rel8_tag.num_records; j++) {
            long_offset* offsets = records[j]->offsets;
            free(offsets);
            free(records[j]);
        }
        free(records);
    }
    free(pdus);
}
