#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_ENTRIES 1024

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void log_entry(NFAPI_CRC_INDICATION_PDU_T *entry) {
    FILE *audit_file = fopen("audit.log", "a");
    if (audit_file == NULL) {
        perror("Failed to open audit file");
        return;
    }
    fprintf(audit_file, "RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d\n",
            entry->RX_UE_INFORMATION_TAG, entry->RNTI, entry->CRC_INDICATION_REL8_TAG);
    fclose(audit_file);
}

int is_duplicate(NFAPI_CRC_INDICATION_PDU_T *entries, int count, NFAPI_CRC_INDICATION_PDU_T new_entry) {
    for (int i = 0; i < count; i++) {
        if (entries[i].RNTI == new_entry.RNTI) {
            return 1;
        }
    }
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* create_entries(int N, int *error_code) {
    if (N > MAX_ENTRIES) {
        *error_code = -1; // Error code for exceeding maximum entries
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T *entries = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (entries == NULL) {
        *error_code = -2; // Error code for memory allocation failure
        return NULL;
    }

    srand(time(NULL)); // Seed for random number generation

    int count = 0;
    while (count < N) {
        NFAPI_CRC_INDICATION_PDU_T new_entry;
        new_entry.RX_UE_INFORMATION_TAG = rand() % 1000; // Example range
        new_entry.RNTI = rand() % 4096; // Example range, assuming valid RNTI values are within this range
        new_entry.CRC_INDICATION_REL8_TAG = (rand() % 2) ? 1 : 0; // Randomly set CRCFLAG

        if (!is_duplicate(entries, count, new_entry)) {
            entries[count++] = new_entry;
            log_entry(&entries[count - 1]);
        }
