        offsets[i] = rand();
        keys[i] = rand() % (max_value - min_value + 1) + min_value;
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }

    // Log allocation details
    log_info("Allocated memory for offsets, keys, and records");

    return records;
}

void cleanup_resources(void* records, size_t num_records) {
