NFAPI_CRC_INDICATION_PDU_T* create_and_populate_list(int N, pthread_mutex_t* mutex, pthread_cond_t* cond) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(mutex);
        list[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
        pthread_mutex_unlock(mutex);

        // Simulate DNS resolution and caching
        static DNS_ENTRY_T dns_cache[DNS_CACHE_SIZE];
        static int cache_index = 0;
        if (cache_index >= DNS_CACHE_SIZE) {
            cache_index = 0; // Simple round-robin replacement policy
        }
        strcpy(dns_cache[cache_index].hostname, "example.com");
        dns_cache[cache_index].ip_address = rand() % 256; // Simulated IP address
        cache_index++;
    }

    return list;
}

void* async_dns_resolution(void* arg) {
    char** hostnames = (char**)arg;
    for (int i = 0; i < MAX_HOSTS; i++) {
        if (!hostnames[i]) break;

        // Simulate DNS resolution
        printf("Resolving %s\n", hostnames[i]);
        sleep(1); // Simulated network delay

        // Cache the resolved IP address
        static DNS_ENTRY_T dns_cache[DNS_CACHE_SIZE];
        static int cache_index = 0;
        if (cache_index >= DNS_CACHE_SIZE) {
            cache_index = 0; // Simple round-robin replacement policy
        }
        strcpy(dns_cache[cache_index].hostname, hostnames[i]);
        dns_cache[cache_index].ip_address = rand() % 256; // Simulated IP address
        cache_index++;
    }

    return NULL;
}

int main() {
    srand(time(NULL));

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    NFAPI_CRC_INDICATION_PDU_T* list = create_and_populate_list(10, &mutex, &cond);
    if (list) {
        free(list);
    }

    char* hostnames[MAX_HOSTS];
    for (int i = 0; i < MAX_HOSTS; i++) {
        hostnames[i] = (char*)malloc(256 * sizeof(char));
        snprintf(hostnames[i], 256, "example%d.com", i);
    }

    pthread_t dns_threads[RATE_LIMITER_MAX_CONCURRENT_REQUESTS];
    for (int i = 0; i < RATE_LIMITER_MAX_CONCURRENT_REQUESTS; i++) {
        if (pthread_create(&dns_threads[i], NULL, async_dns_resolution, hostnames) != 0) {
            perror("Failed to create thread");
        }
    }

    for (int i = 0; i < RATE_LIMITER_MAX_CONCURRENT_REQUESTS; i++) {
        pthread_join(dns_threads[i], NULL);
    }

    for (int i = 0; i < MAX_HOSTS; i++) {
        free(hostnames[i]);
    }

    return 0;
}
