#define MAX_PDUS 1000

NFAPI_RX_PDU_T *pdus;
int pdu_count = 0;
pthread_mutex_t pdus_mutex;

void init_pdus() {
    pthread_mutex_init(&pdus_mutex, NULL);
    pdus = (NFAPI_RX_PDU_T *)malloc(MAX_PDUS * sizeof(NFAPI_RX_PDU_T));
    if (!pdus) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
}

void cleanup_pdus() {
    pthread_mutex_destroy(&pdus_mutex);
    free(pdus);
}

void* process_pdu(void* arg) {
    int index = *(int*)arg;
    NFAPI_RX_PDU_T *pdu = &pdus[index];
    pthread_mutex_lock(&pdus_mutex);
    pdu->RX_UE_INFORMATION_TAG = rand() % 1000; // Example tag
    pdu->RNTI = rand() % 256; // Example RNTI
    pdu->CRC_INDICATION_REL8_TAG = rand() % 2; // Random CRC flag
    pthread_mutex_unlock(&pdus_mutex);
    return NULL;
}

void process_pdus_in_parallel(int num_threads) {
    pthread_t threads[num_threads];
    int indices[num_threads];

    for (int i = 0; i < num_threads; i++) {
        indices[i] = i * MAX_PDUS / num_threads;
        if (pthread_create(&threads[i], NULL, process_pdu, &indices[i]) != 0) {
            fprintf(stderr, "Thread creation failed\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }
}

void report_results() {
    printf("Total PDUs processed: %d\n", pdu_count);
}

int main() {
    srand(time(NULL));
    init_pdus();

    int num_threads = 4;
    process_pdus_in_parallel(num_threads);

    cleanup_pdus();
    report_results();

    return 0;
}
