typedef struct {
    int connection_id;
    char buffer[BUFFER_SIZE];
    time_t last_update;
    TCP_STATUS status;
} TCP_CONNECTION_T;

TCP_CONNECTION_T* initialize_connections(int num_connections) {
    TCP_CONNECTION_T* connections = (TCP_CONNECTION_T*)malloc(num_connections * sizeof(TCP_CONNECTION_T));
    if (connections == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    for (int i = 0; i < num_connections; i++) {
        connections[i].connection_id = i + 1;
        connections[i].last_update = time(NULL);
        connections[i].status = ACTIVE;

        // Populate buffer with dummy data
        for (int j = 0; j < BUFFER_SIZE; j++) {
            connections[i].buffer[j] = 'A' + (i % 26);
        }
    }

    return connections;
}

void update_connection_status(TCP_CONNECTION_T* connections, int num_connections) {
    time_t current_time = time(NULL);

    for (int i = 0; i < num_connections; i++) {
        if (current_time - connections[i].last_update > 60) { // Simulate timeout after 1 minute
            connections[i].status = IDLE;
        }
    }
}

void log_connection_status(TCP_CONNECTION_T* connections, int num_connections) {
    for (int i = 0; i < num_connections; i++) {
        printf("Connection %d: Status=%s, Last Update=%ld\n", 
               connections[i].connection_id, 
               connections[i].status == ACTIVE ? "ACTIVE" : 
               connections[i].status == IDLE ? "IDLE" : "CLOSED",
               connections[i].last_update);
    }
}

void free_connections(TCP_CONNECTION_T* connections) {
    if (connections != NULL) {
        free(connections);
    }
}

int main() {
    int num_connections = 5;
    TCP_CONNECTION_T* connections = initialize_connections(num_connections);

    if (connections != NULL) {
        update_connection_status(connections, num_connections);
        log_connection_status(connections, num_connections);
        free_connections(connections);
    }

    return 0;
}
