#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    long timestamp;
    struct NFAPI_CRC_INDICATION_PDU_T *prev;
    struct NFAPI_CRC_INDICATION_PDU_T *next;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    int count;
    pthread_mutex_t mutex;
} CRC_LIST;

int init_crc_list(CRC_LIST *list) {
    list->head = NULL;
    list->tail = NULL;
    list->count = 0;
    return pthread_mutex_init(&list->mutex, NULL);
}

void destroy_crc_list(CRC_LIST *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->mutex);
}

int add_to_crc_list(CRC_LIST *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG, long timestamp) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *new_node = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_node == NULL) {
        pthread_mutex_unlock(&list->mutex);
        return -1; // Memory allocation failure
    }
    new_node->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    new_node->RNTI = RNTI;
    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->timestamp = timestamp;
    new_node->prev = NULL;
    new_node->next = list->head;

    if (list->head != NULL) {
        list->head->prev = new_node;
    } else {
        list->tail = new_node;
    }
    list->head = new_node;
    list->count++;
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

int remove_from_crc_list(CRC_LIST *list, int RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (current->prev != NULL) {
                current->prev->next = current->next;
            } else {
                list->head = current->next;
            }
            if (current->next != NULL) {
                current->next->prev = current->prev;
            } else {
                list->tail = current->prev;
            }
            free(current);
            list->count--;
            pthread_mutex_unlock(&list->mutex);
            return 0;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return -1; // Element not found
}

int get_crc_list_count(CRC_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    int count = list->count;
    pthread_mutex_unlock(&list->mutex);
    return count;
}
