    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* dynamic_list[MAX_STRUCTURES];
int current_size = 0;
int threshold = 5000; // Default threshold for automatic scaling

void generate_random_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    srand(time(NULL));
    pdu->RX_UE_INFORMATION_TAG = rand() % 100000;
    pdu->RNTI = rand() % 256;
    pdu->CRC_INDICATION_REL8_TAG = rand() % 1000;
    pdu->CRCFLAG = rand() % 2; // Randomly set CRCFLAG to either 0 or 1
}

int add_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (current_size >= MAX_STRUCTURES) {
        printf("Error: Maximum number of structures reached.\n");
        return -1;
    }

    dynamic_list[current_size] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!dynamic_list[current_size]) {
        printf("Error: Memory allocation failed.\n");
        return -1;
    }

    *dynamic_list[current_size] = *pdu;
    current_size++;
    return 0;
}

int verify_checksum(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Simple checksum verification using XOR
    int checksum = pdu->RX_UE_INFORMATION_TAG ^ pdu->RNTI ^ pdu->CRC_INDICATION_REL8_TAG;
    return (checksum == pdu->CRCFLAG);
}

void cleanup() {
    for (int i = 0; i < current_size; i++) {
        free(dynamic_list[i]);
    }
    current_size = 0;
}

int main() {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    generate_random_crc_indication(&pdu);

    if (!verify_checksum(&pdu)) {
        printf("Checksum verification failed.\n");
        return -1;
    }

    if (add_to_list(&pdu) == 0) {
        printf("Structure added successfully.\n");
    }

    cleanup();
    return 0;
}
