    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t count;
    pthread_mutex_t lock;
} CRC_LIST_T;

CRC_LIST_T* create_crc_list() {
    CRC_LIST_T *list = (CRC_LIST_T*)malloc(sizeof(CRC_LIST_T));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void destroy_crc_list(CRC_LIST_T *list) {
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }
    pthread_mutex_destroy(&list->lock);
    free(list);
}

int add_crc_node(CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
