    new_node->CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    new_node->CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    if (list->tail) {
        list->tail->next = new_node;
    } else {
        list->head = new_node;
    }
    list->tail = new_node;
    list->count++;
    pthread_mutex_unlock(&list->lock);
    return 0; // Success
}

int verify_crc_list(CRC_LIST_T *list) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current && current->next) {
        if (current->CRCFLAG == current->next->CRCFLAG) {
            pthread_mutex_unlock(&list->lock);
            return -1; // Consecutive nodes have the same CRCFLAG
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
    return 0; // Verification successful
}

