#include <pthread.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PDUS 10000
#define CACHE_SIZE 1024

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T pdus[MAX_PDUS];
    int count;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} PduList;

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T pdu;
} CacheEntry;

CacheEntry cache[CACHE_SIZE];
int cache_count = 0;
pthread_mutex_t cache_mutex;

PduList *create_pdu_list() {
    PduList *list = (PduList *)malloc(sizeof(PduList));
    if (!list) return NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

void destroy_pdu_list(PduList *list) {
    pthread_mutex_destroy(&list->mutex);
    pthread_cond_destroy(&list->cond);
    free(list);
}

int add_pdu(PduList *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->count >= MAX_PDUS) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    list->pdus[list->count++] = pdu;
    pthread_cond_signal(&list->cond);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T *get_pdu(PduList *list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; i++) {
        if (list->pdus[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && list->pdus[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return &list->pdus[i];
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void *flush_list_to_storage(void *arg) {
    PduList *list = (PduList *)arg;
    while (1) {
        pthread_mutex_lock(&list->mutex);
        while (list->count == 0) {
            pthread_cond_wait(&list->cond, &list->mutex);
        }
        // Code to flush list to storage
        pthread_mutex_unlock(&list->mutex);
        sleep(1); // Simulate periodic flushing
    }
    return NULL;
}

void *cache_thread(void *arg) {
    PduList *list = (PduList *)arg;
    while (1) {
        pthread_mutex_lock(&list->mutex);
        if (list->count > 0) {
            CacheEntry entry;
            entry.RX_UE_INFORMATION_TAG = list->pdus[0].RX_UE_INFORMATION_TAG;
            entry.RNTI = list->pdus[0].RNTI;
            entry.pdu = list->pdus[0];
            pthread_mutex_lock(&cache_mutex);
            if (cache_count < CACHE_SIZE) {
                cache[cache_count++] = entry;
            }
            pthread_mutex_unlock(&cache_mutex);
        }
        pthread_mutex_unlock(&list->mutex);
        sleep(1); // Simulate periodic caching
    }
    return NULL;
}

int main() {
    PduList *list = create_pdu_list();
    if (!list) return -1;

    pthread_t flush_thread, cache_tid;
    pthread_create(&flush_thread, NULL, flush_list_to_storage, list);
    pthread_create(&cache_tid, NULL, cache_thread, list);

    // Simulate adding PDUs
    for (int i = 0; i < MAX_PDUS; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.RX_UE_INFORMATION_TAG = rand();
        pdu.RNTI = rand() % 1024;
        pdu.CRCFLAG = rand() % 2;
        add_pdu(list, pdu);
    }

    pthread_join(flush_thread, NULL);
    pthread_join(cache_tid, NULL);

    destroy_pdu_list(list);
    return 0;
}
