typedef enum {
    ACTIVE,
    INACTIVE
} ConnectionStatus;

typedef struct {
    char ip[16];
    int port;
    ConnectionStatus status;
} TCPConnection;

TCPConnection connections[MAX_CONNECTIONS];
int connection_count = 0;

void add_connection(const char *ip, int port) {
    if (connection_count >= MAX_CONNECTIONS) {
        printf("Maximum number of connections reached.\n");
        return;
    }
    strcpy(connections[connection_count].ip, ip);
    connections[connection_count].port = port;
    connections[connection_count].status = ACTIVE;
    connection_count++;
}

void update_connection(const char *ip, int port, ConnectionStatus status) {
    for (int i = 0; i < connection_count; i++) {
        if (strcmp(connections[i].ip, ip) == 0 && connections[i].port == port) {
            connections[i].status = status;
            return;
        }
    }
    printf("Connection not found.\n");
}

void remove_connection(const char *ip, int port) {
    for (int i = 0; i < connection_count; i++) {
        if (strcmp(connections[i].ip, ip) == 0 && connections[i].port == port) {
            for (int j = i; j < connection_count - 1; j++) {
                connections[j] = connections[j + 1];
            }
            connection_count--;
            return;
        }
    }
    printf("Connection not found.\n");
}

void clean_up_inactive_connections() {
    for (int i = 0; i < connection_count; i++) {
        if (connections[i].status == INACTIVE) {
            remove_connection(connections[i].ip, connections[i].port);
        }
    }
}

int main() {
    add_connection("192.168.1.1", 8080);
    update_connection("192.168.1.1", 8080, INACTIVE);
    clean_up_inactive_connections();
    return 0;
}
