#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_SESSIONS 1024

typedef struct {
    int id;
    char ip[16];
    char headers[1024];
    time_t timeout;
} HttpSession;

HttpSession sessions[MAX_SESSIONS];
int session_count = 0;
pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(int id, const char* ip, const char* headers, int timeout) {
    pthread_mutex_lock(&session_lock);
    if (session_count < MAX_SESSIONS) {
        HttpSession new_session = {id, ip, headers, time(NULL) + timeout};
        sessions[session_count++] = new_session;
    }
    pthread_mutex_unlock(&session_lock);
}

void update_session(int id, const char* ip, const char* headers, int timeout) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; ++i) {
        if (sessions[i].id == id) {
            sessions[i] = (HttpSession){id, ip, headers, time(NULL) + timeout};
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void terminate_session(int id) {
    pthread_mutex_lock(&session_lock);
    for (int i = 0; i < session_count; ++i) {
        if (sessions[i].id == id) {
            sessions[i] = sessions[--session_count];
            break;
        }
    }
    pthread_mutex_unlock(&session_lock);
}

void* cleanup_sessions(void* arg) {
    while (1) {
        time_t now = time(NULL);
        pthread_mutex_lock(&session_lock);
        for (int i = 0; i < session_count; ++i) {
            if (sessions[i].timeout <= now) {
                sessions[i] = sessions[--session_count];
                --i;
            }
        }
        pthread_mutex_unlock(&session_lock);
        sleep(60); // Check every minute
    }
    return NULL;
}

int main() {
    pthread_t cleanup_thread;
    pthread_create(&cleanup_thread, NULL, cleanup_sessions, NULL);

    add_session(1, "192.168.1.1", "User-Agent: Firefox", 300);
    update_session(1, "192.168.1.1", "User-Agent: Chrome", 600);
    terminate_session(1);

    pthread_join(cleanup_thread, NULL);
    return 0;
}
