typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu_list;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} NFAPI_CRC_LIST_T;

NFAPI_CRC_LIST_T* create_crc_list() {
    NFAPI_CRC_LIST_T *list = (NFAPI_CRC_LIST_T*)malloc(sizeof(NFAPI_CRC_LIST_T));
    if (!list) return NULL;
    list->pdu_list = NULL;
    list->capacity = 0;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void destroy_crc_list(NFAPI_CRC_LIST_T *list) {
    if (list->pdu_list) free(list->pdu_list);
    pthread_mutex_destroy(&list->mutex);
    free(list);
}

int add_crc_pdu(NFAPI_CRC_LIST_T *list, int RX_UE_INFORMATION_TAG, int RNTI, int CRC_INDICATION_REL8_TAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : 1;
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list->pdu_list, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_list) {
            pthread_mutex_unlock(&list->mutex);
            return -1; // Memory allocation failed
        }
        list->pdu_list = new_list;
        list->capacity = new_capacity;
    }

    int i;
    for (i = 0; i < list->size; ++i) {
        if (list->pdu_list[i].RNTI == RNTI) {
            pthread_mutex_unlock(&list->mutex);
            return -2; // Duplicate RNTI detected
        }
    }

    list->pdu_list[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->pdu_list[list->size].RNTI = RNTI;
    list->pdu_list[list->size].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    ++list->size;

    pthread_mutex_unlock(&list->mutex);
    return 0; // Success
}

int generate_random_rnti() {
    static int last_rnti = -1;
    int rnti;
    do {
        rnti = rand() % MAX_RNTI_RANGE + 1;
    } while (rnti == last_rnti);
    last_rnti = rnti;
    return rnti;
