LTE_PHY_RX_PROC *lte_phy_rx_proc_list[MAX_UE_ID];
int lte_phy_rx_proc_count = 0;

bool add_lte_phy_rx_proc(int UE_ID, float SNR, size_t buffer_size) {
    if (lte_phy_rx_proc_count >= MAX_UE_ID) return false;
    LTE_PHY_RX_PROC *new_entry = malloc(sizeof(LTE_PHY_RX_PROC));
    if (!new_entry) return false;
    new_entry->UE_ID = UE_ID;
    new_entry->SNR = SNR;
    new_entry->data_buffer = malloc(buffer_size);
    if (!new_entry->data_buffer) {
        free(new_entry);
        return false;
    }
    new_entry->buffer_size = buffer_size;
    lte_phy_rx_proc_list[lte_phy_rx_proc_count++] = new_entry;
    return true;
}

bool update_lte_phy_rx_proc(int UE_ID, float SNR, size_t buffer_size) {
    for (int i = 0; i < lte_phy_rx_proc_count; i++) {
        if (lte_phy_rx_proc_list[i]->UE_ID == UE_ID) {
            free(lte_phy_rx_proc_list[i]->data_buffer);
            lte_phy_rx_proc_list[i]->SNR = SNR;
            lte_phy_rx_proc_list[i]->data_buffer = realloc(lte_phy_rx_proc_list[i]->data_buffer, buffer_size);
            if (!lte_phy_rx_proc_list[i]->data_buffer) return false;
            lte_phy_rx_proc_list[i]->buffer_size = buffer_size;
            return true;
        }
    }
    return false;
}

void process_data_samples() {
    for (int i = 0; i < lte_phy_rx_proc_count; i++) {
        // Process data samples here
        printf("Processing UE_ID %d with SNR %.2f\n", lte_phy_rx_proc_list[i]->UE_ID, lte_phy_rx_proc_list[i]->SNR);
    }
}

void free_lte_phy_rx_proc() {
    for (int i = 0; i < lte_phy_rx_proc_count; i++) {
        free(lte_phy_rx_proc_list[i]->data_buffer);
        free(lte_phy_rx_proc_list[i]);
    }
    lte_phy_rx_proc_count = 0;
