            for (int j = i; j < crc_list.count - 1; j++) {
                crc_list.entries[j] = crc_list.entries[j + 1];
            }
            crc_list.count--;
            pthread_mutex_unlock(&crc_list.lock);
            return 0;
        }
    }
    printf("Error: Entry with RNTI %d not found\n", RNTI);
    pthread_mutex_unlock(&crc_list.lock);
    return -1;
}

void validate_crc_indications() {
    pthread_mutex_lock(&crc_list.lock);
    for (int i = 0; i < crc_list.count; i++) {
        int recalculated_crcflag = /* Recalculate CRCFLAG based on RX_UE_INFORMATION_TAG and CRC_INDICATION_REL8_TAG */;
        if (recalculated_crcflag != crc_list.entries[i].CRCFLAG) {
            printf("Error: Discrepancy detected for RNTI %d\n", crc_list.entries[i].RNTI);
        }
    }
    pthread_mutex_unlock(&crc_list.lock);
}

int main() {
    init_crc_list();
    add_entry(1, 101, 201);
    update_entry(101, 301);
    remove_entry(101);
    validate_crc_indications();
