#include <time.h>

#define MAX_RNTI_RANGE 1024
#define MAX_CONCURRENT_REQUESTS 100

typedef struct {
    int RNTI;
    // Other fields as per NFAPI_CRC_INDICATION_PDU_T structure
} UE_Data;

typedef struct {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    UE_Data *queue[MAX_CONCURRENT_REQUESTS];
    int front, rear, size;
} ThreadSafeQueue;

void init_queue(ThreadSafeQueue *q) {
    q->front = q->rear = q->size = 0;
    pthread_mutex_init(&q->lock, NULL);
    pthread_cond_init(&q->cond, NULL);
}

int enqueue(ThreadSafeQueue *q, UE_Data *data) {
    pthread_mutex_lock(&q->lock);
    while (q->size == MAX_CONCURRENT_REQUESTS) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    q->queue[q->rear] = data;
    q->rear = (q->rear + 1) % MAX_CONCURRENT_REQUESTS;
    q->size++;
    pthread_mutex_unlock(&q->lock);
    pthread_cond_signal(&q->cond);
    return 0;
}

UE_Data *dequeue(ThreadSafeQueue *q) {
    pthread_mutex_lock(&q->lock);
    while (q->size == 0) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    UE_Data *data = q->queue[q->front];
    q->front = (q->front + 1) % MAX_CONCURRENT_REQUESTS;
    q->size--;
    pthread_mutex_unlock(&q->lock);
    pthread_cond_signal(&q->cond);
    return data;
}

int create_and_populate_nfaapi_pdu(int N, ThreadSafeQueue *queue) {
    srand(time(NULL));
    int rnti_range[MAX_RNTI_RANGE];
    for (int i = 0; i < MAX_RNTI_RANGE; i++) {
        rnti_range[i] = i;
    }

    for (int i = 1; i < MAX_RNTI_RANGE; i++) {
        int j = rand() % (MAX_RNTI_RANGE - i) + i;
        int temp = rnti_range[i];
        rnti_range[i] = rnti_range[j];
        rnti_range[j] = temp;
    }

    for (int i = 0; i < N; i++) {
        UE_Data *data = malloc(sizeof(UE_Data));
        if (!data) {
            // Handle memory allocation failure
            return -1;
        }
        data->RNTI = rnti_range[i % MAX_RNTI_RANGE];
        // Populate other fields as per NFAPI_CRC_INDICATION_PDU_T structure

        enqueue(queue, data);
    }

    return 0;
}
