#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

#define MAX_RNTI 1024
#define MAX_ENTRIES 10000

typedef struct {
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    NFAPI_CRC_INDICATION_PDU_T crc_indication;
} Entry;

typedef struct {
    Entry *entries;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} DynamicArray;

DynamicArray* create_dynamic_array() {
    DynamicArray *array = (DynamicArray*)malloc(sizeof(DynamicArray));
    array->entries = (Entry*)calloc(MAX_ENTRIES, sizeof(Entry));
    array->size = 0;
    array->capacity = MAX_ENTRIES;
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

void destroy_dynamic_array(DynamicArray *array) {
    free(array->entries);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int add_entry(DynamicArray *array, int RX_UE_INFORMATION_TAG, int RNTI, int CRCFLAG) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        Entry *new_entries = (Entry*)realloc(array->entries, array->capacity * 2 * sizeof(Entry));
        if (!new_entries) {
            pthread_mutex_unlock(&array->mutex);
            return -1;
        }
        array->entries = new_entries;
        array->capacity *= 2;
    }
    array->entries[array->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array->entries[array->size].RNTI = RNTI;
    array->entries[array->size].crc_indication.CRCFLAG = CRCFLAG;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

int update_entry(DynamicArray *array, int RNTI, int new_CRCFLAG) {
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        if (array->entries[i].RNTI == RNTI) {
            array->entries[i].crc_indication.CRCFLAG = new_CRCFLAG;
            pthread_mutex_unlock(&array->mutex);
            return 0;
        }
    }
    pthread_mutex_unlock(&array->mutex);
    return -1;
}

void print_statistics(DynamicArray *array) {
    int total_crcflag = 0;
    int max_crcflag = 0;
    for (int i = 0; i < array->size; i++) {
        total_crcflag += array->entries[i].crc_indication.CRCFLAG;
        if (array->entries[i].crc_indication.CRCFLAG > max_crcflag) {
            max_crcflag = array->entries[i].crc_indication.CRCFLAG;
        }
    }
    double average_crcflag = (double)total_crcflag / array->size;
    printf("Total CRCFLAG: %d\n", total_crcflag);
    printf("Maximum CRCFLAG: %d\n", max_crcflag);
    printf("Average CRCFLAG: %.2f\n", average_crcflag);
}

int main() {
    DynamicArray *array = create_dynamic_array();
    add_entry(array, 1, 101, 1);
    add_entry(array, 2, 102, 0);
    update_entry(array, 101, 0);
    print_statistics(array);
    destroy_dynamic_array(array);
    return 0;
}
