void resolve_dns(const char* hostname, u_char* ip_address) {
    struct addrinfo hints, *res, *p;
    int status;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // Allow IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    if ((status = getaddrinfo(hostname, NULL, &hints, &res)) != 0) {
        fprintf(stderr, "getaddrinfo error: %s\n", gai_strerror(status));
        return;
    }

    for (p = res; p != NULL; p = p->ai_next) {
        if (p->ai_family == AF_INET) { // IPv4
            struct sockaddr_in* ipv4 = (struct sockaddr_in*)p->ai_addr;
            memcpy(ip_address, &ipv4->sin_addr, 4);
            break;
        }
    }

    freeaddrinfo(res);
}

void manage_dns_cache(const char* hostname, u_char* ip_address) {
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (strcmp(dns_cache[i].hostname, hostname) == 0 && time(NULL) - dns_cache[i].last_resolved < 3600) {
            memcpy(ip_address, dns_cache[i].ip_address, 16);
            return;
        }
    }

    resolve_dns(hostname, ip_address);
    for (int i = 0; i < DNS_CACHE_SIZE; i++) {
        if (dns_cache[i].last_resolved == 0) {
            strcpy(dns_cache[i].hostname, hostname);
            memcpy(dns_cache[i].ip_address, ip_address, 16);
            dns_cache[i].last_resolved = time(NULL);
            return;
        }
    }

    // Evict least recently used entry
    int lru_index = 0;
    for (int i = 1; i < DNS_CACHE_SIZE; i++) {
        if (time(NULL) - dns_cache[lru_index].last_resolved > time(NULL) - dns_cache[i].last_resolved) {
            lru_index = i;
        }
    }
    strcpy(dns_cache[lru_index].hostname, hostname);
    memcpy(dns_cache[lru_index].ip_address, ip_address, 16);
    dns_cache[lru_index].last_resolved = time(NULL);
}

